    function Config:Save()
        if not executor.writefile or not http then return false, "writefile_indisponivel" end
        self.ProfileKey = self:GetProfileKey()
        self.FileName = self:GetFileName(self.ProfileKey)
        local ok, encoded = pcall(function() return http:JSONEncode(self:Serialize()) end)
        if not ok then return false, "json_encode_falhou" end
        local wrote, errorMessage = pcall(executor.writefile, self.FileName, encoded)
        return wrote, errorMessage
    end

    function Config:Load()
        self.ProfileKey = self:GetProfileKey()
        self.FileName = self:GetFileName(self.ProfileKey)
        applyDefaults()

        local current = readConfig(self.FileName)
        if current then
            self:Apply(current, false)
            return "current"
        end

        local legacy = readConfig(self.LegacyFileName)
        if legacy then
            self:Apply(legacy, true)
            self:Save()
            return "migrated"
        end

        self:Save()
        return "new"
    end

    function Config:Reset()
        applyDefaults()
        return self:Save()
    end

    function Config:CheckPlayer()
        local profileKey = self:GetProfileKey()
        if profileKey == self.ProfileKey then return false end
        self:Load()
        return true
    end

    Flow.Config = Config
end)(Flow)
