        for id, entry in pairs(self.Runtime.entries) do
            if not isAlive(entry) then
                self.Runtime.entries[id] = nil
                removed = true
            end
        end
        if removed then self.Runtime.revision = self.Runtime.revision + 1 end
        return removed
    end

