        local kind = tostring(input.kind or "")
        if id == "" or kind == "" then return nil, "opportunity_id_and_kind_required" end
        local ttl = math.max(0.5, math.min(60, tonumber(input.ttl) or self.DefaultTTL))
        local existing = self.Runtime.entries[id]
        local entry = existing or {id = id, firstObservedAt = now()}
        entry.kind = kind
        entry.owner = input.owner and tostring(input.owner) or entry.owner
        entry.source = input.source and tostring(input.source) or entry.source or "unknown"
        entry.name = input.name and tostring(input.name) or entry.name or kind
        entry.object = input.object or entry.object
        entry.position = copyPosition(input.position) or entry.position
        entry.distance = math.max(0, tonumber(input.distance) or entry.distance or math.huge)
        entry.score = tonumber(input.score) or entry.score or 0
        entry.priority = tonumber(input.priority) or entry.priority or 0
        entry.metadata = type(input.metadata) == "table" and input.metadata or entry.metadata or {}
        entry.observedAt = now()
        entry.expiresAt = entry.observedAt + ttl
        entry.state = entry.state == "claimed" and "claimed" or "observed"
        self.Runtime.entries[id] = entry
        self.Runtime.revision = self.Runtime.revision + 1
