            end
        elseif not self:UseWorldPortals() then
            plan.worldPortalUnavailable = "world_portals_disabled"
        end

        local best = {mode = "direct", seconds = directSeconds, reason = "direct_faster"}
        for _, candidate in ipairs(candidates) do
            if candidate.seconds + self.PortalSavingsMargin < best.seconds then
                best = candidate
            end
        end

        plan.mode = best.mode
        plan.reason = best.reason
