            if not ticket then return false, "travel_busy" end
            ownsTicket = true
        end
        if self:IsCancelled(ticket) then
            if ownsTicket then self:EndTravel(ticket) end
            return false, ticket.cancelReason or "cancelled"
        end

        local character, root = self:GetCharacter(), self:GetRoot()
        if not character or not root or not tweenService then
            if ownsTicket then self:EndTravel(ticket) end
            return false, "sem_personagem"
        end

