            tween:Play()
            tween.Completed:Wait()
            if ticket.tween == tween then ticket.tween = nil end
        end)
        self:StopMotionStabilizer(ticket)

        local cancelled = self:IsCancelled(ticket)
        if ownsTicket then self:EndTravel(ticket) end
        if cancelled then return false, ticket.cancelReason or "cancelled" end
        return ok, errorMessage
    end

    Flow.Features.Teleport = Teleport
    Flow.Features.Movement = Teleport
end)(Flow)
Flow.Performance.modules['features/travel/travel_direct.lua'] = math.floor((os.clock() - __flow_module_started) * 1000 + 0.5) / 1000
end

