                local fromLanding = (root.Position - edge.landing).Magnitude
                if fromSource > self.ArrivalDistance and fromLanding < 900 then
                    return true
                end
            end
            task.wait(0.1)
        until os.clock() >= deadline
        return false, "no_native_arrival"
    end

    function WorldPortals:RecordMetric(name, seconds)
        if self.Metrics[name] then self.Metrics[name] = average(self.Metrics[name], seconds) end
    end

    function WorldPortals:UseEdge(edge, ticket, finalPosition)
        if not edge or not ticket then return false, "edge_unavailable" end
        if teleport:IsCancelled(ticket) then return false, "cancelled" end

        local source = self:FindPath(edge.sourcePath)
        if not source and edge.sourceEstimate then
            -- The part can be outside the stream radius. Approach a point near
            -- its recorded exterior through normal shared Travel first; never
            -- use the raw unlocked Tween for a map-length trip just to stream
            -- a portal in.
            local stage = edge.sourceEstimate + Vector3.new(0, 0, 30)
            local staged, stageReason = teleport:MoveAndConfirm(stage, ticket, nil)
            if not staged then return false, stageReason end
            source = self:WaitForHitbox(edge.sourcePath, self.HitboxTimeout, ticket)
        end
        if not source then return false, "hitbox_unavailable" end
