        local entered, enterReason = self:ApproachAndEnterHitbox(source, ticket)
        if not entered then return false, enterReason end

        local arrived, arrivalReason = self:WaitForArrival(edge, ticket)
        if not arrived then return false, arrivalReason end
        self:RecordMetric("portal", os.clock() - startedAt)

        local arrivalHitbox, arrivalReasonHitbox = self:WaitForHitbox(edge.arrivalPath, self.HitboxTimeout, ticket)
        if not arrivalHitbox then return false, arrivalReasonHitbox end
        local exited, exitReason = self:ExitHitbox(arrivalHitbox, finalPosition or edge.landing, ticket)
        if not exited then return false, exitReason end
        self:RecordMetric("settle", 0.2)
        self:SetStatus(edge.key, "available", "manual")
        return true
    end

    function WorldPortals:GetEdgeSourcePosition(edge)
        if not edge then return nil end
        -- Source positions are replaced by streamed Hitbox positions whenever
        -- possible; stored coordinates remain the read-only planning fallback.
        local source = self:FindPath(edge.sourcePath)
        return (source and source.Position) or edge.sourceEstimate or edge.landing
    end

    function WorldPortals:GetEdgeSeconds(fromPosition, edge, speed)
        local sourcePosition = self:GetEdgeSourcePosition(edge)
        if not sourcePosition then return math.huge, nil end
        local toEntry = math.max(0.1, (fromPosition - sourcePosition).Magnitude / speed)
        local exitSeconds = 25 / speed
        local transfer = (self.Metrics.portal or 1.8) + (self.Metrics.settle or 0.2) + exitSeconds
        return toEntry + transfer, sourcePosition
    end

    -- Search the confirmed directed portal graph instead of considering one
    -- edge only. This naturally supports every valid chain, such as
    -- Tiki → Castle → Mansion, rather than hard-coding that special case.
    function WorldPortals:EstimateTravel(targetPosition, speed)
        self:EnsureState()
        if Flow.State.useWorldPortals ~= true then return nil end
        local root = teleport:GetRoot()
        if not root or not targetPosition then return nil end
        speed = clamp(tonumber(speed) or teleport:GetSpeed(), teleport.MinSpeed, teleport.MaxSpeed)

        local best
        local function copyEdges(edges)
            local copied = {}
            for index, edge in ipairs(edges) do copied[index] = edge end
            return copied
        end
        local function copyUsed(used)
            local copied = {}
            for key, value in pairs(used) do copied[key] = value end
            return copied
        end
        local function consider(fromPosition, elapsed, edges, used, labels)
            for edgeName, edge in pairs(self.Edges) do
                if not used[edgeName] and self:IsConfirmed(edge.key) then
                    local edgeSeconds = self:GetEdgeSeconds(fromPosition, edge, speed)
                    if edgeSeconds < math.huge then
                        local totalBeforeFinal = elapsed + edgeSeconds
                        local finalSeconds = math.max(0.1, (edge.landing - targetPosition).Magnitude / speed)
                        local chain = copyEdges(edges)
                        table.insert(chain, {name = edgeName, edge = edge})
                        local chainLabels = {}
                        for index, value in ipairs(labels) do chainLabels[index] = value end
                        table.insert(chainLabels, edge.label)
                        local total = totalBeforeFinal + finalSeconds
                        if not best or total < best.total then
                            best = {
                                mode = "world_portal",
                                edgeName = chain[1].name,
                                edge = chain[1].edge,
                                edges = chain,
                                hops = #chain,
                                total = total,
                                finalSeconds = finalSeconds,
                                label = table.concat(chainLabels, " → "),
                            }
                        end

                        if #chain < self.MaxRouteHops then
                            local nextUsed = copyUsed(used)
                            nextUsed[edgeName] = true
                            consider(edge.landing, totalBeforeFinal, chain, nextUsed, chainLabels)
                        end
                    end
                end
            end
        end
        consider(root.Position, 0, {}, {}, {})
