    end

    function WorldPortals:Travel(plan, ticket, targetPosition)
        if not plan or plan.mode ~= "world_portal" or not plan.edge then return false, "world_portal_plan_missing" end
        local edges = plan.edges or {{name = plan.edgeName, edge = plan.edge}}
        for index, item in ipairs(edges) do
            local nextItem = edges[index + 1]
            local exitDirection = nextItem and self:GetEdgeSourcePosition(nextItem.edge) or targetPosition
            local ok, reason = self:UseEdge(item.edge, ticket, exitDirection)
            if not ok then
