    -- user must be able to revoke consent at every point. Keep the exact owned
    -- ticket here rather than guessing from generic teleport state.
    WorldPortals.ActiveTestTicket = nil

    function WorldPortals:IsTestRunning()
        local ticket = self.ActiveTestTicket
        return ticket ~= nil and not teleport:IsCancelled(ticket)
    end

    function WorldPortals:CancelTest(reason)
        local ticket = self.ActiveTestTicket
        if not ticket or teleport:IsCancelled(ticket) then return false, "no_active_test" end
        local cancelled = teleport:CancelTravel("world_portal_test", reason or "user_cancelled")
        return cancelled, cancelled and "cancelled" or "cancel_failed"
    end

    function WorldPortals:TestUnconfirmed()
        self:EnsureState()
        -- A cancelled worker may still be unwinding its final persistence. Do
        -- not start a second test until it clears this owned ticket.
        if self.ActiveTestTicket ~= nil then return false, "test_busy", self:GetUnconfirmedKeys() end
        local ticket, reason = teleport:BeginTravel(nil, "world_portal_test")
        if not ticket then return false, reason, self:GetUnconfirmedKeys() end
        self.ActiveTestTicket = ticket

        local tested, available = {}, {}
        local ok, runtimeError = xpcall(function()
            for _, item in ipairs(self.TestOrder) do
                if teleport:IsCancelled(ticket) then break end
                if not self:IsConfirmed(item.key) then
                    local forward = self.Edges[item.forward]
                    local forwardOk, forwardReason = self:UseEdge(forward, ticket, forward.landing)
                    table.insert(tested, {key = item.key, direction = "forward", ok = forwardOk, reason = forwardReason})
                    if forwardOk then
                        self:SetStatus(item.key, "available", "manual")
                        table.insert(available, item.key)

                        -- The return edge is tested too so the player finishes back at Castle.
                        local backward = self.Edges[item.backward]
                        local backOk, backReason = self:UseEdge(backward, ticket, backward.landing)
                        table.insert(tested, {key = item.key, direction = "return", ok = backOk, reason = backReason})
                    elseif forwardReason == "no_native_arrival" then
                        -- During an explicit user-approved test, entering the
                        -- live hitbox without a native arrival is a meaningful
                        -- locked result for this profile/key.
                        self:SetStatus(item.key, "locked")
                    elseif teleport:IsCancelled(ticket) then
                        break
                    else
                        self:SetStatus(item.key, "temporarily_unavailable")
                    end
                end
            end
        end, debug.traceback)

        local cancelled = teleport:IsCancelled(ticket)
        teleport:EndTravel(ticket)
        if self.ActiveTestTicket == ticket then self.ActiveTestTicket = nil end
        if Flow.Config then pcall(function() Flow.Config:Save() end) end
        if not ok then return false, tostring(runtimeError), tested end
        if cancelled then return false, "cancelled", tested end
        return self:HasAvailable(), #available > 0 and "available" or "no_portal_confirmed", tested
    end

    Flow.Features.WorldPortals = WorldPortals
end)(Flow)
Flow.Performance.modules['features/travel/travel_native_portals.lua'] = math.floor((os.clock() - __flow_module_started) * 1000 + 0.5) / 1000
end

