    Misc.AntiAfkConnection = nil
    Misc.FogSnapshot = nil

    local function safeCall(callback)
        local ok, value = pcall(callback)
        return ok, value
    end

    local function disconnect(connection)
        if connection then pcall(function() connection:Disconnect() end) end
    end

    function Misc:SetAntiAfk(active, save)
        active = active and true or false
        disconnect(self.AntiAfkConnection)
        self.AntiAfkConnection = nil
        state.antiAfkEnabled = active
        if active and player and player.Idled and type(player.Idled.Connect) == "function" then
            self.AntiAfkConnection = player.Idled:Connect(function()
                -- This does not move, click game UI, call a Remote, or change
                -- game state; it only gives Roblox a local idle acknowledgement.
                safeCall(function()
                    if not virtualUser then return end
                    virtualUser:CaptureController()
                    local camera = workspaceService and workspaceService.CurrentCamera
                    if camera and Vector2 then
                        virtualUser:ClickButton2(Vector2.new(0, 0), camera.CFrame)
                    end
                end)
            end)
        end
        if save ~= false and Flow.Config then Flow.Config:Save() end
        return active
    end

    function Misc:CaptureFog()
        if self.FogSnapshot or not lighting then return end
        local snapshot = {
            fogStart = lighting.FogStart,
            fogEnd = lighting.FogEnd,
            atmospheres = {},
        }
        if type(lighting.GetDescendants) == "function" then
            for _, object in ipairs(lighting:GetDescendants()) do
                if object:IsA("Atmosphere") then
                    table.insert(snapshot.atmospheres, {
                        object = object,
                        density = object.Density,
                        haze = object.Haze,
                        glare = object.Glare,
                    })
                end
            end
        end
        self.FogSnapshot = snapshot
    end

    function Misc:RestoreFog()
        local snapshot = self.FogSnapshot
        if not snapshot then return end
        if lighting then
            pcall(function() lighting.FogStart = snapshot.fogStart end)
            pcall(function() lighting.FogEnd = snapshot.fogEnd end)
        end
        for _, item in ipairs(snapshot.atmospheres) do
            if item.object and item.object.Parent then
                pcall(function()
                    item.object.Density = item.density
                    item.object.Haze = item.haze
                    item.object.Glare = item.glare
                end)
            end
        end
        self.FogSnapshot = nil
    end

    function Misc:SetRemoveFog(active, save)
        active = active and true or false
        state.removeFogEnabled = active
        if active then
            self:CaptureFog()
            if lighting then
                pcall(function() lighting.FogStart = 0 end)
                pcall(function() lighting.FogEnd = 1000000 end)
            end
            local snapshot = self.FogSnapshot
            for _, item in ipairs(snapshot and snapshot.atmospheres or {}) do
                if item.object and item.object.Parent then
                    pcall(function()
                        item.object.Density = 0
                        item.object.Haze = 0
                        item.object.Glare = 0
                    end)
                end
            end
        else
            self:RestoreFog()
        end
        if save ~= false and Flow.Config then Flow.Config:Save() end
        return active
    end

    function Misc:ApplySaved()
        self:SetAntiAfk(state.antiAfkEnabled, false)
        self:SetRemoveFog(state.removeFogEnabled, false)
    end

    function Misc:Shutdown()
        disconnect(self.AntiAfkConnection)
        self.AntiAfkConnection = nil
        -- Profile preferences stay saved, but the original Lighting is returned
        -- as soon as this UI instance is closed.
        self:RestoreFog()
    end

    Flow.Features.Misc = Misc
end)(Flow)
Flow.Performance.modules['features/misc/misc_general.lua'] = math.floor((os.clock() - __flow_module_started) * 1000 + 0.5) / 1000
end

