    function Farm:ClearHover()
        local state = self.State
        if state.hoverConnection then pcall(function() state.hoverConnection:Disconnect() end) end
        state.hoverConnection = nil
        state.hoverTarget = nil
        state.hoverCFrame = nil
        state.hoverCenter = nil
        state.hoverCenterProvider = nil
        state.hoverProviderMissingAt = nil
        state.hoverControlMode = nil
        state.hoverHeightOverride = nil
        state.hoverOrbit = false
        state.hoverOrbitRadius = 12
        state.hoverOrbitSpeed = 2.8
        state.hoverOwner = nil
        state.hoverActiveCheck = nil
        state.hoverLastCorrectionAt = -math.huge
        state.hoverLastDriftY = 0
        self:RestoreHoverStabilizer()
    end

    function Farm:HoldSpawn(spawnCFrame, orbit)
        if not spawnCFrame then return false end
        return self:BeginHoverAt(spawnCFrame.Position, orbit == true, "farm")
    end

    function Farm:GetLevel()
        local data = player and player:FindFirstChild("Data")
        local level = data and data:FindFirstChild("Level")
        return level and tonumber(level.Value) or 0
    end

    function Farm:SetPhase(phase, detail, quest, target)
        local state = self.State
        local nextPhase = phase or "idle"
        local enteringCombat = nextPhase == "combat" and (state.phase ~= "combat" or state.combatTarget ~= target)
        if enteringCombat then
            state.combatStartedAt = os.clock()
            state.firstAttackAt = 0
            state.firstDamageAt = 0
            state.combatTarget = target
            state.nextAttackAt = 0
        elseif nextPhase ~= "combat" and state.phase == "combat" then
            state.combatTarget = nil
            self:StopAttackPulse()
        end
        state.phase = nextPhase
        state.detail = detail or ""
        state.quest = quest
        state.target = target

        local checkpoint = Flow.Features and Flow.Features.ProgressCheckpoint
        if checkpoint and checkpoint.Publish then
            local targetRoot = modelRoot(target)
            local targetPosition = targetRoot and targetRoot.Position or nil
            pcall(function()
                checkpoint:Publish("farm_level", {
                    stage = nextPhase,
                    reason = state.detail,
                    quest = quest and {name = quest.name, mob = quest.mob} or nil,
                    target = target and {
                        name = target.Name,
                        position = targetPosition and {x = targetPosition.X, y = targetPosition.Y, z = targetPosition.Z} or nil,
                    } or nil,
                })
            end)
        end
    end

    function Farm:GetSnapshot()
        local state = self.State
        local tracked = self:GetTrackedQuest()
        return {
            running = state.running == true,
            phase = state.phase or "idle",
            detail = state.detail or "",
            level = self:GetLevel(),
            maxQuestLevel = self.MaxQuestLevel,
            quest = state.quest and state.quest.mob or nil,
            target = state.target and state.target.Name or nil,
            weapon = State.farmWeaponType or "",
            progress = tracked and tracked.progress or state.lastQuestProgress or "",
            attackAccepted = state.attackAccepted or 0,
            attackRejected = state.attackRejected or 0,
            cooldown = state.adaptiveAttackCooldown or 0.25,
            orbiting = state.hoverOrbit == true,
            hoverCorrections = state.hoverCorrections or 0,
            hoverVerticalCorrections = state.hoverVerticalCorrections or 0,
            hoverDriftY = state.hoverLastDriftY or 0,
            combatStartedAt = state.combatStartedAt or 0,
            firstAttackAt = state.firstAttackAt or 0,
            firstDamageAt = state.firstDamageAt or 0,
            attackAttempts = state.attackAttempts or 0,
            lastAttackReason = state.lastAttackReason or "",
            weaponEquipTransitions = state.weaponEquipTransitions or 0,
            prewarmSeconds = state.combatPrewarmSeconds or 0,
            attackPulseRunning = state.attackPulseRunning == true,
        }
    end

    function Farm:GetTools()
        local results, seen = {}, {}
        local function collect(container)
            if not container then return end
            for _, item in ipairs(container:GetChildren()) do
                if item:IsA("Tool") and not seen[item.Name] then
                    seen[item.Name] = true
                    table.insert(results, {
                        name = item.Name,
                        toolType = item.ToolTip ~= "" and item.ToolTip or "Tool",
                        equipped = item.Parent == self:GetCharacter(),
                    })
                end
            end
        end
        collect(player and player:FindFirstChild("Backpack"))
        collect(self:GetCharacter())
        table.sort(results, function(a, b) return a.name:lower() < b.name:lower() end)
        return results
    end

    function Farm:WeaponTypeLabelKey()
        return State.farmWeaponType == "Sword" and "farm_sword" or "farm_fighting_style"
    end

    function Farm:GetWeaponByType(toolType)
        if toolType ~= "Melee" and toolType ~= "Sword" then return nil end
        local character = self:GetCharacter()
        local backpack = player and player:FindFirstChild("Backpack")
        local function find(container)
            if not container then return nil end
            for _, item in ipairs(container:GetChildren()) do
                if item:IsA("Tool") and item.ToolTip == toolType then return item end
            end
            return nil
        end
        return find(character) or find(backpack)
    end

    function Farm:HasSelectedWeapon()
        return self:GetWeaponByType(State.farmWeaponType) ~= nil
    end

    -- Farm has exactly two exclusive choices: a Fighting Style or a Sword.
    -- The concrete Tool is resolved at equip time so a newly obtained style or
    -- sword can be used without changing the saved category.
    function Farm:SetWeaponType(toolType)
        if toolType ~= "Melee" and toolType ~= "Sword" then return false end
        State.farmWeaponType = toolType
        State.farmWeaponName = ""
        Flow.Config:Save()
        return true
    end

    function Farm:EquipSelectedWeapon()
        local tool = self:GetWeaponByType(State.farmWeaponType)
        local character = self:GetCharacter()
        local humanoid = self:GetHumanoid()
        if not tool or not character or not humanoid then return nil, "weapon_missing" end
        local state = self.State
        if tool.Parent ~= character then
            local now = os.clock()
            local ok = pcall(function() humanoid:EquipTool(tool) end)
            if not ok then return nil, "weapon_equip_failed" end
            state.weaponEquipTransitions = (state.weaponEquipTransitions or 0) + 1
            state.weaponEquipRequestedAt = now
            -- EquipTool can be asynchronous on touch clients. Do not emit the
            -- attack Remote during the same frame unless the Tool has actually
            -- reached Character; the pulse retries promptly without a fixed
            -- multi-second wait.
            if tool.Parent ~= character then return nil, "weapon_equipping" end
        end
        if state.weaponEquipRequestedAt and state.weaponEquipRequestedAt > 0 then
            state.weaponReadyAt = os.clock()
            state.weaponEquipRequestedAt = 0
        end
        return tool
    end

    function Farm:GetQuestsModule()
        local moduleScript = replicatedStorage and replicatedStorage:FindFirstChild("Quests")
        if not moduleScript then return nil end
        local ok, quests = pcall(require, moduleScript)
        return ok and type(quests) == "table" and quests or nil
    end

    function Farm:GetGuideModule()
        local moduleScript = replicatedStorage and replicatedStorage:FindFirstChild("GuideModule")
        if not moduleScript then return nil end
        local ok, guide = pcall(require, moduleScript)
        return ok and type(guide) == "table" and guide or nil
    end

    -- Resolve directly from the game-provided Quests table. Boss tasks (count 1)
    -- are excluded, so Level Farm always chooses an ordinary repeatable task.
    function Farm:ResolveQuest()
        local level = self:GetLevel()
        if level >= self.MaxQuestLevel and not State.farmAtMaxConfirmed then return nil, "farm_cap" end
        -- At level 2800 or higher, retain the last ordinary NPC quest rather
        -- than selecting any secret-level content beyond the farm scope.
        local questLevel = math.min(level, self.MaxQuestLevel)
        local quests = self:GetQuestsModule()
        if not quests then return nil, "quest_data_unavailable" end

        local choice, highest = nil, -1
        for questName, stages in pairs(quests) do
            if type(stages) == "table" then
                for stageId, info in pairs(stages) do
                    if type(info) == "table" and type(info.LevelReq) == "number" and info.LevelReq <= questLevel and type(info.Task) == "table" then
                        local mob, count
                        for candidate, required in pairs(info.Task) do
                            if type(candidate) == "string" and type(required) == "number" and required > 1 then
                                mob, count = candidate, required
                                break
                            end
                        end
                        if mob and info.LevelReq >= highest then
                            local replace = info.LevelReq > highest
                            if not replace and choice then
                                replace = tostring(questName) < tostring(choice.name)
                            end
                            if replace then
                                highest = info.LevelReq
                                choice = {
                                    name = questName,
                                    id = stageId,
                                    mob = mob,
                                    count = count,
                                    levelReq = info.LevelReq,
                                }
                            end
                        end
                    end
                end
            end
        end
        if choice then return choice, nil end
        return nil, "quest_not_found"
    end

    -- Update 30 moved the active quest display out of Main.Quest. The old
    -- panel remains in PlayerGui with stale content and Visible=false, whereas
    -- TrackedQuestFrame is the server-updated source of title and progress.
    function Farm:GetTrackedQuest()
        local gui = player and player:FindFirstChildOfClass("PlayerGui")
        local tracked = gui and gui:FindFirstChild("TrackedQuestFrame")
        local frame = tracked and tracked:FindFirstChild("Frame")
        local header = frame and frame:FindFirstChild("header")
        local title = header and header:FindFirstChild("textLabel")
        local progress = frame and frame:FindFirstChild("progress")
        local visible = tracked and tracked.Enabled ~= false and frame and frame.Visible ~= false
        local titleText = title and tostring(title.Text or "") or ""
        local progressText = progress and tostring(progress.Text or "") or ""
        local current, required = progressText:match("^(%d+)%s*/%s*(%d+)$")
        if visible and titleText ~= "" and current and required then
            return { title = titleText, progress = progressText, current = tonumber(current), required = tonumber(required) }
        end
        return nil
    end

    function Farm:GetActiveTask(expectedQuest)
        local guide = self:GetGuideModule()
        local data = guide and guide.Data
        local questData = data and data.QuestData
        local taskData = questData and questData.Task
        if type(taskData) == "table" then
            for mob, required in pairs(taskData) do
                if type(mob) == "string" and (type(required) ~= "number" or required > 0) then
                    return mob
                end
            end
        end

        local tracked = self:GetTrackedQuest()
        if tracked then
            if expectedQuest and expectedQuest.mob then
                local expected = normalizedName(expectedQuest.mob)
                local observed = normalizedName(tracked.title)
                if observed:find(expected, 1, true) then return expectedQuest.mob, tracked end
                return "different", tracked
            end
            return "active", tracked
        end

        -- Compatibility fallback for older UI layouts.
        local gui = player and player:FindFirstChild("PlayerGui")
        local main = gui and gui:FindFirstChild("Main")
        local questGui = main and main:FindFirstChild("Quest")
        if questGui and questGui.Visible then return "active" end
        return nil
    end

    function Farm:GetQuestPosition(quest)
        if not quest then return nil end
        local guide = self:GetGuideModule()
        local data = guide and guide.Data or {}

        local function asCFrame(value)
            if typeof(value) == "CFrame" then return value end
            if typeof(value) == "Vector3" then return CFrame.new(value) end
            return nil
        end
        local function coordinateOf(entry)
            if type(entry) ~= "table" then return nil end
            return asCFrame(entry.QuestCFrame)
                or asCFrame(entry.QuestPosition)
                or asCFrame(entry.CFrame)
                or asCFrame(entry.Position)
        end

        -- Current GuideModule data identifies each quest giver with
        -- InternalQuestName and Position. The original implementation looked
        -- for a non-existent Data.NPCs mapping, which made the Farm remain in
        -- "quest position missing" and never begin travel.
        local npcList = type(data.NPCList) == "table" and data.NPCList or {}
        for npc, info in pairs(npcList) do
            if type(info) == "table" and (
                info.InternalQuestName == quest.name
                or info.QuestName == quest.name
                or info.NameQuest == quest.name
            ) then
                local position = coordinateOf(info)
                if position then return position end
                local pivot = asCFrame(npc)
                if pivot then return pivot end
                if typeof(npc) == "Instance" then
                    local ok, instancePivot = pcall(function() return npc:GetPivot() end)
                    if ok and instancePivot then return instancePivot end
                end
            end
        end

        -- Preserve compatible fallbacks for older GuideModule layouts.
        local npcName = type(data.NPCs) == "table" and data.NPCs[quest.name] or nil
        if npcName then
            local npcFolders = {
                workspace and workspace:FindFirstChild("NPCs"),
                replicatedStorage and replicatedStorage:FindFirstChild("NPCs"),
            }
            for _, folder in ipairs(npcFolders) do
                local npc = folder and folder:FindFirstChild(npcName)
                if npc then
                    local ok, pivot = pcall(function() return npc:GetPivot() end)
                    if ok and pivot then return pivot end
                end
            end
        end

        local direct = coordinateOf(quest)
        if direct then return direct end
        return nil
    end

    function Farm:IsSubmergedQuest(quest)
        return quest and type(quest.name) == "string" and quest.name:match("^SubmergedQuest") ~= nil
    end

    function Farm:IsOnSubmergedIsland(quest)
        local root = self:GetRoot()
        if not root then return false end
        -- The confirmed submarine landing dock is a more reliable transition
        -- marker than a single quest giver, which may be over 1,500 studs away.
        if (root.Position - self.SubmergedEntryPosition).Magnitude <= self.SubmergedArrivalRadius then return true end
        local questPosition = self:GetQuestPosition(quest)
        return questPosition and (root.Position - questPosition.Position).Magnitude <= self.SubmergedArrivalRadius or false
    end

    function Farm:GetSubmarineWorker()
        local npcs = workspace and workspace:FindFirstChild("NPCs")
        local worker = npcs and npcs:FindFirstChild("Submarine Worker")
        return worker and worker:IsA("Model") and worker or nil
    end

    function Farm:GetSubmarineWorkerPosition()
        local worker = self:GetSubmarineWorker()
        if worker then
            local ok, pivot = pcall(function() return worker:GetPivot() end)
            if ok and pivot then return pivot end
        end
        return CFrame.new(self.SubmarineWorkerPosition)
    end

    -- Confirmed by the bounded Submarine Worker diagnostic. The path and
    -- argument are fixed, rather than discovered at runtime, so this bypasses
    -- the local dialogue presentation without using screen coordinates.
    function Farm:GetSubmarineWorkerRemote()
        local modules = replicatedStorage and replicatedStorage:FindFirstChild("Modules")
        local net = modules and modules:FindFirstChild("Net")
        local remote = net and net:FindFirstChild("RF/SubmarineWorkerSpeak")
        return remote and remote:IsA("RemoteFunction") and remote or nil
    end

    function Farm:RequestSubmarineTransfer()
        local now = os.clock()
        if now < (self.State.submarineWaitingUntil or 0) then return false, "submarine_waiting" end
        local remote = self:GetSubmarineWorkerRemote()
        if not remote then return false, "submarine_unavailable" end
        local ok, response = pcall(function()
            return remote:InvokeServer("TravelToSubmergedIsland")
        end)
        if ok then
            self.State.submarineDialogueAt = now
            -- The server-side transfer was observed in under a second after
            -- this exact request. Keep a recovery window for map streaming and
            -- avoid duplicate requests if the client is briefly delayed.
            self.State.submarineWaitingUntil = now + 18
            return true, response
        end
        return false, tostring(response or "submarine_transfer_failed")
    end

    function Farm:EnterSubmergedIsland(quest)
        local root = self:GetRoot()
        local workerPosition = self:GetSubmarineWorkerPosition()
        if not root or not workerPosition then
            self:SetPhase("submarine_unavailable", "submarine_unavailable", quest, nil)
            return true
        end
        if (root.Position - workerPosition.Position).Magnitude > 12 then
            self:SetPhase("going_to_submarine", "going_to_submarine", quest, nil)
            local moved, moveReason = self:MoveTo(workerPosition, "submarine:Sub Port 01")
            if not moved then self:SetPhase("movement_failed", moveReason or "movement_failed", quest, nil) end
            return true
        end
        if os.clock() < (self.State.submarineWaitingUntil or 0) then
            self:SetPhase("submarine_transferring", "submarine_waiting", quest, nil)
            return true
        end
        local requested, reason = self:RequestSubmarineTransfer()
        self:SetPhase(requested and "submarine_transferring" or "submarine_unavailable", reason or "submarine_transfer_failed", quest, nil)
        return true
    end

    function Farm:GetEnemies()
        return workspace and workspace:FindFirstChild("Enemies")
    end

    function Farm:GetQuestMobs(mobName)
        local enemies = self:GetEnemies()
        local results = {}
        if not enemies or not mobName then return results end
        for _, enemy in ipairs(enemies:GetChildren()) do
            local enemyRoot = modelRoot(enemy)
            if sameMobName(enemy.Name, mobName) and alive(enemy) and enemyRoot and not self:IsTemporarilyRejectedTarget(enemy) then
                table.insert(results, { model = enemy, root = enemyRoot, humanoid = enemy:FindFirstChildOfClass("Humanoid") })
                self:RememberObservedAnchor(mobName, enemyRoot.Position)
            end
        end
        return results
    end

    function Farm:RememberObservedAnchor(mobName, position)
        if not mobName or typeof(position) ~= "Vector3" then return end
        local anchors = self.State.observedAnchors[mobName] or {}
        for _, existing in ipairs(anchors) do if (existing - position).Magnitude <= 40 then return end end
        table.insert(anchors, position)
        while #anchors > 8 do table.remove(anchors, 1) end
        self.State.observedAnchors[mobName] = anchors
    end

    function Farm:GetNaturalCluster(mobName)
        local mobs = self:GetQuestMobs(mobName)
        local best, bestAnchor, bestDistance = {}, nil, math.huge
        local playerRoot = self:GetRoot()
        for _, seed in ipairs(mobs) do
            local group = {}
            for _, candidate in ipairs(mobs) do
                -- Every selected NPC is within 55 studs of this *seed*, not
                -- merely the averaged centroid. At +30 this keeps every member
                -- inside the confirmed hit reach and avoids a stale midpoint.
                if (candidate.root.Position - seed.root.Position).Magnitude <= 55 then table.insert(group, candidate) end
            end
            local distance = playerRoot and (playerRoot.Position - seed.root.Position).Magnitude or 0
            if #group > #best or (#group == #best and distance < bestDistance) then
                best, bestAnchor, bestDistance = group, seed.root.Position, distance
            end
        end
        if #best == 0 then return nil, nil, mobs end
        return best, bestAnchor, mobs
    end

    function Farm:FindTarget(mobName)
        local root = self:GetRoot()
        local closest, shortest = nil, math.huge
        for _, item in ipairs(self:GetQuestMobs(mobName)) do
            local distance = root and (item.root.Position - root.Position).Magnitude or 0
            if distance < shortest then closest, shortest = item.model, distance end
        end
        return closest
    end

    function Farm:GetSpawnPositions(mobName)
        local results = {}
        local worldOrigin = workspace and workspace:FindFirstChild("_WorldOrigin")
        local spawns = worldOrigin and worldOrigin:FindFirstChild("EnemySpawns")
        local desired = normalizedName(mobName)
        if spawns and desired ~= "" then
            for _, spawn in ipairs(spawns:GetChildren()) do
                if normalizedName(spawn.Name) == desired then
                    local position = nil
                    if spawn:IsA("BasePart") then position = spawn.Position else
                        local ok, pivot = pcall(function() return spawn:GetPivot() end)
                        position = ok and pivot and pivot.Position or nil
                    end
                    if position then table.insert(results, position); self:RememberObservedAnchor(mobName, position) end
                end
            end
        end
        return results
    end

    function Farm:GetKnownWaitAnchors(mobName)
        local direct = self.KnownQuestAnchors[mobName]
        if direct then return direct end
        local normalized = normalizedName(mobName)
        for key, anchors in pairs(self.KnownQuestAnchors) do
            if normalizedName(key) == normalized then return anchors end
        end
        return nil
    end

    function Farm:GetWaitAnchor(mobName)
        local anchors = self.State.observedAnchors[mobName] or {}
        local root = self:GetRoot()
        local best, distance = nil, math.huge
        for _, position in ipairs(anchors) do
            local d = root and (root.Position - position).Magnitude or 0
            if d < distance then best, distance = position, d end
        end
        if best then return best end
        local spawns = self:GetSpawnPositions(mobName)
        if spawns[1] then return spawns[1] end
        local known = self:GetKnownWaitAnchors(mobName)
        if known and known[1] then
            for _, position in ipairs(known) do self:RememberObservedAnchor(mobName, position) end
            return known[1]
        end
        return nil
    end

    function Farm:GetSpawnPosition(mobName)
        local position = self:GetWaitAnchor(mobName)
        return position and CFrame.new(position) or nil
    end

    function Farm:MoveTo(targetCFrame, targetLabel)
        -- Long routes use the shared travel executor. Remove the close-combat
        -- hover lock first so all character properties are restored before it
        -- takes control.
        self:ClearHover()
        local root = self:GetRoot()
        local teleport = Flow.Features.Teleport
        if not root or not targetCFrame then return false, "root_missing" end
        local destination = targetCFrame.Position
        if (root.Position - destination).Magnitude <= 7 then return true, "arrived" end
        if not teleport or not teleport.TravelToPosition then return false, "movement_unavailable" end
        local label = tostring(targetLabel or "Farm")
        local horizontal = Vector3.new(root.Position.X - destination.X, 0, root.Position.Z - destination.Z).Magnitude
        local localCombatApproach = (label:sub(1, 8) == "cluster:" or label:sub(1, 6) == "spawn:")
            and horizontal <= self.LocalCombatHorizontalDistance
        if localCombatApproach and teleport.TravelDirectToPosition then
            -- Preserve genuine water/wall protection, but do not turn a
            -- no-support probe or a moving-target correction into a sequence
            -- of ever-higher routes. The next Farm step will re-read the live
            -- cluster anchor if this one direct attempt is not accepted.
            return teleport:TravelDirectToPosition(destination, "farm", label, {
                ignoreNoSupportWater = true,
                disableAdaptiveClearance = true,
                -- The server arrival check is read-only but can last 1.2 s.
                -- Keep velocity neutral during it so a safe route never turns
                -- into a visible gravity fall before Farm re-reads its anchor.
                holdArrivalVelocity = true,
                -- The live target trace reached visible close range about 1.5 s
                -- before combat because the generic world-route confirmation
                -- always observed for 1.2 s. Keep a real reconciliation check,
                -- but shrink this known local combat sample to 0.25 s.
                arrivalConfirmSeconds = 0.25,
                maxAttempts = 1,
            })
        end
        return teleport:TravelToPosition(
            destination,
            "farm",
            label,
            Flow.Features.Portal,
            Flow.Features.WorldPortals
        )
    end

    function Farm:StartQuest(quest)
        local remotes = replicatedStorage and replicatedStorage:FindFirstChild("Remotes")
        local commF = remotes and remotes:FindFirstChild("CommF_")
        if not commF or not commF.InvokeServer then return false, "quest_remote_unavailable" end
        local ok, response = pcall(function()
            -- Intentional, fixed and auditable quest call. Flow does not scan or
            -- invoke arbitrary Remote names or argument sets.
            return commF:InvokeServer("StartQuest", quest.name, quest.id)
        end)
        return ok, response
    end

    function Farm:ResetCombatAnchor()
        local state = self.State
        state.combatAnchor = nil
        state.combatAnchorMob = nil
        state.combatAnchorChangedAt = 0
        state.wave = nil
    end

    function Farm:RestoreGrouped()
        for enemy, saved in pairs(self.State.grouped) do
            if enemy and enemy.Parent then
                local humanoid = enemy:FindFirstChildOfClass("Humanoid")
                local root = modelRoot(enemy)
                if root and saved.canCollide ~= nil then pcall(function() root.CanCollide = saved.canCollide end) end
                if humanoid and saved.walkSpeed ~= nil then pcall(function() humanoid.WalkSpeed = saved.walkSpeed end) end
            end
        end
        self.State.grouped = {}
        self.State.wave = nil
    end

    function Farm:SetCombatAnchor(quest, center)
        if typeof(center) ~= "Vector3" or not quest then return false end
        local state = self.State
        local changed = not state.combatAnchor
            or not sameMobName(state.combatAnchorMob, quest.mob)
            or (state.combatAnchor - center).Magnitude > self.CombatAnchorShift
        if changed then
            self:RestoreGrouped()
            state.combatAnchor = center
            state.combatAnchorMob = quest.mob
            state.combatAnchorChangedAt = os.clock()
            state.wave = { mob = quest.mob, center = center, staged = false }
        end
        self:RememberObservedAnchor(quest.mob, center)
        return changed
    end

    -- One optional, reversible local stage per wave. It never moves the same
    -- NPC again in the combat loop and the player anchor never follows staged
    -- NPC Roots, so a server correction cannot drag the player away.
    function Farm:BringMobs(target, center)
        -- Farm Level must not client-CFrame Workspace NPCs. On mobile/current
        -- servers that creates local-only copies at the rally point while the
        -- server keeps the real NPC elsewhere; combat then targets a visual
        -- clone and every hit is rejected. Raid has its separately bounded
        -- owned-wave handling. Level Farm remains stable_no_sim and follows
        -- server-replicated NPC positions only.
        self:RestoreGrouped()
        return false, "disabled_stable_no_sim"
    end

    function Farm:IsSafeExternalStageSurface(position, ignored)
        if typeof(position) ~= "Vector3" then return false, "position_missing" end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = ignored or {}
        params.IgnoreWater = false
        local ok, hit = pcall(function() return workspace:Raycast(position + Vector3.new(0, 260, 0), Vector3.new(0, -650, 0), params) end)
        if not ok or not hit then return false, "surface_missing" end
        local n, m = string.lower(tostring(hit.Instance and hit.Instance.Name or "")), string.lower(tostring(hit.Material or ""))
        if n:find("water", 1, true) or n:find("lava", 1, true) or m:find("water", 1, true) or m:find("lava", 1, true) then
            return false, "hazard_" .. tostring(hit.Instance and hit.Instance.Name or hit.Material)
        end
        return true, "safe_" .. tostring(hit.Instance and hit.Instance.Name or hit.Material)
    end

    function Farm:FindSafeExternalStagePosition(center, offset, ignored)
        local desired = center + offset
        local safe, detail = self:IsSafeExternalStageSurface(desired, ignored)
        if safe then return desired, detail end
        -- If the desired side hits water/lava, first try the opposite side of
        -- the rally point; this pulls the NPCs inward instead of toward sea.
        local alternatives = {
            center - offset,
            center + Vector3.new(18, 0, 0), center + Vector3.new(-18, 0, 0),
            center + Vector3.new(0, 0, 18), center + Vector3.new(0, 0, -18),
        }
        for _, candidate in ipairs(alternatives) do
            local okay, why = self:IsSafeExternalStageSurface(candidate, ignored)
            if okay then return candidate, "inward_after_" .. tostring(detail) .. "|" .. tostring(why) end
        end
        return nil, detail
    end

    function Farm:StageExternalWave(owner, candidates, center, stageKey, anchorModel)
        local state = self.State
        if not State.farmBringMobs then return false, "bring_off" end
        if state.hoverOwner ~= owner or typeof(center) ~= "Vector3" then return false, "stage_not_owned" end
        if stageKey and state.externalStageKey == stageKey then return true, "already_staged" end
        self:RestoreGrouped()
        local radius = clamp(tonumber(State.farmBringRadius) or 450, 60, 600)
        local eligible, ignored = {}, {}
        local character = self:GetCharacter()
        if character then table.insert(ignored, character) end
        for index, entry in ipairs(candidates or {}) do
            local enemy, root = entry and entry.model, entry and entry.root
            if enemy and root and alive(enemy) and (root.Position - center).Magnitude <= radius then
                table.insert(eligible, { enemy = enemy, root = root })
                table.insert(ignored, enemy)
                if #eligible >= 24 then break end
            end
            if index % 20 == 0 then task.wait() end
        end
        local staged, blocked, lastDetail = 0, 0, ""
        for index, entry in ipairs(eligible) do
            local enemy, root = entry.enemy, entry.root
            -- Keep the current target where it is; Raid follows it above the
            -- head while surrounding owned mobs are pulled to safe slots.
            if enemy ~= anchorModel then
                local angle = (index - 1) * math.pi * 2 / math.max(1, #eligible)
                local offset = Vector3.new(math.cos(angle) * 13, 0, math.sin(angle) * 13)
                local stagedPosition, detail = self:FindSafeExternalStagePosition(center, offset, ignored)
                lastDetail = detail or lastDetail
                if stagedPosition then
                    local humanoid = enemy:FindFirstChildOfClass("Humanoid")
                    state.grouped[enemy] = { canCollide = root.CanCollide, walkSpeed = humanoid and humanoid.WalkSpeed or nil }
                    pcall(function() root.CanCollide = false; root.CFrame = CFrame.new(stagedPosition) end)
                    if humanoid then pcall(function() humanoid.WalkSpeed = 0 end) end
                    staged = staged + 1
                else
                    blocked = blocked + 1
                end
            end
            if index % 20 == 0 then task.wait() end
        end
        state.externalStageKey = stageKey or tostring(center)
        return true, "staged=" .. tostring(staged) .. "|hazard_blocked=" .. tostring(blocked) .. "|" .. tostring(lastDetail)
    end

    function Farm:ClearExternalStage(owner)
        if owner and self.State.hoverOwner and self.State.hoverOwner ~= owner then return false, "stage_not_owned" end
        self:RestoreGrouped()
        self.State.externalStageKey = nil
        return true
    end

    function Farm:UpdateAttackFeedback()
        local pending = self.State.pendingAttack
        if not pending or os.clock() - pending.at < 0.16 then return end
        local accepted = false
        for model, healthBefore in pairs(pending.health) do
            local humanoid = model and model:FindFirstChildOfClass("Humanoid")
            if not humanoid or humanoid.Health < healthBefore then accepted = true break end
        end
        if accepted then
            self.State.attackAccepted = self.State.attackAccepted + 1
            if (self.State.combatStartedAt or 0) > 0 and (self.State.firstDamageAt or 0) == 0 then
                self.State.firstDamageAt = os.clock()
            end
            self.State.consecutiveRejected = 0
            self.State.singleTargetMode = false
            self.State.adaptiveAttackCooldown = math.max(0.25, (self.State.adaptiveAttackCooldown or 0.25) - 0.01)
        else
            self.State.attackRejected = self.State.attackRejected + 1
            self.State.consecutiveRejected = self.State.consecutiveRejected + 1
            -- A single-model failure is attributable. Quarantine that model
            -- briefly instead of hovering and retrying the same untouchable
            -- clone indefinitely. Group failures first switch to exact target
            -- mode so a good neighboring NPC is never discarded blindly.
            if pending.models and #pending.models == 1 and not self.State.skipRejectedTargetForSeaBeast then
                self:MarkRejectedTarget(pending.models[1])
            end
            if self.State.consecutiveRejected >= 2 then
                self.State.singleTargetMode = true
                self.State.adaptiveAttackCooldown = math.min(0.35, (self.State.adaptiveAttackCooldown or 0.25) + 0.02)
            end
        end
        self.State.pendingAttack = nil
    end

    -- Resolve only the Hub's known combat surfaces before a target is in
    -- range. This moves one-time executor/module work off the first damage
    -- window without firing a Remote or changing the character.
    function Farm:PrewarmCombat()
        local state = self.State
        if state.combatPrewarmRunning then return end
        state.combatPrewarmRunning = true
        state.combatPrewarmAt = os.clock()
        task.spawn(function()
            local began = os.clock()
            pcall(function()
                self:GetCombatRemotes()
                if self:HasCombatRemoteThread() then self:GetSendHitsToServer() end
            end)
            state.combatPrewarmSeconds = os.clock() - began
            state.combatPrewarmRunning = false
        end)
    end

    function Farm:StopAttackPulse()
        local state = self.State
        state.attackPulseId = (state.attackPulseId or 0) + 1
        state.attackPulseRunning = false
        state.nextAttackAt = 0
    end

    -- Quest/cluster planning stays at 0.12 s for mobile friendliness. A
    -- narrowly-owned pulse schedules only combat attempts by their actual
    -- cooldown, removing the old 0.25 s -> ~0.36 s loop quantization.
    function Farm:StartAttackPulse()
        local state = self.State
        -- Settings → Combat owns the continuous nearby-mob cadence whenever it
        -- is enabled. Farm still owns quest, anchor and hover work, but must
        -- never send a duplicate second attack stream for the same enemy.
        local autoCombat = Flow.Features and Flow.Features.AutoCombat
        if autoCombat and autoCombat.IsMobEnabled and autoCombat:IsMobEnabled() then
            self:StopAttackPulse()
            state.lastAttackReason = "settings_auto_combat_mobs"
            return
        end
        if state.attackPulseRunning then return end
        state.attackPulseRunning = true
        state.attackPulseId = (state.attackPulseId or 0) + 1
        local pulseId, generation = state.attackPulseId, state.generation
        task.spawn(function()
            while State.farmLevelEnabled and state.generation == generation and state.attackPulseId == pulseId and state.phase == "combat" do
                local autoCombat = Flow.Features and Flow.Features.AutoCombat
                if autoCombat and autoCombat.IsMobEnabled and autoCombat:IsMobEnabled() then
                    state.lastAttackReason = "settings_auto_combat_mobs"
                    break
                end
                self:UpdateAttackFeedback()
                local now = os.clock()
                local cooldown = math.max(0.25, state.adaptiveAttackCooldown or 0.25)
                local dueAt = math.max(state.nextAttackAt or 0, (state.lastAttackAt or 0) + cooldown)
                if now >= dueAt then
                    local target = state.target
                    local ok, attacked, reason = pcall(function() return self:Attack(target) end)
                    if not ok then
                        state.lastAttackReason = tostring(attacked)
                        state.nextAttackAt = os.clock() + 0.08
                    elseif reason == "weapon_equipping" then
                        state.lastAttackReason = reason
                        state.nextAttackAt = os.clock() + 0.04
                    elseif reason == "cooldown" then
                        state.nextAttackAt = (state.lastAttackAt or os.clock()) + math.max(0.25, state.adaptiveAttackCooldown or 0.25)
                    else
                        state.lastAttackReason = tostring(reason or "")
                        if attacked and reason == "attacked" then
                            state.nextAttackAt = (state.lastAttackAt or os.clock()) + math.max(0.25, state.adaptiveAttackCooldown or 0.25)
                        else
                            state.nextAttackAt = os.clock() + 0.06
                        end
                    end
                else
                    task.wait(math.max(0.01, math.min(0.05, dueAt - now)))
                end
            end
            if state.attackPulseId == pulseId then state.attackPulseRunning = false end
        end)
    end

    function Farm:GetCombatRemotes()
        local modules = replicatedStorage and replicatedStorage:FindFirstChild("Modules")
        local net = modules and modules:FindFirstChild("Net")
        local attack = net and net:FindFirstChild("RE/RegisterAttack")
        local hit = net and net:FindFirstChild("RE/RegisterHit")
        if attack and hit and attack:IsA("RemoteEvent") and hit:IsA("RemoteEvent") then return attack, hit end
        return nil, nil
    end

    -- Prefer the current game's own combat sender when the feature flag says
    -- that a threaded combat path is active. This is the same bounded known
    -- surface used by Raid; no arbitrary Remote discovery or replay occurs.
    function Farm:GetSendHitsToServer()
        local state, now = self.State, os.clock()
        if type(state.sendHits) == "function" then return state.sendHits end
        if now < (state.sendHitsRetryAt or -math.huge) then return nil end
        state.sendHitsRetryAt = now + 2
        local getsenv = Flow:GetExecutorFunction("getsenv")
        local scripts = player and player:FindFirstChild("PlayerScripts")
        if type(getsenv) ~= "function" or not scripts then return nil end
        local checked = 0
        for _, script in ipairs(scripts:GetChildren()) do
            checked = checked + 1
            if checked > 100 then break end
            if script:IsA("LocalScript") then
                local ok, environment = pcall(getsenv, script)
                local sender = ok and environment and environment._G and environment._G.SendHitsToServer or nil
                if type(sender) == "function" then
                    state.sendHits = sender
                    state.sendHitsResolved = true
                    return sender
                end
            end
        end
        state.sendHitsResolved = false
        return nil
    end

    function Farm:HasCombatRemoteThread()
        if self.State.combatThreadAvailable ~= nil then return self.State.combatThreadAvailable == true end
        local flags = replicatedStorage and replicatedStorage:FindFirstChild("Modules") and replicatedStorage.Modules:FindFirstChild("Flags")
        local ok, values = pcall(function() return flags and require(flags) end)
        self.State.combatThreadAvailable = ok and type(values) == "table" and values.COMBAT_REMOTE_THREAD == true
        return self.State.combatThreadAvailable == true
    end

    function Farm:GetCombatHitData(target, rangeOverride)
        local root = self:GetRoot()
        local hitRange = tonumber(rangeOverride) or 80
        local enemies = self:GetEnemies()
        if not root or not enemies or not target then return nil, nil, nil end
        local hitData, health = {}, {}
        local preferredParts = { "RightLowerArm", "RightUpperArm", "LeftLowerArm", "LeftUpperArm", "RightHand", "LeftHand" }
        for _, enemy in ipairs(enemies:GetChildren()) do
            local enemyRoot = modelRoot(enemy)
            local sameTarget = enemy == target
            local eligible = self.State.singleTargetMode == true and sameTarget or enemy.Name == target.Name
            if eligible and alive(enemy) and enemyRoot and (enemyRoot.Position - root.Position).Magnitude <= hitRange and not self:IsTemporarilyRejectedTarget(enemy) then
                local part = nil
                for _, name in ipairs(preferredParts) do part = enemy:FindFirstChild(name); if part then break end end
                part = part or enemy.PrimaryPart or enemyRoot
                local humanoid = enemy:FindFirstChildOfClass("Humanoid")
                if part and humanoid then
                    table.insert(hitData, { enemy, part })
                    health[enemy] = humanoid.Health
                end
            end
        end
        if #hitData == 0 then return nil, hitData, health end
        self.State.attackPrimaryIndex = (self.State.attackPrimaryIndex % #hitData) + 1
        return hitData[self.State.attackPrimaryIndex][2], hitData, health
    end

    function Farm:Attack(target, options)
        options = options or {}
        if not State.farmAutoAttack or not alive(target) then return false, "attack_off" end
        self:UpdateAttackFeedback()
        local now = os.clock()
        local cooldown = math.max(0.25, self.State.adaptiveAttackCooldown or 0.25)
        if now - self.State.lastAttackAt < cooldown then
            local character = self:GetCharacter()
            local weapon = character and character:FindFirstChildWhichIsA("Tool")
            if weapon then
                warn("[farm] cooldown on weapon:", weapon.Name, "| last use:", os.clock() - (self.State.lastAttackAt or 0))
            end
            return true, "cooldown"
        end
        local tool, reason = self:EquipSelectedWeapon()
        if not tool then return false, reason end
        local attack, hit = self:GetCombatRemotes()
        if not attack or not hit then return false, "combat_remotes_unavailable" end
        local primaryPart, hitData, health = self:GetCombatHitData(target, options.range)
        if not primaryPart or #hitData == 0 then
            -- v1.6.3 range diagnosis. Farm has no EventFarm journal closure, so
            -- retain primitive evidence in State; EventFarm copies it into its
            -- own journal immediately when this exact return reason is observed.
            local root = self:GetRoot()
            local enemies = self:GetEnemies()
            local debugEnemies = {}
            if enemies and root then
                for _, enemy in ipairs(enemies:GetChildren()) do
                    local enemyRoot = modelRoot(enemy)
                    if enemyRoot then
                        table.insert(debugEnemies, {
                            name = enemy.Name,
                            rootName = enemyRoot.Name,
                            dist = (enemyRoot.Position - root.Position).Magnitude,
                            sameTarget = enemy == target,
                            nameMatchesTarget = target and enemy.Name == target.Name or false,
                            alive = alive(enemy),
                        })
                    end
                end
            end
            local sharkRoot = modelRoot(target)
            self.State.lastAttackRangeDebug = {
                playerRootPos = root and {root.Position.X, root.Position.Y, root.Position.Z} or nil,
                questMob = self.State.quest and self.State.quest.mob or nil,
                singleTargetMode = self.State.singleTargetMode == true,
                enemiesContainer = enemies and enemies:GetFullName() or nil,
                sharkName = target and target.Name or nil,
                sharkParent = target and target.Parent and target.Parent.Name or nil,
                sharkInEnemies = target ~= nil and enemies ~= nil and target.Parent == enemies,
                sharkRootName = sharkRoot and sharkRoot.Name or nil,
                sharkDist = sharkRoot and root and (sharkRoot.Position - root.Position).Magnitude or -1,
                enemies = debugEnemies,
            }
            return false, "target_out_of_range"
        end
        local root = self:GetRoot()
        -- Tool:Activate is the game's normal local input path and, unlike a
        -- keyboard simulation, works on touch-only Delta/Android clients. Its
        -- own LocalScript may prepare move state before the known combat route.
        pcall(function() tool:Activate() end)
        -- Preserve the known combat transport after the normal tool activation.
        local click = tool:FindFirstChild("LeftClickRemote")
        if click and click:IsA("RemoteEvent") and root then
            local delta = primaryPart.Position - root.Position
            local direction = delta.Magnitude > 0 and delta.Unit or Vector3.zero
            pcall(function() click:FireServer(direction, 1) end)
        end
        self.State.lastAttackAt = now
        self.State.attackAttempts = (self.State.attackAttempts or 0) + 1
        if (self.State.combatStartedAt or 0) > 0 and (self.State.firstAttackAt or 0) == 0 then
            self.State.firstAttackAt = now
        end
        local models = {}
        for _, row in ipairs(hitData) do table.insert(models, row[1]) end
        local ok, errorMessage = pcall(function()
            attack:FireServer(0)
            local sender = self:HasCombatRemoteThread() and self:GetSendHitsToServer() or nil
            if sender then sender(primaryPart, hitData) else hit:FireServer(primaryPart, hitData) end
        end)
        if ok then self.State.pendingAttack = { at = now, health = health, targets = #hitData, models = models } end
        self.State.lastAttackReason = ok and "attacked" or tostring(errorMessage or "attack_failed")
        return ok, self.State.lastAttackReason
    end

    function Farm:GetCheckpoint(reason)
        local state = self.State
        local targetRoot = modelRoot(state.target)
        return {
            stage = state.phase or "idle",
            reason = reason or state.detail or "",
            quest = state.quest and {name = state.quest.name, mob = state.quest.mob} or nil,
            target = state.target and {
                name = state.target.Name,
                position = targetRoot and {x = targetRoot.Position.X, y = targetRoot.Position.Y, z = targetRoot.Position.Z} or nil,
            } or nil,
        }
    end

    function Farm:CanYield(context)
        if State.farmLevelEnabled ~= true or State.farmAutomationMode == "missions" then return true, "farm_not_requested" end
        local phase = self.State.phase or "idle"
        -- A fruit/event may take the route only outside local combat and its
        -- immediate approach. The queued opportunity remains visible until a
        -- safe checkpoint appears instead of interrupting an attack sequence.
        if phase == "combat" or phase == "approaching_target" then return false, "farm_combat_active" end
        return true, "farm_safe_checkpoint"
    end

    function Farm:PauseForCoordinator(context)
        local requester = type(context) == "table" and context.requester or "coordinator"
        return self:PauseForPriority("coordinator_" .. tostring(requester))
    end

    function Farm:ResumeFromCoordinator(checkpoint)
        if State.farmLevelEnabled ~= true or State.farmAutomationMode == "missions" then return false, "farm_not_requested" end
        self.State.priorityPauseReason = nil
        self:SetPhase("resuming_checkpoint", checkpoint and checkpoint.stage or "coordinator_resume", nil, nil)
        return true
    end

    function Farm:IsCoordinatorRequested()
        return State.farmLevelEnabled == true and State.farmAutomationMode ~= "missions"
    end

    function Farm:EnsureCoordinatorLease()
        local coordinator = Flow.Features and Flow.Features.FarmCoordinator
        if not coordinator then return true end
        if coordinator:Owns("farm_level", "movement") and coordinator:Owns("farm_level", "combat") then return true end
        local nowAt = os.clock()
        if nowAt < (self.State.nextCoordinatorAttemptAt or 0) then
            return false, self.State.lastCoordinatorReason or "coordinator_wait"
        end
        self.State.nextCoordinatorAttemptAt = nowAt + 0.45
        local acquired, leaseOrReason = coordinator:TryAcquire("farm_level", {
            resources = {"movement", "combat"},
            priority = 40,
            preemptible = true,
            context = {stage = self.State.phase or "idle"},
        })
        self.State.lastCoordinatorReason = acquired and nil or tostring(leaseOrReason)
        return acquired, leaseOrReason
    end

    function Farm:PauseForPriority(reason)
        reason = tostring(reason or "priority")
        if self.State.priorityPauseReason == reason then return true end
        self.State.priorityPauseReason = reason
        self:StopAttackPulse()
        -- Never clear another owner's Raid/fruit hover; Farm only releases its
        -- own local lease and its own pending movement.
        if self.State.hoverOwner == "farm" then self:ClearHover() end
        self:RestoreGrouped()
        local teleport = Flow.Features.Teleport
        if teleport and teleport.CancelTravel then pcall(function() teleport:CancelTravel("farm", "priority_" .. reason) end) end
        self:SetPhase("paused_priority", reason, nil, nil)
        return true
    end

    function Farm:Step()
        self:UpdateAttackFeedback()
        if not State.farmLevelEnabled then self:ClearHover(); return false end
        local leaseHeld, leaseReason = self:EnsureCoordinatorLease()
        if not leaseHeld then return self:PauseForPriority(leaseReason or "coordinator_busy") end
        self.State.priorityPauseReason = nil
        local level = self:GetLevel()
        if level >= self.MaxQuestLevel and not State.farmAtMaxConfirmed then
            -- Data.Level can become available just after the toggle is pressed.
            -- Stop safely, but hand the decision back to the UI instead of
            -- silently cancelling Farm at the cap.
            State.farmCapPromptPending = true
            self:ClearHover(); self:SetPhase("farm_cap", "level_cap", nil, nil); self:SetEnabled(false); return false
        end
        if not self:HasSelectedWeapon() then self:ClearHover(); self:SetPhase("weapon_missing", "weapon_missing", nil, nil); return true end
        local quest, questReason = self:ResolveQuest()
        if not quest then self:ClearHover(); self:SetPhase(questReason or "quest_unavailable", questReason or "quest_unavailable", nil, nil); return true end
        if self:IsSubmergedQuest(quest) and not self:IsOnSubmergedIsland(quest) then self:ClearHover(); return self:EnterSubmergedIsland(quest) end

        local activeTask, tracked = self:GetActiveTask(quest)
        if tracked and tracked.progress then self.State.lastQuestProgress = tracked.progress end
        if not activeTask then
            self:ClearHover()
            local position = self:GetQuestPosition(quest)
            if not position then self:SetPhase("quest_position_missing", "quest_position_missing", quest, nil); return true end
            local root = self:GetRoot()
            if root and (root.Position - position.Position).Magnitude > 10 then
                self:SetPhase("going_to_quest", "going_to_quest", quest, nil)
                local moved, moveReason = self:MoveTo(position, "quest:" .. tostring(quest.name))
                if not moved then self:SetPhase("movement_failed", moveReason or "movement_failed", quest, nil) end
            elseif os.clock() >= (self.State.questStartWaitingUntil or 0) then
                self:SetPhase("starting_quest", "starting_quest", quest, nil)
                local started, startReason = self:StartQuest(quest)
                self.State.questStartWaitingUntil = os.clock() + 1.2
                if not started then self:SetPhase("quest_start_failed", tostring(startReason or "quest_start_failed"), quest, nil) end
            else self:SetPhase("starting_quest", "starting_quest", quest, nil) end
            return true
        end
        if activeTask ~= "active" and not sameMobName(activeTask, quest.mob) then self:ClearHover(); self:SetPhase("different_quest", "different_quest", quest, nil); return true end

        local cluster, center, allMobs = self:GetNaturalCluster(quest.mob)
        if not cluster then
            self:RestoreGrouped()
            -- A respawn after even one empty scan is a new wave. Clearing this
            -- state makes the first already-existing mob immediately become the
            -- fresh combat anchor instead of waiting for later spawns to move a
            -- stale anchor far enough.
            self:ResetCombatAnchor()
            local waitAnchor = self:GetWaitAnchor(quest.mob)
            if waitAnchor then
                local root = self:GetRoot()
                local desired = self:GetAnchorControlCFrame(waitAnchor)
                if not root or not desired then self:SetPhase("character_missing", "character_missing", quest, nil)
                elseif (root.Position - desired.Position).Magnitude > 150 then
                    self:ClearHover(); self:SetPhase("searching_target", "searching_target", quest, nil)
                    local moved, moveReason = self:MoveTo(desired, "spawn:" .. tostring(quest.mob))
                    if not moved then self:SetPhase("movement_failed", moveReason or "movement_failed", quest, nil) end
                else
                    self:BeginHoverAt(waitAnchor, true)
                    self.State.orbitSeconds = self.State.orbitSeconds + 0.12
                    self:SetPhase("orbiting_spawn", "waiting_for_spawn", quest, nil)
                end
            else
                self:ClearHover(); self:SetPhase("target_not_found", "target_not_found", quest, nil)
            end
            return true
        end

        self:SetCombatAnchor(quest, center)
        local anchor = self.State.combatAnchor or center
        local target = cluster[1] and cluster[1].model or self:FindTarget(quest.mob)
        -- A player-selected orbit/star layout is useful while waiting at a
        -- spawn, but it is counterproductive in live combat: it makes the
        -- hover circle a fixed anchor while a Grand Devotee walks away. Combat
        -- always holds the stable vertical point directly above its anchor.
        local root = self:GetRoot(); local desired = self:GetAnchorControlCFrame(anchor, "above")
        if not target or not root or not desired then self:ClearHover(); self:SetPhase("character_missing", "character_missing", quest, target); return true end
        if (root.Position - desired.Position).Magnitude > 150 then
            self:ClearHover(); self:SetPhase("approaching_target", "approaching_target", quest, target)
            local moved, moveReason = self:MoveTo(desired, "cluster:" .. tostring(quest.mob))
            if not moved then self:SetPhase("movement_failed", moveReason or "movement_failed", quest, nil) end
            return true
        end
        self:BeginHoverAt(anchor, false, nil, nil, nil, "above")
        self:SetPhase("combat", "combat", quest, target)
        self:BringMobs(target, anchor)
        -- Attack owns its own exact cooldown pulse; Step remains responsible
        -- for target/quest safety and never starts a second concurrent sender.
        self:StartAttackPulse()
        return true
    end

    function Farm:Run(generation)
        -- `farmLevelEnabled` is the shared Farm master intent. Mission mode is
        -- consumed by SpecialQuests through its own coordinator owner, so the
        -- level worker must never remain alive after the profile changes.
        while State.farmLevelEnabled and State.farmAutomationMode ~= "missions" and self.State.generation == generation do
            local ok, errorMessage = pcall(function() self:Step() end)
            if not ok then self:SetPhase("error", tostring(errorMessage), nil, nil) end
            -- A requested-but-preempted Farm stays armed for automatic resume,
            -- but it need not wake at combat cadence while it owns no lease.
