    -- Per-stage bounds. A stage without a timeout can never become an infinite
    -- loop when an executor is finally released.
    SpecialQuests.StageLimits = {
        maxAttempts = 3,
        maxStageSeconds = 240,
        retryDelaySeconds = 3,
        -- A stage may route backwards (verify -> fight -> verify). The attempt
        -- limit resets on every advance, so transitions are what bound the whole
        -- chain: without this a two-stage ping-pong would run forever.
        maxTransitions = 24,
        -- How often one mutating call may be issued for a stage before the chain
        -- gives up. This is what stops a fruit hand-over from repeating.
        maxCallIssues = 2,
    }

    -- Stage budgets which differ from the generic per-stage limit. A long grind
    -- keeps its wall-clock bound but must not be treated as three failed retries;
    -- a discrete Remote call keeps the tight attempt limit.
    SpecialQuests.StageBudgetSeconds = {
        defeat_swan_pirates = 3600,
