    -- A capability is released by observation, not by a manual flag: the exact
    -- query for the mission must answer with one of the two shapes the source
    -- material documents. Capabilities stays available as a hard override.
    SpecialQuests.Validated = {}

    function SpecialQuests:GetContractCoverage()
        local missing = {}
        for _, jobId in ipairs(self.JobOrder) do
            local contracts = self.StageContracts[jobId] or {}
            for _, stage in ipairs(self.Stages[jobId] or {}) do
                if type(contracts[stage]) ~= "table" then missing[#missing + 1] = jobId .. "." .. stage end
            end
            for stage in pairs(contracts) do
                local covered = false
                for _, candidate in ipairs(self.Stages[jobId] or {}) do
                    if candidate == stage then covered = true break end
                end
                if not covered then missing[#missing + 1] = jobId .. "." .. stage .. "=orphan" end
            end
        end
        return missing
    end

    SpecialQuests.Runtime = {
        running = false,
        generation = 0,
        phase = "idle",
        detail = "",
        stage = "idle",
        blocker = nil,
        expectedTarget = nil,
        attempt = 0,
        stageStartedAt = 0,
        leaseWaitSince = nil,
        lastVerifiedAt = 0,
        lastTransitionAt = 0,
        checkpointReason = nil,
        paused = false,
        -- Action accounting. Transitions and issued calls are what bound a chain
        -- once its executors exist, so they are counted rather than inferred.
        transitions = 0,
        issuedCalls = 0,
        callIssues = {},
        lastCallResponse = nil,
        lastActionAt = 0,
        callLedger = {},
        combatTarget = nil,
        plateCursor = 1,
    }

    local function now()
        return os.clock()
    end

    local function copyPrimitive(value, depth)
        depth = depth or 0
        if depth > 4 then return nil end
        local kind = type(value)
        if kind == "string" or kind == "number" or kind == "boolean" then return value end
        if kind ~= "table" then return nil end
        local result = {}
        for key, item in pairs(value) do
            if type(key) == "string" or type(key) == "number" then
                local clean = copyPrimitive(item, depth + 1)
                if clean ~= nil then result[key] = clean end
            end
        end
        return result
    end

    local function selectedJob()
        local job = tostring(State.farmSpecialQuest or "access_second_sea")
        return SpecialQuests.Jobs[job] and job or "access_second_sea"
    end

    local function evidence()
        return Flow.Features and Flow.Features.QuestEvidence or nil
    end

    local function checkpoint()
        return Flow.Features and Flow.Features.ProgressCheckpoint or nil
    end

    local function coordinator()
        return Flow.Features and Flow.Features.FarmCoordinator or nil
    end

    local function farm()
        return Flow.Features and Flow.Features.Farm or nil
    end

    local function flag(progress, name)
        return type(progress) == "table" and type(progress.flags) == "table" and progress.flags[name] == true
    end

    local function progressOf(self, forceFresh)
        local source = evidence()
        if not source or type(source.GetMissionProgress) ~= "function" then
            return {known = false, reason = "evidence_unavailable"}
        end
        return source:GetMissionProgress(selectedJob(), forceFresh == true)
    end

    -- A missing quest Remote means the game itself is unreachable, which is the
    -- same situation the unvalidated capability state already reports. One
    -- vocabulary keeps the UI from inventing a second name for "not in game".
    local function unsupportedReason(progress)
        local reason = tostring((type(progress) == "table" and progress.reason) or "mission_evidence_unsupported")
        if reason == "quest_remote_unavailable" then return "capability_unvalidated" end
        return reason
    end

    local function readable(progress)
        return type(progress) == "table" and progress.known == true
    end

    local function objectivePresent(names)
        local source = evidence()
        if not source or type(source.GetKnownEnemy) ~= "function" then return nil, "evidence_unavailable" end
        for _, name in ipairs(names or {}) do
            local observed = source:GetKnownEnemy(name)
            if observed and observed.alive == true then return name end
        end
        return nil
    end

    local function anyFlag(progress, names)
        for _, name in ipairs(names or {}) do
            if flag(progress, name) then return true end
        end
        return false
    end

    -- Shared stage predicates. They only ever read the observations the evidence
    -- module already exposes, so a stage cannot pass on a wish.
    -- Either shape the sources document for a step counts: the boolean field the
    -- table answer carries, or the completion value the number answer carries.
    local function stageWhenAnyFlag(names, stage, otherwise)
        return function(self, ctx, progress)
            if not readable(progress) then return false, unsupportedReason(progress) end
            if anyFlag(progress, names) then return stage, "flag_reported" end
            if progress.done == true then return stage, "chain_reported_done" end
            return otherwise
        end
    end

    local function stageWhenObjectiveSpawned(names, stage)
        return function(self, ctx, progress)
            local present = objectivePresent(names)
            if present then return stage, "spawned:" .. tostring(present) end
            return nil, "target_not_spawned"
        end
    end

    local function stageWhenSea(sea, stage, waitingReason)
        return function(self, ctx, progress)
            local source = evidence()
            local current = source and source:GetSea() or nil
            if type(current) == "number" and current >= sea then return stage end
            return nil, waitingReason or ("sea_below_" .. tostring(sea))
        end
    end

    local function stageWhenTool(held, stage, missingStage)
        return function(self, ctx, progress)
            local source = evidence()
            local found = source and source:HasInventoryTool(held) or false
            if found then return stage end
            return missingStage or false, "key_not_in_inventory"
        end
    end

    function SpecialQuests:FailClosed(ctx, reason)
        local stage = (type(ctx) == "table" and ctx.stage) or self.Runtime.stage
        self:StopOwnedMotion(reason or "mission_blocked")
        self:SetPhase("blocked", tostring(reason), stage, tostring(reason))
        self:Disarm(reason or "mission_blocked")
        return false, tostring(reason)
    end

    function SpecialQuests:Finish(reason)
        self.Runtime.transitions = 0
        self.Runtime.callIssues = {}
        self:SetPhase("completed", tostring(reason or "mission_completed"), "completed", nil)
        self:Disarm(reason or "mission_completed")
        return false, tostring(reason or "mission_completed")
    end

    function SpecialQuests:AdvanceTo(ctx, nextStage, detail, target)
        local ok, result = self:AdvanceStage(nextStage, detail, target or self.Runtime.expectedTarget)
        if not ok then return self:FailClosed(ctx, tostring(result or "stage_not_in_plan")) end
        return true, tostring(result or nextStage), "advance"
    end

    -- Movement always goes through the shared travel executor under this Owner,
    -- which keeps water/wall protection and cancellation identical to Farm's.
    function SpecialQuests:TravelToLive(position, label)
        if not position then return false, "position_missing" end
        local teleport = Flow.Features and Flow.Features.Teleport
        if not teleport or type(teleport.TravelToPosition) ~= "function" then return false, "movement_unavailable" end
        local source = evidence()
        local distance = source and type(source.GetDistanceTo) == "function" and source:GetDistanceTo(position) or nil
        if distance and distance <= self.ArrivalDistance then return true, "arrived" end
        local moved, reason = teleport:TravelToPosition(position, self.Owner, label,
            Flow.Features.Portal, Flow.Features.WorldPortals)
        if moved == true then return true, "arrived" end
        return false, tostring(reason or "travel_pending")
    end

    function SpecialQuests:TargetPosition(model)
        if not model then return nil end
        local position
        pcall(function()
            if type(model.GetPivot) == "function" then
                local pivot = model:GetPivot()
                if pivot and pivot.Position then position = pivot.Position return end
            end
            if model.PrimaryPart and model.PrimaryPart.Position then position = model.PrimaryPart.Position return end
            if type(model.FindFirstChildOfClass) == "function" then
                local part = model:FindFirstChildOfClass("Part") or model:FindFirstChildOfClass("MeshPart")
                if part and part.Position then position = part.Position end
            end
        end)
        return position
    end

    function SpecialQuests:FindCombatTarget(names)
        local owner = farm()
        if not owner or type(owner.FindTarget) ~= "function" then return nil, "combat_primitive_unavailable" end
        for _, name in ipairs(names or {}) do
            local target = owner:FindTarget(name)
            if target then return target, name end
        end
        return nil, "target_absent"
    end

    -- Combat reuses Farm's own primitives and nothing else: hover is requested
    -- with this Owner so any other consumer sees the resource as taken, and the
    -- attack stream stays Farm's cooldown-limited one. The extractor's per-frame
    -- `repeat task.wait() until dead` loop is deliberately not ported; the stage
    -- budget in Step is what bounds the grind.
    function SpecialQuests:CombatStep(names, stage)
        local owner = farm()
        if not owner then return false, "combat_primitive_unavailable" end
        if State.farmAutoAttack ~= true then return false, "auto_attack_required" end
        local target, targetName = self:FindCombatTarget(names)
        if not target then
            if type(owner.EndExternalHover) == "function" then pcall(function() owner:EndExternalHover(self.Owner) end) end
            return false, "target_absent"
        end
        local position = self:TargetPosition(target)
        if not position then return false, "target_position_missing" end
        if type(owner.BeginExternalHover) == "function" then
            pcall(function()
                owner:BeginExternalHover(self.Owner, position, function()
                    return self.Runtime.running == true and self.Runtime.stage == stage
                end, self.CombatHoverHeight)
            end)
        end
        self.Runtime.combatTarget = targetName
        local attacked, reason = false, "attack_unavailable"
        if type(owner.Attack) == "function" then
            local ok, value, note = pcall(owner.Attack, owner, target)
            attacked = ok and value == true
            reason = tostring(note or value or "attack_refused")
        end
        return true, attacked and ("attacked:" .. tostring(targetName)) or ("attack_pending:" .. reason), "progress"
    end

    -- The only place a mutating quest call is issued. The key must exist in
    -- QuestCalls, the issue count is bounded per key, and the observation cache
    -- is invalidated so the next predicate reads the server's new answer.
    function SpecialQuests:RecordCall(key, name, arguments)
        local ledger = self.Runtime.callLedger
        local parts = {tostring(name)}
        for _, value in ipairs(type(arguments) == "table" and arguments or {}) do
            parts[#parts + 1] = tostring(value)
        end
        ledger[#ledger + 1] = {key = tostring(key), signature = table.concat(parts, ":"), at = now()}
        while #ledger > 8 do table.remove(ledger, 1) end
        return ledger[#ledger]
    end

    function SpecialQuests:GetIssuedCalls()
        local results = {}
        for _, entry in ipairs(self.Runtime.callLedger or {}) do results[#results + 1] = entry.signature end
        return results
    end

    function SpecialQuests:RunQuestCalls(keys, ctx)
        local source = evidence()
        if not source or type(source.InvokeQuest) ~= "function" then return false, "evidence_unavailable" end
        local list = keys or {}
        for index = 1, #list do
            local key = list[index]
            local spec = self.QuestCalls[key]
            if type(spec) ~= "table" then return false, "call_not_listed:" .. tostring(key) end
            local issues = self.Runtime.callIssues
            local issued = tonumber(issues[key]) or 0
            if issued >= (tonumber(self.StageLimits.maxCallIssues) or 2) then return false, "call_issue_limit" end
            local invoked, response = source:InvokeQuest(spec.name, spec.args)
            issues[key] = issued + 1
            self.Runtime.issuedCalls = (tonumber(self.Runtime.issuedCalls) or 0) + 1
            self.Runtime.lastCallResponse = type(response) == "table" and "table" or (response == nil and "nil" or tostring(response))
            self.Runtime.lastActionAt = now()
            self:RecordCall(key, spec.name, spec.args)
            if not invoked then return false, tostring(response) end
        end
        if type(source.InvalidateMissionProgress) == "function" then source:InvalidateMissionProgress(selectedJob()) end
        self:PublishCheckpoint("action:" .. tostring(type(ctx) == "table" and ctx.stage or self.Runtime.stage))
        return true, "invoked"
    end

    function SpecialQuests:GetEliteCandidates()
        local candidates, seen = {}, {}
        local function add(name)
            if type(name) == "string" and name ~= "" and not seen[name] then
                seen[name] = true
                candidates[#candidates + 1] = name
            end
        end
        local source = evidence()
        if source then
            for _, name in ipairs(source.EliteNames or {}) do add(name) end
            if type(source:GetEliteSnapshot()) == "table" then
                for _, name in ipairs((source:GetEliteSnapshot()).names or {}) do add(name) end
            end
        end
        return candidates
    end

    -- The assigned elite is taken from the quest label the game is displaying,
    -- never from a local guess about which target is "best".
    function SpecialQuests:ParseAssignedTarget()
        local source = evidence()
        if not source or type(source.QuestMentions) ~= "function" then return nil end
        for _, name in ipairs(self:GetEliteCandidates()) do
            local found = source:QuestMentions(name)
            if found then return name end
        end
        return nil
    end

    -- The extractors press the Colosseum plates with click-detector calls. Flow
    -- only walks onto them with its own travel primitive, one plate per step, so
    -- a stale or renamed plate can never be forced open.
    function SpecialQuests:NextPlateTarget()
        local source = evidence()
        if not source or type(source.GetBartiloPlatePositions) ~= "function" then return nil end
        local positions = source:GetBartiloPlatePositions()
        if type(positions) ~= "table" or #positions == 0 then return nil end
        local runtime = self.Runtime
        local index = math.max(1, math.floor(tonumber(runtime.plateCursor) or 1))
        if index > #positions then index = 1 end
        runtime.plateCursor = index + 1
        return positions[index]
    end

    local function allowListMatches(list, fruitName)
        if type(list) ~= "table" then return false end
        local name = tostring(fruitName or "")
        local base = name:gsub("%s+[Ff]ruit%s*$", "")
        for key, value in pairs(list) do
            for _, candidate in ipairs({key, value}) do
                if type(candidate) == "string" and candidate ~= "" then
                    local normalized = candidate:gsub("%s+[Ff]ruit%s*$", "")
                    if string.lower(normalized) == string.lower(base) or string.lower(normalized) == string.lower(name) then
                        return true
                    end
                end
            end
        end
        return false
    end

    -- Handing Trevor a fruit destroys the item, so it is the one step that can
    -- never run on the player's behalf unless their own policy picked the fruit
    -- or they confirmed this activation. There is no "any fruit" fallback.
    function SpecialQuests:PickTrevorFruit(source)
        source = source or evidence()
        if not source or type(source.GetFruitTools) ~= "function" then return nil, "evidence_unavailable" end
        local fruits = source:GetFruitTools()
        if type(fruits) ~= "table" or #fruits == 0 then return nil, "trevor_fruit_missing" end
        if tostring(State.farmTrevorFruitPolicy or "ask") == "allow_list" then
            for _, name in ipairs(fruits) do
                if allowListMatches(State.farmTrevorFruitAllowList, name) then return name, "allow_list" end
            end
            return nil, "trevor_fruit_not_allowed"
        end
        if State.farmTrevorConfirmed == true then return fruits[1], "confirmed_this_activation" end
        return nil, "trevor_confirmation_required"
    end

    -- Session-only: confirming must never persist into the next game session, so
    -- a fruit is not handed over on a later restart.
    function SpecialQuests:ConfirmTrevorFruit()
        State.farmTrevorConfirmed = true
        self.Runtime.blocker = nil
        if self:IsRequested() then
            local stage, reason = self.Runtime.stage, "trevor_confirmed"
            self:SetPhase("eligibility_check", reason, stage, nil)
            if not self.Runtime.running then
                local generation = self.Runtime.generation
                self.Runtime.running = true
                task.spawn(function() self:Run(generation) end)
            end
        end
        return true, "trevor_confirmed_for_this_activation"
    end

    function SpecialQuests:SetTrevorFruitPolicy(policy)
        policy = tostring(policy or "")
        if policy ~= "ask" and policy ~= "allow_list" then return false, "policy_unknown" end
        State.farmTrevorFruitPolicy = policy
        State.farmTrevorConfirmed = false
        if Flow.Config then Flow.Config:Save() end
        return true, policy
    end

    -- A stage predicate returns one of three things: a stage name (advance),
    -- `true` (the chain is finished), `false` plus a reason (stop and disarm so
    -- the player can fix it), or only a reason (keep working inside the budget).
    local function decideStage(ctx, predicate, progress)
        if type(predicate) ~= "function" then return nil, nil, "none" end
        local ok, nextStage, reason = pcall(predicate, SpecialQuests, ctx, progress)
        if not ok then return nil, "predicate_error:" .. tostring(nextStage), "stop" end
        if nextStage == true then return nil, tostring(reason or "mission_completed"), "finish" end
        if nextStage == false then return nil, tostring(reason or "objective_pending"), "stop" end
        if type(nextStage) == "string" and nextStage ~= "" then return nextStage, tostring(reason or "verified"), "advance" end
        return nil, tostring(nextStage or reason or "objective_pending"), "wait"
    end

    local function applyDecision(self, ctx, stage, reason, action)
        if action == "advance" then return self:AdvanceTo(ctx, stage, reason) end
        if action == "stop" then return self:FailClosed(ctx, reason) end
        if action == "finish" then return self:Finish(reason) end
        return nil
    end

    local function buildExecutor(spec)
        local kind = tostring(spec.kind or "decide")
        if kind == "terminal" then
            return function(self, ctx) return self:Finish(spec.reason or "mission_completed") end
        end
        if kind == "decide" then
            return function(self, ctx)
                local stage, reason, action = decideStage(ctx, spec.decide, progressOf(self))
                local handled, detail, mode = applyDecision(self, ctx, stage, reason, action)
                if handled ~= nil then return handled, detail, mode end
                return true, tostring(reason or "objective_pending"), "progress"
            end
        end
        if kind == "travel" then
            return function(self, ctx)
                local stage, reason, action = decideStage(ctx, spec.decide, progressOf(self))
                local handled, detail, mode = applyDecision(self, ctx, stage, reason, action)
                if handled ~= nil then return handled, detail, mode end
                local position = nil
                if type(spec.at) == "function" then
                    local ok, value = pcall(spec.at, self, evidence(), ctx)
                    position = ok and value or nil
                end
                if not position then
                    if spec.optional and spec.thenStage then return self:AdvanceTo(ctx, spec.thenStage, "target_not_observed") end
                    return self:FailClosed(ctx, spec.missing or "target_not_observed")
                end
                local moved, note = self:TravelToLive(position, spec.label or ctx.stage)
                if not moved then return true, tostring(note or "travel_pending"), "progress" end
                if spec.thenStage then return self:AdvanceTo(ctx, spec.thenStage, "arrived") end
                return true, "arrived", "progress"
            end
        end
        if kind == "combat" then
            return function(self, ctx)
                local stage, reason, action = decideStage(ctx, spec.decide, progressOf(self))
                local handled, detail, mode = applyDecision(self, ctx, stage, reason, action)
                if handled ~= nil then return handled, detail, mode end
                local names = spec.enemies
                if spec.targetFromRuntime then
                    -- The elite's name is only known once the game offered the
                    -- quest, so the target list comes from the parsed label.
                    local target = self.Runtime.expectedTarget
                    if type(target) ~= "string" or target == "" then
                        return true, "target_unparsed", "progress"
                    end
                    names = {target}
                end
                local engaged, note = self:CombatStep(names, ctx.stage)
                if engaged == false then
                    if note == "auto_attack_required" or note == "combat_primitive_unavailable" then
                        return self:FailClosed(ctx, tostring(note))
                    end
                    if note == "target_absent" and spec.thenStage then return self:AdvanceTo(ctx, spec.thenStage, "target_absent") end
                    return true, tostring(note or "combat_pending"), "progress"
                end
                return true, tostring(note or "engaged"), "progress"
            end
        end
        -- "act" is the only kind that can change game state. `entry` skips the
        -- call when the objective is already satisfied, `pre` enforces a local
        -- precondition (an equipped tool, a policy decision), and `decide`
        -- confirms the effect on a forced-fresh read before advancing.
        return function(self, ctx)
            local progress = progressOf(self)
            local source = evidence()
            local stage, reason, action = decideStage(ctx, spec.entry, progress)
            if action == "none" then
                stage, reason, action = decideStage(ctx, spec.decide, progress)
                if action == "advance" then return self:AdvanceTo(ctx, stage, "already_satisfied:" .. tostring(reason)) end
            elseif action == "advance" then
                return self:AdvanceTo(ctx, stage, "already_satisfied")
            elseif action == "stop" then
                return self:FailClosed(ctx, reason)
            end
            -- `near` mirrors the source's own shape: walk to the NPC first, and
            -- only then issue the call. An irreversible call (a hand-over) is
            -- never issued to a NPC this client cannot even see.
            if type(spec.near) == "string" and spec.near ~= "" then
                local source = evidence()
                local npc = source and type(source.FindNpc) == "function" and source:FindNpc(spec.near) or nil
                if not npc then
                    return true, "npc_not_replicated:" .. spec.near, "progress"
                end
                local distance = source.GetDistanceTo and source:GetDistanceTo(npc.position) or nil
                local radius = tonumber(spec.nearRadius) or 60
                if not distance then
                    return true, "distance_unavailable:" .. spec.near, "progress"
                end
                if distance > radius then
                    local moved, note = self:TravelToLive(npc.position, "mission:" .. spec.near)
                    if not moved then return true, tostring(note or "approach_pending"), "progress" end
                    return true, "arrived:" .. spec.near, "progress"
                end
            end
            if type(spec.pre) == "function" then
                local ok, ready, preReason, preAction = pcall(spec.pre, self, ctx, progress)
                if not ok then return self:FailClosed(ctx, "precondition_error") end
                if ready ~= true then
                    if preAction == "stop" then return self:FailClosed(ctx, tostring(preReason or "precondition_unmet")) end
                    return true, "precondition:" .. tostring(preReason or "unmet"), "progress"
                end
            end
            if spec.start then
                local owner = farm()
                local quest = self.QuestStarts[tostring(spec.start)]
                if not owner or type(owner.StartQuest) ~= "function" or type(quest) ~= "table" then
                    return self:FailClosed(ctx, "quest_start_unavailable")
                end
                local issues = self.Runtime.callIssues
                local key = "start:" .. tostring(spec.start)
                local issued = tonumber(issues[key]) or 0
                if issued >= (tonumber(self.StageLimits.maxCallIssues) or 2) then return self:FailClosed(ctx, "call_issue_limit") end
                issues[key] = issued + 1
                self.Runtime.issuedCalls = (tonumber(self.Runtime.issuedCalls) or 0) + 1
                local started, response = owner:StartQuest(quest)
                self:RecordCall(key, "StartQuest", {quest.name, quest.id})
                -- The shared cache must not still hold the pre-accept answer, or
                -- the verify stage below would route back and re-accept.
                if source and type(source.InvalidateMissionProgress) == "function" then
                    source:InvalidateMissionProgress(selectedJob())
                end
                self:PublishCheckpoint("action:" .. tostring(type(ctx) == "table" and ctx.stage or self.Runtime.stage))
                if started ~= true then return true, "start_failed:" .. tostring(response) end
                self.Runtime.lastCallResponse = type(response) == "table" and "table" or (response == nil and "nil" or tostring(response))
            else
                local invoked, callReason = self:RunQuestCalls(spec.calls, ctx)
                if not invoked then
                    if callReason == "call_issue_limit" then return self:FailClosed(ctx, tostring(callReason)) end
                    return true, "call_failed:" .. tostring(callReason)
                end
            end
            if type(spec.decide) == "function" then
                local afterStage, afterReason, afterAction = decideStage(ctx, spec.decide, progressOf(self, true))
                if afterAction == "advance" then return self:AdvanceTo(ctx, afterStage, "observed:" .. tostring(afterReason)) end
                if afterAction == "finish" then return self:Finish(afterReason) end
                if afterAction == "stop" then return self:FailClosed(ctx, afterReason) end
                return true, "awaiting_observation:" .. tostring(afterReason), "progress"
            end
            if spec.thenStage then return self:AdvanceTo(ctx, spec.thenStage, "invoked") end
            return true, "invoked", "progress"
        end
    end

    -- One contract per stage of every plan. Routing may jump forward inside the
    -- mission's own plan (a player who already holds the Key does not go fetch
    -- another), but AdvanceStage refuses any stage the plan does not list.
    SpecialQuests.StageContracts = {
        access_second_sea = {
            inspect_sea = {kind = "decide", decide = function(self, ctx)
                local eligibility = type(ctx) == "table" and ctx.eligibility or {}
                if tonumber(eligibility.sea) ~= 1 then return false, "requires_sea_1" end
                if (tonumber(eligibility.level) or 0) < 700 then return false, "level_below_700" end
                return "inspect_dressrosa_progress", "sea_and_level_confirmed"
            end},
            inspect_dressrosa_progress = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                if flag(progress, "iceBossDead") then return "request_second_sea", "boss_already_dead" end
                if progress.done == true then return "request_second_sea", "chain_cleared" end
                if flag(progress, "usedKey") then return "locate_ice_admiral", "gate_already_open" end
                if flag(progress, "talkedDetective") then return "unlock_gate", "key_already_given" end
                return "travel_detective", "quest_owed"
            end},
            travel_detective = {kind = "travel", label = "mission:detective", optional = true,
                at = function(self, source)
                    local npc = source and type(source.FindNpc) == "function" and source:FindNpc("Military Detective") or nil
                    return npc and npc.position or nil
                end,
                thenStage = "obtain_key"},
            obtain_key = {kind = "act", calls = {"second_sea_detective"}, thenStage = "verify_key_or_open_gate", near = "Military Detective",
                entry = function(self, ctx, progress)
                    local source = evidence()
                    if source and source:HasInventoryTool("Key") then return "verify_key_or_open_gate", "key_held" end
                    if flag(progress, "talkedDetective") then return "verify_key_or_open_gate", "detective_already_talked" end
                    return nil
                end},
            verify_key_or_open_gate = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                if source and source:HasInventoryTool("Key") then return "travel_frozen_gate", "key_held" end
                if flag(progress, "talkedDetective") then return nil, "key_not_in_inventory_yet" end
                return "travel_detective", "return_to_detective"
            end},
            travel_frozen_gate = {kind = "travel", label = "mission:frozen_gate",
                at = function(self, source) return source and source:GetObjectPosition({"Map", "Ice", "Door"}) or nil end,
                decide = function(self, ctx, progress)
                    local source = evidence()
                    if source and source:IsFrozenGateLocked() == false then return "locate_ice_admiral", "gate_already_open" end
                    return nil
                end,
                missing = "frozen_gate_not_observed", thenStage = "unlock_gate"},
            unlock_gate = {kind = "act", calls = {"second_sea_use_key"}, thenStage = "verify_ice_completion",
                entry = function(self, ctx, progress)
                    local source = evidence()
                    if source and source:IsFrozenGateLocked() == false then return "locate_ice_admiral", "gate_open" end
                    if flag(progress, "usedKey") then return "locate_ice_admiral", "key_already_used" end
                    return nil
                end,
                pre = function(self, ctx, progress)
                    local source = evidence()
                    if not source then return false, "evidence_unavailable", "stop" end
                    if not source:HasInventoryTool("Key") then return false, "key_not_in_inventory" end
                    local equipped, reason = source:EquipTool("Key")
                    if equipped ~= true then return false, tostring(reason or "key_not_equipped") end
                    return true
                end,
                decide = function(self, ctx, progress)
                    local source = evidence()
                    if source and source:IsFrozenGateLocked() == false then return "locate_ice_admiral", "gate_unlocked" end
                    if flag(progress, "usedKey") then return "locate_ice_admiral", "key_used" end
                    return nil, "gate_still_locked"
                end},
            locate_ice_admiral = {kind = "travel", label = "mission:ice_admiral",
                at = function(self, source) return source and source:GetObjectPosition({"Map", "Ice", "Door"}) or nil end,
                missing = "frozen_gate_not_observed", thenStage = "defeat_ice_admiral"},
            -- No blind "mob is not visible, so it must be dead" advance: a boss can
            -- be despawned, reloading or outside the streaming radius, and an open
            -- gate only proves the Key was spent. The stage ends on the two answers
            -- the sources themselves read for this boss.
            defeat_ice_admiral = {kind = "combat", enemies = {"Ice Admiral"},
                decide = function(self, ctx, progress)
                    if readable(progress) and (flag(progress, "iceBossDead") or progress.done == true) then
                        return "verify_ice_completion", "boss_dead"
                    end
                    if objectivePresent({"Ice Admiral"}) then return nil, "boss_alive" end
                    return nil, "boss_not_confirmed_dead"
                end},
            verify_ice_completion = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                if flag(progress, "iceBossDead") or progress.done == true then
                    return "travel_experienced_captain", "boss_confirmed_dead"
                end
                if objectivePresent({"Ice Admiral"}) then return "defeat_ice_admiral", "boss_still_alive" end
                return nil, "boss_kill_not_reported"
            end},
            travel_experienced_captain = {kind = "travel", label = "mission:experienced_captain", optional = true,
                at = function(self, source)
                    local npc = source and type(source.FindNpc) == "function" and source:FindNpc("Experienced Captain") or nil
                    return npc and npc.position or nil
                end,
                thenStage = "request_second_sea"},
            request_second_sea = {kind = "act", calls = {"second_sea_travel"}, thenStage = "verify_second_sea",
                decide = stageWhenSea(2, "verify_second_sea")},
            verify_second_sea = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                local sea = source and source:GetSea() or nil
                if type(sea) == "number" and sea >= 2 then return true, "second_sea_unlocked" end
                return "request_second_sea", "travel_not_confirmed"
            end},
            completed = {kind = "terminal", reason = "second_sea_unlocked"},
        },
        bartilo = {
            inspect_bartilo = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                local source = evidence()
                if progress.done == true or (source and source:HasInventoryTool("Warrior Helmet")) then
                    return "verify_bartilo_complete", "already_complete"
                end
                if flag(progress, "killedSpring") then return "verify_gladiators_released", "ack_pending" end
                if flag(progress, "platesPending") then return "travel_colosseum", "plates_phase" end
                if flag(progress, "jeremyPhase") then return "verify_jeremy_objective", "jeremy_phase" end
                if flag(progress, "banditsCleared") or flag(progress, "killedBandits") then return "recontact_bartilo", "bandits_cleared" end
                return "travel_bartilo", "quest_needed"
            end},
            travel_bartilo = {kind = "travel", label = "mission:bartilo", optional = true,
