                    local npc = source and type(source.FindNpc) == "function" and source:FindNpc("Bartilo") or nil
                    return npc and npc.position or nil
                end,
                thenStage = "accept_bartilo"},
            accept_bartilo = {kind = "act", start = "bartilo", thenStage = "verify_swan_quest",
