                end},
            verify_swan_quest = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                if source and source:QuestMentions("Swan Pirate") then return "defeat_swan_pirates", "quest_active" end
                if readable(progress) and anyFlag(progress, {"killedBandits", "banditsCleared"}) then return "recontact_bartilo", "bandits_cleared" end
                return "accept_bartilo", "quest_not_offered"
            end},
            defeat_swan_pirates = {kind = "combat", enemies = {"Swan Pirate"},
                decide = stageWhenAnyFlag({"killedBandits", "banditsCleared"}, "verify_pirates_complete")},
            verify_pirates_complete = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                if flag(progress, "killedBandits") or flag(progress, "banditsCleared") then return "recontact_bartilo", "bandits_cleared" end
                if flag(progress, "jeremyPhase") then return "verify_jeremy_objective", "jeremy_phase" end
                return "defeat_swan_pirates", "bandits_still_alive"
            end},
            recontact_bartilo = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                if source and source:QuestMentions("Jeremy") then return "locate_jeremy", "jeremy_offered" end
                if readable(progress) then
                    if flag(progress, "jeremyPhase") then return "locate_jeremy", "jeremy_phase" end
                    if flag(progress, "killedBandits") or flag(progress, "banditsCleared") then return nil, "jeremy_not_spawned_yet" end
                end
                return "defeat_swan_pirates", "bandits_not_cleared"
            end},
            verify_jeremy_objective = {kind = "decide", decide = function(self, ctx, progress)
                if readable(progress) and flag(progress, "killedSpring") then return "verify_gladiators_released", "ack_pending" end
                if readable(progress) and flag(progress, "platesPending") then return "travel_colosseum", "plates_phase" end
                if objectivePresent({"Jeremy"}) then return "locate_jeremy", "jeremy_present" end
                if readable(progress) and (flag(progress, "banditsCleared") or flag(progress, "killedBandits")) then
                    return "locate_jeremy", "awaiting_jeremy"
                end
                return "verify_pirates_complete", "jeremy_objective_missing"
            end},
            locate_jeremy = {kind = "decide", decide = stageWhenObjectiveSpawned({"Jeremy"}, "defeat_jeremy")},
            defeat_jeremy = {kind = "combat", enemies = {"Jeremy"},
                decide = stageWhenAnyFlag({"platesPending", "killedSpring"}, "verify_jeremy_complete")},
            verify_jeremy_complete = {kind = "decide", decide = function(self, ctx, progress)
                if objectivePresent({"Jeremy"}) then return "defeat_jeremy", "jeremy_alive" end
                if readable(progress) and (progress.done == true or flag(progress, "killedSpring")) then
                    return "verify_gladiators_released", "jeremy_reported_dead"
                end
                return "travel_colosseum", "plates_phase"
            end},
            travel_colosseum = {kind = "travel", label = "mission:colosseum",
                at = function(self, source) return source and source:GetObjectPosition({"Map", "Dressrosa", "BartiloPlates"}) or nil end,
                missing = "colosseum_not_observed", thenStage = "solve_colosseum_plates"},
            solve_colosseum_plates = {kind = "travel", label = "mission:bartilo_plate",
                at = function(self) return self:NextPlateTarget() end,
                missing = "plates_not_observed", thenStage = "verify_gladiators_released"},
            verify_gladiators_released = {kind = "act", calls = {"bartilo_ack_plates"}, thenStage = "verify_bartilo_complete",
                entry = function(self, ctx, progress)
                    if readable(progress) and progress.done == true then return "verify_bartilo_complete", "already_complete" end
                    local source = evidence()
                    if source and source:HasInventoryTool("Warrior Helmet") then return "verify_bartilo_complete", "helmet_held" end
                    -- The ack is only ever issued on the state the extractor also
                    -- acks for, and never twice.
                    if not (readable(progress) and (flag(progress, "killedSpring") or flag(progress, "platesPending"))) then
                        return "verify_bartilo_complete", "ack_not_required"
                    end
                    return nil
                end},
            verify_bartilo_complete = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                if source and source:HasInventoryTool("Warrior Helmet") then return true, "warrior_helmet_held" end
                if readable(progress) and progress.done == true then return true, "bartilo_complete" end
                if readable(progress) and (flag(progress, "killedSpring") or flag(progress, "platesPending")) then
                    return "verify_gladiators_released", "ack_pending"
                end
                return "verify_jeremy_complete", "bartilo_still_open"
            end},
        },
        access_third_sea = {
            inspect_sea_and_z_progress = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                return "ensure_bartilo_complete", "z_progress_read"
            end},
            ensure_bartilo_complete = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                if flag(progress, "bartiloComplete") then return "inspect_trevor_requirement", "bartilo_confirmed" end
                local source = evidence()
                if source and source:HasInventoryTool("Warrior Helmet") then return "inspect_trevor_requirement", "helmet_held" end
                return false, "bartilo_required"
            end},
            inspect_trevor_requirement = {kind = "decide", decide = function(self, ctx, progress)
