                    if not source or type(source.EquipTool) ~= "function" then return false, "evidence_unavailable", "stop" end
                    local equipped, reason = source:EquipTool(fruit)
                    if equipped ~= true then
                        -- Equipping is asynchronous on touch clients: retry once
