                        return false, tostring(reason or "fruit_not_equipped"), "stop"
                    end
                    return true, fruit
                end,
                decide = function(self, ctx, progress)
                    if readable(progress) and not flag(progress, "fruitOutstanding") then return "verify_flamingo_access", "fruit_accepted" end
                    return nil, "fruit_still_outstanding"
