            verify_don_swan = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                if flag(progress, "accessGranted") then return "travel_king_red_head", "access_granted" end
                if objectivePresent({"Don Swan"}) then return "defeat_don_swan", "don_swan_alive" end
                return "locate_don_swan", "access_not_granted"
