            travel_king_red_head = {kind = "travel", label = "mission:indra_island",
                at = function(self, source) return source and source:GetObjectPosition({"Map", "IndraIsland", "Part"}) or nil end,
                decide = function(self, ctx, progress)
                    if readable(progress) and flag(progress, "indraDead") then return "travel_mr_captain", "indra_already_dead" end
                    return nil
                end,
                missing = "indra_island_not_observed", thenStage = "start_indra_stage"},
            start_indra_stage = {kind = "act", calls = {"third_sea_begin_indra"}, thenStage = "locate_rip_indra",
                entry = function(self, ctx, progress)
                    if not readable(progress) then return false, unsupportedReason(progress) end
                    if flag(progress, "indraDead") then return "verify_indra_stage", "indra_already_dead" end
                    if flag(progress, "indraBegun") then return "locate_rip_indra", "stage_already_begun" end
                    return nil
                end,
                decide = function(self, ctx, progress)
                    if readable(progress) and flag(progress, "indraBegun") then return "locate_rip_indra", "stage_begun" end
                    return nil, "begin_not_observed_yet"
                end},
            locate_rip_indra = {kind = "decide", decide = stageWhenObjectiveSpawned({"rip_indra", "rip_indra True Form"}, "defeat_rip_indra")},
            defeat_rip_indra = {kind = "combat", enemies = {"rip_indra", "rip_indra True Form"},
                decide = stageWhenAnyFlag({"indraDead"}, "verify_indra_stage")},
            verify_indra_stage = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                if flag(progress, "indraDead") then return "travel_mr_captain", "indra_dead" end
                if objectivePresent({"rip_indra", "rip_indra True Form"}) then return "defeat_rip_indra", "indra_alive" end
                if flag(progress, "indraBegun") then return "locate_rip_indra", "waiting_for_respawn" end
                return "start_indra_stage", "stage_not_begun"
            end},
            travel_mr_captain = {kind = "travel", label = "mission:mr_captain", optional = true,
                at = function(self, source)
                    local npc = source and type(source.FindNpc) == "function" and source:FindNpc("Mr. Captain") or nil
                    return npc and npc.position or nil
                end,
                thenStage = "request_third_sea"},
            request_third_sea = {kind = "act", calls = {"third_sea_travel"}, thenStage = "verify_third_sea",
                decide = stageWhenSea(3, "verify_third_sea")},
            verify_third_sea = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                local sea = source and source:GetSea() or nil
                if type(sea) == "number" and sea >= 3 then return true, "third_sea_unlocked" end
                return "request_third_sea", "travel_not_confirmed"
            end},
            completed = {kind = "terminal", reason = "third_sea_unlocked"},
        },
        citizen = {
            inspect_citizen = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                if source and source:HasInventoryTool("Musketeer Hat") then return true, "citizen_reward_held" end
                if not readable(progress) then return false, unsupportedReason(progress) end
                if progress.done == true then return "verify_citizen_complete", "treasure_found" end
                if flag(progress, "killedBoss") then return "locate_musketeer_hat", "boss_dead" end
                if flag(progress, "killedBandits") then return "locate_captain_elephant", "bandits_cleared" end
                return "travel_citizen", "quest_needed"
            end},
            travel_citizen = {kind = "travel", label = "mission:citizen", optional = true,
                at = function(self, source)
                    local npc = source and type(source.FindNpc) == "function" and source:FindNpc("Citizen") or nil
                    return npc and npc.position or nil
                end,
                thenStage = "accept_citizen"},
            accept_citizen = {kind = "act", calls = {"citizen_accept"}, thenStage = "verify_forest_pirates_quest",
                entry = function(self, ctx, progress)
                    local source = evidence()
                    if source and source:QuestMentions("Forest Pirate") then return "defeat_forest_pirates", "quest_already_active" end
                    if readable(progress) and flag(progress, "killedBandits") then return "locate_captain_elephant", "bandits_cleared" end
                    return nil
                end},
            verify_forest_pirates_quest = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                if source and source:QuestMentions("Forest Pirate") then return "defeat_forest_pirates", "quest_active" end
                if readable(progress) and flag(progress, "killedBandits") then return "locate_captain_elephant", "bandits_cleared" end
                return "accept_citizen", "quest_not_offered"
            end},
            defeat_forest_pirates = {kind = "combat", enemies = {"Forest Pirate"},
                decide = stageWhenAnyFlag({"killedBandits"}, "verify_pirates_complete")},
            verify_pirates_complete = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                if flag(progress, "killedBandits") then return "locate_captain_elephant", "bandits_cleared" end
                return "defeat_forest_pirates", "bandits_still_alive"
            end},
            locate_captain_elephant = {kind = "decide", decide = function(self, ctx, progress)
                if readable(progress) and flag(progress, "killedBoss") then return "verify_elephant_complete", "boss_reported_dead" end
                if objectivePresent({"Captain Elephant"}) then return "defeat_captain_elephant", "elephant_present" end
                return "defeat_forest_pirates", "target_not_spawned"
            end},
            defeat_captain_elephant = {kind = "combat", enemies = {"Captain Elephant"},
                decide = stageWhenAnyFlag({"killedBoss"}, "verify_elephant_complete")},
            verify_elephant_complete = {kind = "act", calls = {"citizen_hand_in"}, thenStage = "locate_musketeer_hat",
                entry = function(self, ctx, progress)
                    if not readable(progress) then return false, unsupportedReason(progress) end
                    if flag(progress, "killedBoss") then return "locate_musketeer_hat", "boss_dead" end
                    if objectivePresent({"Captain Elephant"}) then return "defeat_captain_elephant", "boss_alive" end
                    return nil
                end,
                decide = function(self, ctx, progress)
                    if readable(progress) and flag(progress, "killedBoss") then return "locate_musketeer_hat", "boss_confirmed_dead" end
                    return nil, "boss_kill_not_reported"
                end},
            locate_musketeer_hat = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                if source and source:HasInventoryTool("Musketeer Hat") then return "verify_hat", "hat_held" end
                if readable(progress) and flag(progress, "foundTreasure") then return "recontact_citizen", "treasure_flagged" end
                -- Flow will not use the extractor's baked coordinates for the hat
                -- perch, so this waits for a live object instead of flying blind.
                return false, "hat_location_not_observed"
            end},
            acquire_musketeer_hat = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                if source and source:HasInventoryTool("Musketeer Hat") then return "verify_hat", "hat_held" end
                return false, "hat_pickup_not_observable"
            end},
            verify_hat = {kind = "decide", decide = stageWhenTool("Musketeer Hat", "recontact_citizen")},
            recontact_citizen = {kind = "act", calls = {"citizen_hand_in"}, thenStage = "verify_citizen_complete",
                entry = function(self, ctx, progress)
                    if readable(progress) and flag(progress, "foundTreasure") then return "verify_citizen_complete", "treasure_found" end
                    local source = evidence()
                    if source and source:HasInventoryTool("Musketeer Hat") then return nil, "hand_in_needed" end
                    return false, "hat_required_for_hand_in"
                end,
                decide = function(self, ctx, progress)
                    if readable(progress) and flag(progress, "foundTreasure") then return "verify_citizen_complete", "treasure_confirmed" end
                    return nil, "hand_in_not_confirmed"
                end},
            verify_citizen_complete = {kind = "decide", decide = function(self, ctx, progress)
                local source = evidence()
                if source and source:HasInventoryTool("Musketeer Hat") then return true, "citizen_reward_held" end
                if readable(progress) and progress.done == true then return true, "citizen_complete" end
                return "recontact_citizen", "citizen_still_open"
            end},
        },
        elite_hunter = {
            inspect_elite_snapshot = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                local assigned = self:ParseAssignedTarget()
                if assigned then
                    self.Runtime.expectedTarget = assigned
                    return "locate_assigned_elite", "quest_already_active"
                end
                local source = evidence()
                local elite = source and source:GetEliteSnapshot() or {active = false, names = {}}
                if type(elite.names) ~= "table" or #elite.names == 0 then return false, "no_elite_spawned" end
                return "travel_elite_hunter", "elite_available"
            end},
            travel_elite_hunter = {kind = "travel", label = "mission:elite_hunter_npc", optional = true,
                at = function(self, source)
                    local npc = source and type(source.FindNpc) == "function" and source:FindNpc("Elite Hunter") or nil
                    return npc and npc.position or nil
                end,
                thenStage = "request_eligible_quest"},
            request_eligible_quest = {kind = "act", calls = {"elite_accept"}, thenStage = "parse_assigned_target", near = "Elite Hunter",
                entry = function(self, ctx, progress)
                    local assigned = self:ParseAssignedTarget()
                    if assigned then return "parse_assigned_target", "quest_already_active" end
                    return nil
                end,
                decide = function(self, ctx, progress)
                    local assigned = self:ParseAssignedTarget()
                    if assigned then return "parse_assigned_target", "quest_offered" end
                    return nil, "quest_not_offered_yet"
                end},
            parse_assigned_target = {kind = "decide", decide = function(self, ctx)
                local assigned = self:ParseAssignedTarget()
                if assigned then
                    self.Runtime.expectedTarget = assigned
                    return "locate_assigned_elite", assigned
                end
                return "request_eligible_quest", "no_target_in_quest_label"
            end},
            locate_assigned_elite = {kind = "decide", decide = function(self, ctx, progress)
                local target = self.Runtime.expectedTarget or self:ParseAssignedTarget()
                if not target then return "parse_assigned_target", "target_lost" end
                local present = objectivePresent({target})
                if present then return "combat_assigned_elite", "elite_present" end
                return nil, "target_not_spawned"
            end},
            combat_assigned_elite = {kind = "combat", targetFromRuntime = true,
                decide = function(self, ctx, progress)
                    local target = self.Runtime.expectedTarget
                    if not target then return "parse_assigned_target", "target_lost" end
                    if objectivePresent({target}) then return nil, "elite_alive" end
                    local source = evidence()
                    if source and source:QuestMentions(target) then return nil, "quest_still_offered" end
                    return "verify_completion_or_cancellation", "quest_closed"
                end},
            verify_completion_or_cancellation = {kind = "decide", decide = function(self, ctx, progress)
                if not readable(progress) then return false, unsupportedReason(progress) end
                local target = self.Runtime.expectedTarget
                if not target then return false, "quest_not_observed" end
                if objectivePresent({target}) then return "combat_assigned_elite", "elite_alive" end
                local source = evidence()
                if source and source:QuestMentions(target) then return "locate_assigned_elite", "quest_still_offered" end
                return true, "elite_quest_closed"
            end},
            completed = {kind = "terminal", reason = "elite_hunter_completed"},
        },
    }

    do
        local executors = {}
        for jobId, contracts in pairs(SpecialQuests.StageContracts) do
            local byStage = {}
            for stage, spec in pairs(contracts) do byStage[stage] = buildExecutor(spec) end
            executors[jobId] = byStage
        end
        SpecialQuests.Executors = executors
    end

    function SpecialQuests:IsMissionMode()
        return State.farmAutomationMode == "missions"
    end

    function SpecialQuests:IsRequested()
        return State.farmLevelEnabled == true and self:IsMissionMode()
    end

    function SpecialQuests:GetJobs()
        local jobs = {}
        for _, id in ipairs(self.JobOrder) do
            local definition = self.Jobs[id]
            jobs[#jobs + 1] = {
                id = id,
                titleKey = definition.titleKey,
                requiredSea = definition.requiredSea,
                minimumLevel = definition.minimumLevel,
                enabled = self:HasCapability(id),
            }
        end
        return jobs
    end

    function SpecialQuests:GetSelectedJob()
        return selectedJob()
    end

    function SpecialQuests:HasCapability(jobId)
        local id = tostring(jobId or "")
        if self.Capabilities[id] == true then return true end
        if self.Capabilities[id] == false and self.AutoValidate == false then return false end
        return self.Validated[id] == true
    end

    -- Releasing a mission no longer waits for a manual capture: the mission's own
    -- query has to answer with one of the two shapes the source material
    -- documents. An unreadable answer keeps the chain off, which is the same
    -- fail-closed property, now re-checked every time the master is armed.
    SpecialQuests.AutoValidate = true

    function SpecialQuests:ValidateJob(jobId)
        jobId = tostring(jobId or selectedJob())
        if not self.Jobs[jobId] then return false, "mission_unknown" end
        if self.Capabilities[jobId] == true then return true, "manually_released" end
        if self.Capabilities[jobId] == false and self.AutoValidate == false then return false, "capability_unvalidated" end
        local progress = progressOf(self)
        if readable(progress) then
            self.Validated[jobId] = true
            return true, "response_validated"
        end
        self.Validated[jobId] = false
        return false, unsupportedReason(progress)
    end

    function SpecialQuests:GetStagePlan(jobId)
        return self.Stages[tostring(jobId or "")] or {}
    end

    function SpecialQuests:IsStageValid(jobId, stage)
        for _, candidate in ipairs(self:GetStagePlan(jobId)) do
            if candidate == tostring(stage or "") then return true end
        end
        return false
    end

    function SpecialQuests:GetStageProgress()
        local jobId = selectedJob()
        local plan = self:GetStagePlan(jobId)
        local current = tostring(self.Runtime.stage or "")
        for index, stage in ipairs(plan) do
            if stage == current then
                return {job = jobId, index = index, total = #plan, stage = stage}
            end
        end
        return {job = jobId, index = 0, total = #plan, stage = current ~= "" and current or "idle"}
    end

    -- A checkpoint is only a hint. The job must match, the stage must belong to
    -- that job's plan, and attempts must be bounded; otherwise resume from the
    -- first plan stage and let live evidence move it forward again.
    function SpecialQuests:ResolveResumeStage(saved)
        local jobId = selectedJob()
        if type(saved) ~= "table" then return "eligibility_check", nil end
        if tostring(saved.job or "") ~= jobId then return "eligibility_check", "checkpoint_job_changed" end
        local stage = tostring(saved.stage or "")
        if stage == "" or stage == "idle" then return "eligibility_check", nil end
        if not self:IsStageValid(jobId, stage) then return "eligibility_check", "checkpoint_stage_invalid" end
        local attempts = math.max(0, math.min(self.StageLimits.maxAttempts, math.floor(tonumber(saved.attempt) or 0)))
        return stage, attempts > 0 and "checkpoint_restored" or nil
    end

    function SpecialQuests:GetEligibility(jobId)
        jobId = tostring(jobId or selectedJob())
        local job = self.Jobs[jobId]
        if not job then return {status = "blocked", reason = "mission_unknown", job = jobId} end

        local reader = evidence()
        if not reader then return {status = "blocked", reason = "evidence_unavailable", job = jobId} end
        local sea = reader:GetSea()
        local level = reader:GetLevel()
        local characterReady = reader:IsCharacterReady()
        -- Validation is part of eligibility, not a separate switch: whoever asks
        -- (arm, resume, or the page refresh) gets the same answer, and an
        -- unreadable game response leaves the mission unvalidated everywhere.
        if not self:HasCapability(jobId) then self:ValidateJob(jobId) end
        local result = {
            status = "ready",
            reason = nil,
            job = jobId,
            sea = sea,
            level = level,
            minimumLevel = job.minimumLevel,
            requiredSea = job.requiredSea,
            characterReady = characterReady == true,
            capabilityReady = self:HasCapability(jobId),
        }

        if job.completeAtSea and type(sea) == "number" and sea >= job.completeAtSea then
            result.status = "completed"
            result.reason = "already_unlocked"
            return result
        end
        if not sea then
            result.status = "blocked"
            result.reason = "sea_unknown"
            return result
        end
        if sea ~= job.requiredSea then
            result.status = "blocked"
            result.reason = "requires_sea_" .. tostring(job.requiredSea)
            return result
        end
        if level < job.minimumLevel then
            result.status = "blocked"
            result.reason = "level_below_" .. tostring(job.minimumLevel)
            return result
        end
        if characterReady ~= true then
            result.status = "blocked"
            result.reason = "character_not_ready"
            return result
        end
        if not result.capabilityReady then
            result.status = "blocked"
            result.reason = "capability_unvalidated"
            return result
        end

        -- From here on the answer is only used for routing and for a completion
        -- the player is already holding; an unreadable response is reported by the
        -- first stage rather than by turning the whole profile off.
        local progress = reader:GetMissionProgress(jobId)
        result.progress = copyPrimitive(progress)
        if job.completionTool and reader:HasInventoryTool(job.completionTool) then
            result.status = "completed"
            result.reason = "reward_already_held"
            return result
        end
        if progress.known == true and progress.done == true and not job.completeAtSea then
            result.status = "completed"
            result.reason = "flags_report_completed"
            return result
        end
        return result
    end

    function SpecialQuests:GetCheckpoint(reason)
        local runtime = self.Runtime
        return {
            version = 1,
            job = selectedJob(),
            stage = tostring(runtime.stage or "idle"),
            status = runtime.running and "running" or (runtime.blocker and "blocked" or "idle"),
            attempt = math.max(0, math.floor(tonumber(runtime.attempt) or 0)),
            expectedTarget = runtime.expectedTarget and tostring(runtime.expectedTarget) or nil,
            lastVerifiedAt = tonumber(runtime.lastVerifiedAt) or 0,
            lastTransitionAt = tonumber(runtime.lastTransitionAt) or 0,
            blocker = runtime.blocker and tostring(runtime.blocker) or nil,
            reason = reason or runtime.checkpointReason or runtime.detail or nil,
        }
    end

    function SpecialQuests:PublishCheckpoint(reason)
        local writer = checkpoint()
        if not writer or type(writer.Publish) ~= "function" then return false, "checkpoint_unavailable" end
        return writer:Publish(self.Owner, self:GetCheckpoint(reason))
    end

    function SpecialQuests:SetPhase(phase, detail, stage, blocker)
        local runtime = self.Runtime
        runtime.phase = tostring(phase or "idle")
        runtime.detail = tostring(detail or "")
        runtime.stage = tostring(stage or runtime.phase)
        runtime.blocker = blocker and tostring(blocker) or nil
        runtime.lastTransitionAt = now()
        if runtime.running or runtime.blocker then self:PublishCheckpoint(runtime.detail) end
    end

    function SpecialQuests:SetSelectedJob(jobId)
        jobId = tostring(jobId or "")
        if not self.Jobs[jobId] then return false, "mission_unknown" end
        if selectedJob() == jobId then return true, jobId end

        if self.Runtime.running then self:SetEnabled(false, "mission_changed") end
        -- Progress read for the previous chain must not answer for this one.
        local source = evidence()
        if source and type(source.InvalidateMissionProgress) == "function" then source:InvalidateMissionProgress() end
        State.farmSpecialQuest = jobId
        State.farmAutomationMode = "missions"
        self.Runtime.attempt = 0
        self.Runtime.expectedTarget = nil
        self:SetPhase("idle", "mission_selected", "idle", nil)
        if Flow.Config then Flow.Config:Save() end
        return true, jobId
    end

    function SpecialQuests:ClearCheckpoint()
        local writer = checkpoint()
        if writer and type(writer.Clear) == "function" then writer:Clear(self.Owner, "cleared_by_player") end
        self.Runtime.attempt = 0
        self.Runtime.expectedTarget = nil
        self.Runtime.checkpointReason = nil
        if not self.Runtime.running then self:SetPhase("idle", "checkpoint_cleared", "idle", nil) end
        return true
    end

    function SpecialQuests:StopOwnedMotion(reason)
        local farm = Flow.Features and Flow.Features.Farm
        if farm and type(farm.EndExternalHover) == "function" then
            pcall(function() farm:EndExternalHover(self.Owner) end)
        end
        local teleport = Flow.Features and Flow.Features.Teleport
        if teleport and type(teleport.CancelTravel) == "function" then
            pcall(function() teleport:CancelTravel(self.Owner, reason or "mission_stopped") end)
        end
    end

    function SpecialQuests:CanYield()
        -- Current foundation never enters an atomic game-changing transition.
        -- Future stages must return false only around a bounded, already
        -- validated interaction and immediately publish before yielding.
        return true, "mission_safe_checkpoint"
    end

    function SpecialQuests:PauseForCoordinator(context)
        self:StopOwnedMotion("mission_preempted")
        self.Runtime.paused = true
        self.Runtime.running = false
        self.Runtime.checkpointReason = "preempted_by:" .. tostring(type(context) == "table" and context.requester or "coordinator")
        self:SetPhase("paused_preempted", self.Runtime.checkpointReason, self.Runtime.stage, nil)
        return true
    end

    function SpecialQuests:ResumeFromCoordinator(saved)
        if not self:IsRequested() then return false, "mission_not_requested" end
        local stage, resumeNote = self:ResolveResumeStage(saved)
        self.Runtime.paused = false
        self.Runtime.running = true
        self.Runtime.generation = self.Runtime.generation + 1
        self.Runtime.stageStartedAt = now()
        self:SetPhase("eligibility_check", resumeNote or "coordinator_resumed", stage, nil)
        local generation = self.Runtime.generation
        task.spawn(function() self:Run(generation) end)
        return true
    end

    -- Released executors call this after their own post-condition holds. Moving
    -- to an unlisted stage is refused, so a misread cannot invent progress.
    function SpecialQuests:AdvanceStage(nextStage, detail, expectedTarget)
        local jobId = selectedJob()
        if not self:IsStageValid(jobId, nextStage) then return false, "stage_not_in_plan" end
        local runtime = self.Runtime
        runtime.attempt = 0
        runtime.stageStartedAt = now()
        runtime.transitions = (tonumber(runtime.transitions) or 0) + 1
        runtime.expectedTarget = expectedTarget and tostring(expectedTarget) or nil
        if runtime.transitions > (tonumber(self.StageLimits.maxTransitions) or 24) then
            self:Disarm("transition_limit")
            return false, "transition_limit"
        end
        self:SetPhase(nextStage == "completed" and "completed" or "stage_active", detail or nextStage, nextStage, nil)
        return true, nextStage
    end

    function SpecialQuests:EnsureCoordinatorLease()
        local arbiter = coordinator()
        if not arbiter then return true end
        if arbiter:Owns(self.Owner, "movement") and arbiter:Owns(self.Owner, "combat") then return true end
        return arbiter:TryAcquire(self.Owner, {
            resources = {"movement", "combat"},
            priority = self.Priority,
            preemptible = true,
            context = {job = selectedJob(), stage = self.Runtime.stage or "idle"},
        })
    end

    function SpecialQuests:Step()
        local runtime = self.Runtime
        local jobId = selectedJob()
        local eligibility = self:GetEligibility(jobId)
        runtime.lastVerifiedAt = now()
        if eligibility.status == "completed" then
            self:SetPhase("completed", eligibility.reason, "completed", nil)
            self:Disarm(eligibility.reason)
            return false, eligibility.reason
        end
        if eligibility.status ~= "ready" then
            self:SetPhase("blocked", eligibility.reason, "eligibility_check", eligibility.reason)
            self:Disarm(eligibility.reason)
            return false, eligibility.reason
        end

        -- Normalize the entry point into the mission's own plan. Blocked states
        -- keep their diagnostic stage; a resumed job may already hold a valid
        -- later stage from its checkpoint.
        if not self:IsStageValid(jobId, runtime.stage) then
            local plan = self:GetStagePlan(jobId)
            runtime.stage = plan[1] or "inspect_progress"
            runtime.stageStartedAt = now()
            runtime.attempt = 0
        end

        -- A released transition must be an explicit function for this exact
        -- mission and stage. Absent one, the job stops with a diagnosable
        -- reason instead of guessing a game call.
        local executor = self.Executors[jobId] and self.Executors[jobId][tostring(runtime.stage or "")]
        if type(executor) ~= "function" then
            self:SetPhase("blocked", "executor_not_released", runtime.stage or "capability_gate", "executor_not_released")
            self:Disarm("executor_not_released")
            return false, "executor_not_released"
        end

        local budget = tonumber(self.StageBudgetSeconds[tostring(runtime.stage or "")]) or self.StageLimits.maxStageSeconds
        if runtime.stageStartedAt and (now() - runtime.stageStartedAt) > budget then
            self:SetPhase("blocked", "stage_timeout", runtime.stage, "stage_timeout")
            self:Disarm("stage_timeout")
            return false, "stage_timeout"
        end
        if (tonumber(runtime.attempt) or 0) >= self.StageLimits.maxAttempts then
            self:SetPhase("blocked", "attempt_limit", runtime.stage, "attempt_limit")
            self:Disarm("attempt_limit")
            return false, "attempt_limit"
        end

        local acquired, leaseOrReason = self:EnsureCoordinatorLease()
        if not acquired then
            -- Losing the lease is not a failed game action: a waiting chain must
            -- not consume its stage attempts, or a long Event Farm run would make
            -- the mission give up before it ever touched the world.
            runtime.leaseWaitSince = runtime.leaseWaitSince or now()
            self:SetPhase("waiting_lease", tostring(leaseOrReason), runtime.stage, "resource_busy")
            return true, "waiting_lease"
        end
        runtime.leaseWaitSince = nil

        runtime.attempt = (tonumber(runtime.attempt) or 0) + 1
        local ok, keepRunning, detail, mode = pcall(executor, self, {
            job = jobId,
            stage = tostring(runtime.stage or ""),
            eligibility = eligibility,
            evidence = evidence(),
            lease = coordinator() and coordinator():GetLease(self.Owner) or nil,
        })
        if ok and mode == "progress" then
            -- Waiting on the world (a boss still alive, a plate not reached yet,
            -- a quest flag not replicated) is not a failed retry, so it must not
            -- consume one of the three attempts a discrete game call gets. The
            -- stage's own time budget is what bounds this kind of waiting.
            runtime.attempt = math.max(0, (tonumber(runtime.attempt) or 1) - 1)
        end
        if not ok then
            self:SetPhase("error", tostring(keepRunning), runtime.stage, "executor_error")
            return true, "executor_error"
        end
        self.Runtime.checkpointReason = nil
        return keepRunning ~= false, detail
    end

    -- A terminal stage (completed, blocked, refused) must leave the shared Farm
    -- master disarmed: the player fixes the reported requirement and re-arms it
    -- deliberately instead of the job retrying forever in the background.
    function SpecialQuests:Disarm(reason)
        local runtime = self.Runtime
        runtime.running = false
        runtime.paused = false
        runtime.transitions = 0
        runtime.callIssues = {}
        runtime.checkpointReason = reason and tostring(reason) or runtime.checkpointReason
        State.farmLevelEnabled = false
        self:StopOwnedMotion(reason or "mission_finished")
        local arbiter = coordinator()
