    function SpecialQuests:GetSnapshot()
        local runtime = self.Runtime
        local eligibility = self:GetEligibility(selectedJob())
        local progress = self:GetStageProgress()
        return {
            enabled = self:IsRequested(),
            running = runtime.running == true,
            mode = State.farmAutomationMode == "missions" and "missions" or "level",
            job = selectedJob(),
            phase = runtime.phase or "idle",
            detail = runtime.detail or "",
            stage = runtime.stage or "idle",
            blocker = runtime.blocker,
            expectedTarget = runtime.expectedTarget,
            attempt = runtime.attempt or 0,
            waitingForLeaseSince = runtime.leaseWaitSince,
            stageIndex = progress.index,
