            CanYield = function(_, context) return SpecialQuests:CanYield(context) end,
            Pause = function(_, context) return SpecialQuests:PauseForCoordinator(context) end,
            Resume = function(_, saved) return SpecialQuests:ResumeFromCoordinator(saved) end,
