        runtime.holdDirection = flatDirection(passengerSeat.CFrame.LookVector) or Vector3.new(0, 0, -1)
        runtime.authorityStallSince = nil
        changed()
    end

    local function holdForBoarding(runtime, remote, passengerSeat, targetRoot)
