        local verticalDistance = math.abs(delta.Y)
        -- Let the invitee walk a little or line up with the seat. Reacquire
        -- only after a meaningful departure, not every minor movement.
        if horizontalDistance > BoatFriend.BoardingReleaseRange or verticalDistance > BoatFriend.BoardingReleaseVertical then
            runtime.phase = "approaching_friend"
            runtime.nearInviteSent = false
            runtime.holdLift, runtime.holdDirection = nil, nil
            runtime.heightMode = horizontalDistance >= BoatFriend.HorizontalReacquireRange and "high" or "matching"
            changed()
            return false, "reacquire"
        end
        local direction = runtime.holdDirection or flatDirection(passengerSeat.CFrame.LookVector) or Vector3.new(0, 0, -1)
        local lift = runtime.holdLift or clamp(tonumber(remote.State and remote.State.lift) or 0, 0, BoatFriend.RouteCruiseLift)
        return remote:SetExternalCommand(BoatFriend.OwnerKey, {
            direction = direction,
            speed = BoatFriend.BoardingHoldSpeed,
            lift = lift,
        })
    end

    local function beginWorker(generation)
