                notify("Barco TP", "Não foi possível transferir o controle nativo do barco.", "danger")
                return
            end

            runtime.phase = "approaching_friend"
            changed()
            notify("Barco TP", "Aproximando do jogador. Ele precisa entrar voluntariamente no assento de passageiro.", "info")

