                            return
                        end
                        if distance and distance <= BoatFriend.ReturnRange then
                            runtime.phase = "delivered"
                            changed()
                            notify("Barco TP", "Barco retornou próximo ao dono.", "success")
                            -- Boat TP has no manual panel to return to; release
                            -- the headless writer and restore the native boat state.
                            BoatFriend:Stop("delivered")
                            return
                        end
                    end
                end
                task.wait(0.08)
            end
        end)
    end

    function BoatFriend:Start(target)
        if self.Runtime.active then return false, "already_active" end
        if typeof(target) == "number" then target = Players:GetPlayerByUserId(target) end
        if not target or target == player or not target:IsA("Player") then return false, "select_friend_first" end
        local boat, pilot = ownedBoat()
        if not boat or not pilot then
            notify("Barco TP", "Você não possui um barco com assento de piloto disponível.", "danger")
            return false, "owned_boat_missing"
        end
        local passenger = freePassengerSeat(boat, pilot)
        if not passenger then
            notify("Barco TP", "Este barco não possui assento de passageiro livre.", "danger")
            return false, "no_passenger_seat"
        end
        local localHumanoid = humanoidOf(player)
        -- Monitor evidence: a direct empty-seat writer can update local fields
        -- while physical speed stays at zero. Use the already-proven native
        -- seated handoff instead. The owner chooses to sit; after its short
        -- normal prime, RemoteBoat releases that seat and no manual GUI opens.
        if pilot.Occupant ~= localHumanoid then
            notify("Barco TP", "Sente voluntariamente no assento de piloto para iniciar o handoff nativo do seu barco.", "info")
            return false, "sit_in_own_pilot_seat_first"
        end
        local ownerRoot = rootOf(player)
        if not ownerRoot then return false, "owner_character_missing" end
        -- Capture a fixed departure anchor while the owner is still seated.
        -- After normal handoff the owner's character is no longer a valid
        -- return target because it can move independently of the boat.
        local returnAnchor = ownerRoot.Position
        local farm = eventFarm()
        if not farm or type(farm.BeginExternalBoatAutonomy) ~= "function" then return false, "eventfarm_native_controller_missing" end
        -- Use the actual EventFarm native-autonomy renderer, not a RemoteBoat
        -- recreation of its fields. The lease is armed at this direct course
        -- before normal release and survives continuously afterwards.
        local initialRoot = rootOf(target)
        local initialDirection = initialRoot and flatDirection(initialRoot.Position - passenger.Position) or nil
        if not initialDirection then return false, "target_character_missing" end
        local ok, controllerOrReason = farm:BeginExternalBoatAutonomy(self.OwnerKey, {
            direction = initialDirection,
            speed = self.NativeCarrierSpeed,
            lift = 200,
            liftRate = 220,
        })
        if not ok then
            notify("Barco TP", "Não foi possível armar o controlador nativo: " .. tostring(controllerOrReason) .. ".", "danger")
            return false, controllerOrReason
        end
        local runtime = self.Runtime
        local remote = controllerOrReason
        runtime.controller = remote
        runtime.active, runtime.reason = true, nil
        runtime.target, runtime.boat, runtime.pilotSeat, runtime.passengerSeat = target, boat, pilot, passenger
        runtime.returnAnchor = returnAnchor
        runtime.phase, runtime.nearInviteSent, runtime.heightMode = "arming_boat", false, "high"
        runtime.horizontalAlignedAt, runtime.verticalTarget, runtime.verticalTargetAt = nil, self.RouteCruiseLift, os.clock()
        runtime.generation = runtime.generation + 1
        -- BeginExternal has deliberately started the seated native prime, but
        -- it is not command-ready until that handoff has really completed and
        -- the voluntary pilot seat has been released. Sending the first route
        -- here used to call SetExternalCommand while dismountReady was false,
        -- producing "remote_not_ready" and immediately aborting every route.
        -- beginWorker waits for IsExternalReady and sends its first command on
        -- the very first ready tick, preserving a single horizontal/lift start
        -- without racing the native transfer.
        changed()
        beginWorker(runtime.generation)
        return true
    end

    function BoatFriend:Shutdown()
        self:Stop("hub_closed")
    end

    Flow.Features.BoatFriend = BoatFriend
end)(Flow)
Flow.Performance.modules['features/travel/boat_friend.lua'] = math.floor((os.clock() - __flow_module_started) * 1000 + 0.5) / 1000
end

