    EventFarm.TerrorSharkBoatAutonomySpeed = 300
    EventFarm.TerrorSharkBoatAutonomySteer = math.rad(26)
    EventFarm.BoatSafeDistance = 500
    EventFarm.BoatAwayMaximumDistance = 2600
    EventFarm.BoatCompassClearDanger = 1
    EventFarm.BoatFarReplacementDistance = 2600
    EventFarm.BoatAwayMinimumTravel = 650
    EventFarm.BoatAwayTimeout = 8
    -- Raid boats use the same relative-lift scale as Boat Local → Float:
    -- 0–500 studs above the native vertical support. The event response is
