    EventFarm.RaidBoatDetectionDistance = 520
    EventFarm.RaidBoatLiftHeight = 400
    EventFarm.RaidBoatLiftRiseRate = 500
    EventFarm.RaidBoatLiftReturnRate = 500
    EventFarm.RaidBoatClearSeconds = 0.75
    -- If a non-selected sea mob knocks the player out during cruise, return to
    -- the current owned seat and resume the saved native heading. This never
    -- treats a temporary dismount as boat loss or gives up after one attempt.
    EventFarm.CruiseSeatRecoveryHorizontalTolerance = 24
    EventFarm.CruiseSeatRecoveryVerticalTolerance = 40
    EventFarm.CruiseSeatRecoveryAttachSeconds = 1.25
    EventFarm.CruiseSeatRecoveryRetrySeconds = 0.45
    EventFarm.TerrorSharkCloseDodgeRange = 170
    EventFarm.SupportedEvents = {
        {id = "terror_shark", name = "Terror Shark"},
        {id = "sea_beast", name = "Sea Beast"},
        {id = "fish_boat", name = "Fish Boat"},
        {id = "pirate_brigade", name = "Pirate Brigade"},
        {id = "pirate_grand_brigade", name = "Pirate Grand Brigade"},
        {id = "pirate_basic", name = "Pirate Basic"},
    }
    -- Confirmed in the previous Tiki explorations: this is the WEST dealer,
    -- facing the endless/open sea — not the east dock toward other islands.
    EventFarm.VerifiedTikiWestDealer = Vector3.new(-16928.927734375, 7.7660064697265625, 434.6199951171875)
    EventFarm.TikiOpenSeaDirection = Vector3.new(-0.9952259659767151, 0, 0.09759844839572906)
    EventFarm.Runtime = {
        active = false,
        -- event_farm | frozen_dimension_search | idle. Both live modes retain
        -- the same exclusive native boat lease; only the former can acquire
        -- sea-mob opportunities or invoke combat.
        mode = "idle",
        generation = 0,
        phase = "idle",
        reason = nil,
        boat = nil,
        seat = nil,
        movement = nil,
        original = nil,
        baseBodyPosition = nil,
        lift = 0,
        targetLift = 0,
        liftRate = 0,
        direction = nil,
        -- `speed` is the native Movement.Velocity command. Live Tiki testing
        -- confirmed that positive throttle follows the requested physical
        -- direction; the old negative sign sent the boat into the island sea.
        speed = 0,
        cruiseDirection = nil,
        lastPosition = nil,
        -- Set by the native writer when the owned hull/forces disappear. This
        -- is handled by the Farm worker, not from RenderStep itself.
        boatLostReason = nil,
        -- v1.6.6: a hull can vanish after combat has truly started. Preserve
        -- the player/target duel; reset for a replacement only after the target
        -- reaches its terminal defeated state.
        deferBoatLossUntilTargetDefeated = false,
        combatBoatLossReason = nil,
        resettingAfterBoatLoss = false,
        forceFreshBoat = false,
        -- A respawn/return to Tiki must never reclaim a prior hull. This is
        -- set only by live recovery detection and cleared after a new BuyBoat
        -- instance is confirmed.
        tikiReturnNeedsFreshBoat = false,
        tikiReturnReason = nil,
        boatCharacter = nil,
        tikiSeatRecoveryAttempts = 0,
        stalledFor = 0,
        preStallLift = nil,
        stallBoost = 0,
        -- Peak altitude is held after a real obstacle clears. It prevents one
        -- good frame from sending the hull straight down into the same island.
        obstructionHold = {untilAt = 0, lift = nil, source = nil},
        -- Kept independently from seat visuals. A recovery may occur once per
        -- hull; repeated lack of physical response retires that hull instead
        -- of endlessly lifting a controller the server no longer accepts.
        nativeAuthority = {armedAt = 0, lostSince = nil, repairAttempted = false, lastPhysicalSpeed = 0, lastCommandSpeed = 0, lastReason = nil},
        marker = {mode = "none", lastGood = nil, seenFor = 0, missingFor = 0},
        -- Dynamic Mirage/Prehistoric markers can be streamed in front of a
        -- cruising boat. This state holds the 500-stud clearance while such an
        -- island remains ahead, without replacing obstacle/stall recovery.
        islandClearance = {active = false, name = nil, lastSeenAt = 0, distance = nil},
        islandScan = {nextAt = 0, candidates = {}},
        target = nil,
        -- Stage-level checkpoint for the active Farm generation. It keeps the
        -- intent/target separate from transient seat and boat references, so
        -- activation can claim an already-live selected event before deciding
        -- whether a boat is actually needed for that encounter.
        progress = {stage = "idle", reason = nil, changedAt = 0, checkpoint = nil},
        -- A target type is locked from discovery until its safe return is
        -- complete. This serializes two simultaneous selected spawns: the
        -- second mob waits, never starts a parallel combat worker.
        targetKind = nil,
        targetBackoff = {},
        -- One saved cruise command survives an involuntary dismount. It is
        -- intentionally not used during normal Sea Beast dismount/combat.
        unseatedCruiseDrive = nil,
        seatRecovery = {attempts = 0, startedAt = nil, lastReason = nil},
        boatSafeTarget = nil,
        boatSafeAt = 0,
        boatAwayActive = false,
        awayProgressCheck = nil,
        boatAwayFallbackTarget = nil,
        -- Raid boats temporarily own only vertical clearance. The saved
        -- target lift is restored once their range is continuously clear.
        raidLift = {active = false, returning = false, restoreTargetLift = nil, resumePhase = nil, name = nil, distance = nil, clearSince = nil, detectedAt = nil},
        raidConnections = {},
        raidSpawnCandidate = nil,
        emergencyUntil = 0,
        vortexSignal = nil,
        evadeActive = false,
        combatOffset = nil,
        lastStopReason = nil,
        lastFailureReason = nil,
        journal = {},
        journalLimit = 700,
        transit = {active = false, collisions = {}, thrust = nil, lastSampleAt = 0, samplePosition = nil, stuckFor = 0, recoveries = 0, avoidUntil = 0, avoidDirection = nil, lastSeatFixAt = 0, lastObstacleAt = 0}, 
        vortexConnections = {},
        seaBeastConnections = {},
        seaBeastBeamSignal = nil,
        seaBeastEvadeActive = false,
        seaBeastCombatReady = false,
        -- Per-model box tops are retained briefly only if a replicated box is
        -- momentarily missing. Weak keys ensure despawned Sea Beasts are free.
        seaBeastSurfaceCache = setmetatable({}, {__mode = "k"}),
        -- Track scans are a fallback when AnimationPlayed was emitted just
        -- before its listener attached. Weak keys never retain old tracks.
        seaBeastPreBeamTracks = setmetatable({}, {__mode = "k"}),
        nextSeaBeastPreBeamScan = 0,
        seaBeastKillWitness = nil,
        seaBeastAltitudeViolation = nil,
        seaBeastObservation = {attempts = 0, activated = 0, skippedActive = 0, skippedNoDodges = 0, skippedUnavailable = 0, lastAt = nil, lastKey = nil},
        seaBeastSkill = {lastTry = {}, cycles = 0, casts = 0, confirmed = 0, skippedCooldown = 0, skippedDisabled = 0, lastRoute = nil},
        -- Aim is a temporary Moveset Mouse lease for Sea Beast skills only. It
        -- is cleared on stop, evade, target loss or timeout and owns no camera.
        seaBeastSkillAim = {attempts = 0, applied = 0, moduleReads = 0, nativeWrites = 0, mobilityBypassed = 0, unavailable = 0, lastRoute = nil, lastPoint = nil, lastMobilityRule = nil},
        -- This is a bounded in-memory lease. `finalized` distinguishes an
        -- intentional end from an observed native-controller reset, so the
        -- writer can restore the latter but never restart after combat ends.
        seaBeastBoatAutonomy = {active = false, finalized = true, target = nil, recoveries = 0, lastRecoveryAt = 0},
        -- Terror Shark uses the same bounded native lease but a larger safety
        -- radius; it replaces the old static boat-away/repark flow.
        terrorSharkBoatAutonomy = {active = false, finalized = true, target = nil, recoveries = 0, lastRecoveryAt = 0},
        -- Raid boats use the same native lease pattern as Terror Shark, but it
        -- is unconditional once a checked raid target is claimed.
        raidBoatAutonomy = {active = false, finalized = true, target = nil, kind = nil, recoveries = 0, lastRecoveryAt = 0},
        raidBoatSkill = {lastTry = {}, cycles = 0, casts = 0, confirmed = 0, skippedCooldown = 0, skippedDisabled = 0, lastRoute = nil},
        raidBoatSkillAim = {attempts = 0, applied = 0, moduleReads = 0, nativeWrites = 0, mobilityBypassed = 0, unavailable = 0, lastRoute = nil, lastPoint = nil, lastMobilityRule = nil},
        controlConnection = nil,
        -- Owner-scoped direct-route lease. It uses this exact EventFarm native
        -- renderer/hand-off lifecycle, but supplies a straight course instead
        -- of a Sea Beast/Terror Shark orbit. It never starts Farm combat.
        externalBoatLease = nil,
        nativeReady = false,
        vortexLift = nil,
        lastVortexObservation = nil,
        lastNotice = {},
        startedAt = 0,
        statusChangedAt = 0,
    }

    local function now()
        return os.clock()
    end

    local function targetSelections()
        if type(State.eventFarmTargets) ~= "table" then State.eventFarmTargets = {} end
        -- New targets are always opt-in. Existing profiles retain their prior
        -- choices while every newly introduced raid type starts unchecked.
        for _, definition in ipairs(EventFarm.SupportedEvents) do
            if State.eventFarmTargets[definition.id] == nil then State.eventFarmTargets[definition.id] = false end
        end
        return State.eventFarmTargets
    end

    local function validTargetId(id)
        for _, definition in ipairs(EventFarm.SupportedEvents) do
            if definition.id == id then return true end
        end
        return false
    end

    local function isTargetSelected(id)
        return validTargetId(id) and targetSelections()[id] == true
    end

    local function selectedTargetCount()
        local selected, count = targetSelections(), 0
        for _, definition in ipairs(EventFarm.SupportedEvents) do
            if selected[definition.id] == true then count = count + 1 end
        end
        return count
    end

    local function isTargetLocked(id)
        return EventFarm.Runtime.targetKind == id
    end

    -- A selection may change while a player is travelling or fighting. The
    -- current lock prevents a new selection from rerouting that combat, while
    -- this guard lets an unselected current mob exit through its normal safe
    -- cleanup path before the other selected mob is considered.
    local function canContinueTarget(id)
        return isTargetSelected(id) and isTargetLocked(id)
    end

    local function lower(value)
        return string.lower(tostring(value or ""))
    end

    local function safeGet(object, property)
        local ok, value = pcall(function() return object and object[property] end)
        return ok and value or nil
    end

    local function rootPart()
        local character = player and player.Character
        return character and character:FindFirstChild("HumanoidRootPart") or nil
    end

    local function humanoid()
        local character = player and player.Character
        return character and character:FindFirstChildOfClass("Humanoid") or nil
    end

    local function isAlive()
        local hum = humanoid()
        return hum and hum.Health > 0
    end

    -- Plain-number snapshots keep diagnostic journal entries JSON-exportable.
    -- They intentionally report client-observed state only; no field is
    -- labelled as a server position or server velocity.
    local function vectorSnapshot(value)
        if not value then return nil end
        return {x = value.X, y = value.Y, z = value.Z}
    end

    local function humanoidStateName(h)
        local state = h and h:GetState()
        return state and state.Name or nil
    end

    local function positionOf(object)
        if not object then return nil end
        local ok, pivot = pcall(function() return object:GetPivot() end)
        if ok and pivot then return pivot.Position end
        local position = safeGet(object, "Position")
        return typeof(position) == "Vector3" and position or nil
    end

    local function notify(title, message, kind, throttleKey, seconds)
        local runtime = EventFarm.Runtime
        local key = throttleKey or title
        local at = now()
        if runtime.lastNotice[key] and at - runtime.lastNotice[key] < (seconds or 2) then return end
        runtime.lastNotice[key] = at
        Flow:Notify({title = tostring(title), message = tostring(message), type = kind or "info", duration = 4})
    end

    local function journal(kind, fields)
        local runtime = EventFarm.Runtime
        local row = {t = now(), kind = kind, fields = fields or {}}
        table.insert(runtime.journal, row)
        if #runtime.journal > (runtime.journalLimit or 700) then table.remove(runtime.journal, 1) end
    end

    local function setPhase(phase, reason)
        local runtime = EventFarm.Runtime
        runtime.phase = phase
        runtime.reason = reason
        runtime.statusChangedAt = now()
        local progress = runtime.progress
        if progress then
            progress.stage = phase
            progress.reason = reason
            progress.changedAt = runtime.statusChangedAt
        end
        journal("phase", {phase = phase, reason = reason})
        local checkpoint = Flow.Features and Flow.Features.ProgressCheckpoint
        if checkpoint and checkpoint.Publish then
            local target = runtime.target
            local targetPosition = positionOf(target)
            local activeCheckpoint = progress and progress.checkpoint or nil
            pcall(function()
                checkpoint:Publish("event_farm", {
                    stage = phase,
                    reason = reason,
                    target = target and {
                        kind = runtime.targetKind,
                        name = target.Name,
                        position = vectorSnapshot(targetPosition),
                    } or (activeCheckpoint and {
                        kind = activeCheckpoint.kind,
                        name = activeCheckpoint.targetName,
                        position = activeCheckpoint.target and vectorSnapshot(positionOf(activeCheckpoint.target)) or nil,
                    }) or nil,
                    boat = {
                        selectedName = State.eventFarmBoat,
                        mode = runtime.mode == "frozen_dimension_search" and runtime.mode
                            or (activeCheckpoint and activeCheckpoint.mode) or runtime.mode,
                    }, 
                })
            end)
        end
        Flow:Log("Sea Farm | " .. tostring(phase) .. (reason and (" | " .. tostring(reason)) or ""))
    end

    -- Event Farm is a single-owner sequence. A previous Hub direct route may
    -- otherwise keep Teleport.ActiveTravel occupied for minutes (especially a
    -- distant interrupted route), making the Sea Beast handoff return
    -- `travel_busy` before combat is ever entered. Take over only when this
    -- Farm itself is starting/entering its combat handoff; this uses the
    -- existing Hub cancellation and never touches game movement/remotes.
    local function releaseEventFarmTravel(stage)
        local teleport = Flow.Features and Flow.Features.Teleport
        local ticket = teleport and teleport.ActiveTravel
        if not ticket or ticket.finished or ticket.cancelled then return true, "no_active_travel" end
        local owner, startedAt, id = ticket.owner, ticket.startedAt, ticket.id
        local cancelled = false
        if type(teleport.CancelTravel) == "function" then
            local ok, result = pcall(function()
                return teleport:CancelTravel(nil, "sea_event_takeover_" .. tostring(stage or "unknown"))
            end)
            cancelled = ok and result == true
        end
        task.wait()
        local remaining = teleport.ActiveTravel
        local released = not remaining or remaining.finished or remaining.cancelled
        journal("sea_event_travel_takeover", {
            stage = tostring(stage or "unknown"), owner = tostring(owner or "unknown"),
            ticketId = id, startedAt = startedAt, cancelled = cancelled, released = released,
            remainingOwner = remaining and tostring(remaining.owner or "unknown") or nil,
        })
        return released, released and "released" or "travel_still_active"
    end

    local function ownedBoatByName(name)
        local boats = Workspace and Workspace:FindFirstChild("Boats")
        if not boats then return nil end
        for _, boat in ipairs(boats:GetChildren()) do
            local owner = boat:FindFirstChild("Owner")
            if boat.Name == name and owner and safeGet(owner, "Value") == player then
                return boat
            end
        end
        return nil
    end

    local function rootSeat(boat)
        if not boat then return nil end
        local direct = boat:FindFirstChild("VehicleSeat")
        if direct and direct:IsA("VehicleSeat") then return direct end
        for _, child in ipairs(boat:GetDescendants()) do
            if child:IsA("VehicleSeat") and child.Name == "VehicleSeat" then return child end
        end
        return nil
    end

    local function localOccupies(seat)
        local occupant = seat and safeGet(seat, "Occupant")
        return occupant and occupant.Parent == player.Character
    end

    local function otherPlayerDrives(seat)
        local occupant = seat and safeGet(seat, "Occupant")
        return occupant and occupant.Parent ~= player.Character
    end

    local function getShipMovement(boat)
        local global = ReplicatedStorage and ReplicatedStorage:FindFirstChild("Global")
        if not global then return nil end
        local ok, api = pcall(require, global)
        if not ok or type(api) ~= "table" then return nil end
        local ship
        if type(api.getShipFromBoat) == "function" then
            local shipOk, value = pcall(api.getShipFromBoat, boat)
            if shipOk then ship = value end
        end
        if not ship and type(api.getLocalShipFromPlayer) == "function" then
            local shipOk, value = pcall(api.getLocalShipFromPlayer, player)
            if shipOk then ship = value end
        end
        return ship and ship.Movement or nil
    end

    local function getBoatInfoList()
        local module = ReplicatedStorage and ReplicatedStorage:FindFirstChild("Modules")
        local boatInfo = module and module:FindFirstChild("BoatInfo")
        if not boatInfo then return {} end
        local ok, definition = pcall(require, boatInfo)
        local list = ok and type(definition) == "table" and definition.List or nil
        if type(list) ~= "table" then return {} end
        local output = {}
        for name, info in pairs(list) do
            if type(name) == "string" and type(info) == "table" then
                table.insert(output, {
                    name = name,
                    display = tostring(info.DisplayName or info.Name or name),
                    cost = tonumber(info.Cost),
                    unlocked = info.Unlocked ~= false and info.Locked ~= true,
                })
            end
        end
        table.sort(output, function(a, b) return a.display < b.display end)
        return output
    end

    function EventFarm:GetBoats()
        return getBoatInfoList()
    end

    function EventFarm:GetSupportedEvents()
        local copy = {}
        for _, definition in ipairs(self.SupportedEvents) do
            table.insert(copy, {id = definition.id, name = definition.name, selected = isTargetSelected(definition.id)})
        end
        return copy
    end

    function EventFarm:IsTargetSelected(id)
        return isTargetSelected(id)
    end

    function EventFarm:GetSelectedEvents()
        local selected = {}
        for _, definition in ipairs(self.SupportedEvents) do
            if isTargetSelected(definition.id) then table.insert(selected, definition.id) end
        end
        return selected
    end

    function EventFarm:GetSnapshot()
        local runtime = self.Runtime
        local seat = runtime.seat
        local boat = runtime.boat
        local physical = seat and seat.AssemblyLinearVelocity or nil
        return {
            enabled = runtime.active,
            mode = runtime.mode or "idle",
            frozenDimensionSearchEnabled = State.frozenDimensionSearchEnabled == true,
            frozenDimension = runtime.frozenDimension and runtime.frozenDimension.instance and runtime.frozenDimension.instance.Parent and {
                name = runtime.frozenDimension.instance.Name,
                distance = runtime.frozenDimension.distance,
                position = vectorSnapshot(runtime.frozenDimension.position),
            } or nil,
            phase = runtime.phase,
            reason = runtime.reason,
            boat = boat and boat.Name or nil,
            selectedBoat = State.eventFarmBoat,
            selectedEvents = self:GetSelectedEvents(),
            targetKind = runtime.targetKind,
            vortexEvade = State.eventFarmVortexEvade == true,
            seaBeastBeamDodge = State.eventFarmSeaBeastBeamDodge == true,
            seaBeastAnimationDodge = State.eventFarmSeaBeastAnimationDodge == true,
            seaBeastObservationDodge = State.eventFarmSeaBeastObservationDodge == true,
            seaBeastObservationActivations = runtime.seaBeastObservation and runtime.seaBeastObservation.activated or 0,
            seaBeastCapturedAttackOffset = type(State.eventFarmSeaBeastAttackOffset) == "table" and {
                right = State.eventFarmSeaBeastAttackOffset.right,
                forward = State.eventFarmSeaBeastAttackOffset.forward,
                height = State.eventFarmSeaBeastAttackOffset.height,
            } or nil,
            seaBeastEvading = runtime.seaBeastEvadeActive == true,
            seaBeastCombatReady = runtime.seaBeastCombatReady == true,
            seaBeastSkillCasts = runtime.seaBeastSkill and runtime.seaBeastSkill.casts or 0,
            seaBeastSkillAimApplied = runtime.seaBeastSkillAim and runtime.seaBeastSkillAim.applied or 0,
            seaBeastSkillAimIntercepts = runtime.seaBeastSkillAim and runtime.seaBeastSkillAim.intercepts or 0,
            seaBeastSkillAimNoRead = runtime.seaBeastSkillAim and runtime.seaBeastSkillAim.noRead or 0,
            seaBeastSkillCameraLocks = runtime.seaBeastSkillAim and runtime.seaBeastSkillAim.cameraLocks or 0,
            seaBeastSkillAimRoute = runtime.seaBeastSkillAim and runtime.seaBeastSkillAim.lastRoute or nil,
            seaBeastBoatAutonomy = runtime.seaBeastBoatAutonomy and runtime.seaBeastBoatAutonomy.active == true,
            seaBeastBoatAutonomyRecoveries = runtime.seaBeastBoatAutonomy and runtime.seaBeastBoatAutonomy.recoveries or 0,
            terrorSharkBoatOrbit = State.eventFarmMoveBoatAway == true,
            terrorSharkBoatAutonomy = runtime.terrorSharkBoatAutonomy and runtime.terrorSharkBoatAutonomy.active == true,
            terrorSharkBoatAutonomyRecoveries = runtime.terrorSharkBoatAutonomy and runtime.terrorSharkBoatAutonomy.recoveries or 0,
            raidBoatOrbit = runtime.raidBoatAutonomy and runtime.raidBoatAutonomy.active == true,
            raidBoatOrbitKind = runtime.raidBoatAutonomy and runtime.raidBoatAutonomy.kind or nil,
            raidBoatOrbitRecoveries = runtime.raidBoatAutonomy and runtime.raidBoatAutonomy.recoveries or 0,
            raidBoatSkillCasts = runtime.raidBoatSkill and runtime.raidBoatSkill.casts or 0,
            -- Compatibility snapshot field: the existing UI/config toggle now
            -- means Terror Shark protective orbit, never a static move-away.
            moveBoatAway = State.eventFarmMoveBoatAway == true,
            lift = runtime.lift,
            targetLift = runtime.targetLift,
            markerMode = runtime.marker.mode,
            islandClearance = runtime.islandClearance and runtime.islandClearance.active == true,
            islandAhead = runtime.islandClearance and runtime.islandClearance.name or nil,
            dangerLevel = tonumber(player and player:GetAttribute("DangerLevel")) or 0,
            target = runtime.target and runtime.target.Name or nil,
            checkpoint = runtime.progress and runtime.progress.checkpoint and {
                kind = runtime.progress.checkpoint.kind,
                mode = runtime.progress.checkpoint.mode,
                target = runtime.progress.checkpoint.target and runtime.progress.checkpoint.target.Name or runtime.progress.checkpoint.targetName,
                source = runtime.progress.checkpoint.source,
            } or nil,
            progressStage = runtime.progress and runtime.progress.stage or runtime.phase,
            driver = localOccupies(seat),
            otherDriver = otherPlayerDrives(seat),
            physicalSpeed = physical and Vector3.new(physical.X, 0, physical.Z).Magnitude or 0,
            nativeAuthority = runtime.nativeAuthority and {
                armedAt = runtime.nativeAuthority.armedAt,
                lostSince = runtime.nativeAuthority.lostSince,
                repairAttempted = runtime.nativeAuthority.repairAttempted == true,
                lastPhysicalSpeed = runtime.nativeAuthority.lastPhysicalSpeed,
                lastCommandSpeed = runtime.nativeAuthority.lastCommandSpeed,
                lastReason = runtime.nativeAuthority.lastReason,
            } or nil,
            obstructionHold = runtime.obstructionHold and {
                active = (runtime.obstructionHold.untilAt or 0) > now(),
                untilAt = runtime.obstructionHold.untilAt,
                lift = runtime.obstructionHold.lift,
                source = runtime.obstructionHold.source,
            } or nil,
        }
    end

    function EventFarm:SetBoat(name)
        name = tostring(name or "")
        local valid = false
        for _, boat in ipairs(getBoatInfoList()) do
            if boat.name == name then valid = true break end
        end
        if not valid then return false, "boat_not_in_runtime_catalog" end
        State.eventFarmBoat = name
        Flow.Config:Save()
        return true
    end

    function EventFarm:SetTargetSelected(id, active)
        id = tostring(id or "")
        if not validTargetId(id) then return false, "event_not_supported" end
        targetSelections()[id] = active == true
        -- The old one-choice field is deliberately blanked as soon as the new
        -- list is edited, preventing a stale profile preference from winning
        -- after reload.
        State.eventFarmTarget = ""
        Flow.Config:Save()
        if self.Runtime.active and self.Runtime.mode == "event_farm" and selectedTargetCount() == 0 then
            self:SetEnabled(false, "no_farm_mobs_selected")
        end
        return true
    end

    -- Compatibility for any older UI/plugin call: selecting through the old
    -- API still works, but intentionally becomes a one-item list selection.
    function EventFarm:SetEvent(id)
        id = tostring(id or "")
        if not validTargetId(id) then return false, "event_not_supported" end
        local targets = targetSelections()
        for _, definition in ipairs(EventFarm.SupportedEvents) do targets[definition.id] = false end
        targets[id] = true
        State.eventFarmTarget = ""
        Flow.Config:Save()
        return true
    end

    function EventFarm:SetVortexEvade(active)
        State.eventFarmVortexEvade = active == true
        Flow.Config:Save()
        return true
    end

    function EventFarm:SetMoveBoatAway(active)
        State.eventFarmMoveBoatAway = active == true
        Flow.Config:Save()
        return true
    end

    function EventFarm:SetSeaBeastBeamDodge(active)
        local enabled = active == true
        -- The old UI exposed the early animation detector as a separate switch,
        -- so the apparent beam-dodge toggle could be on while no climb was ever
        -- armed. Keep both stored fields synchronized for legacy profiles but
        -- present/execute one unambiguous defense choice.
        State.eventFarmSeaBeastBeamDodge = enabled
        State.eventFarmSeaBeastAnimationDodge = enabled
        State.eventFarmSeaBeastDodgeDefaultRevision = 1
        Flow.Config:Save()
        return true
    end

    function EventFarm:SetSeaBeastAnimationDodge(active)
        return self:SetSeaBeastBeamDodge(active)
    end

    function EventFarm:SetSeaBeastObservationDodge(active)
        State.eventFarmSeaBeastObservationDodge = active == true
        Flow.Config:Save()
        return true
    end

    local function saveControlState(boat, seat, movement)
        local bodyPosition = seat and seat:FindFirstChild("BodyPosition")
        local bodyVelocity = seat and seat:FindFirstChild("BodyVelocity")
        local bodyGyro = seat and seat:FindFirstChild("BodyGyro")
        if not bodyPosition or not bodyVelocity or not bodyGyro or not movement then
            return nil, "native_controller_or_forces_missing"
        end
        return {
            boat = boat,
            seat = seat,
            movement = movement,
            bodyPosition = bodyPosition,
            bodyVelocity = bodyVelocity,
            bodyGyro = bodyGyro,
            seatMaxSpeed = seat.MaxSpeed,
            seatTorque = seat.Torque,
            seatTurnSpeed = seat.TurnSpeed,
            movementVelocity = movement.Velocity,
            movementSteer = movement.Steer,
            movementActive = movement.Active,
            movementInUse = movement.InUse,
            -- Same dual vertical support used by the proven BoatLocal Float:
            -- PositionOffset plus BodyPosition, never a boat CFrame move.
            movementPositionOffset = movement.PositionOffset,
            movementYOffset = (typeof(movement.YOffset) == "Vector3" and movement.YOffset.Y) or bodyPosition.Position.Y,
            bodyPositionPosition = bodyPosition.Position,
            bodyVelocityVelocity = bodyVelocity.Velocity,
            bodyVelocityMaxForce = bodyVelocity.MaxForce,
            bodyGyroCFrame = bodyGyro.CFrame,
        }
    end

    local function restoreBoatControl()
        local runtime = EventFarm.Runtime
        local original = runtime.original
        if original then
            pcall(function()
                original.seat.MaxSpeed = original.seatMaxSpeed
                original.seat.Torque = original.seatTorque
                original.seat.TurnSpeed = original.seatTurnSpeed
                original.movement.Velocity = original.movementVelocity
                original.movement.Steer = original.movementSteer
                original.movement.Active = original.movementActive
                original.movement.InUse = original.movementInUse
                original.movement.PositionOffset = original.movementPositionOffset
                original.bodyPosition.Position = original.bodyPositionPosition
                original.bodyVelocity.Velocity = original.bodyVelocityVelocity
                original.bodyVelocity.MaxForce = original.bodyVelocityMaxForce
                original.bodyGyro.CFrame = original.bodyGyroCFrame
            end)
        end
        runtime.original = nil
        runtime.movement = nil
        runtime.baseBodyPosition = nil
        runtime.direction = nil
        runtime.speed = 0
        runtime.lift = 0
        runtime.targetLift = 0
        runtime.liftRate = 0
        runtime.targetKind = nil
        runtime.unseatedCruiseDrive = nil
        runtime.seatRecovery = {attempts = 0, startedAt = nil, lastReason = nil}
        runtime.stalledFor = 0
        runtime.preStallLift = nil
        runtime.stallBoost = 0
        runtime.obstructionHold = {untilAt = 0, lift = nil, source = nil}
        runtime.nativeAuthority = {armedAt = 0, lostSince = nil, repairAttempted = false, lastPhysicalSpeed = 0, lastCommandSpeed = 0, lastReason = nil}
        runtime.nativeReady = false
        runtime.boatLostReason = nil
        runtime.deferBoatLossUntilTargetDefeated = false
        runtime.combatBoatLossReason = nil
        runtime.resettingAfterBoatLoss = false
        runtime.boatSafeTarget = nil
        runtime.boatSafeAt = 0
        runtime.boatAwayActive = false
        runtime.raidLift = {active = false, returning = false, restoreTargetLift = nil, resumePhase = nil, name = nil, distance = nil, clearSince = nil, detectedAt = nil}
        runtime.raidSpawnCandidate = nil
        runtime.emergencyUntil = 0
        runtime.vortexSignal = nil
        runtime.seaBeastBeamSignal = nil
        runtime.seaBeastEvadeActive = false
        runtime.seaBeastCombatReady = false
        runtime.seaBeastSurfaceCache = setmetatable({}, {__mode = "k"})
        runtime.seaBeastPreBeamTracks = setmetatable({}, {__mode = "k"})
        runtime.nextSeaBeastPreBeamScan = 0
        runtime.seaBeastKillWitness = nil
        runtime.seaBeastAltitudeViolation = nil
        runtime.seaBeastObservation = {attempts = 0, activated = 0, skippedActive = 0, skippedNoDodges = 0, skippedUnavailable = 0, lastAt = nil, lastKey = nil}
        runtime.seaBeastSkill = {lastTry = {}, cycles = 0, casts = 0, confirmed = 0, skippedCooldown = 0, skippedDisabled = 0, lastRoute = nil}
        runtime.seaBeastSkillAim = {attempts = 0, applied = 0, moduleReads = 0, nativeWrites = 0, mobilityBypassed = 0, unavailable = 0, lastRoute = nil, lastPoint = nil, lastMobilityRule = nil}
        runtime.seaBeastBoatAutonomy = {active = false, finalized = true, target = nil, recoveries = 0, lastRecoveryAt = 0}
        runtime.terrorSharkBoatAutonomy = {active = false, finalized = true, target = nil, recoveries = 0, lastRecoveryAt = 0}
        runtime.islandClearance = {active = false, name = nil, lastSeenAt = 0, distance = nil}
        runtime.islandScan = {nextAt = 0, candidates = {}}
        runtime.evadeActive = false
        runtime.combatOffset = nil
        runtime.transit = {active = false, collisions = {}, thrust = nil, lastSampleAt = 0, samplePosition = nil, stuckFor = 0, recoveries = 0, avoidUntil = 0, avoidDirection = nil, lastSeatFixAt = 0, lastObstacleAt = 0}
    end

    local function destroyVortexLift()
        local lift = EventFarm.Runtime.vortexLift
        if lift and lift.Parent then pcall(function() lift:Destroy() end) end
        EventFarm.Runtime.vortexLift = nil
    end

    local function disconnectVortexWatch()
        local runtime = EventFarm.Runtime
        for _, connection in ipairs(runtime.vortexConnections or {}) do
            pcall(function() connection:Disconnect() end)
        end
        runtime.vortexConnections = {}
        runtime.vortexSignal = nil
    end

    local function vortexTextMatches(value)
        local text = lower(value)
        return text:find("npc.chainshark.vortex", 1, true) ~= nil
            or text:find("chains hark vortex", 1, true) ~= nil
            or text:find("suction", 1, true) ~= nil
    end

    local function valueContainsVortex(value, depth)
        depth = depth or 0
        if depth > 3 then return false end
        local kind = typeof(value)
        if kind == "string" then return vortexTextMatches(value) end
        if kind == "Instance" then
            return vortexTextMatches(value.Name) or vortexTextMatches(value:GetFullName())
        end
        if type(value) == "table" then
            for key, item in pairs(value) do
                if vortexTextMatches(key) or valueContainsVortex(item, depth + 1) then return true end
            end
        end
        return false
    end

    local function isVortexTelegraphInstance(instance)
        return instance and vortexTextMatches(instance.Name)
    end

    local function recordVortexTelegraph(source)
        local runtime = EventFarm.Runtime
        local target = runtime.target
        if not runtime.active or not target or not targetAlive(target) then return end
        -- Record the authoritative Vortex/Suction telegraph immediately. The
        -- old close-range filter discarded the early warning, then fired Test
        -- 6 only after the player had already fallen from the boat.
        local label = typeof(source) == "Instance" and source:GetFullName() or tostring(source)
        runtime.vortexSignal = {at = now(), source = label, instance = source}
        journal("vortex_signal", {source = label, target = target.Name})
    end

    local function remoteMayCarryAttackEffects(remote)
        local name = lower(remote and remote.Name)
        return name:find("fx", 1, true) ~= nil or name:find("attack", 1, true) ~= nil
            or name:find("effect", 1, true) ~= nil or name:find("tween", 1, true) ~= nil
    end

    local function installVortexWatch()
        disconnectVortexWatch()
        local runtime = EventFarm.Runtime
        local function bindRemote(remote)
            if not remote:IsA("RemoteEvent") or not remoteMayCarryAttackEffects(remote) then return end
            runtime.vortexConnections[#runtime.vortexConnections + 1] = remote.OnClientEvent:Connect(function(...)
                local args = table.pack(...)
                for i = 1, args.n do
                    if valueContainsVortex(args[i]) then
                        recordVortexTelegraph("remote:" .. remote:GetFullName())
                        return
                    end
                end
            end)
        end
        runtime.vortexConnections[#runtime.vortexConnections + 1] = Workspace.DescendantAdded:Connect(function(item)
            if isVortexTelegraphInstance(item) then recordVortexTelegraph(item) end
        end)
        runtime.vortexConnections[#runtime.vortexConnections + 1] = ReplicatedStorage.DescendantAdded:Connect(function(item)
            if item:IsA("RemoteEvent") then bindRemote(item)
            elseif isVortexTelegraphInstance(item) then recordVortexTelegraph(item) end
        end)
        for _, item in ipairs(ReplicatedStorage:GetDescendants()) do
            if item:IsA("RemoteEvent") then bindRemote(item) end
        end
    end

    local function endExternalCombat()
        local farm = Flow.Features.Farm
        if farm and farm.EndExternalHover then
            pcall(function() farm:EndExternalHover("sea_event_farm") end)
            pcall(function() farm:EndExternalHover("sea_event_vortex_evade") end)
        end
    end

    -- Sea Beast combat owns only its normal follow lease. Its beam response is
    -- TravelDirect-only and never starts an external hover/orbit lease, keeping
    -- this cleanup isolated from the established Terror Shark path.
    local function endSeaBeastCombat()
        if clearSeaBeastSkillAim then clearSeaBeastSkillAim() end
        local farm = Flow.Features.Farm
        if farm and farm.EndExternalHover then
            pcall(function() farm:EndExternalHover("sea_event_sea_beast") end)
        end
    end

    local function terrorDangerAnimation(target)
        local hum = target and target:FindFirstChildOfClass("Humanoid")
        if not hum then return false end
        local ok, tracks = pcall(function() return hum:GetPlayingAnimationTracks() end)
        if not ok or type(tracks) ~= "table" then return false end
        for _, track in ipairs(tracks) do
            local animation = track and track.Animation
            if animation and animation.AnimationId == EventFarm.TerrorSharkDangerAnimationId then return true, track end
        end
        return false
    end

    local function combatFollow(target)
        local farm = Flow.Features.Farm
        local runtime = EventFarm.Runtime
        if not farm or not farm.BeginExternalFollow then return false end
        local initial = targetRoot(target)
        if not initial then return false end
        local playerRoot = rootPart()
        local flat = playerRoot and Vector3.new(playerRoot.Position.X-initial.Position.X,0,playerRoot.Position.Z-initial.Position.Z) or Vector3.new(0,0,1)
        if flat.Magnitude < 1 then flat = Vector3.new(0,0,1) end
        runtime.combatOffset = flat.Unit * EventFarm.TerrorSharkCombatLateralOffset
        return farm:BeginExternalFollow("sea_event_farm", initial.Position + runtime.combatOffset, function()
            local current = targetRoot(target)
            return current and (current.Position + (runtime.combatOffset or Vector3.new(0,0,65))) or nil
        end, function()
            return EventFarm.Runtime.active and not EventFarm.Runtime.evadeActive and targetAlive(target) and isTerrorSharkTargetValid(target)
        end, EventFarm.TerrorSharkCombatHeight)
    end

    local function stopTransitAssist(reason)
        local runtime, transit = EventFarm.Runtime, EventFarm.Runtime.transit
        if not transit then return end
        if transit.thrust and transit.thrust.Parent then pcall(function() transit.thrust:Destroy() end) end
        transit.thrust = nil
        for part, value in pairs(transit.collisions or {}) do
            if part and part.Parent then pcall(function() part.CanCollide = value end) end
        end
        transit.collisions = {}
        if transit.active then journal("transit_restore", {reason = reason}) end
        transit.active = false
    end

    local function startTransitAssist()
        local runtime = EventFarm.Runtime
        if State.eventFarmTransitAssist == false or not runtime.seat or not runtime.boat then return end
        local transit = runtime.transit
        if transit.active then return end
        transit.active = true
        transit.collisions = {}
        local function snapshot(container)
            for _, item in ipairs(container:GetDescendants()) do
                if item:IsA("BasePart") and transit.collisions[item] == nil then
                    transit.collisions[item] = item.CanCollide
                    item.CanCollide = false
                end
            end
        end
        snapshot(runtime.boat)
        local character = player and player.Character
        if character then snapshot(character) end
        -- The native ship Movement/BodyGyro is the only propulsion writer.
        -- Local noclip supports passage; no second BodyVelocity is attached.
        transit.thrust = nil
        transit.lastSampleAt, transit.samplePosition, transit.stuckFor, transit.recoveries, transit.startedAt, transit.lastObstacleAt = now(), runtime.seat.Position, 0, 0, now(), 0
        journal("transit_start", {seatY = EventFarm.TransitCruiseSeatY, speed = EventFarm.TransitSpeed})
    end

    local function transitObstacleStep()
        local runtime, transit, seat = EventFarm.Runtime, EventFarm.Runtime.transit, EventFarm.Runtime.seat
        if not transit.active or not seat or not runtime.direction then return end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = {runtime.boat, player and player.Character}
        local origin = seat.Position + Vector3.new(0, 8, 0)
        local hit = Workspace:Raycast(origin, runtime.direction * 110, params)
        if hit and hit.Instance and not hit.Instance:IsDescendantOf(Workspace.Terrain) then
            transit.lastObstacleAt = now()
            -- Noclip local hull can cross this geometry; preserve a single
            -- native heading rather than assigning a competing lateral thrust.
            transit.avoidDirection = nil
            transit.avoidUntil = 0
            journal("transit_obstacle_bypass", {part = hit.Instance.Name, mode = "noclip_single_heading"})
        elseif not runtime.boatAwayActive
            and (runtime.phase == "sea_cruise" or runtime.phase == "calibrating_sea_marker" or runtime.phase == "calibrating_existing_sea")
            and runtime.cruiseDirection then
            -- A temporary obstacle/raid heading must never become the permanent
            -- cruise course after the blocking ray is clear.
            drive(runtime.cruiseDirection, 300)
        end
    end

    local function transitStep(dt)
        local runtime, transit, seat = EventFarm.Runtime, EventFarm.Runtime.transit, EventFarm.Runtime.seat
        if not transit.active or not seat or not seat.Parent or not localOccupies(seat) then return end
        local direction = runtime.direction
        if transit.avoidDirection and now() < transit.avoidUntil then direction = transit.avoidDirection else transit.avoidDirection = nil end
        -- Horizontal velocity is owned by native drive(direction, speed).
        -- The native ship BodyPosition owns altitude. Directly assigning the
        -- VehicleSeat CFrame fought its lift/marker writer and caused the
        -- observed +/- 4k stud/s vertical teleport loop. Transit owns only
        -- local collision and horizontal thrust; it never writes seat Y.
        transit.lastSeatFixAt = now()
        if now() - transit.lastSampleAt < 0.5 then return end
        local progress = transit.samplePosition and (seat.Position - transit.samplePosition).Magnitude or 0
        transit.lastSampleAt, transit.samplePosition = now(), seat.Position
        local canWatchProgress = (runtime.phase == "calibrating_sea_marker" or runtime.phase == "calibrating_existing_sea")
            and now() - (transit.startedAt or now()) >= 5
        if canWatchProgress and direction and runtime.speed >= 80 and progress < EventFarm.TransitMinimumProgress then
            transit.stuckFor = transit.stuckFor + 0.5
            if transit.stuckFor >= EventFarm.TransitStuckSeconds then
                transit.stuckFor, transit.recoveries = 0, transit.recoveries + 1
                -- Do not reanchor the seat during a native BodyPosition
                -- cruise. Reapply only horizontal thrust and let the existing
                -- Tiki/stall recovery own vertical correction.
                journal("transit_stuck_recovery", {attempt = transit.recoveries, progress = progress, mode = "observe_native"})
                if transit.recoveries >= EventFarm.TransitMaxRecoveries then
                    -- A sampled stall is not evidence that the hull died. Keep
                    -- the native boat, reset the observer and let the normal
                    -- Tiki exit/recovery path decide whether a repurchase is due.
                    journal("transit_stall_observed", {recoveries = transit.recoveries})
                    transit.recoveries = 0
                end
            end
        else
            transit.stuckFor = 0
        end
        transitObstacleStep()
    end

    local function disconnectControl()
        local runtime = EventFarm.Runtime
        local control = runtime.controlConnection
        if type(control) == "string" then
            -- EventFarm owns one last-render writer while it is active. This
            -- explicitly removes it before any restoration or replacement.
            pcall(function() RunService:UnbindFromRenderStep(control) end)
        elseif control then
            pcall(function() control:Disconnect() end)
        end
        runtime.controlConnection = nil
    end

    local function applyControl(dt)
        local runtime = EventFarm.Runtime
        local externalLease = runtime.externalBoatLease
        -- Boat TP's direct route is deliberately rendered by this same
        -- EventFarm controller, not by a second RemoteBoat approximation.
        -- Either Farm or one live external lease owns the writer, never both.
        if not (runtime.active or (externalLease and externalLease.active == true)) or not runtime.original or not runtime.nativeReady then return end
        local original = runtime.original
        local seat = original.seat
        local seatExists = seat ~= nil
        local seatParented = seatExists and seat.Parent ~= nil
        local boatExists = original.boat ~= nil
        local boatParented = boatExists and original.boat.Parent ~= nil
        if not seatExists or not seatParented or not boatExists or not boatParented then
            -- The writer runs at RenderStep frequency. Journal this diagnostic
            -- once per loss, not once per rendered frame.
            if not runtime.boatLostReason then
                local h, root = humanoid(), rootPart()
                journal("boat_removed_detail", {
                    seatExists = seatExists,
                    seatParented = seatParented,
                    boatExists = boatExists,
                    boatParented = boatParented,
                    humanoidState = h and h:GetState().Name or nil,
                    playerPos = root and {x = root.Position.X, y = root.Position.Y, z = root.Position.Z} or nil,
                    seatPos = seat and {x = seat.Position.X, y = seat.Position.Y, z = seat.Position.Z} or nil,
                })
            end
            runtime.boatLostReason = runtime.boatLostReason or "boat_removed"
            runtime.direction = nil
            runtime.speed = 0
            return
        end
        if not original.bodyPosition or not original.bodyPosition.Parent
            or not original.bodyVelocity or not original.bodyVelocity.Parent
            or not original.bodyGyro or not original.bodyGyro.Parent then
            runtime.boatLostReason = runtime.boatLostReason or "native_boat_forces_removed"
            runtime.direction = nil
            runtime.speed = 0
            return
        end
        runtime.lastPosition = seat.Position
        if otherPlayerDrives(seat) then
            -- Never compete with another player for a helm.
            runtime.direction = nil
            runtime.speed = 0
            return
        end

        -- The only authorized unseated branches are the bounded Sea Beast and
        -- Terror Shark native-orbit leases. They supply target-relative courses
        -- to this existing writer only; neither moves the hull by CFrame nor
        -- creates a second force.
        local autonomous = seaBeastAutonomyCommand and seaBeastAutonomyCommand()
        if not autonomous then autonomous = terrorSharkAutonomyCommand and terrorSharkAutonomyCommand() end
        if not autonomous then autonomous = raidBoatAutonomyCommand and raidBoatAutonomyCommand() end
        -- The external lease plugs into the *existing* EventFarm autonomous
        -- branch. Its geometry is direct point-to-point, not an orbit.
        if not autonomous and externalLease and externalLease.active == true and externalLease.direction then
            local requested = externalLease.direction
            local heading = externalLease.heading or requested
            local alignmentDot = math.clamp(heading:Dot(requested), -1, 1)
            local turnAngle = math.acos(alignmentDot)
            if turnAngle > 0.0005 then
                local turnSign = heading:Cross(requested).Y >= 0 and 1 or -1
                local turnStep = math.min(turnAngle, EventFarm.ExternalRouteTurnRate * math.max(dt, 0))
                heading = (CFrame.fromAxisAngle(Vector3.new(0, 1, 0), turnSign * turnStep)):VectorToWorldSpace(heading)
                heading = Vector3.new(heading.X, 0, heading.Z)
                heading = heading.Magnitude > 0.01 and heading.Unit or requested
            else
                heading = requested
            end
            -- Cornering keeps the native carrier alive but prevents a high
            -- speed circle while the bow is still facing away from the target.
            local alignment = math.clamp((alignmentDot + 1) * 0.5, 0, 1)
            local cornerSpeed = math.max(80, externalLease.speed * (alignment ^ EventFarm.ExternalRouteCornerExponent))
            local smoothSpeed = tonumber(externalLease.smoothedSpeed) or 80
            local speedDelta = cornerSpeed - smoothSpeed
            local speedRate = speedDelta >= 0 and EventFarm.ExternalRouteAcceleration or EventFarm.ExternalRouteDeceleration
            smoothSpeed = math.clamp(smoothSpeed + math.clamp(speedDelta, -speedRate * math.max(dt, 0), speedRate * math.max(dt, 0)), 80, 400)
            externalLease.heading, externalLease.smoothedSpeed = heading, smoothSpeed
            autonomous = {
                direction = heading,
                speed = smoothSpeed,
                steer = 0,
            }
        end
        if not localOccupies(seat) and not autonomous then
            local phase = runtime.phase
            local recoveringCruise = phase == "sea_cruise" or phase == "calibrating_sea_marker"
                or phase == "calibrating_existing_sea" or phase == "raid_boat_descending"
                or phase == "leaving_tiki"
            if recoveringCruise and not runtime.unseatedCruiseDrive and runtime.direction then
                runtime.unseatedCruiseDrive = {direction = runtime.direction, speed = runtime.speed, phase = phase, reason = runtime.reason}
                journal("cruise_seat_lost", {phase = phase, seat = vectorSnapshot(seat.Position), speed = runtime.speed})
            end
            runtime.direction = nil
            runtime.speed = 0
            return
        end

        local direction = autonomous and autonomous.direction or runtime.direction
        local speed = autonomous and autonomous.speed or runtime.speed
        local steer = autonomous and autonomous.steer or 0
        local current = runtime.lift
        local target = runtime.targetLift
        local rate = math.max(1, runtime.liftRate)
        local delta = target - current
        if math.abs(delta) > 0.01 then
            local step = math.min(math.abs(delta), rate * math.max(0, dt))
            runtime.lift = current + (delta > 0 and step or -step)
        end
        if externalLease and externalLease.controller and externalLease.controller.State then
            externalLease.frames = (externalLease.frames or 0) + 1
            externalLease.controller.State.lift = runtime.lift
            externalLease.controller.State.targetLift = runtime.targetLift
            externalLease.controller.State.requestedSpeed = externalLease.speed
            externalLease.controller.State.externalSpeed = externalLease.smoothedSpeed
            externalLease.controller.State.phase = externalLease.active and "active" or "idle"
            externalLease.controller.State.writerFrames = externalLease.frames
            externalLease.controller.State.writerFailures = 0
            externalLease.controller.State.writerStage = externalLease.released and "eventfarm_external_route" or "eventfarm_seated_prime"
        end
        -- Transit is seated-only; an unseated Sea Beast orbit must not also
        -- retain its cruise collision/obstruction helper.
        if not autonomous then transitStep(dt) end
        pcall(function()
            seat.MaxSpeed = math.max(original.seatMaxSpeed, math.max(60, math.abs(speed)))
            seat.Torque = math.max(original.seatTorque, 4)
            seat.TurnSpeed = math.max(original.seatTurnSpeed, 1)
            if autonomous then
                -- ShipController normally marks Movement inactive once the
                -- seat becomes empty. Reassert just these existing native flags
                -- after its frame; this is also the automatic recovery if the
                -- controller clears them during the encounter.
                original.movement.Active = true
                original.movement.InUse = true
            end
            original.movement.Velocity = direction and speed or 0
            original.movement.Steer = steer
            if direction and direction.Magnitude > 0.01 then
                -- The live Tiki probe established the current native mapping:
                -- positive Movement.Velocity follows the gyro's LookVector.
                -- Aim toward the requested physical direction and let the
                -- native controller move the hull; never translate CFrame.
                original.bodyGyro.CFrame = CFrame.lookAt(Vector3.zero, direction.Unit)
            end
            -- BodyPosition's horizontal target is maintained by the game's
            -- native ship controller. Preserve its live X/Z each heartbeat;
            -- only this feature's vertical offset is imposed.
            -- Mirror BoatLocal Float exactly: preserve native X/Z values and
            -- add the same progressive lift to both vertical support channels.
            local offset = original.movementPositionOffset or Vector3.new()
            original.movement.PositionOffset = Vector3.new(offset.X, offset.Y + runtime.lift, offset.Z)
            local live = original.bodyPosition.Position
            original.bodyPosition.Position = Vector3.new(live.X, original.movementYOffset + runtime.lift, live.Z)
        end)
    end

    local function attachNativeControl(boat)
        local runtime = EventFarm.Runtime
        local seat = rootSeat(boat)
        if not seat then return false, "driver_seat_missing" end
        if otherPlayerDrives(seat) then return false, "boat_is_driven_by_someone_else" end
        local hum = humanoid()
        if not hum then return false, "character_missing" end
        if not localOccupies(seat) then
            -- A freshly bought boat can spawn a short distance out from the
            -- Boat Dealer. Seat:Sit is not a route: it simply fails when the
            -- humanoid is beyond the native seat interaction envelope. Approach
            -- the *live* seat once before the bounded sit retry; never pull the
            -- boat or assume a fixed dealer-to-boat offset.
            local root = rootPart()
            local horizontal = root and math.sqrt((root.Position.X - seat.Position.X) ^ 2 + (root.Position.Z - seat.Position.Z) ^ 2) or math.huge
            local vertical = root and math.abs(root.Position.Y - seat.Position.Y) or math.huge
            local travelAttempted, moved, travelReason = false, false, "already_near_seat"
            if horizontal > EventFarm.CruiseSeatRecoveryHorizontalTolerance
                or vertical > EventFarm.CruiseSeatRecoveryVerticalTolerance then
                travelAttempted = true
                setPhase("approaching_boat_seat", "initial_boarding")
                local teleport = Flow.Features.Teleport
                if teleport and type(teleport.TravelDirectToPosition) == "function" then
                    moved, travelReason = teleport:TravelDirectToPosition(seat.Position + Vector3.new(0, 12, 0), "sea_event_initial_board", "Event boat", {
                        holdArrivalVelocity = true, arrivalConfirmSeconds = 0.30, maxAttempts = 2,
                        ignoreNoSupportWater = true, disableAdaptiveClearance = true,
                    })
                else
                    travelReason = "direct_travel_unavailable"
                end
                root = rootPart()
                horizontal = root and math.sqrt((root.Position.X - seat.Position.X) ^ 2 + (root.Position.Z - seat.Position.Z) ^ 2) or math.huge
                vertical = root and math.abs(root.Position.Y - seat.Position.Y) or math.huge
            end
            journal("initial_boat_seat_approach", {
                attempted = travelAttempted, moved = moved == true, reason = travelReason,
                horizontal = horizontal, vertical = vertical,
            })
            -- Clear an orphaned/previous SeatPart state before asking the live
            -- owned seat to attach. This does not move the hull and is a no-op
            -- when the Humanoid is already standing, but avoids a stale seat
            -- reference rejecting the immediate native Seat:Sit request.
            pcall(function() hum.Sit = false end)
            task.wait(0.05)
            pcall(function() seat:Sit(hum) end)
            local deadline = now() + 3
            repeat task.wait(0.1) until localOccupies(seat) or now() >= deadline or not EventFarm.Runtime.active
        end
        if not localOccupies(seat) then return false, "could_not_enter_driver_seat" end
        local movement = getShipMovement(boat)
        local original, reason = saveControlState(boat, seat, movement)
        if not original then return false, reason end
        runtime.boat = boat
        runtime.seat = seat
        runtime.boatCharacter = player and player.Character or nil
        runtime.movement = movement
        runtime.original = original
        runtime.baseBodyPosition = original.bodyPositionPosition
        runtime.lastPosition = seat.Position
        runtime.stalledFor = 0
        runtime.preStallLift = nil
        runtime.stallBoost = 0
        runtime.obstructionHold = {untilAt = 0, lift = nil, source = nil}
        runtime.nativeAuthority = runtime.nativeAuthority or {}
        runtime.nativeAuthority.armedAt = now()
        runtime.nativeAuthority.lostSince = nil
        runtime.nativeAuthority.lastPhysicalSpeed = 0
        runtime.nativeAuthority.lastCommandSpeed = 0
        runtime.nativeAuthority.lastReason = "attached"
        -- A newly spawned native boat needs a short controller settle before
        -- the farm touches height. This avoids the game overwriting our first
        -- progressive lift frame.
        runtime.nativeReady = false
        -- The game ship controller rewrites BodyPosition after Heartbeat.
        -- Write at RenderPriority.Last (as BoatLocal does) so PositionOffset
        -- and BodyPosition survive into physics. Heartbeat was the direct
        -- cause of the farm's apparent "no flight" behavior.
        local bindName = "FlowKanSeaFarm/NativeControl/" .. tostring(runtime.generation)
        runtime.controlConnection = bindName
        RunService:BindToRenderStep(bindName, Enum.RenderPriority.Last.Value, function(dt)
            applyControl(dt)
        end)
        return true
    end

    local function clearNativeControl()
        -- Any temporary Sea Beast/Terror Shark lease must finalize before native
        -- values are restored. This covers Farm stop, boat loss, reset and an
        -- early combat exit through one cleanup path.
        if stopSeaBeastBoatAutonomy then stopSeaBeastBoatAutonomy("native_control_clear") end
        if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("native_control_clear") end
        if stopRaidBoatAutonomy then stopRaidBoatAutonomy("native_control_clear") end
        stopTransitAssist("native_control_clear")
        disconnectControl()
        restoreBoatControl()
    end

    local function isCurrent(generation)
        return EventFarm.Runtime.active and EventFarm.Runtime.generation == generation
    end

    local function waitSeconds(generation, seconds)
        local deadline = now() + seconds
        while isCurrent(generation) and not EventFarm.Runtime.boatLostReason and now() < deadline do task.wait(0.05) end
        return isCurrent(generation) and not EventFarm.Runtime.boatLostReason
    end

    local function settleNativeBoat(generation)
        if not waitSeconds(generation, 1.5) then return false end
        local runtime = EventFarm.Runtime
        local original = runtime.original
        if not original or not original.bodyPosition or not original.bodyPosition.Parent then
            runtime.boatLostReason = runtime.boatLostReason or "native_boat_forces_removed"
            return false
        end
        -- Capture the real post-spawn native anchor for vertical offsets while
        -- retaining the pre-farm values separately for exact restoration.
        runtime.baseBodyPosition = original.bodyPosition.Position
        runtime.lastPosition = runtime.seat and runtime.seat.Position or runtime.lastPosition
        runtime.nativeReady = true
        startTransitAssist()
        return true
    end

    drive = function(direction, speed)
        local runtime = EventFarm.Runtime
        local flat = direction and Vector3.new(direction.X, 0, direction.Z) or nil
        runtime.direction = flat and flat.Magnitude > 0.01 and flat.Unit or nil
        -- Live Tiki motion probe: -80 moved +X/-Z (toward the island-side
        -- sea), while the requested endless-sea course is -X/+Z. Native
        -- positive throttle is therefore the verified forward command.
        runtime.speed = runtime.direction and math.abs(tonumber(speed) or 0) or 0
    end

    setLift = function(target, rate)
        local runtime = EventFarm.Runtime
        runtime.targetLift = math.max(0, tonumber(target) or 0)
        runtime.liftRate = math.max(1, tonumber(rate) or 120)
    end

    -- Shared EventFarm native autonomy lease ---------------------------------
    --
    -- BARCO TP uses this owner-scoped adapter instead of maintaining a second
    -- copy of the native ship writer. The EventFarm renderer stays unchanged;
    -- this lease supplies a direct course where a Sea-event lease supplies an
    -- orbit course.
    function EventFarm:EndExternalBoatAutonomy(owner, reason)
        local runtime = self.Runtime
        local lease = runtime.externalBoatLease
        if not lease then return false, "external_lease_missing" end
        if owner ~= nil and lease.owner ~= tostring(owner) then return false, "external_owner_mismatch" end
        lease.active = false
        lease.reason = tostring(reason or "stopped")
        if lease.controller and lease.controller.State then
            lease.controller.State.phase = "idle"
            lease.controller.State.dismountReady = false
        end
        runtime.externalBoatLease = nil
        -- Same saved-state teardown used by the EventFarm native controller.
        -- It does not touch any passenger character or passenger seat.
        disconnectControl()
        restoreBoatControl()
        runtime.boat, runtime.seat, runtime.movement = nil, nil, nil
        runtime.direction, runtime.speed = nil, 0
        runtime.targetLift, runtime.lift, runtime.liftRate = 0, 0, 0
        runtime.nativeReady = false
        if Flow.Runtime then Flow.Runtime.remoteBoatLease = false end
        return true
    end

    function EventFarm:BeginExternalBoatAutonomy(owner, options)
        owner = tostring(owner or "boat_friend")
        options = type(options) == "table" and options or {}
        local runtime = self.Runtime
        if runtime.active then return false, "event_farm_active" end
        if runtime.externalBoatLease and runtime.externalBoatLease.active then return false, "external_lease_busy" end
        local remote = Flow.Features and Flow.Features.RemoteBoat
        if remote and remote.State and remote.State.phase ~= "idle" then return false, "remote_boat_busy" end

        local boat, seat
        local boats = Workspace and Workspace:FindFirstChild("Boats")
        if boats then
            for _, candidate in ipairs(boats:GetChildren()) do
                local ownerValue = candidate:FindFirstChild("Owner")
                local candidateSeat = rootSeat(candidate)
                if ownerValue and safeGet(ownerValue, "Value") == player and candidateSeat and candidateSeat:IsA("VehicleSeat") then
                    boat, seat = candidate, candidateSeat
                    break
                end
            end
        end
        if not boat or not seat then return false, "owned_boat_with_pilot_seat_required" end
        if not localOccupies(seat) then return false, "sit_in_own_pilot_seat_first" end

        local function flatCourse(vector)
            if typeof(vector) ~= "Vector3" then return nil end
            local flat = Vector3.new(vector.X, 0, vector.Z)
            return flat.Magnitude > 0.01 and flat.Unit or nil
        end
        local direction = flatCourse(options.direction)
        if not direction then return false, "initial_direction_missing" end

        runtime.generation = runtime.generation + 1
        local lease = {
            active = true,
            owner = owner,
            -- direction/speed are the requested route. heading/smoothedSpeed
            -- are the actual progressive native command consumed per frame.
            direction = direction,
            speed = math.clamp(tonumber(options.speed) or 80, 80, 400),
            heading = direction,
            smoothedSpeed = 80,
            lift = math.clamp(tonumber(options.lift) or 200, 0, 3000),
            liftRate = math.max(1, tonumber(options.liftRate) or 220),
            readyForRelease = false,
            released = false,
            reason = nil,
            frames = 0,
        }
        local controller = {Version = "EventFarmNativeLease 1.0.0", State = {phase = "active", lift = 0, targetLift = 0, nativeReady = false, dismountReady = false, writerFrames = 0, writerFailures = 0, writerStage = "eventfarm_seated_prime"}}
        lease.controller = controller

        local function sync()
            local state = controller.State
            state.phase = lease.active and "active" or "idle"
            state.lift = runtime.lift or 0
            state.targetLift = runtime.targetLift or 0
            state.nativeReady = runtime.nativeReady == true
            state.dismountReady = lease.released == true
            state.writerStage = lease.released and "eventfarm_external_route" or "eventfarm_seated_prime"
            state.requestedSpeed = lease.speed
            state.externalSpeed = lease.smoothedSpeed
            state.writerFrames = lease.frames or 0
            state.writerFailures = 0
        end

        runtime.externalBoatLease = lease
        if Flow.Runtime then Flow.Runtime.remoteBoatLease = true end
        local attached, attachReason = attachNativeControl(boat)
        if not attached then
            runtime.externalBoatLease = nil
            if Flow.Runtime then Flow.Runtime.remoteBoatLease = false end
            return false, attachReason
        end
        -- The EventFarm autonomous branch receives this direct course before
        -- seat release, retaining one continuous controller lease thereafter.
        runtime.direction, runtime.speed = direction, lease.speed
        setLift(lease.lift, lease.liftRate)

        function controller:IsExternalReady(requestOwner)
            if tostring(requestOwner or owner) ~= lease.owner or not lease.active then return false end
            if lease.readyForRelease and not lease.released then
                local h, liveSeat = humanoid(), runtime.seat
                if not h or not liveSeat or not localOccupies(liveSeat) then
                    EventFarm:EndExternalBoatAutonomy(lease.owner, "pilot_left_before_native_release")
                    return false
                end
                local previousDisabled, previousCanTouch = liveSeat.Disabled, liveSeat.CanTouch
                pcall(function()
                    liveSeat.Disabled = true
                    liveSeat.CanTouch = false
                    h.Sit = false
                end)
                local deadline = now() + 1.2
                repeat task.wait(0.05) until (not localOccupies(liveSeat) and h.Sit == false) or now() >= deadline or not lease.active
                pcall(function()
                    if liveSeat and liveSeat.Parent then
                        liveSeat.Disabled = previousDisabled
                        liveSeat.CanTouch = previousCanTouch
                    end
                end)
                if not lease.active or localOccupies(liveSeat) then
                    EventFarm:EndExternalBoatAutonomy(lease.owner, "could_not_leave_pilot_seat")
                    return false
                end
                lease.released = true
            end
            sync()
            return lease.released == true
        end

        function controller:SetExternalCommand(requestOwner, command)
            if tostring(requestOwner or owner) ~= lease.owner or not lease.active then return false, "external_owner_mismatch" end
            if type(command) ~= "table" then return false, "command_missing" end
            local requested = flatCourse(command.direction)
            local speed = math.clamp(tonumber(command.speed) or 0, 0, 400)
            if not requested or speed < 80 then return false, "invalid_command" end
            -- Do not snap the native writer to this 80 ms route sample. The
            -- render-step branch eases heading and carrier speed toward it.
            lease.direction, lease.speed = requested, speed
            if type(command.lift) == "number" then setLift(math.clamp(command.lift, 0, 3000), lease.liftRate) end
            sync()
            return true
        end

        function controller:ClearExternal(requestOwner)
            if tostring(requestOwner or owner) ~= lease.owner then return false, "external_owner_mismatch" end
            return EventFarm:EndExternalBoatAutonomy(lease.owner, "external_cleared")
        end

        function controller:Stop(reason)
            return EventFarm:EndExternalBoatAutonomy(lease.owner, reason)
        end

        task.spawn(function()
            task.wait(1.5)
            if runtime.externalBoatLease ~= lease or not lease.active or not runtime.original or not runtime.seat or not localOccupies(runtime.seat) then return end
            runtime.baseBodyPosition = runtime.original.bodyPosition.Position
            runtime.lastPosition = runtime.seat.Position
            runtime.nativeReady = true
            setLift(lease.lift, lease.liftRate)
            local deadline = now() + 12
            while runtime.externalBoatLease == lease and lease.active and localOccupies(runtime.seat)
                and runtime.lift < lease.lift - 10 and now() < deadline do
                task.wait(0.05)
            end
            if runtime.externalBoatLease ~= lease or not lease.active or not localOccupies(runtime.seat) then return end
            local primeDeadline = now() + 1.20
            while runtime.externalBoatLease == lease and lease.active and localOccupies(runtime.seat) and now() < primeDeadline do task.wait(0.04) end
            if runtime.externalBoatLease == lease and lease.active and localOccupies(runtime.seat) then
                lease.readyForRelease = true
                sync()
            end
        end)
        sync()
        return true, controller
    end

    local function waitForLift(generation, target, margin, timeout)
        local deadline = now() + (timeout or 12)
        while isCurrent(generation) and not EventFarm.Runtime.boatLostReason and now() < deadline do
            if math.abs(EventFarm.Runtime.lift - target) <= (margin or 8) then return true end
            task.wait(0.05)
        end
        return false
    end

    targetRoot = function(target)
        return target and (target:FindFirstChild("HumanoidRootPart") or target.PrimaryPart or target:FindFirstChildWhichIsA("BasePart")) or nil
    end

    local function isTerrorSharkName(name)
        -- Case, spaces, underscore and hyphen are formatting only. Thus this
        -- matches Terrorshark, TerrorShark, terror_shark and terror shark.
        local normalized = lower(name):gsub("[%s_%-]", "")
        return normalized:find("terrorshark", 1, true) ~= nil
    end

    local function terrorSharkCandidates()
        -- Search the Workspace tree only two levels below Workspace. This
        -- covers Workspace.Enemies.Terrorshark, Workspace.SeaBeasts.TerrorShark
        -- and an equivalent one-folder container without an unbounded scan of
        -- effects/projectiles. Candidates are de-duplicated by Instance.
        local workspaceRoot = Workspace
        if not workspaceRoot then return {} end
        local queue, output, seen = {{node = workspaceRoot, depth = 0}}, {}, {}
        local cursor = 1
        while cursor <= #queue do
            local row = queue[cursor]
            cursor = cursor + 1
            if row.depth < 2 then
                for _, child in ipairs(row.node:GetChildren()) do
                    local depth = row.depth + 1
                    if child:IsA("Model") and isTerrorSharkName(child.Name) and not seen[child] then
                        seen[child] = true
                        output[#output + 1] = child
                    end
                    if depth < 2 and (child:IsA("Folder") or child:IsA("Model")) then
                        queue[#queue + 1] = {node = child, depth = depth}
                    end
                end
            end
        end
        return output
    end

    local function targetOperationalDistance(target)
        local root = targetRoot(target)
        local runtime = EventFarm.Runtime
        local anchor = runtime.seat and runtime.seat.Parent and runtime.seat.Position
            or (rootPart() and rootPart().Position)
        return root and anchor and (root.Position - anchor).Magnitude or math.huge
    end

    isTerrorSharkTargetValid = function(target)
        if not target or not target.Parent then return false end
        local hum = target:FindFirstChildOfClass("Humanoid")
        if hum and hum.Health <= 0 then return false end
        local runtime = EventFarm.Runtime
        local limit = runtime.target == target and EventFarm.TerrorSharkMaxTrackedDistance or EventFarm.TerrorSharkMaxTargetDistance
        return targetOperationalDistance(target) <= limit
    end

    -- DangerLevel is retained as calibration telemetry only. Live evidence
    -- showed it remains 600 even after the boat reaches 2,400+ studs from a
    -- Terrorshark, so it cannot be used as a boolean "compass active" gate.
    -- Parking is consequently governed by measured boat-to-target separation.
    local function compassIsClear()
        return true, tonumber(player and player:GetAttribute("DangerLevel")) or 0
    end

    local function boatHealthRatio(boat)
        if not boat then return nil end
        local current = tonumber(boat:GetAttribute("Health")) or tonumber(boat:GetAttribute("HullHealth"))
        local maximum = tonumber(boat:GetAttribute("MaxHealth")) or tonumber(boat:GetAttribute("MaxHullHealth"))
        local healthValue = boat:FindFirstChild("Health", true) or boat:FindFirstChild("HullHealth", true)
        local maxValue = boat:FindFirstChild("MaxHealth", true) or boat:FindFirstChild("MaxHullHealth", true)
        if current == nil and healthValue and (healthValue:IsA("NumberValue") or healthValue:IsA("IntValue")) then current = healthValue.Value end
        if maximum == nil and maxValue and (maxValue:IsA("NumberValue") or maxValue:IsA("IntValue")) then maximum = maxValue.Value end
        if current ~= nil and maximum and maximum > 0 then return current / maximum, current, maximum, "numeric" end

        -- Live MarineSloop evidence: the replicated hull owns MaxHealth but
        -- does not expose a numeric current-Health attribute/value. Its native
        -- ShipHealthBBG is the authoritative replicated client health display;
        -- ShipHealthBar.Size.X.Scale is 1.0 on a fresh 2500/2500 hull and
        -- contracts with real hull damage. Treat it as confirmed health rather
        -- than falsely declaring a healthy boat gone after it leaves Tiki.
        local shipHealth = boat:FindFirstChild("ShipHealthBBG", true)
        local healthBar = shipHealth and shipHealth:FindFirstChild("ShipHealthBar", true)
        local visibleRatio = healthBar and healthBar:IsA("GuiObject") and tonumber(healthBar.Size.X.Scale) or nil
        if visibleRatio and visibleRatio >= 0 and visibleRatio <= 1 and maximum and maximum > 0 then
            return visibleRatio, visibleRatio * maximum, maximum, "ship_health_bar"
        end
        return nil, nil, maximum, "unreadable"
    end

    local function visibleTerrorShark()
        local runtime = EventFarm.Runtime
        local nearest, nearestDistance
        for _, object in ipairs(terrorSharkCandidates()) do
            local blockedUntil = runtime.targetBackoff[object]
            local d = targetOperationalDistance(object)
            if (not blockedUntil or now() >= blockedUntil)
                and isTerrorSharkTargetValid(object)
                and (not nearestDistance or d < nearestDistance) then
                nearest, nearestDistance = object, d
            end
        end
        return nearest
    end

    local function isSeaBeastName(name)
        local normalized = lower(name):gsub("[%s_%-]", "")
        return normalized:find("seabeast", 1, true) ~= nil
    end

    local function seaBeastCandidates()
        -- Sea Beast is deliberately restricted to Workspace.SeaBeasts. This
        -- excludes Leviathan/Terror Shark containers and avoids a broad enemy
        -- scan that could select an unrelated sea mob.
        local folder = Workspace and Workspace:FindFirstChild("SeaBeasts")
        if not folder then return {} end
        local output = {}
        for _, child in ipairs(folder:GetChildren()) do
            if child:IsA("Model") and isSeaBeastName(child.Name) then table.insert(output, child) end
        end
        return output
    end

    -- This is an identity boundary, not merely discovery filtering. A selection
    -- can change after driveSea found a target; a Terror Shark must never enter
    -- any Sea Beast travel, follow, evade or skill code in that transition.
    local function isSeaBeastTarget(target)
        local folder = Workspace and Workspace:FindFirstChild("SeaBeasts")
        return target ~= nil and target:IsA("Model") and target.Parent == folder and isSeaBeastName(target.Name)
    end

    local function seaBeastAlive(target)
        if not target or not target.Parent then return false end
        local hum = target:FindFirstChildOfClass("Humanoid")
        if hum then return hum.Health > 0 end
        local health = target:FindFirstChild("Health", true)
        if health and health:IsA("ValueBase") then
            local value = tonumber(health.Value)
            return value == nil or value > 0
        end
        return true
    end

    -- Removal from Workspace is not a kill signal: the model can stream out if
    -- the player is displaced. Success is reported only after an observed,
    -- terminal replicated health value, never merely because the target vanished.
    local function seaBeastTerminalDefeat(target)
        if not target or not target.Parent then return false, nil end
        local hum = target:FindFirstChildOfClass("Humanoid")
        if hum and hum.Health <= 0 then return true, "humanoid_health_zero" end
        local health = target:FindFirstChild("Health", true)
        if health and health:IsA("ValueBase") then
            local value = tonumber(health.Value)
            if value and value <= 0 then return true, "health_value_zero" end
        end
        return false, nil
    end

    local function isSeaBeastTargetValid(target)
        if not isSeaBeastTarget(target) or not seaBeastAlive(target) then return false end
        return targetOperationalDistance(target) <= EventFarm.SeaBeastMaxTargetDistance
    end

    local function horizontalDistance(a, b)
        if not a or not b then return math.huge end
        local dx, dz = a.X - b.X, a.Z - b.Z
        return math.sqrt(dx * dx + dz * dz)
    end

    function EventFarm.FrozenDimensionName(name)
        return lower(name):gsub("[%s_%-]", "") == "frozendimension"
    end

    -- The live world does not expose a stable server-side target API for this
    -- island. Detect only a replicated Model/BasePart with its exact normalized
    -- world name and a usable pivot. The bounded three-level walk covers the
    -- streamed Map/_WorldOrigin containers without touching every descendant
    -- (particles, projectiles and boat internals) on every cruise frame.
    function EventFarm.FindFrozenDimension()
        local runtime = EventFarm.Runtime
        local remembered = runtime.frozenDimension
        local anchor = runtime.seat and runtime.seat.Parent and runtime.seat.Position
            or (rootPart() and rootPart().Position)
        if remembered and remembered.instance and remembered.instance.Parent then
            local position = positionOf(remembered.instance)
            if position then
                remembered.position = position
                remembered.distance = anchor and horizontalDistance(anchor, position) or math.huge
            end
        end
        if remembered and now() - (remembered.lastScanAt or 0) < EventFarm.FrozenDimensionScanInterval then
            return remembered.instance and remembered.instance.Parent and remembered or nil
        end

        local nearest, nearestPosition, nearestDistance = nil, nil, nil
        local queue, cursor, seen = {{node = Workspace, depth = 0}}, 1, {}
        while cursor <= #queue do
            local row = queue[cursor]
            cursor = cursor + 1
            local node = row.node
            if node and node.Parent and not seen[node] then
                seen[node] = true
                if row.depth > 0 and (node:IsA("Model") or node:IsA("BasePart")) and EventFarm.FrozenDimensionName(node.Name) then
                    local position = positionOf(node)
                    local distanceToBoat = position and anchor and horizontalDistance(anchor, position) or math.huge
                    if position and (not nearestDistance or distanceToBoat < nearestDistance) then
                        nearest, nearestPosition, nearestDistance = node, position, distanceToBoat
                    end
                end
                if row.depth < EventFarm.FrozenDimensionSearchDepth then
                    for _, child in ipairs(node:GetChildren()) do
                        -- At Workspace itself, enter only the known streamed
                        -- island roots (while still accepting a direct named
                        -- Frozen Dimension). Nested branches then remain
                        -- bounded. This avoids walking boats, NPCs and effects.
                        local rootContainer = row.depth == 0 and (
                            lower(child.Name) == "map" or lower(child.Name) == "_worldorigin"
                            or lower(child.Name) == "locations" or EventFarm.FrozenDimensionName(child.Name)
                        )
                        if (child:IsA("Folder") or child:IsA("Model")) and (row.depth > 0 or rootContainer) then
                            queue[#queue + 1] = {node = child, depth = row.depth + 1}
                        elseif child:IsA("BasePart") and EventFarm.FrozenDimensionName(child.Name) then
                            queue[#queue + 1] = {node = child, depth = row.depth + 1}
                        end
                    end
                end
            end
        end
        runtime.frozenDimension = {
            instance = nearest,
            position = nearestPosition,
            distance = nearestDistance,
            lastScanAt = now(),
        }
        return nearest and runtime.frozenDimension or nil
    end

    -- The model root/pivot can sit below the sea. Its bounding-box top is the
    -- only live surface reference for a valid model. In particular, never floor
    -- a valid box by the player's Y: evade puts the player high temporarily and
    -- that feedback loop was causing each return/follow to climb without limit.
    local function seaBeastSurfaceAnchor(target, referencePosition)
        local root = targetRoot(target)
        if not root then return nil, nil end
        local runtime = EventFarm.Runtime
        runtime.seaBeastSurfaceCache = runtime.seaBeastSurfaceCache or setmetatable({}, {__mode = "k"})
        local cached = runtime.seaBeastSurfaceCache[target]
        local cacheAge = cached and now() - (cached.at or -math.huge) or nil
        local anchor, source = nil, nil
        local ok, box, size = pcall(function() return target:GetBoundingBox() end)
        if ok and box and size and size.Y > 0 then
            local candidate = Vector3.new(box.Position.X, box.Position.Y + size.Y * 0.5, box.Position.Z)
            -- Streaming can transiently produce a radically different box Y for
            -- the same live Sea Beast. Preserve the recent stable surface rather
            -- than falsely calling the player too high/low and abandoning it.
            if cached and cached.position and cacheAge <= EventFarm.SeaBeastSurfaceAnchorCacheSeconds
                and math.abs(candidate.Y - cached.position.Y) > EventFarm.SeaBeastSurfaceMaximumVerticalJump then
                anchor, source = cached.position, "bounding_box_top_vertical_outlier"
            else
                anchor, source = candidate, "bounding_box_top"
                runtime.seaBeastSurfaceCache[target] = {position = anchor, at = now()}
                cacheAge = 0
            end
        else
            if cached and cached.position and cacheAge <= EventFarm.SeaBeastSurfaceAnchorCacheSeconds then
                anchor, source = cached.position, "cached_bounding_box_top"
            else
                anchor, source = root.Position, "root_fallback"
                -- Only a *nearby* player reference may protect an initial
                -- missing box. A high evade/combat position is intentionally
                -- ignored rather than becoming the next surface anchor.
                local reference = referencePosition
                local aboveRoot = reference and (reference.Y - root.Position.Y) or nil
                if reference and aboveRoot and aboveRoot > EventFarm.SeaBeastSurfaceReferenceDrop
                    and aboveRoot <= EventFarm.SeaBeastFallbackReferenceMaximumAboveRoot then
                    anchor = Vector3.new(anchor.X, reference.Y - EventFarm.SeaBeastSurfaceReferenceDrop, anchor.Z)
                    source = "root_fallback_reference_floor_bounded"
                end
            end
        end
        return anchor, {source = source, root = root.Position, anchor = anchor, boxSizeY = ok and size and size.Y or nil, cacheAge = cacheAge}
    end

    -- Spawn uses a transient submerged bounding box. This deliberately reads
    -- raw replicated geometry (no cache/fallback) until both the model root and
    -- its top are vertically stable for a continuous window. It prevents the
    -- first below-water box from becoming the combat cache.
    local function waitForSeaBeastSpawnSurface(generation, target)
        local runtime = EventFarm.Runtime
        runtime.seaBeastSurfaceCache = runtime.seaBeastSurfaceCache or setmetatable({}, {__mode = "k"})
        runtime.seaBeastSurfaceCache[target] = nil
        local began, stableSince, previous = now(), nil, nil
        journal("sea_beast_spawn_settle_enter", {target = target.Name, minimum = EventFarm.SeaBeastSpawnSettleMinimumSeconds, stable = EventFarm.SeaBeastSpawnSettleStableSeconds})
        while isCurrent(generation) and canContinueTarget("sea_beast") and isSeaBeastTarget(target) and seaBeastAlive(target) do
            local root = targetRoot(target)
            local ok, box, size = pcall(function() return target:GetBoundingBox() end)
            local candidate = ok and box and size and size.Y >= EventFarm.SeaBeastSpawnMinimumBoxHeight
                and Vector3.new(box.Position.X, box.Position.Y + size.Y * 0.5, box.Position.Z) or nil
            if root and candidate then
                local verticallyStable = previous
                    and math.abs(candidate.Y - previous.anchor.Y) <= EventFarm.SeaBeastSpawnMaximumVerticalDrift
                    and math.abs(root.Position.Y - previous.root.Y) <= EventFarm.SeaBeastSpawnMaximumVerticalDrift
                if verticallyStable then
                    stableSince = stableSince or now()
                else
                    stableSince = nil
                end
                previous = {anchor = candidate, root = root.Position, sizeY = size.Y}
                if now() - began >= EventFarm.SeaBeastSpawnSettleMinimumSeconds and stableSince
                    and now() - stableSince >= EventFarm.SeaBeastSpawnSettleStableSeconds then
                    runtime.seaBeastSurfaceCache[target] = {position = candidate, at = now()}
                    local info = {source = "spawn_settled_bounding_box_top", root = root.Position, anchor = candidate, boxSizeY = size.Y}
                    journal("sea_beast_spawn_settle_ready", {target = target.Name, elapsed = now() - began, anchor = vectorSnapshot(candidate), root = vectorSnapshot(root.Position), boxSizeY = size.Y})
                    return true, info
                end
            else
                stableSince, previous = nil, nil
            end
            if now() - began >= EventFarm.SeaBeastSpawnSettleMaximumSeconds then
                journal("sea_beast_spawn_settle_timeout", {target = target.Name, hadBox = candidate ~= nil, elapsed = now() - began})
                return false, "spawn_surface_not_stable"
            end
            task.wait(EventFarm.SeaBeastSpawnSettleSampleSeconds)
        end
        return false, "spawn_target_lost_or_stopped"
    end

    -- The capture uses target-local yaw. The saved numbers are right/forward/
    -- height around the live Sea Beast, so dynamic map spawn coordinates never
    -- enter the preference or follow calculation.
    local function seaBeastYawFrame(target)
        local root = targetRoot(target)
        if not root then return nil end
        local look = root.CFrame.LookVector
        local flat = Vector3.new(look.X, 0, look.Z)
        if flat.Magnitude < 0.01 then return nil end
        return CFrame.lookAt(Vector3.zero, flat.Unit)
    end

    local function capturedSeaBeastCombatOffset(target)
        local saved = State.eventFarmSeaBeastAttackOffset
        if type(saved) ~= "table" then return nil, nil, nil end
        local right, forward, height = tonumber(saved.right), tonumber(saved.forward), tonumber(saved.height)
        if not right or not forward or not height then return nil, nil, nil end
        local yaw = seaBeastYawFrame(target)
        if not yaw then return nil, nil, nil end
        local horizontal = yaw:VectorToWorldSpace(Vector3.new(right, 0, forward))
        return horizontal, math.max(EventFarm.SeaBeastCapturedOffsetMinimumHeight, math.min(EventFarm.SeaBeastCapturedOffsetMaximumHeight, height)), "captured_relative"
    end

    local function seaBeastCombatPlacement(target, playerPosition)
        local surface, anchorInfo = seaBeastSurfaceAnchor(target, playerPosition)
        if not surface then return nil, nil, nil, anchorInfo, nil end
        local capturedOffset, capturedHeight, capturedSource = capturedSeaBeastCombatOffset(target)
        if capturedOffset and capturedHeight then return surface, capturedOffset, capturedHeight, anchorInfo, capturedSource end
        local flat = playerPosition and Vector3.new(playerPosition.X - surface.X, 0, playerPosition.Z - surface.Z) or Vector3.new(0, 0, 1)
        if flat.Magnitude < 1 then flat = Vector3.new(0, 0, 1) end
        return surface, flat.Unit * EventFarm.SeaBeastCombatLateralOffset, EventFarm.SeaBeastCombatHeight, anchorInfo, "adaptive_default"
    end

    local function seaBeastCombatAltitudeSafe(target)
        local pRoot = rootPart()
        local surface, surfaceInfo = seaBeastSurfaceAnchor(target)
        if not pRoot or not surface then return false, "surface_or_player_missing", nil end
        local height = pRoot.Position.Y - surface.Y
        if height < EventFarm.SeaBeastTravelMinimumHeightAboveSurface
            or height > EventFarm.SeaBeastCombatMaximumHeightAboveSurface then
            return false, "height_out_of_bounds", {heightAboveSurface = height, anchor = surface, anchorSource = surfaceInfo and surfaceInfo.source, player = pRoot.Position}
        end
        return true, nil, {heightAboveSurface = height, anchor = surface, anchorSource = surfaceInfo and surfaceInfo.source, player = pRoot.Position}
    end

    local function seaBeastAltitudeAbandonMessage(reason, geometry)
        if reason == "height_out_of_bounds" and geometry and geometry.heightAboveSurface then
            return string.format("Sea Beast abandonado: altura de combate fora da faixa segura (%.0f studs; permitido %d–%d).", geometry.heightAboveSurface, EventFarm.SeaBeastTravelMinimumHeightAboveSurface, EventFarm.SeaBeastCombatMaximumHeightAboveSurface)
        end
        return "Sea Beast abandonado: não foi possível confirmar uma altura de combate segura."
    end

    local function visibleSeaBeast()
        local runtime = EventFarm.Runtime
        local nearest, nearestDistance
        for _, object in ipairs(seaBeastCandidates()) do
            local blockedUntil = runtime.targetBackoff[object]
            local d = targetOperationalDistance(object)
            if (not blockedUntil or now() >= blockedUntil)
                and isSeaBeastTargetValid(object)
                and (not nearestDistance or d < nearestDistance) then
                nearest, nearestDistance = object, d
            end
        end
        return nearest
    end

    -- Temporary Sea Beast boat autonomy -------------------------------------
    --
    -- The hull remains entirely on the normal ShipController route. The mode
    -- only reasserts the existing Movement state after that controller's own
    -- frame, retaining the exact pattern proven in the 60-second standalone
    -- test: active/in-use native Movement, Velocity/Steer, BodyGyro heading
    -- and the boat's existing BodyPosition. No CFrame hull move, anchor,
    -- added force/constraint, Remote or collision change is used here.
    local function boatAutonomyRecovery(mode, reason)
        local at = now()
        if at - (mode.lastRecoveryAt or 0) < 0.75 then return end
        mode.lastRecoveryAt = at
        mode.recoveries = (mode.recoveries or 0) + 1
        -- Journal the first reactivation and then sparse checkpoints; a
        -- controller can intentionally clear state every render frame while
        -- unseated, so per-frame journal rows would conceal real diagnostics.
        if mode.recoveries == 1 or mode.recoveries % 12 == 0 then
            journal("sea_beast_boat_autonomy_reassert", {
                target = mode.target and mode.target.Name or nil,
                reason = reason,
                recoveries = mode.recoveries,
            })
        end
    end

    seaBeastAutonomyCommand = function()
        local runtime = EventFarm.Runtime
        local mode = runtime.seaBeastBoatAutonomy
        if not mode or mode.finalized == true then return nil end
        if not runtime.active or runtime.targetKind ~= "sea_beast" or runtime.target ~= mode.target then return nil end
        if not runtime.seat or not runtime.seat.Parent or not runtime.original then return nil end

        -- A non-final false flag is an observed controller interruption, not a
        -- user stop. Reactivate it in-place without a new dismount/prime.
        if mode.active ~= true then
            mode.active = true
            boatAutonomyRecovery(mode, "lease_was_inactive")
        end

        local movement = runtime.original.movement
        if not movement then return nil end
        if movement.Active ~= true or movement.InUse ~= true then
            boatAutonomyRecovery(mode, "native_movement_not_armed")
        end

        local seat = runtime.seat
        local targetPart = targetRoot(mode.target)
        local center = targetPart and targetPart.Position or mode.lastCenter
        if not center then return nil end
        mode.lastCenter = center

        -- Lift starts first. While rising, retain the existing live cruise
        -- direction rather than beginning the large circle low over the sea.
        if mode.orbitArmed ~= true then
            local primeDirection = runtime.direction
            if not primeDirection or primeDirection.Magnitude < 0.01 then
                primeDirection = Vector3.new(seat.CFrame.LookVector.X, 0, seat.CFrame.LookVector.Z)
            end
            if not primeDirection or primeDirection.Magnitude < 0.01 then return nil end
            return {
                direction = primeDirection.Unit,
                speed = math.max(80, tonumber(runtime.speed) or EventFarm.SeaBeastBoatAutonomySpeed),
                steer = 0,
            }
        end

        local radial = Vector3.new(seat.Position.X - center.X, 0, seat.Position.Z - center.Z)
        if radial.Magnitude < 8 then radial = mode.lastRadial end
        if not radial or radial.Magnitude < 0.01 then
            radial = Vector3.new(seat.CFrame.LookVector.X, 0, seat.CFrame.LookVector.Z)
        end
        if radial.Magnitude < 0.01 then radial = Vector3.new(0, 0, 1) end
        radial = radial.Unit
        mode.lastRadial = radial

        local radius = EventFarm.SeaBeastBoatAutonomyRadius
        local outer = math.max(radius + 80, EventFarm.SeaBeastBoatAutonomyOuterRadius)
        local radialDistance = Vector3.new(seat.Position.X - center.X, 0, seat.Position.Z - center.Z).Magnitude
        local correction
        if radialDistance < radius * 0.70 then
            correction = 0.92 -- leave the centre before committing to the circle
        elseif radialDistance > outer then
            correction = -0.92 -- never allow the return distance to run away
        else
            correction = math.clamp((radius - radialDistance) / radius * 1.35, -0.58, 0.58)
        end
        local sign = mode.turnSign or 1
        local tangent = Vector3.new(-radial.Z * sign, 0, radial.X * sign)
        local direction = tangent * (1 - math.abs(correction) * 0.22) + radial * correction
        if direction.Magnitude < 0.01 then direction = tangent end
        mode.lastDirection = direction.Unit
        mode.lastRadius = radialDistance
        return {
            direction = mode.lastDirection,
            speed = EventFarm.SeaBeastBoatAutonomySpeed,
            steer = EventFarm.SeaBeastBoatAutonomySteer * sign,
        }
    end

    stopSeaBeastBoatAutonomy = function(reason)
        local runtime = EventFarm.Runtime
        local mode = runtime.seaBeastBoatAutonomy
        if not mode or mode.finalized == true then return false end
        mode.active = false
        mode.finalized = true
        mode.endedAt = now()
        mode.endReason = tostring(reason or "released")
        journal("sea_beast_boat_autonomy_exit", {
            target = mode.target and mode.target.Name or nil,
            reason = mode.endReason,
            recoveries = mode.recoveries or 0,
            lastRadius = mode.lastRadius,
        })
        return true
    end

    startSeaBeastBoatAutonomy = function(generation, target)
        local runtime = EventFarm.Runtime
        if EventFarm.SeaBeastBoatAutonomyExperiment ~= true then return false, "experiment_disabled" end
        if not isCurrent(generation) or not canContinueTarget("sea_beast") or runtime.target ~= target then
            return false, "sea_beast_target_not_current"
        end
        if not runtime.nativeReady or not runtime.original or not runtime.seat or not localOccupies(runtime.seat) then
            return false, "native_boat_not_seated_ready"
        end
        if not targetRoot(target) then return false, "sea_beast_root_missing" end

        -- Cruise transit changes hull collision state while seated. The orbit
        -- keeps the regular native hull and must be its sole temporary writer.
        stopTransitAssist("sea_beast_boat_autonomy_enter")
        local seed = targetRoot(target).Position
        local radial = Vector3.new(runtime.seat.Position.X - seed.X, 0, runtime.seat.Position.Z - seed.Z)
        if radial.Magnitude < 8 then
            radial = Vector3.new(runtime.seat.CFrame.LookVector.X, 0, runtime.seat.CFrame.LookVector.Z)
        end
        local mode = {
            active = true,
            finalized = false,
            target = target,
            startedAt = now(),
            lastCenter = seed,
            lastRadial = radial.Magnitude > 0.01 and radial.Unit or Vector3.new(0, 0, 1),
            lastDirection = nil,
            lastRadius = radial.Magnitude,
            turnSign = 1,
            orbitArmed = false,
            recoveries = 0,
            lastRecoveryAt = 0,
            preOrbitLift = runtime.targetLift,
        }
        runtime.seaBeastBoatAutonomy = mode
        setLift(EventFarm.SeaBeastBoatAutonomyLift, EventFarm.SeaBeastBoatAutonomyLiftRate)
        setPhase("sea_beast_boat_lifting", "autonomy_prepare")
        journal("sea_beast_boat_autonomy_enter", {
            target = target.Name,
            lift = EventFarm.SeaBeastBoatAutonomyLift,
            radius = EventFarm.SeaBeastBoatAutonomyRadius,
            outerRadius = EventFarm.SeaBeastBoatAutonomyOuterRadius,
            speed = EventFarm.SeaBeastBoatAutonomySpeed,
            steer = EventFarm.SeaBeastBoatAutonomySteer,
        })

        if not waitForLift(generation, EventFarm.SeaBeastBoatAutonomyLift, 12, 12) then
            stopSeaBeastBoatAutonomy("lift_not_confirmed")
            return false, "sea_beast_boat_lift_not_confirmed"
        end
        if not isCurrent(generation) or not canContinueTarget("sea_beast") or runtime.target ~= target
            or not localOccupies(runtime.seat) then
            stopSeaBeastBoatAutonomy("pre_dismount_guard")
            return false, "sea_beast_boat_pre_dismount_guard"
        end

        -- Keep the normal native controller armed for the measured priming
        -- window before the player leaves the VehicleSeat. The RenderStep
        -- writer is already active, so the following dismount is not a new
        -- worker or a race with ShipController initialization.
        mode.orbitArmed = true
        setPhase("sea_beast_boat_orbit_priming", "height_" .. tostring(EventFarm.SeaBeastBoatAutonomyLift) .. "_reached")
        local deadline = now() + EventFarm.SeaBeastBoatAutonomyPrimeSeconds
        while isCurrent(generation) and canContinueTarget("sea_beast") and runtime.target == target
            and localOccupies(runtime.seat) and now() < deadline do
            task.wait(0.04)
        end
        if not isCurrent(generation) or runtime.target ~= target or not localOccupies(runtime.seat) then
            stopSeaBeastBoatAutonomy("prime_interrupted")
            return false, "sea_beast_boat_prime_interrupted"
        end
        journal("sea_beast_boat_autonomy_primed", {
            target = target.Name,
            lift = runtime.lift,
            primeSeconds = EventFarm.SeaBeastBoatAutonomyPrimeSeconds,
        })
        return true
    end

    -- Temporary Terror Shark boat autonomy ----------------------------------
