    raidBoatAutonomyCommand = function()
        local runtime = EventFarm.Runtime
        local mode = runtime.raidBoatAutonomy
        if not mode or mode.finalized == true then return nil end
        if not runtime.active or runtime.targetKind ~= mode.kind or runtime.target ~= mode.target then return nil end
        if not runtime.seat or not runtime.seat.Parent or not runtime.original or not raidBoatAlive(mode.target) then return nil end

        if mode.active ~= true then
            mode.active = true
            raidBoatAutonomyRecovery(mode, "lease_was_inactive")
        end
        local movement = runtime.original.movement
        if not movement then return nil end
        if movement.Active ~= true or movement.InUse ~= true then
            raidBoatAutonomyRecovery(mode, "native_movement_not_armed")
        end

        local seat = runtime.seat
        local targetPart = raidBoatRoot(mode.target)
        local center = targetPart and targetPart.Position or mode.lastCenter
        if not center then return nil end
        mode.lastCenter = center
        if mode.orbitArmed ~= true then
            local primeDirection = runtime.direction
            if not primeDirection or primeDirection.Magnitude < 0.01 then
                primeDirection = Vector3.new(seat.CFrame.LookVector.X, 0, seat.CFrame.LookVector.Z)
            end
            if not primeDirection or primeDirection.Magnitude < 0.01 then return nil end
            return {direction = primeDirection.Unit, speed = EventFarm.RaidBoatAutonomySpeed, steer = 0}
        end

        local radial = Vector3.new(seat.Position.X - center.X, 0, seat.Position.Z - center.Z)
        if radial.Magnitude < 8 then radial = mode.lastRadial end
        if not radial or radial.Magnitude < 0.01 then radial = Vector3.new(seat.CFrame.LookVector.X, 0, seat.CFrame.LookVector.Z) end
        if radial.Magnitude < 0.01 then radial = Vector3.new(0, 0, 1) end
        radial = radial.Unit
        mode.lastRadial = radial

        local radius = EventFarm.RaidBoatAutonomyRadius
        local outer = math.max(radius + 80, EventFarm.RaidBoatAutonomyOuterRadius)
        local radialDistance = Vector3.new(seat.Position.X - center.X, 0, seat.Position.Z - center.Z).Magnitude
        local correction
        if radialDistance < radius * 0.82 then
            correction = 0.96
        elseif radialDistance > outer then
            correction = -0.96
        else
            correction = math.clamp((radius - radialDistance) / radius * 1.45, -0.54, 0.54)
        end
        local sign = mode.turnSign or 1
        local tangent = Vector3.new(-radial.Z * sign, 0, radial.X * sign)
        local direction = tangent * (1 - math.abs(correction) * 0.20) + radial * correction
        if direction.Magnitude < 0.01 then direction = tangent end
        mode.lastDirection, mode.lastRadius = direction.Unit, radialDistance
        return {
            direction = mode.lastDirection,
            speed = EventFarm.RaidBoatAutonomySpeed,
            steer = EventFarm.RaidBoatAutonomySteer * sign,
        }
    end

    stopRaidBoatAutonomy = function(reason)
        local runtime = EventFarm.Runtime
        local mode = runtime.raidBoatAutonomy
        if not mode or mode.finalized == true then return false end
        mode.active, mode.finalized, mode.endedAt = false, true, now()
        mode.endReason = tostring(reason or "released")
        journal("raid_boat_autonomy_exit", {
            target = mode.target and mode.target.Name or nil,
            kind = mode.kind,
            reason = mode.endReason,
            recoveries = mode.recoveries or 0,
            lastRadius = mode.lastRadius,
        })
        return true
    end

    startRaidBoatAutonomy = function(generation, target, kind)
        local runtime = EventFarm.Runtime
        if not isRaidBoatKind(kind) or not isCurrent(generation) or runtime.targetKind ~= kind or runtime.target ~= target then
            return false, "raid_boat_target_not_current"
        end
        if not isRaidBoatTargetValid(target, kind) or not raidBoatRoot(target) then return false, "raid_boat_target_invalid" end
        if not runtime.nativeReady or not runtime.original or not runtime.seat or not localOccupies(runtime.seat) then
            return false, "native_boat_not_seated_ready"
        end
        local released, releaseReason = releaseEventFarmTravel("raid_boat_orbit_prepare")
        if not released then return false, "travel_lock_" .. tostring(releaseReason) end

        stopTransitAssist("raid_boat_autonomy_enter")
        local seed = raidBoatRoot(target).Position
        local radial = Vector3.new(runtime.seat.Position.X - seed.X, 0, runtime.seat.Position.Z - seed.Z)
        if radial.Magnitude < 8 then radial = Vector3.new(runtime.seat.CFrame.LookVector.X, 0, runtime.seat.CFrame.LookVector.Z) end
        local mode = {
            active = true, finalized = false, target = target, kind = kind, startedAt = now(), lastCenter = seed,
            lastRadial = radial.Magnitude > 0.01 and radial.Unit or Vector3.new(0, 0, 1),
            lastDirection = nil, lastRadius = radial.Magnitude, turnSign = 1, orbitArmed = false,
            recoveries = 0, lastRecoveryAt = 0, preOrbitLift = runtime.targetLift,
        }
        runtime.raidBoatAutonomy = mode
        setLift(EventFarm.RaidBoatAutonomyLift, EventFarm.RaidBoatAutonomyLiftRate)
        setPhase("raid_boat_orbit_lifting", "protective_orbit_prepare")
        journal("raid_boat_autonomy_enter", {
            target = target.Name, kind = kind, lift = EventFarm.RaidBoatAutonomyLift,
            radius = EventFarm.RaidBoatAutonomyRadius, outerRadius = EventFarm.RaidBoatAutonomyOuterRadius,
            speed = EventFarm.RaidBoatAutonomySpeed, steer = EventFarm.RaidBoatAutonomySteer,
        })
        if not waitForLift(generation, EventFarm.RaidBoatAutonomyLift, 12, 12) then
            stopRaidBoatAutonomy("lift_not_confirmed")
            return false, "raid_boat_lift_not_confirmed"
        end
        if not isCurrent(generation) or runtime.targetKind ~= kind or runtime.target ~= target or not localOccupies(runtime.seat) then
            stopRaidBoatAutonomy("pre_dismount_guard")
            return false, "raid_boat_pre_dismount_guard"
        end
        mode.orbitArmed = true
        setPhase("raid_boat_orbit_priming", "height_" .. tostring(EventFarm.RaidBoatAutonomyLift) .. "_reached")
        local deadline = now() + EventFarm.RaidBoatAutonomyPrimeSeconds
        while isCurrent(generation) and runtime.targetKind == kind and runtime.target == target
            and localOccupies(runtime.seat) and now() < deadline do task.wait(0.04) end
        if not isCurrent(generation) or runtime.target ~= target or not localOccupies(runtime.seat) then
            stopRaidBoatAutonomy("prime_interrupted")
            return false, "raid_boat_prime_interrupted"
        end
        journal("raid_boat_autonomy_primed", {target = target.Name, kind = kind, lift = runtime.lift, primeSeconds = EventFarm.RaidBoatAutonomyPrimeSeconds})
        return true
    end

    targetAlive = function(target)
        if not target or not target.Parent then return false end
        local hum = target:FindFirstChildOfClass("Humanoid")
        return not hum or hum.Health > 0
    end

    distance = function(a, b)
        if not a or not b then return math.huge end
        return (a - b).Magnitude
    end

    local function tikiPosition()
        local worldOrigin = Workspace and Workspace:FindFirstChild("_WorldOrigin")
        local locations = worldOrigin and worldOrigin:FindFirstChild("Locations")
        local tiki = locations and locations:FindFirstChild("Tiki Outpost")
        return tiki and positionOf(tiki) or nil
    end

    local function getTikiOpenSeaRoute()
        local worldOrigin = Workspace and Workspace:FindFirstChild("_WorldOrigin")
        local spawns = worldOrigin and worldOrigin:FindFirstChild("BoatSpawns")
        local tiki = tikiPosition()
        local chosen
        if spawns and tiki then
            for _, spawn in ipairs(spawns:GetChildren()) do
                local offset = spawn.Position - tiki
                local look = Vector3.new(spawn.CFrame.LookVector.X, 0, spawn.CFrame.LookVector.Z)
                if offset.Magnitude < 1200 and look.Magnitude > 0.01 then
                    look = look.Unit
                    -- The west-facing spawn is the validated endless-sea side,
                    -- opposite Floating Turtle/Castle. Prefer the most westward
                    -- real map marker rather than an arbitrary radial vector.
                    if look.X < -0.8 and (not chosen or look.X < chosen.direction.X) then
                        chosen = {spawn = spawn, direction = look}
                    end
                end
            end
        end
        if chosen then return chosen end
        return {spawn = nil, direction = EventFarm.TikiOpenSeaDirection, fallback = true}
    end

    local function isAtTiki(position)
        if not position then return false end
        -- Location decides whether the expensive Tiki exit is needed. Danger
        -- level is used only for height calibration; it can be stale while a
        -- newly spawned boat is still beside the island.
        local tiki = tikiPosition()
        return tiki and (position - tiki).Magnitude <= 1800 or false
    end

    local function requiresFreshBoatAtTiki()
        local runtime = EventFarm.Runtime
        local root = rootPart()
        if not root or not isAtTiki(root.Position) then return false end
        if runtime.tikiReturnNeedsFreshBoat == true then
            return true, runtime.tikiReturnReason or "tiki_return_pending"
        end
        -- A replacement Character is the reliable signature of a reset/death.
        -- Do not teleport it to an old seat; it is already back at Tiki.
        if runtime.boatCharacter and player and player.Character and runtime.boatCharacter ~= player.Character then
            return true, "character_replaced_at_tiki"
        end
        -- This also covers a server relocation to Tiki that did not produce a
        -- detectable Character replacement: an offshore hull is never pulled
        -- back or reclaimed from the dealer area.
        local seat = runtime.seat
        if seat and seat.Parent and not isAtTiki(seat.Position) then
            return true, "player_at_tiki_old_boat_offshore"
        end
        return false
    end

    -- Dynamic sea islands are not part of the normal map marker calibration.
    -- We only treat explicit Mirage/Prehistoric instances as this clearance
    -- case; ordinary rocks continue through the existing noclip/stall logic.
    local function namedSeaIsland(item)
        if not item or not (item:IsA("Model") or item:IsA("BasePart")) then return false end
        local name = lower(item.Name)
        return name:find("mirage", 1, true) ~= nil or name:find("prehistoric", 1, true) ~= nil
    end

    local function islandBounds(item)
        if not item then return nil, 0 end
        if item:IsA("Model") then
            local ok, box, size = pcall(function() return item:GetBoundingBox() end)
            if ok and box and size then return box.Position, math.max(size.X, size.Z) * 0.5 end
        end
        local position = positionOf(item)
        if item:IsA("BasePart") then
            return position, math.max(item.Size.X, item.Size.Z) * 0.5
        end
        return position, 0
    end

    local function refreshNamedSeaIslands()
        local runtime = EventFarm.Runtime
        local scan = runtime.islandScan or {nextAt = 0, candidates = {}}
        runtime.islandScan = scan
        if now() < (scan.nextAt or 0) then return scan.candidates end
        scan.nextAt = now() + 1.0
        scan.candidates = {}
        -- Dynamic Mirage and Prehistoric instances may be parented at different
        -- points per sea/server. A throttled workspace scan avoids assuming a
        -- fixed parent while keeping the cruise loop light.
        for _, item in ipairs(Workspace:GetDescendants()) do
            if namedSeaIsland(item) then table.insert(scan.candidates, item) end
        end
        return scan.candidates
    end

    local function namedIslandAhead()
        local runtime = EventFarm.Runtime
        local seat, direction = runtime.seat, runtime.direction
        if not seat or not direction or direction.Magnitude <= 0.01 then return nil end
        local heading = Vector3.new(direction.X, 0, direction.Z)
        if heading.Magnitude <= 0.01 then return nil end
        heading = heading.Unit
        local nearest
        for _, island in ipairs(refreshNamedSeaIslands()) do
            if island and island.Parent then
                local position, radius = islandBounds(island)
                if position then
                    local delta = Vector3.new(position.X - seat.Position.X, 0, position.Z - seat.Position.Z)
                    local centerDistance = delta.Magnitude
                    if centerDistance > 0.1 then
                        local forward = delta.Unit:Dot(heading)
                        local edgeDistance = math.max(0, centerDistance - (radius or 0))
                        if forward >= EventFarm.IslandAheadDot and edgeDistance <= EventFarm.IslandAheadDistance
                            and (not nearest or edgeDistance < nearest.distance) then
                            nearest = {instance = island, name = island.Name, distance = edgeDistance, forward = forward}
                        end
                    end
                end
            end
        end
        return nearest
    end

    local function updateNamedIslandClearance()
        local runtime = EventFarm.Runtime
        local clearance = runtime.islandClearance
        local island = namedIslandAhead()
        if island then
            local newlyActive = not clearance.active or clearance.name ~= island.name
            clearance.active = true
            clearance.name = island.name
            clearance.distance = island.distance
            clearance.lastSeenAt = now()
            -- Preserve any larger recovery/obstacle lift. This writer only
            -- establishes the 500-stud BoatLocal Float baseline for an island
            -- that is actually ahead of the native travel heading.
            if runtime.targetLift < EventFarm.IslandClearanceLift then
                setLift(EventFarm.IslandClearanceLift, EventFarm.IslandClearanceRate)
            end
            if newlyActive then
                journal("named_island_clearance", {name = island.name, distance = island.distance, lift = EventFarm.IslandClearanceLift, forward = island.forward})
                notify("Farm Eventos", "Ilha à frente: mantendo altura 500 (" .. tostring(island.name) .. ").", "info", "island_clearance_" .. tostring(island.name), 5)
            end
            return true
        end
        if clearance.active and now() - (clearance.lastSeenAt or 0) >= EventFarm.IslandClearanceHold then
            journal("named_island_clearance_clear", {name = clearance.name, distance = clearance.distance})
            clearance.active = false
            clearance.name = nil
            clearance.distance = nil
        end
        return clearance.active == true
    end

    local function findTikiWestDealer()
        -- Prefer the exact verified dock point. Scan only to bind the visible
        -- model to that point; never choose the nearest/east Boat Dealer.
        local verified = EventFarm.VerifiedTikiWestDealer
        local best, bestDistance
        local roots = {Workspace and Workspace:FindFirstChild("NPCs"), Workspace}
        for _, container in ipairs(roots) do
            if container then
                for _, item in ipairs(container:GetDescendants()) do
                    if lower(item.Name):find("boat dealer", 1, true) then
                        local model = item:IsA("Model") and item or item:FindFirstAncestorOfClass("Model")
                        local position = positionOf(model or item)
                        local d = position and (position - verified).Magnitude or math.huge
                        if d <= 250 and (not bestDistance or d < bestDistance) then
                            best, bestDistance = {object = model or item, position = position, verified = true}, d
                        end
                    end
                end
            end
        end
        -- The coordinate itself was measured at the correct WEST dealer. It is
        -- a safe fallback while that NPC model is not yet streamed locally.
        return best or {object = nil, position = verified, verified = true, fallback = true}
    end

    local function acquireBoat(generation, options)
        options = options or {}
        local selected = State.eventFarmBoat
        if type(selected) ~= "string" or selected == "" then return nil, "boat_not_selected" end
        local runtime = EventFarm.Runtime
        local existing = ownedBoatByName(selected)
        local previousBoat = existing
        local root = rootPart()
        local forceFreshBoat = runtime.forceFreshBoat == true
        local freshAtTiki, tikiReason = requiresFreshBoatAtTiki()
        if freshAtTiki then
            forceFreshBoat = true
            runtime.forceFreshBoat = true
            runtime.tikiReturnNeedsFreshBoat = true
            runtime.tikiReturnReason = tikiReason
            journal("tiki_return_fresh_boat_required", {reason = tikiReason, existingBoat = existing and existing.Name or nil})
        end
        if existing and not forceFreshBoat then
            local seat = rootSeat(existing)
            local ratio, health, maximum, healthSource = boatHealthRatio(existing)
            -- Health can replicate a few frames after a hull appears. Do not
            -- silently accept an unknown value: wait briefly, then treat it as
            -- unsafe rather than navigating back to a potentially dying hull.
            local healthDeadline = now() + 1.0
            while ratio == nil and isCurrent(generation) and existing.Parent and now() < healthDeadline do
                task.wait(0.10)
                ratio, health, maximum, healthSource = boatHealthRatio(existing)
            end
            root = rootPart()
            local seatDistance = root and seat and seat.Parent and (root.Position - seat.Position).Magnitude or math.huge
            local reusable = root ~= nil and seat ~= nil and seat.Parent ~= nil
                and ratio ~= nil and ratio >= EventFarm.BoatReuseMinimumHealthRatio
                and seatDistance <= EventFarm.BoatReuseMaximumSeatDistance
            journal(reusable and "boat_reuse_approved" or "boat_reuse_rejected", {
                boat = existing.Name,
                ratio = ratio,
                health = health,
                maximum = maximum,
                healthSource = healthSource,
                seatDistance = seatDistance,
                minimumRatio = EventFarm.BoatReuseMinimumHealthRatio,
                maximumDistance = EventFarm.BoatReuseMaximumSeatDistance,
                seatValid = seat ~= nil and seat.Parent ~= nil,
            })
            if reusable then return existing end
            -- A far, unparented, unknown-health or sub-50% hull is never
            -- reclaimed. BuyBoat must produce a clean instance instead.
            forceFreshBoat = true
            runtime.forceFreshBoat = true
        end
        -- A live selected target at activation owns the immediate checkpoint.
        -- Do not spend it travelling to/buying a hull if no existing hull is
        -- safely reusable: the direct combat adapter can engage it now and the
        -- regular boat pipeline resumes only after that encounter resolves.
        if options.skipPurchase == true then
            journal("checkpoint_boat_unavailable", {
                reason = existing and "existing_boat_not_reusable" or "no_owned_boat",
                selectedBoat = selected,
                checkpointKind = options.checkpointKind,
            })
            return nil, existing and "checkpoint_existing_boat_not_reusable" or "checkpoint_no_owned_boat"
        end
        local dealer = findTikiWestDealer()
        if not dealer then return nil, "boat_dealer_not_found" end
        if not root then return nil, "character_missing" end
        local dealerDistance = (root.Position - dealer.position).Magnitude
        if dealerDistance > 18 then
            setPhase("going_to_dealer")
            -- Combat death respawns can place the character a short distance from
            -- the verified west Tiki dealer. Farm:MoveTo selects a generic map
            -- route in that case and was observed to abort before arrival. Use
            -- the shared local direct route first, then retain Farm:MoveTo only
            -- as a compatible fallback. This is a travel failure recovery, not
            -- an NPC scan or a different dealer selection.
            local teleport = Flow.Features.Teleport
            local arrived, moveReason = false, "direct_travel_unavailable"
            if teleport and type(teleport.TravelDirectToPosition) == "function" then
                arrived, moveReason = teleport:TravelDirectToPosition(dealer.position, "sea_event_boat_dealer", "Boat Dealer", {
                    ignoreNoSupportWater = true, disableAdaptiveClearance = true,
                    holdArrivalVelocity = true, arrivalConfirmSeconds = 0.35, maxAttempts = 2,
                })
            end
            if not arrived then
                local farm = Flow.Features.Farm
                if farm and type(farm.MoveTo) == "function" then
                    arrived, moveReason = farm:MoveTo(CFrame.new(dealer.position), "sea_event_boat_dealer")
                end
            end
            journal("boat_dealer_travel", {directDistance = dealerDistance, arrived = arrived == true, reason = moveReason, verified = dealer.verified == true, fallbackPosition = dealer.fallback == true})
            if not arrived or not isCurrent(generation) then return nil, "could_not_reach_boat_dealer_" .. tostring(moveReason) end
            root = rootPart()
            if not root or (root.Position - dealer.position).Magnitude > 24 then return nil, "verified_west_boat_dealer_out_of_range" end
        end
        local comm = ReplicatedStorage and ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("CommF_")
        if not comm or type(comm.InvokeServer) ~= "function" then return nil, "buyboat_remote_missing" end
        setPhase("buying_boat", selected)
        local ok, result = pcall(function() return comm:InvokeServer("BuyBoat", selected) end)
        if not ok then return nil, "buyboat_call_failed" end
        local deadline = now() + 12
        repeat
            existing = ownedBoatByName(selected)
            -- After a sea reset, do not bind to the stale hull that triggered
            -- it: wait until BuyBoat has produced a different owned instance.
            if existing and (not forceFreshBoat or existing ~= previousBoat) then
                runtime.forceFreshBoat = false
                runtime.tikiReturnNeedsFreshBoat = false
                runtime.tikiReturnReason = nil
                return existing
            end
            task.wait(0.15)
        until not isCurrent(generation) or now() >= deadline
        return nil, (forceFreshBoat and "fresh_boat_not_spawned_" or "boat_not_spawned_") .. tostring(result)
    end

    -- When all measured Tiki exit lifts still produce insignificant forward
    -- travel, the hull is considered stuck rather than merely too low. Return
    -- to the verified WEST/open-sea Boat Dealer and request a genuinely new
    -- boat instance. This intentionally never scans/selects the island-side
    -- dealer.
    local function buyReplacementBoatAtTikiWestDealer(generation, previousBoat)
        local selected = State.eventFarmBoat
        if type(selected) ~= "string" or selected == "" then return nil, "boat_not_selected" end
        local dealer = findTikiWestDealer()
        if not dealer or not dealer.verified then return nil, "verified_west_boat_dealer_not_found" end
        local root = rootPart()
        if not root then return nil, "character_missing" end
        local dealerDistance = (root.Position - dealer.position).Magnitude
        if dealerDistance > 18 then
            setPhase("returning_to_verified_west_dealer")
            local arrived, travelReason = false, "direct_travel_unavailable"
            local teleport = Flow.Features.Teleport
            if teleport and type(teleport.TravelDirectToPosition) == "function" then
                arrived, travelReason = teleport:TravelDirectToPosition(dealer.position, "sea_event_replace_stuck_boat", "Boat Dealer", {
                    ignoreNoSupportWater = true, disableAdaptiveClearance = true,
                    holdArrivalVelocity = true, arrivalConfirmSeconds = 0.35, maxAttempts = 2,
                })
            end
            if not arrived then
                local farm = Flow.Features.Farm
                if farm and type(farm.MoveTo) == "function" then
                    arrived, travelReason = farm:MoveTo(CFrame.new(dealer.position), "sea_event_replace_stuck_boat")
                end
            end
            journal("replacement_dealer_travel", {directDistance = dealerDistance, arrived = arrived == true, reason = travelReason, verified = true})
            if not arrived or not isCurrent(generation) then return nil, "could_not_reach_verified_west_dealer_" .. tostring(travelReason) end
            root = rootPart()
            if not root or (root.Position - dealer.position).Magnitude > 24 then
                return nil, "verified_west_boat_dealer_out_of_range"
            end
        end
        local comm = ReplicatedStorage and ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("CommF_")
        if not comm or type(comm.InvokeServer) ~= "function" then return nil, "buyboat_remote_missing" end
        setPhase("rebuying_stuck_boat", selected)
        local ok, result = pcall(function() return comm:InvokeServer("BuyBoat", selected) end)
        if not ok then return nil, "replacement_buyboat_call_failed" end
        local deadline = now() + 12
        repeat
            local replacement = ownedBoatByName(selected)
            -- Do not bind again to the same stranded Model. BuyBoat normally
            -- removes it and creates a new owned instance with the same name.
            if replacement and replacement ~= previousBoat then return replacement end
            task.wait(0.15)
        until not isCurrent(generation) or now() >= deadline
        return nil, "replacement_boat_not_spawned_" .. tostring(result)
    end

    local function beginExistingSeaCalibration()
        local runtime = EventFarm.Runtime
        local markerVisible = (tonumber(player and player:GetAttribute("DangerLevel")) or 0) > 1
        runtime.marker.lastGood = markerVisible and runtime.lift or nil
        runtime.marker.seenFor = 0
        runtime.marker.missingFor = 0
        runtime.marker.mode = markerVisible and "seek_highest" or "recover_marker"
        setPhase("calibrating_existing_sea")
    end

    local function setOpenSeaCourse(generation)
        local runtime = EventFarm.Runtime
        local route = getTikiOpenSeaRoute()
        runtime.cruiseDirection = route.direction
        setPhase("leaving_tiki")
        -- Start high immediately and keep that altitude throughout Tiki. The
        -- only response to a blocked horizontal route is more lift, never a
        -- downward retry. Descent/calibration begins only after projection
        -- proves that the hull has left the island.
        local lifts = {EventFarm.TikiExitFirstLift, EventFarm.TikiExitSecondLift, EventFarm.TikiExitThirdLift}
        local lastProjection = 0
        for attempt, requestedLift in ipairs(lifts) do
            if not isCurrent(generation) then return false, "stopped" end
            local liftTarget = math.max(runtime.targetLift or 0, runtime.lift or 0, requestedLift)
            setPhase("leaving_tiki", "high_lift_" .. tostring(math.floor(liftTarget)))
            drive(nil, 0)
            setLift(liftTarget, 420)
            if not waitForLift(generation, liftTarget, 12, 10) then return false, "high_lift_timeout" end
            local seat = runtime.seat
            local startPosition = seat and seat.Position
            drive(route.direction, 300)
            if not waitSeconds(generation, 3.5) then return false, "stopped" end
            local finish = seat and seat.Position
            lastProjection = startPosition and finish and Vector3.new(finish.X - startPosition.X, 0, finish.Z - startPosition.Z):Dot(route.direction) or 0
            if lastProjection >= EventFarm.TikiExitMinimumProjection then
                runtime.marker.mode = "rapid_descent"
                runtime.marker.lastGood = nil
                runtime.marker.seenFor = 0
                runtime.marker.missingFor = 0
                setPhase("calibrating_sea_marker", "outside_tiki")
                drive(route.direction, 300)
                return true
            end
            drive(nil, 0)
            journal("tiki_obstacle_lift", {attempt = attempt, lift = liftTarget, projection = lastProjection})
        end
        return false, "open_sea_exit_not_confirmed_projection_" .. tostring(math.floor(lastProjection))
    end

    local function updateCruiseCalibration(dt)
        local runtime = EventFarm.Runtime
        -- A physical obstruction has cleared, but a single good velocity frame
        -- is not enough to descend safely. Preserve the highest verified lift
        -- for ten seconds while the boat re-establishes its forward course.
        local obstructionHold = runtime.obstructionHold
        if obstructionHold and (obstructionHold.untilAt or 0) > now() then
            local heldLift = math.max(tonumber(obstructionHold.lift) or 0, tonumber(runtime.targetLift) or 0)
            if runtime.targetLift < heldLift then setLift(heldLift, EventFarm.IslandClearanceRate) end
            runtime.marker.mode = "obstruction_hold"
            return
        elseif obstructionHold and obstructionHold.lift ~= nil then
            journal("obstruction_clearance_hold_complete", {source = obstructionHold.source, lift = obstructionHold.lift})
            runtime.obstructionHold = {untilAt = 0, lift = nil, source = nil}
            if runtime.marker.mode == "obstruction_hold" then runtime.marker.mode = "rapid_descent" end
        end
        -- A named dynamic island ahead owns the standard 500-stud clearance
        -- until it is no longer in front of the boat. Do not let compass
        -- descent/calibration immediately undo that clearance.
        if runtime.islandClearance and runtime.islandClearance.active then
            if runtime.targetLift < EventFarm.IslandClearanceLift then
                setLift(EventFarm.IslandClearanceLift, EventFarm.IslandClearanceRate)
            end
            return
        end
        -- Obstruction recovery owns lift until real forward travel resumes.
        -- This prevents rapid_descent from cancelling the recovery climb.
        if runtime.preStallLift ~= nil then
            runtime.marker.mode = "stall_recovery"
            return
        end
        local rawDanger = tonumber(player and player:GetAttribute("DangerLevel")) or 0
        -- This is exactly the SeaExploration HUD enabling condition: DangerLevel > 1.
        local markerVisible = rawDanger > 1
        local marker = runtime.marker
        if marker.mode == "rapid_descent" then
            -- First leave the clearance altitude quickly. Only after reaching a
            -- low sea-height sample do we trust the marker to seek its maximum
            -- usable altitude again.
            if runtime.targetLift > 80 then
                setLift(math.max(80, runtime.targetLift - 520 * dt), 520)
            elseif markerVisible then
                marker.mode = "seek_highest"
                marker.seenFor = 0
                marker.missingFor = 0
                marker.lastGood = runtime.lift
                setLift(runtime.lift + 42, 220)
            end
        elseif marker.mode == "seek_highest" then
            if markerVisible then
                marker.seenFor = marker.seenFor + dt
                marker.lastGood = runtime.lift
                setLift(runtime.targetLift + 42 * dt, 220)
            else
                marker.mode = "recover_marker"
                marker.missingFor = 0
                setLift(math.max(0, (marker.lastGood or runtime.lift) - 35), 220)
            end
        elseif marker.mode == "recover_marker" then
            if markerVisible then
                marker.seenFor = marker.seenFor + dt
                if marker.seenFor >= 0.5 then
                    marker.mode = "locked"
                    marker.lastGood = runtime.lift
                    setLift(marker.lastGood, 100)
                    notify("Farm Eventos", "Altura marítima calibrada pela bússola.", "success", "marker_locked", 20)
                end
            else
                marker.seenFor = 0
                setLift(math.max(0, runtime.targetLift - 12 * dt), 80)
            end
        elseif marker.mode == "locked" then
            if markerVisible then
                marker.missingFor = 0
                setLift(marker.lastGood or runtime.targetLift, 100)
            else
                marker.missingFor = marker.missingFor + dt
                if marker.missingFor > 0.8 then
                    marker.mode = "recover_marker"
                    marker.seenFor = 0
                    setLift(math.max(0, (marker.lastGood or runtime.targetLift) - 10), 100)
                end
            end
        end
    end

    local function updateStallRecovery(dt)
        local runtime = EventFarm.Runtime
        if runtime.transit and runtime.transit.active and runtime.phase == "leaving_tiki" then return end
        local seat = runtime.seat
        -- While a seated player is deliberately parking the hull away from a
        -- Terror Shark, vertical obstruction recovery is forbidden. It was
        -- the source of the recorded 2962 stud/s upward ejection.
        if runtime.boatAwayActive then return end
        if runtime.raidLift and (runtime.raidLift.active or runtime.raidLift.returning) then return end
        if not seat or not runtime.direction or math.abs(runtime.speed) < 80 then return end
        local velocity = seat.AssemblyLinearVelocity
        local horizontal = Vector3.new(velocity.X, 0, velocity.Z).Magnitude
        if horizontal < 35 then
            runtime.stalledFor = runtime.stalledFor + dt
            if runtime.stalledFor >= 0.9 then
                if runtime.preStallLift == nil then
                    runtime.preStallLift = runtime.targetLift
                    runtime.stallBoost = 0
                    notify("Farm Eventos", "Barco obstruído: assumindo altura de recuperação.", "info", "boat_stall", 8)
                end
                -- Rise in bounded tiers while physical movement is genuinely
                -- blocked. The first tier clears Tiki-scale geometry; later
                -- tiers handle taller streamed geometry without unbounded lift.
                local tier = math.floor((runtime.stalledFor - 0.9) / 1.25)
                local wantedBoost = math.min(1120, 420 + tier * 160)
                local wantedLift = math.min(1200, runtime.preStallLift + wantedBoost)
                if runtime.targetLift < wantedLift - 2 then
                    runtime.stallBoost = wantedBoost
                    setLift(wantedLift, 440)
                end
            end
        else
            runtime.stalledFor = 0
            if runtime.preStallLift ~= nil then
                local peakLift = math.max(tonumber(runtime.targetLift) or 0, tonumber(runtime.lift) or 0, tonumber(runtime.preStallLift) or 0)
                runtime.obstructionHold = {
                    untilAt = now() + EventFarm.ObstructionRecoveryHold,
                    lift = peakLift,
                    source = "physical_stall",
                }
                journal("obstruction_clearance_hold", {source = "physical_stall", lift = peakLift, seconds = EventFarm.ObstructionRecoveryHold})
                runtime.preStallLift = nil
                runtime.stallBoost = 0
                -- Do not restore/descent on the first moving sample. The hold
                -- above owns altitude until sustained post-obstruction travel.
                if runtime.marker.mode == "stall_recovery" then runtime.marker.mode = "obstruction_hold" end
                notify("Farm Eventos", "Rota liberada: mantendo altura segura antes de descer.", "success", "boat_unstuck", 8)
            end
        end
    end

    -- Raid boats are identity-bound to live enemy Models. Matching a similarly
    -- named owned hull in Workspace.Boats is intentionally impossible here.
    local raidBoatDefinitions = {
        fish_boat = {normalized = "fishboat", name = "Fish Boat"},
        pirate_brigade = {normalized = "piratebrigade", name = "Pirate Brigade"},
        pirate_grand_brigade = {normalized = "pirategrandbrigade", name = "Pirate Grand Brigade"},
        pirate_basic = {normalized = "piratebasic", name = "Pirate Basic"},
    }

    raidBoatKindFromName = function(name)
        local normalized = lower(name):gsub("[%s_%-]", "")
        for id, definition in pairs(raidBoatDefinitions) do
            if normalized == definition.normalized then return id end
        end
        return nil
    end

    isRaidBoatKind = function(id)
        return raidBoatDefinitions[id] ~= nil
    end

    local function isRaidBoatName(name)
        return raidBoatKindFromName(name) ~= nil
    end

    raidBoatRoot = function(target)
        if not target then return nil end
        local body = target:FindFirstChild("Body", true)
        if body then
            if body:IsA("BasePart") then return body end
            local bodyPart = body:FindFirstChildWhichIsA("BasePart", true)
            if bodyPart then return bodyPart end
        end
        return targetRoot(target)
    end

    isRaidBoatTarget = function(target, expectedKind)
        local enemies = Workspace and Workspace:FindFirstChild("Enemies")
        local kind = target and target:IsA("Model") and target.Parent == enemies and raidBoatKindFromName(target.Name) or nil
        return kind ~= nil and (expectedKind == nil or kind == expectedKind), kind
    end

    local function raidBoatHealth(target)
        if not target then return nil, nil, nil end
        local current = tonumber(target:GetAttribute("Health")) or tonumber(target:GetAttribute("HullHealth"))
        local maximum = tonumber(target:GetAttribute("MaxHealth")) or tonumber(target:GetAttribute("MaxHullHealth"))
        local healthValue = target:FindFirstChild("Health", true) or target:FindFirstChild("HullHealth", true)
        local maxValue = target:FindFirstChild("MaxHealth", true) or target:FindFirstChild("MaxHullHealth", true)
        if not current and healthValue and healthValue:IsA("ValueBase") then current = tonumber(healthValue.Value) end
        if not maximum and maxValue and maxValue:IsA("ValueBase") then maximum = tonumber(maxValue.Value) end
        return current, maximum, current and current <= 0 or false
    end

    raidBoatAlive = function(target)
        local isRaid = isRaidBoatTarget(target)
        if not isRaid then return false end
        local current, _, terminal = raidBoatHealth(target)
        return not terminal and (current == nil or current > 0)
    end

    raidBoatTerminalDefeat = function(target)
        local isRaid = isRaidBoatTarget(target)
        if not isRaid then return false, nil end
        local current, _, terminal = raidBoatHealth(target)
        if terminal then return true, "raid_boat_health_zero" end
        return false, current and "raid_boat_health_live" or nil
    end

    raidBoatOperationalDistance = function(target)
        local root = raidBoatRoot(target)
        local runtime = EventFarm.Runtime
        local anchor = runtime.seat and runtime.seat.Parent and runtime.seat.Position or (rootPart() and rootPart().Position)
        return root and anchor and (root.Position - anchor).Magnitude or math.huge
    end

    isRaidBoatTargetValid = function(target, expectedKind)
        local isRaid, kind = isRaidBoatTarget(target, expectedKind)
        if not isRaid or not raidBoatAlive(target) then return false, kind end
        local runtime = EventFarm.Runtime
        local limit = runtime.target == target and EventFarm.RaidBoatMaxTargetDistance * 1.35 or EventFarm.RaidBoatMaxTargetDistance
        return raidBoatOperationalDistance(target) <= limit, kind
    end

    visibleRaidBoat = function(kind)
        local enemies = Workspace and Workspace:FindFirstChild("Enemies")
        if not enemies then return nil end
        local runtime, nearest, nearestDistance = EventFarm.Runtime, nil, nil
        for _, item in ipairs(enemies:GetChildren()) do
            local matches, itemKind = isRaidBoatTarget(item, kind)
            local blockedUntil = matches and runtime.targetBackoff[item] or nil
            local d = matches and raidBoatOperationalDistance(item) or math.huge
            if matches and (not blockedUntil or now() >= blockedUntil)
                and isRaidBoatTargetValid(item, kind) and (not nearestDistance or d < nearestDistance) then
                nearest, nearestDistance = item, d
            end
        end
        return nearest, nearestDistance
    end

    selectedRaidBoatExists = function()
        for id in pairs(raidBoatDefinitions) do
            if isTargetSelected(id) then
                local target = visibleRaidBoat(id)
                if target then return true end
            end
        end
        return false
    end

    -- A raid encounter can contain several hulls. Pick the closest remaining
    -- checked hull, excluding the just-finished model, so combat stays in the
    -- same native-orbit session until the local raid group is clear.
    local function nextSelectedRaidBoat(excluded)
        local choice = nil
        for priority, definition in ipairs(EventFarm.SupportedEvents) do
            local kind = definition.id
            if isRaidBoatKind(kind) and isTargetSelected(kind) then
                local target, targetDistance = visibleRaidBoat(kind)
                if target and target ~= excluded and (not choice or targetDistance < choice.distance
                    or (targetDistance == choice.distance and priority < choice.priority)) then
                    choice = {target = target, kind = kind, distance = targetDistance, priority = priority}
                end
            end
        end
        return choice and choice.target or nil, choice and choice.kind or nil, choice and choice.distance or nil
    end

    local function nearbyRaidBoat(origin)
        local enemies = Workspace and Workspace:FindFirstChild("Enemies")
        local seat = EventFarm.Runtime.seat
        local originPosition = origin and origin.Position or (seat and seat.Position) or (rootPart() and rootPart().Position)
        if not enemies or not originPosition then return nil end
        local nearest, nearestDistance
        for _, item in ipairs(enemies:GetChildren()) do
            if item:IsA("Model") and isRaidBoatName(item.Name) then
                local root = raidBoatRoot(item)
                local d = root and distance(originPosition, root.Position) or math.huge
                if d <= EventFarm.RaidBoatDetectionDistance and (not nearestDistance or d < nearestDistance) then
                    nearest, nearestDistance = item, d
                end
            end
        end
        return nearest, nearestDistance
    end

    local function setRaidBoatLift(raid, raidDistance, source)
        local runtime = EventFarm.Runtime
        local lift = runtime.raidLift or {active = false, returning = false}
        runtime.raidLift = lift
        if not lift.active and not lift.returning then
            lift.restoreTargetLift = tonumber(runtime.targetLift) or 0
            lift.resumePhase = runtime.phase
            lift.detectedAt = now()
            lift.name = raid and raid.Name or "RaidBoat"
            journal("raid_boat_spawn_detected", {
                name = lift.name, distance = raidDistance, source = source,
                restoreTargetLift = lift.restoreTargetLift, liftTarget = EventFarm.RaidBoatLiftHeight,
            })
            notify("Farm Eventos", "Barco de Raid detectado: subindo o barco para altura segura.", "warning", "raid_boat_lift", 2)
        end
        lift.active, lift.returning = true, false
        lift.distance = raidDistance
        lift.clearSince = nil
        -- Preserve a higher pre-existing safety lift (e.g. a dynamic island),
        -- but never lower the boat merely to force the 400-stud raid setting.
        local target = math.max(EventFarm.RaidBoatLiftHeight, tonumber(lift.restoreTargetLift) or 0)
        setLift(target, EventFarm.RaidBoatLiftRiseRate)
        -- Do not steer away from the event. Keep the established sea heading
        -- while the boat rises, so this is vertical clearance rather than a
        -- lateral evade loop.
        drive(runtime.cruiseDirection or runtime.direction or EventFarm.TikiOpenSeaDirection, 300)
    end

    local function updateRaidBoatLift(raid, raidDistance)
        local runtime = EventFarm.Runtime
        -- A checked raid boat is a combat target. Its dedicated native orbit,
        -- not the cruise-only +400 escape lift, owns the hull from claim until
        -- safe return. Unchecked raid boats retain the established safeguard.
        if isRaidBoatKind(runtime.targetKind) and runtime.target and isRaidBoatTarget(runtime.target, runtime.targetKind) then
            return false
        end
        local lift = runtime.raidLift or {active = false, returning = false}
        runtime.raidLift = lift
        if raid then
            setRaidBoatLift(raid, raidDistance, "poll")
            return true
        end
        if lift.active then
            lift.clearSince = lift.clearSince or now()
            if now() - lift.clearSince < EventFarm.RaidBoatClearSeconds then
                -- Keep the 400-stud clearance through a short quiet window so
                -- a streamed one-frame absence cannot make the boat bounce.
                setLift(math.max(EventFarm.RaidBoatLiftHeight, tonumber(lift.restoreTargetLift) or 0), EventFarm.RaidBoatLiftRiseRate)
                return true
            end
            lift.active, lift.returning = false, true
            setPhase("raid_boat_descending", "raid_boat_clear")
            setLift(tonumber(lift.restoreTargetLift) or 0, EventFarm.RaidBoatLiftReturnRate)
            notify("Farm Eventos", "Barco de Raid distante: voltando à altura de navegação.", "success", "raid_boat_lower", 2)
            journal("raid_boat_clear", {name = lift.name, restoreTargetLift = lift.restoreTargetLift})
            return true
        end
        if lift.returning then
            local target = tonumber(lift.restoreTargetLift) or 0
            setLift(target, EventFarm.RaidBoatLiftReturnRate)
            if math.abs((tonumber(runtime.lift) or 0) - target) <= 3 then
                local resume = lift.resumePhase
                if resume ~= "calibrating_sea_marker" and resume ~= "calibrating_existing_sea" then resume = "sea_cruise" end
                runtime.raidLift = {active = false, returning = false, restoreTargetLift = nil, resumePhase = nil, name = nil, distance = nil, clearSince = nil, detectedAt = nil}
                setPhase(resume, "raid_boat_height_restored")
                journal("raid_boat_height_restored", {targetLift = target, resumePhase = resume})
                return false
            end
            return true
        end
        return false
    end

    disconnectRaidBoatWatch = function()
        local runtime = EventFarm.Runtime
        for _, connection in ipairs(runtime.raidConnections or {}) do pcall(function() connection:Disconnect() end) end
        runtime.raidConnections = {}
        runtime.raidSpawnCandidate = nil
    end

    local function installRaidBoatWatch()
        disconnectRaidBoatWatch()
        local runtime = EventFarm.Runtime
        local function inspect(item, source)
            if not runtime.active or not item or not item:IsA("Model") or not isRaidBoatName(item.Name) then return end
            runtime.raidSpawnCandidate = {instance = item, at = now(), source = source}
            -- Do not let the passive cruise watcher steal a selected raid boat
            -- away from its combat handoff. It remains defensive for every
            -- unselected raid model.
            local kind = raidBoatKindFromName(item.Name)
            if kind and isTargetSelected(kind) then return end
            local seat, root = runtime.seat, raidBoatRoot(item)
            local d = seat and root and distance(seat.Position, root.Position) or math.huge
            if d <= EventFarm.RaidBoatDetectionDistance then
                setRaidBoatLift(item, d, source)
            end
        end
        local function bindEnemies(folder)
            if not folder then return end
            for _, item in ipairs(folder:GetChildren()) do inspect(item, "initial_scan") end
            runtime.raidConnections[#runtime.raidConnections + 1] = folder.ChildAdded:Connect(function(item)
                inspect(item, "enemies_child_added")
            end)
        end
        if Workspace then
            bindEnemies(Workspace:FindFirstChild("Enemies"))
            runtime.raidConnections[#runtime.raidConnections + 1] = Workspace.ChildAdded:Connect(function(item)
                if item.Name == "Enemies" then bindEnemies(item) end
            end)
        end
    end

    -- One shared resolver is used both by cruise and by activation checkpoints.
    -- It only returns currently replicated, selected, in-range targets; it
    -- never fabricates a spawn or trusts a stale saved Instance reference.
    function EventFarm:ResolveLiveSelectedTarget()
        local options, current = {}, {}
        local baseScore = {sea_beast = 460, terror_shark = 430, fish_boat = 330, pirate_grand_brigade = 320, pirate_brigade = 310, pirate_basic = 300}
        local function observe(target, kind, targetDistance)
            if not target then return end
            targetDistance = tonumber(targetDistance) or math.huge
            local id = "sea_event|" .. tostring(kind) .. "|" .. tostring(target)
            local option = {
                id = id, target = target, kind = kind, distance = targetDistance,
                -- Distance is a bounded cost, never an implicit reason to pick
                -- a lesser unchecked reward over a selected live Sea Beast.
                score = (baseScore[kind] or 250) - math.min(180, targetDistance / 45),
            }
            options[#options + 1] = option
            current[id] = option
            local queue = Flow.Features and Flow.Features.OpportunityQueue
            if queue and queue.Observe then
                queue:Observe({
                    id = id, kind = kind, owner = "event_farm", source = "live_selected_scan",
                    name = target.Name, object = target, position = positionOf(target),
                    distance = targetDistance, score = option.score, priority = 80, ttl = 2.0,
                    metadata = {selected = true},
                })
            end
        end
        for id in pairs(raidBoatDefinitions) do
            if isTargetSelected(id) then
                local target, targetDistance = visibleRaidBoat(id)
                observe(target, id, targetDistance)
            end
        end
        if isTargetSelected("terror_shark") then
            local target = visibleTerrorShark()
            observe(target, "terror_shark", target and targetOperationalDistance(target) or nil)
        end
        if isTargetSelected("sea_beast") then
            local target = visibleSeaBeast()
            observe(target, "sea_beast", target and targetOperationalDistance(target) or nil)
        end
        if #options == 0 then return nil end

        local queue = Flow.Features and Flow.Features.OpportunityQueue
        local selected = queue and queue.GetBest and queue:GetBest(function(entry)
            return entry.owner == "event_farm" and current[entry.id] ~= nil
        end) or nil
        local choice = selected and current[selected.id] or nil
        if not choice then
            table.sort(options, function(a, b)
                if a.score == b.score then return a.distance < b.distance end
                return a.score > b.score
            end)
            choice = options[1]
        end
        if choice and queue and queue.Claim then
            local claimed = queue:Claim(choice.id, "event_farm", {
                resources = {"movement", "combat", "boat"}, priority = 80, preemptible = true,
                context = {stage = "event_target", targetKind = choice.kind},
            })
            if claimed then EventFarm.Runtime.targetOpportunityId = choice.id end
        end
        return choice, #options
    end

    local function driveSea(generation, options)
        options = options or {}
        local runtime = EventFarm.Runtime
        -- A previous fight has fully released its target before returning here.
        -- Start each cruise search with no stale type lock. A target-only route
        -- (Frozen Dimension) never owns an opportunity-queue claim in the
        -- first place and intentionally does not inspect sea mobs.
        if runtime.targetOpportunityId then
            local queue = Flow.Features and Flow.Features.OpportunityQueue
            if queue and queue.ReleaseClaim then pcall(function() queue:ReleaseClaim(runtime.targetOpportunityId, "event_farm", "deferred") end) end
            runtime.targetOpportunityId = nil
        end
        runtime.target = nil
        runtime.targetKind = nil
        drive(runtime.cruiseDirection or EventFarm.TikiOpenSeaDirection, 300)
        local last = now()
        while isCurrent(generation) do
            if runtime.boatLostReason then return nil, "boat_lost" end
            if not localOccupies(runtime.seat) then
                local rejoined, rejoinReason
                if recoverCruiseSeat then
                    rejoined, rejoinReason = recoverCruiseSeat(generation)
                else
                    rejoined, rejoinReason = false, "seat_recovery_unavailable"
                end
                if not rejoined then
                    if rejoinReason == "boat_lost" or runtime.boatLostReason then return nil, "boat_lost" end
                    if rejoinReason == "tiki_return_rebuy" then return nil, "tiki_return_rebuy" end
                    if rejoinReason == "character_died" then return nil, "character_died" end
                    if not isCurrent(generation) then return nil, "stopped" end
                end
                -- Re-read the world after the seat recovery; do not acquire a
                -- target using a player/boat position from before the knock-off.
                last = now()
                task.wait(0.05)
                continue
            end
            if not isAlive() then
                setPhase("waiting_respawn", "player_died_during_cruise")
                repeat task.wait(0.25) until not isCurrent(generation) or isAlive()
                return nil, isCurrent(generation) and "character_died" or "stopped"
            end
            local ratio, health, maximum, healthSource = boatHealthRatio(runtime.boat)
            if ratio == nil or ratio < EventFarm.BoatReuseMinimumHealthRatio then
                local percentage = ratio and math.floor(ratio * 100) or "unknown"
                runtime.boatLostReason = "boat_health_below_50_percent_" .. tostring(percentage)
                journal("boat_replacement_required", {
                    ratio = ratio, health = health, maximum = maximum, healthSource = healthSource,
                    minimumRatio = EventFarm.BoatReuseMinimumHealthRatio,
                    reason = ratio == nil and "health_unreadable" or "below_50_percent",
                })
                return nil, "boat_lost"
            end
            -- A seated visual can persist while the server no longer grants
            -- physical hull authority. Treat native command, seat state and
            -- measured X/Z speed as separate facts. Real named/raycasted
            -- obstructions are exempt and keep their own ten-second hold.
            local authority = runtime.nativeAuthority or {}
            runtime.nativeAuthority = authority
            local seatVelocity = runtime.seat and runtime.seat.AssemblyLinearVelocity
            local physicalSpeed = seatVelocity and Vector3.new(seatVelocity.X, 0, seatVelocity.Z).Magnitude or 0
            local commandedSpeed = tonumber(runtime.speed) or 0
            authority.lastPhysicalSpeed = physicalSpeed
            authority.lastCommandSpeed = commandedSpeed
            local transit = runtime.transit or {}
            local obstacleRecent = (runtime.islandClearance and runtime.islandClearance.active == true)
                or ((tonumber(transit.lastObstacleAt) or 0) > 0 and now() - transit.lastObstacleAt <= EventFarm.NativeAuthorityObstacleGrace)
            local authorityArmed = now() - (tonumber(authority.armedAt) or 0) >= EventFarm.NativeAuthoritySettleSeconds
            if authorityArmed and commandedSpeed >= EventFarm.NativeAuthorityCommandMinimum and physicalSpeed < EventFarm.NativeAuthorityMinimumSpeed and not obstacleRecent then
                authority.lostSince = authority.lostSince or now()
                if now() - authority.lostSince >= EventFarm.NativeAuthorityLossSeconds then
                    authority.lastReason = "seated_without_physical_authority"
                    local savedBoat = runtime.boat
                    local savedDirection = runtime.direction or runtime.cruiseDirection or EventFarm.TikiOpenSeaDirection
                    local savedSpeed = commandedSpeed
                    local savedPhase = runtime.phase
                    journal("native_authority_lost_while_seated", {
                        phase = savedPhase, requestedSpeed = savedSpeed, physicalSpeed = physicalSpeed,
                        repairAttempted = authority.repairAttempted == true,
                    })
                    if not authority.repairAttempted and savedBoat and savedBoat.Parent then
                        authority.repairAttempted = true
                        setPhase("recovering_native_authority", "seated_no_physical_motion")
                        clearNativeControl()
                        local attached, attachReason = attachNativeControl(savedBoat)
                        if attached and settleNativeBoat(generation) then
                            drive(savedDirection, savedSpeed)
                            runtime.nativeAuthority = {
                                armedAt = now(), lostSince = nil, repairAttempted = true,
                                lastPhysicalSpeed = 0, lastCommandSpeed = savedSpeed,
                                lastReason = "native_reattached",
                            }
                            setPhase(savedPhase, "native_authority_recovered")
                            journal("native_authority_recovered", {phase = savedPhase, requestedSpeed = savedSpeed})
                            task.wait(0.05)
                            continue
                        end
                        authority.lastReason = "native_reattach_failed_" .. tostring(attachReason)
                        journal("native_authority_repair_failed", {reason = authority.lastReason, phase = savedPhase})
                    end
                    runtime.boatLostReason = "native_authority_lost_while_seated"
                    return nil, "boat_lost"
                end
            else
                authority.lostSince = nil
                if physicalSpeed >= EventFarm.NativeAuthorityMinimumSpeed then authority.lastReason = "physical_motion_confirmed" end
            end
            -- A target-only route is the strict isolation boundary used by
            -- Frozen Dimension search: it must neither enumerate nor claim
            -- mobs/raid boats, and therefore cannot enter a combat handoff.
            if type(options.resolveTarget) == "function" then
                local target, targetKind = options.resolveTarget()
                if target then
                    runtime.target, runtime.targetKind = target, targetKind
                    journal("route_target_detected", {kind = targetKind, name = target.Name})
                    return target, targetKind
                end
            end
            if options.ignoreSeaTargets ~= true then
                -- Resolve every checked mob into one deterministic, exclusive
                -- claim. A checked raid boat is no longer treated as a
                -- cruise-only hazard: it receives its own native orbit/combat
                -- handoff below. The +400 raid-lift response remains only for
                -- raid types that the player did *not* select for farming.
                if not selectedRaidBoatExists() then
                    local raid, raidDistance = nearbyRaidBoat()
                    if updateRaidBoatLift(raid, raidDistance) then
                        last = now()
                        task.wait(0.05)
                        continue
                    end
                end
                local choice, candidateCount = EventFarm:ResolveLiveSelectedTarget()
                if choice then
                    runtime.targetKind = choice.kind
                    journal("target_claimed", {kind = choice.kind, target = choice.target.Name, distance = choice.distance, simultaneousCandidates = candidateCount})
                    return choice.target, choice.kind
                end
            end
            local at = now()
            local dt = math.max(0.01, at - last)
            last = at
            updateNamedIslandClearance()
            updateCruiseCalibration(dt)
            updateStallRecovery(dt)
            task.wait(0.1)
        end
        return nil, runtime.boatLostReason and "boat_lost" or "stopped"
    end

    local function ensureLocalDriver(generation)
        local runtime = EventFarm.Runtime
        local seat = runtime.seat
        if not seat or not seat.Parent then return false, "boat_seat_missing" end
        if localOccupies(seat) then return true end
        if otherPlayerDrives(seat) then return false, "other_player_drives_boat" end
        local h = humanoid()
        if not h then return false, "character_missing" end
        pcall(function() seat:Sit(h) end)
        local deadline = now() + 2
        repeat task.wait(0.05) until not isCurrent(generation) or runtime.boatLostReason or localOccupies(seat) or now() >= deadline
        if runtime.boatLostReason then return false, "boat_lost" end
        return localOccupies(seat), localOccupies(seat) and nil or "could_not_remain_in_boat"
    end

    -- Rejoin only during the cruise worker. Sea Beast combat intentionally
    -- leaves the seat and uses its own return path, so it never enters here.
    recoverCruiseSeat = function(generation)
        local runtime = EventFarm.Runtime
        local tikiReturn, tikiReason = requiresFreshBoatAtTiki()
        if tikiReturn then
            runtime.forceFreshBoat = true
            runtime.tikiReturnNeedsFreshBoat = true
            runtime.tikiReturnReason = tikiReason
            journal("cruise_tiki_return_rebuy", {reason = tikiReason, boat = runtime.boat and runtime.boat.Name or nil})
            notify("Farm Eventos", "Retorno a Tiki detectado. Comprando um barco novo; o antigo não será puxado.", "warning", "tiki_return_rebuy", 2)
            return false, "tiki_return_rebuy"
        end
        local seat = runtime.seat
        if not seat or not seat.Parent or not runtime.boat or not runtime.boat.Parent then
            runtime.boatLostReason = runtime.boatLostReason or "boat_missing_during_cruise_rejoin"
            return false, "boat_lost"
        end
        if localOccupies(seat) then return true, "already_seated" end
        local savedDrive = runtime.unseatedCruiseDrive or {
            direction = runtime.cruiseDirection or EventFarm.TikiOpenSeaDirection,
            speed = 300,
            phase = "sea_cruise",
            reason = "cruise_rejoin",
        }
        local resumePhase = savedDrive.phase or "sea_cruise"
        if resumePhase == "leaving_tiki" then resumePhase = "sea_cruise" end
        local recovery = runtime.seatRecovery or {attempts = 0, startedAt = nil, lastReason = nil}
        runtime.seatRecovery = recovery
        recovery.startedAt = recovery.startedAt or now()
        if runtime.phase ~= "rejoining_boat" and runtime.phase ~= "waiting_for_boat_seat" then
            setPhase("rejoining_boat", "involuntary_dismount")
            notify("Farm Eventos", "Você saiu do barco. Voltando ao assento para continuar a navegação.", "warning", "cruise_seat_rejoin", 2)
        end

        local teleport = Flow.Features.Teleport
        while isCurrent(generation) and not runtime.boatLostReason do
            seat = runtime.seat
            if not seat or not seat.Parent or not runtime.boat or not runtime.boat.Parent then
                runtime.boatLostReason = runtime.boatLostReason or "boat_missing_during_cruise_rejoin"
                return false, "boat_lost"
            end
            if localOccupies(seat) then
                local resumedDirection = savedDrive.direction or runtime.cruiseDirection or EventFarm.TikiOpenSeaDirection
                drive(resumedDirection, tonumber(savedDrive.speed) or 300)
                runtime.unseatedCruiseDrive = nil
                runtime.seatRecovery = {attempts = recovery.attempts or 0, startedAt = nil, lastReason = "rejoined"}
                setPhase(resumePhase, "boat_rejoined")
                journal("cruise_seat_rejoined", {attempts = recovery.attempts, resumedPhase = resumePhase, speed = runtime.speed})
                notify("Farm Eventos", "Assento recuperado. Continuando a navegação.", "success", "cruise_seat_rejoined", 2)
                return true, "rejoined"
            end
            if not isAlive() then return false, "character_died" end
            if otherPlayerDrives(seat) then
                if runtime.phase ~= "waiting_for_boat_seat" then
                    setPhase("waiting_for_boat_seat", "other_player_drives_boat")
                    journal("cruise_seat_waiting", {reason = "other_player_drives_boat"})
                end
                task.wait(EventFarm.CruiseSeatRecoveryRetrySeconds)
                continue
            end

            recovery.attempts = (recovery.attempts or 0) + 1
            local root = rootPart()
            local horizontal = root and horizontalDistance(root.Position, seat.Position) or math.huge
            local vertical = root and math.abs(root.Position.Y - seat.Position.Y) or math.huge
            local nearSeat = horizontal <= EventFarm.CruiseSeatRecoveryHorizontalTolerance
                and vertical <= EventFarm.CruiseSeatRecoveryVerticalTolerance
            local travelReason = "near_seat"
            if not nearSeat then
                if teleport and type(teleport.TravelDirectToPosition) == "function" then
                    local moved
                    moved, travelReason = teleport:TravelDirectToPosition(seat.Position + Vector3.new(0, 12, 0), "sea_event_cruise_rejoin", "Event boat seat", {
                        holdArrivalVelocity = true, arrivalConfirmSeconds = 0.25, maxAttempts = 1,
                        ignoreNoSupportWater = true, disableAdaptiveClearance = true,
                    })
                    root = rootPart()
                    horizontal = root and horizontalDistance(root.Position, seat.Position) or math.huge
                    vertical = root and math.abs(root.Position.Y - seat.Position.Y) or math.huge
                    nearSeat = horizontal <= EventFarm.CruiseSeatRecoveryHorizontalTolerance
                        and vertical <= EventFarm.CruiseSeatRecoveryVerticalTolerance
                    journal("cruise_seat_rejoin_travel", {
                        attempt = recovery.attempts, moved = moved == true, reason = travelReason,
                        horizontal = horizontal, vertical = vertical, nearSeat = nearSeat == true,
                    })
                else
                    travelReason = "direct_travel_unavailable"
                end
            end
            if nearSeat then
                local h = humanoid()
                if h then pcall(function() seat:Sit(h) end) end
                local deadline = now() + EventFarm.CruiseSeatRecoveryAttachSeconds
                repeat task.wait(0.05) until not isCurrent(generation) or runtime.boatLostReason
                    or localOccupies(seat) or now() >= deadline
            end
            if localOccupies(seat) then
                -- The next loop iteration restores the saved direction/phase in
                -- one place and resumes the native propulsion writer.
                continue
            end
            recovery.lastReason = nearSeat and "seat_attach_unconfirmed" or travelReason
            journal("cruise_seat_rejoin_retry", {
                attempt = recovery.attempts, reason = recovery.lastReason,
                horizontal = horizontal, vertical = vertical,
            })
            task.wait(EventFarm.CruiseSeatRecoveryRetrySeconds)
        end
        return false, runtime.boatLostReason and "boat_lost" or "stopped"
    end

    local function driveBoatAway(generation, target, approachNotice)
        local runtime = EventFarm.Runtime
        if not State.eventFarmMoveBoatAway then return true, "move_away_disabled" end
        if not isTerrorSharkTargetValid(target) then return false, "target_out_of_range" end
        local seated, seatReason = ensureLocalDriver(generation)
        if not seated then return false, seatReason end
        local root = targetRoot(target)
        local seat = runtime.seat
        if not root or not seat then return false, "boat_or_target_missing" end
        runtime.boatAwayActive = true
        runtime.boatSafeTarget = nil
        runtime.awayProgressCheck = nil
        local function abort(reason, fields)
            drive(nil, 0)
            runtime.boatAwayActive = false
            runtime.awayProgressCheck = nil
            fields = fields or {}
            fields.reason = reason
            journal("boat_away_abort", fields)
            return false, reason
        end
        local function lockSafeDistance()
            drive(nil, 0)
            local untilAt = now() + EventFarm.BoatSafeStableSeconds
            while isCurrent(generation) and now() < untilAt do
                if runtime.boatLostReason then return abort("boat_lost") end
                if not targetAlive(target) then return abort("target_gone") end
                root = targetRoot(target)
                if not root or not root.Parent then return abort("target_root_missing") end
                if not localOccupies(seat) then return abort("left_boat_before_safe_distance") end
                local separationNow = distance(seat.Position, root.Position)
                local vertical = math.abs(seat.AssemblyLinearVelocity.Y)
                if separationNow < EventFarm.BoatSafeDistance or vertical > EventFarm.BoatVerticalSafetySpeed then
                    return abort("boat_distance_or_vertical_motion_unstable")
                end
                task.wait(0.05)
            end
            if not isCurrent(generation) then return abort("stopped") end
            runtime.boatSafeTarget = target
            runtime.boatSafeAt = now()
            runtime.boatAwayActive = false
            runtime.awayProgressCheck = nil
            -- v1.6.4 diagnostic only: record the actual seat/target altitude
            -- when the boat-away guard finishes; runtime.lift alone is a control
            -- value and is not assumed to equal physical Seat Y.
            journal("boat_away_lift_check", {
                finalLift = runtime.lift,
                targetLift = runtime.targetLift,
                seatY = seat and seat.Position.Y or nil,
                sharkY = root and root.Position.Y or nil,
                verticalSeparation = seat and root and (seat.Position.Y - root.Position.Y) or nil,
            })
            return true, "safe_distance_stable"
        end
        local separation = distance(seat.Position, root.Position)
        journal("boat_away_start", {target = target.Name, distance = separation})
        if separation >= EventFarm.BoatSafeDistance then
            local ok, reason = lockSafeDistance()
            if ok then journal("boat_away_success", {distance = separation}) end
            return ok, reason
        end
        local away = Vector3.new(seat.Position.X-root.Position.X,0,seat.Position.Z-root.Position.Z)
        if away.Magnitude < .1 then away=EventFarm.TikiOpenSeaDirection end
        notify("Farm Eventos",approachNotice or "Terror Shark encontrado: permanecendo no barco e criando distância segura.","info","boat_away",1)
        setPhase("moving_boat_away")
        drive(away.Unit,300)
        local started=seat.Position;local deadline=now()+EventFarm.BoatAwayTimeout
        local lastProgressAt = 0
        while isCurrent(generation) and now()<deadline do
            if runtime.boatLostReason then return abort("boat_lost") end
            if not targetAlive(target) then return abort("target_gone") end
            root = targetRoot(target)
            if not root or not root.Parent then return abort("target_root_missing") end
            if not localOccupies(seat) then return abort("left_boat_before_safe_distance") end
            local liveAway = Vector3.new(seat.Position.X - root.Position.X, 0, seat.Position.Z - root.Position.Z)
            if liveAway.Magnitude > 0.1 then drive(liveAway.Unit, 300) end
            separation=distance(seat.Position,root.Position)
            if not runtime.awayProgressCheck then
                runtime.awayProgressCheck = {first = separation, firstAt = now()}
            end
            if now() - runtime.awayProgressCheck.firstAt >= 3 then
                local gained = separation - runtime.awayProgressCheck.first
                if gained < 150 then
                    return abort("shark_following", {gained = gained})
                end
                runtime.awayProgressCheck = {first = separation, firstAt = now()}
            end
            if now() - lastProgressAt >= 0.75 then
                lastProgressAt = now()
                journal("boat_away_progress", {distance = separation, travelled = distance(seat.Position, started)})
            end
            if separation>=EventFarm.BoatSafeDistance and distance(seat.Position,started)>=math.max(80,EventFarm.BoatAwayMinimumTravel) then
                local ok, reason = lockSafeDistance()
                if ok then journal("boat_away_success", {distance = separation}) end
                return ok, reason
            end
            task.wait(.1)
        end
        runtime.targetBackoff[target]=now()+8
        return abort("safe_distance_not_reached")
    end

    local function journalAttack(kind, fields)
        local runtime = EventFarm.Runtime
        runtime.attackJournalAt = runtime.attackJournalAt or {}
        local key = kind .. "|" .. tostring(fields and fields.reason or "")
        if now() - (runtime.attackJournalAt[key] or -math.huge) < 2 then return end
        runtime.attackJournalAt[key] = now()
        journal(kind, fields)
    end

    local function attackTerrorShark(target)
        local runtime = EventFarm.Runtime
        runtime.attackCallCount = (runtime.attackCallCount or 0) + 1

        local function logAttackStats()
            if not runtime.lastAttackStatsLog or now() - runtime.lastAttackStatsLog > 1.0 then
                runtime.lastAttackStatsLog = now()
                journal("attack_stats", {
                    callsTotal = runtime.attackCallCount or 0,
                    acceptedTotal = runtime.attackAcceptedCount or 0,
                    refusedTotal = runtime.attackRefusedCount or 0,
                    cooldownTotal = runtime.attackCooldownCount or 0,
                    outOfRangeTotal = runtime.attackRangeCount or 0,
                })
            end
        end

        local farm = Flow.Features.Farm
        -- v1.6.2 diagnostic: prove the phase, direct Root distance and hover
        -- owner at every EventFarm attack attempt before FIX-18 corrects hover.
        local pRoot, sRoot = rootPart(), targetRoot(target)
        local farmState = farm and farm.State
        journal("attack_attempt", {
            phase = EventFarm.Runtime.phase,
            sharkDist = pRoot and sRoot and (pRoot.Position - sRoot.Position).Magnitude or -1,
            hoverOwner = farmState and farmState.hoverOwner,
        })
        -- v1.6.0 FIX-18: make the dynamic combat-follow provider apply the
        -- current Shark-relative anchor immediately before the range check.
        if farm and type(farm.ApplyHover) == "function" then
            pcall(function() farm:ApplyHover(true) end)
        end
        if not farm or type(farm.Attack) ~= "function" then
            runtime.attackRefusedCount = (runtime.attackRefusedCount or 0) + 1
            logAttackStats()
            journalAttack("attack_refused", {reason = "farm_attack_missing"})
            return false, "farm_attack_missing"
        end
        -- v1.6.5 FIX-22/FIX-23: the Terrorshark Humanoid's Health does not
        -- provide reliable local damage feedback. Scope the rejection bypass to
        -- this exact EventFarm call and use the explicitly requested 130-stud
        -- combat hit range; normal Farm attacks retain their default behavior.
        farm.State.skipRejectedTargetForSeaBeast = true
        local invoked, accepted, reason = pcall(function()
            return farm:Attack(target, {range = 130})
        end)
        farm.State.skipRejectedTargetForSeaBeast = false
        if not invoked then
            runtime.attackRefusedCount = (runtime.attackRefusedCount or 0) + 1
            logAttackStats()
            journalAttack("attack_error", {reason = tostring(accepted)})
            return false, tostring(accepted)
        end
        if accepted ~= true then
            runtime.attackRefusedCount = (runtime.attackRefusedCount or 0) + 1
            if reason == "target_out_of_range" then
                runtime.attackRangeCount = (runtime.attackRangeCount or 0) + 1
                -- Farm owns model enumeration while EventFarm owns this journal.
                -- Copy only primitive diagnostic data prepared by Farm:Attack.
                local rangeDebug = farm and farm.State and farm.State.lastAttackRangeDebug
                if type(rangeDebug) == "table" then journal("attack_range_debug", rangeDebug) end
            end
            logAttackStats()
            journalAttack("attack_refused", {reason = tostring(reason or "attack_rejected")})
            return false, reason
        end
        if reason == "attacked" then
            runtime.attackAcceptedCount = (runtime.attackAcceptedCount or 0) + 1
            journalAttack("attack_accepted", {reason = reason})
        elseif reason == "cooldown" then
            runtime.attackCooldownCount = (runtime.attackCooldownCount or 0) + 1
        else
            journalAttack("attack_result", {reason = tostring(reason)})
        end
        logAttackStats()
        return true, reason
    end

    -- INVARIANT: no Sea Beast run may route toward the boat while an evasive
    -- ascent has not returned the character to its recorded combat position.
    -- The saved destination is player-relative at the instant before climb, so
    -- this restores the real position even when the Sea Beast streamed away.
    local function recoverSeaBeastEvadePosition(generation, recovery, reason)
        local teleport = Flow.Features.Teleport
        if not recovery or typeof(recovery.position) ~= "Vector3" then return true, "no_recovery_position" end
        if not teleport or type(teleport.TravelDirectToPosition) ~= "function" then return false, "direct_travel_missing" end
        setPhase("sea_beast_evade_position_recovery", reason)
        local segments, lastReason = 0, nil
        while isCurrent(generation) and isAlive() and isTargetLocked("sea_beast") do
            local current = rootPart()
            if not current then return false, "player_root_missing" end
            local horizontal = horizontalDistance(current.Position, recovery.position)
            local vertical = math.abs(current.Position.Y - recovery.position.Y)
            if horizontal <= EventFarm.SeaBeastEvadeRecoveryHorizontalTolerance and vertical <= EventFarm.SeaBeastEvadeRecoveryVerticalTolerance then
                journal("sea_beast_evade_position_recovered", {reason = reason, segments = segments, horizontal = horizontal, vertical = vertical, target = recovery.target and recovery.target.Name})
                return true, "original_combat_position_reached"
            end
            local nextY = math.max(recovery.position.Y, current.Position.Y - EventFarm.SeaBeastEvadeRecoveryStep)
            local destination = Vector3.new(recovery.position.X, nextY, recovery.position.Z)
            local moved, travelReason = teleport:TravelDirectToPosition(destination, "sea_beast_evade_position_recovery", "Sea Beast combat position recovery", {
                holdArrivalVelocity = true, arrivalConfirmSeconds = 0.05, maxAttempts = 1,
                ignoreNoSupportWater = true, disableAdaptiveClearance = true,
            })
            segments = segments + 1
            lastReason = travelReason
            journal("sea_beast_evade_position_recovery_segment", {reason = reason, segment = segments, moved = moved == true, travelReason = travelReason, destination = vectorSnapshot(destination), target = recovery.target and recovery.target.Name})
            task.wait(EventFarm.SeaBeastBeamDescentRetryDelay)
        end
        return false, lastReason or "recovery_stopped"
    end

    local function returnToBoat(generation, reason)
        local runtime = EventFarm.Runtime
        -- Returning is the terminal edge of this temporary boat orbit. Stop it
        -- before the character travels to the moving seat; the normal cruise
        -- writer resumes only after the player has re-entered that seat.
        if stopSeaBeastBoatAutonomy then stopSeaBeastBoatAutonomy("return_to_boat_" .. tostring(reason or "unknown")) end
        if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("return_to_boat_" .. tostring(reason or "unknown")) end
        if stopRaidBoatAutonomy then stopRaidBoatAutonomy("return_to_boat_" .. tostring(reason or "unknown")) end
        local recovery = isTargetLocked("sea_beast") and runtime.seaBeastEvadeRecovery or nil
        if recovery then
            local recovered, recoveryReason = recoverSeaBeastEvadePosition(generation, recovery, reason or "boat_return_guard")
            if not recovered then
                journal("sea_beast_boat_return_blocked_by_evade_recovery", {reason = reason, recoveryReason = recoveryReason, target = recovery.target and recovery.target.Name})
                return false, "sea_beast_evade_position_not_recovered_" .. tostring(recoveryReason)
            end
            runtime.seaBeastEvadeRecovery = nil
            -- If the original Sea Beast remains replicated, boat return is not
            -- permitted. The caller may reacquire/resume it, but cannot pull a
            -- distant seat/camera during post-evade recovery.
            if isSeaBeastTarget(recovery.target) and seaBeastAlive(recovery.target) then
                journal("sea_beast_boat_return_blocked_target_still_exists", {reason = reason, target = recovery.target.Name})
                return false, "sea_beast_still_exists_after_evade_recovery"
            end
        end
        local seat = runtime.seat
        if not seat or not seat.Parent then return false, "boat_missing" end
        local playerRoot = rootPart()
        local boatDistance = playerRoot and distance(playerRoot.Position, seat.Position) or math.huge
        if boatDistance > EventFarm.BoatFarReplacementDistance then
            runtime.boatLostReason = "boat_too_far_" .. tostring(math.floor(boatDistance))
            journal("boat_abandoned", {reason = reason, distance = boatDistance})
            return false, runtime.boatLostReason
        end
        setPhase("returning_to_boat", reason)
        endExternalCombat()
        local teleport = Flow.Features.Teleport
        if not teleport or not teleport.TravelDirectToPosition then return false, "direct_travel_unavailable" end

        -- Sea Beast and raid-boat return never bind the player to a lifted,
        -- moving seat from far away. TravelDirect must first confirm the current
        -- seat geometry; only then may Sit run. Terror Shark retains its
        -- established return routine below.
        local carefulReturnKind = nil
        if isTargetLocked("sea_beast") then carefulReturnKind = "sea_beast"
        elseif isRaidBoatKind(runtime.targetKind) then carefulReturnKind = "raid_boat" end
        if carefulReturnKind then
            local nearSeat, lastReason = false, nil
            for attempt = 1, EventFarm.SeaBeastBoatSeatTravelAttempts do
                if not isCurrent(generation) or not seat.Parent then break end
                local h, pNow = humanoid(), rootPart()
                local horizontal = pNow and horizontalDistance(pNow.Position, seat.Position) or math.huge
                local vertical = pNow and math.abs(pNow.Position.Y - seat.Position.Y) or math.huge
                nearSeat = horizontal <= EventFarm.SeaBeastBoatSeatHorizontalTolerance and vertical <= EventFarm.SeaBeastBoatSeatVerticalTolerance
                if nearSeat then break end
                -- A remote/physics seat attachment while still far is explicitly
                -- released; the boat is never CFramed or pulled toward player.
                if h and localOccupies(seat) then pcall(function() h.Sit = false end) end
                local moved, travelReason = teleport:TravelDirectToPosition(seat.Position + Vector3.new(0, 12, 0), "sea_event_return", "Event boat", {
                    holdArrivalVelocity = true, arrivalConfirmSeconds = 0.35, maxAttempts = 1,
                    ignoreNoSupportWater = true, disableAdaptiveClearance = true,
                })
                lastReason = travelReason
                pNow = rootPart()
                horizontal = pNow and horizontalDistance(pNow.Position, seat.Position) or math.huge
                vertical = pNow and math.abs(pNow.Position.Y - seat.Position.Y) or math.huge
                nearSeat = horizontal <= EventFarm.SeaBeastBoatSeatHorizontalTolerance and vertical <= EventFarm.SeaBeastBoatSeatVerticalTolerance
                journal(carefulReturnKind .. "_return_direct", {attempt = attempt, moved = moved == true, reason = travelReason, horizontal = horizontal, vertical = vertical, nearSeat = nearSeat == true})
                if nearSeat then break end
                task.wait(0.08)
            end
            if not nearSeat then
                journal(carefulReturnKind .. "_return_not_seated", {reason = reason, travelReason = lastReason})
                return false, carefulReturnKind .. "_boat_seat_unreached_" .. tostring(lastReason or "unknown")
            end
            local h = humanoid()
            if h and not localOccupies(seat) then pcall(function() seat:Sit(h) end) end
            local deadline = now() + 3
            repeat task.wait(0.05) until not isCurrent(generation) or localOccupies(seat) or now() >= deadline
            local pNow = rootPart()
            local geometryStillNear = pNow and horizontalDistance(pNow.Position, seat.Position) <= EventFarm.SeaBeastBoatSeatHorizontalTolerance
                and math.abs(pNow.Position.Y - seat.Position.Y) <= EventFarm.SeaBeastBoatSeatVerticalTolerance
            if localOccupies(seat) and geometryStillNear then return true end
            if h and localOccupies(seat) then pcall(function() h.Sit = false end) end
            return false, carefulReturnKind .. "_boat_seat_attach_unconfirmed"
        end

        local moved, travelReason = teleport:TravelDirectToPosition(seat.Position + Vector3.new(0, 12, 0), "sea_event_return", "Event boat", {
            holdArrivalVelocity = true, arrivalConfirmSeconds = 0.35, maxAttempts = 2,
        })
        if not moved then return false, "return_direct_failed_" .. tostring(travelReason) end
        local h = humanoid()
        if h then pcall(function() seat:Sit(h) end) end
        local deadline = now() + 3
        repeat task.wait(0.05) until not isCurrent(generation) or localOccupies(seat) or now() >= deadline
        return localOccupies(seat), localOccupies(seat) and nil or "could_not_reenter_boat"
    end

    -- Direct checkpoint combat is used only when activation found a live,
    -- selected target but no safely reusable boat. It owns player combat
    -- movement, never invents a boat or reuses a distant/unknown-health hull.
    function EventFarm:IsDirectCheckpoint(target, kind)
        local checkpoint = EventFarm.Runtime.progress and EventFarm.Runtime.progress.checkpoint
        return checkpoint and checkpoint.mode == "direct_target"
            and checkpoint.target == target and checkpoint.kind == kind
    end

    function EventFarm:CheckpointReturnOrResume(generation, target, kind, reason)
        if EventFarm:IsDirectCheckpoint(target, kind) then
            local runtime = EventFarm.Runtime
            journal("checkpoint_direct_target_finished", {
                kind = kind, target = target and target.Name or nil, reason = reason,
            })
            runtime.progress.checkpoint = nil
            setPhase("checkpoint_target_finished", tostring(kind) .. "_" .. tostring(reason))
            return true, "checkpoint_direct_finished"
        end
        return returnToBoat(generation, reason)
    end

    local function startCombat(generation, target)
        local function gate(kind, passed, fields)
            fields = fields or {}
            fields.passed = passed == true
            journal(kind, fields)
            return passed == true
        end
        if not gate("combat_gate_generation", isCurrent(generation), {generation = generation}) then return false, "generation_changed" end
        local runtime = EventFarm.Runtime
        local targetValid = isTerrorSharkTargetValid(target)
        if not gate("combat_gate_target_valid", targetValid, {target = target and target.Name}) then return false, "target_out_of_range" end
        local root = targetRoot(target)
        local characterRoot = rootPart()
        if not gate("combat_gate_roots", root ~= nil and characterRoot ~= nil, {targetRoot = root and root.Name, playerRoot = characterRoot and characterRoot.Name}) then
            return false, "terror_shark_or_character_root_missing"
        end
        local startDistance = distance(characterRoot.Position, root.Position)
        if not gate("combat_gate_distance_3000", startDistance <= EventFarm.TerrorSharkMaxCombatStartDistance, {distance = startDistance, limit = EventFarm.TerrorSharkMaxCombatStartDistance}) then
            runtime.targetBackoff[target] = now() + 8
            return false, "combat_target_too_distant"
        end
        if State.eventFarmMoveBoatAway then
            -- The existing safety toggle now owns a continuous native Terror
            -- Shark orbit, not a one-time parked distance. Require a verified
            -- armed lease before dismount so a failed preparation never leaves
            -- the selected boat stationary inside the fight.
            local mode = runtime.terrorSharkBoatAutonomy
            local orbitReady = mode and mode.active == true and mode.finalized ~= true
                and mode.target == target and mode.orbitArmed == true and localOccupies(runtime.seat)
            if not gate("combat_gate_boat_orbit", orbitReady, {
                target = target.Name, seated = localOccupies(runtime.seat),
                orbitActive = mode and mode.active == true or false,
                orbitArmed = mode and mode.orbitArmed == true or false,
                radius = mode and mode.lastRadius or nil,
                configuredRadius = EventFarm.TerrorSharkBoatAutonomyRadius,
            }) then
                return false, "terror_shark_boat_orbit_unconfirmed"
            end
        else
            journal("combat_gate_boat_orbit", {passed = true, bypass = "protective_orbit_disabled"})
        end
        local farm, teleport = Flow.Features.Farm, Flow.Features.Teleport
        local modulesReady = farm and type(farm.BeginExternalFollow) == "function" and teleport and type(teleport.TravelDirectToPosition) == "function"
        if not gate("combat_gate_modules_ready", modulesReady, {farm = farm ~= nil, directTravel = teleport and type(teleport.TravelDirectToPosition) == "function"}) then return false, "combat_modules_missing" end
        journal("combat_handoff_enter", {target = target.Name})
        setPhase("disembarking_for_combat")
        local h = humanoid()
        local seat = runtime.seat
        local playerRoot = rootPart()
        -- v1.6.4 diagnostics only. They do not alter the seat, Humanoid, hover,
        -- lift, or travel state; they establish whether a low physical boat
        -- position or an inherited mover is present at the precise handoff.
        journal("dismount_altitude_check", {
            seatY = seat and seat.Position.Y or nil,
            playerY = playerRoot and playerRoot.Position.Y or nil,
            sharkY = root and root.Position.Y or nil,
            boatLift = runtime.lift,
            targetLift = runtime.targetLift,
            waterLevelEstimate = 0,
            humanoidState = humanoidStateName(h),
            seated = localOccupies(seat),
        })
        local farmState = farm and farm.State
        journal("dismount_physics_check", {
            playerBV = playerRoot and playerRoot:FindFirstChild("BodyVelocity") ~= nil or false,
            playerBP = playerRoot and playerRoot:FindFirstChild("BodyPosition") ~= nil or false,
            hoverOwner = farmState and farmState.hoverOwner or nil,
            hoverConnection = farmState and farmState.hoverConnection ~= nil or false,
            humanoidState = humanoidStateName(h),
        })
        journal("combat_dismount_attempt", {seated = localOccupies(seat), humanoidState = humanoidStateName(h)})
        -- Temporarily prevent the VehicleSeat from re-engaging the Humanoid
        -- while the outbound direct travel is about to begin.
        local originalCanTouch = seat and seat.CanTouch
        local originalDisabled = seat and seat.Disabled
        if seat then
            pcall(function() seat.Disabled = true end)
            pcall(function() seat.CanTouch = false end)
        end
        if h then pcall(function() h.Sit = false end) end
        local leaveDeadline, stableSince = now() + 1.2, nil
        repeat
            task.wait(0.05)
            local freeNow = not localOccupies(seat)
            local notSitting = h and h.Sit == false
            if freeNow and notSitting then
                if not stableSince then stableSince = now()
                elseif now() - stableSince >= 0.15 then break end
            else
                stableSince = nil
            end
        until not isCurrent(generation) or now() >= leaveDeadline
        -- Restore the native seat exactly before normal combat/travel control.
        if seat then
            pcall(function() seat.Disabled = originalDisabled or false end)
            pcall(function() seat.CanTouch = originalCanTouch ~= false end)
        end
        if not isCurrent(generation) then return false, "generation_changed" end
        local dismounted = not localOccupies(seat) and h and h.Sit == false
        journal("combat_dismount_success", {
            passed = dismounted,
            stableFor = stableSince and now() - stableSince or 0,
            humanoidState = humanoidStateName(h),
            playerY = rootPart() and rootPart().Position.Y or nil,
            seatY = seat and seat.Position.Y or nil,
        })
        if not dismounted then return false, "could_not_disembark" end
        root = targetRoot(target)
        if not root or not targetAlive(target) then
            journal("combat_gate_target_before_travel", {passed = false, root = root and root.Name})
            return false, "target_lost_before_direct_travel"
        end
        -- A second guard catches any seat re-occupation after the protected
        -- dismount window but before the outbound route acquires its ticket.
        if localOccupies(runtime.seat) then
            journal("combat_gate_target_before_travel", {passed = false, reason = "reoccupied_seat"})
            return false, "dismount_reverted_before_travel"
        end
        journal("combat_gate_target_before_travel", {passed = true, root = root.Name})
        local playerRoot = rootPart()
        local offset = playerRoot and Vector3.new(playerRoot.Position.X - root.Position.X, 0, playerRoot.Position.Z - root.Position.Z) or Vector3.new(0, 0, 1)
        if offset.Magnitude < 1 then offset = Vector3.new(0, 0, 1) end
        runtime.combatOffset = offset.Unit * EventFarm.TerrorSharkCombatLateralOffset
        local destination = root.Position + runtime.combatOffset + Vector3.new(0, EventFarm.TerrorSharkCombatHeight, 0)
        local targetStartPosition = root.Position
        local travelStartedAt = now()
        local confirmWindows = {}
        local sampling = {active = true, sequence = 0}

        local function hostileShipFields(playerRoot)
            local ship, shipDistance = nearbyRaidBoat(playerRoot)
            local shipRoot = ship and targetRoot(ship)
            if not ship then return nil end
            return {
                ship_name = ship.Name,
                ship_pos = shipRoot and vectorSnapshot(shipRoot.Position) or nil,
                distance = shipDistance,
                script_phase = EventFarm.Runtime.phase,
                script_action = "continue_diagnostic_only",
            }
        end

        local function sampleCombatTravel(stage)
            local currentRoot = rootPart()
            local currentTargetRoot = targetRoot(target)
            local h = humanoid()
            sampling.sequence = sampling.sequence + 1
            journal("combat_travel_sample", {
                sequence = sampling.sequence,
                stage = stage,
                elapsed = now() - travelStartedAt,
                client_pos = currentRoot and vectorSnapshot(currentRoot.Position) or nil,
                requested_destination = vectorSnapshot(destination),
                target_pos = currentTargetRoot and vectorSnapshot(currentTargetRoot.Position) or nil,
                target_vel = currentTargetRoot and vectorSnapshot(currentTargetRoot.AssemblyLinearVelocity) or nil,
                delta_client_destination = currentRoot and distance(currentRoot.Position, destination) or nil,
                delta_client_target = currentRoot and currentTargetRoot and distance(currentRoot.Position, currentTargetRoot.Position) or nil,
                velocity = currentRoot and vectorSnapshot(currentRoot.AssemblyLinearVelocity) or nil,
                humanoid_state = humanoidStateName(h),
                localOccupiesSeat = runtime.seat and localOccupies(runtime.seat) or false,
            })
            local shipFields = hostileShipFields(currentRoot)
            if shipFields then journal("hostile_ship_detected", shipFields) end
        end

        -- v1.6.2 diagnostic: EventFarm itself has not started combat follow
        -- at this point; export any residual Farm hover before direct travel.
        local farmState = Flow.Features.Farm.State
        journal("pre_travel_hover_check", {
            hoverOwner = farmState.hoverOwner,
            hoverActive = farmState.hoverConnection ~= nil,
            correctionInterval = Flow.Features.Farm.HoverCorrectionInterval,
        })
        setPhase("combat_travel_direct")
        sampleCombatTravel("start")
        task.spawn(function()
            while sampling.active and isCurrent(generation) and EventFarm.Runtime.phase == "combat_travel_direct" do
                task.wait(0.10)
                if sampling.active and isCurrent(generation) and EventFarm.Runtime.phase == "combat_travel_direct" then
                    sampleCombatTravel("interval")
                end
            end
        end)
        local moved, travelReason = teleport:TravelDirectToPosition(destination, "sea_event_combat", "Terror Shark", {
            holdArrivalVelocity = true, arrivalConfirmSeconds = 0.35, maxAttempts = 2,
            arrivalDiagnostics = {
                onConfirmStart = function(data)
                    confirmWindows[data.attempt or #confirmWindows + 1] = {
                        attempt = data.attempt,
                        observationSeconds = data.observationSeconds,
                        playerRootVelocityAtConfirm = data.root and vectorSnapshot(data.root.AssemblyLinearVelocity) or nil,
                        humanoidStateAtConfirm = humanoidStateName(data.humanoid),
                    }
                end,
                onConfirmEnd = function(data)
                    local row = confirmWindows[data.attempt or #confirmWindows + 1] or {}
                    row.attempt = data.attempt
                    row.observationSeconds = data.observationSeconds
                    row.arrivalConfirmWindowFrames = data.frames
                    row.largestObservedPlayerStep = data.largestStep
                    row.confirmed = data.confirmed
                    row.finalDestinationDelta = data.distance
                    row.playerRootVelocityAtEnd = data.root and vectorSnapshot(data.root.AssemblyLinearVelocity) or nil
                    row.humanoidStateAtEnd = humanoidStateName(data.humanoid)
                    confirmWindows[data.attempt or #confirmWindows + 1] = row
                end,
            },
        })
        sampling.active = false
        sampleCombatTravel("end")
        local currentRoot, currentTargetRoot = rootPart(), targetRoot(target)
        local lastWindow = confirmWindows[#confirmWindows]
        journal("combat_travel_outcome", {
            passed = moved == true,
            reason = travelReason,
            elapsed = now() - travelStartedAt,
            requested_destination = vectorSnapshot(destination),
            final_player_pos = currentRoot and vectorSnapshot(currentRoot.Position) or nil,
            final_target_pos = currentTargetRoot and vectorSnapshot(currentTargetRoot.Position) or nil,
            final_destination_delta = currentRoot and distance(currentRoot.Position, destination) or nil,
            final_target_delta = currentRoot and currentTargetRoot and distance(currentRoot.Position, currentTargetRoot.Position) or nil,
            target_displacement_since_start = currentTargetRoot and distance(currentTargetRoot.Position, targetStartPosition) or nil,
            arrivalConfirmWindowFrames = lastWindow and lastWindow.arrivalConfirmWindowFrames or 0,
            playerRootVelocityAtConfirm = lastWindow and lastWindow.playerRootVelocityAtConfirm or nil,
            playerRootVelocityAtEnd = lastWindow and lastWindow.playerRootVelocityAtEnd or nil,
            humanoidStateAtConfirm = lastWindow and lastWindow.humanoidStateAtConfirm or nil,
            humanoidStateAtEnd = lastWindow and lastWindow.humanoidStateAtEnd or nil,
            arrivalConfirmWindows = confirmWindows,
        })
        journal("combat_travel_return", {passed = moved == true, reason = travelReason})
        if not moved then return false, "combat_direct_failed_" .. tostring(travelReason) end
        if not isCurrent(generation) or not targetAlive(target) then return false, "target_lost_after_direct_travel" end
        root = targetRoot(target)
        local arrivalDistance = root and rootPart() and distance(rootPart().Position, root.Position) or math.huge
        journal("combat_arrival_distance", {distance = arrivalDistance, limit = 180, passed = arrivalDistance <= 180})
        if not root or not rootPart() or arrivalDistance > 180 then return false, "combat_direct_arrival_unconfirmed" end
        local followStarted = combatFollow(target)
        if not followStarted then return false, "combat_follow_not_started" end
        setPhase("combat", "direct_arrival_confirmed")
        journal("combat_ready", {target = target.Name, distance = arrivalDistance})
        -- v1.6.0 FIX-13: Travel confirms its static destination, while a live
        -- Shark can have moved substantially during the route. BeginExternalFollow
        -- above already owns the provider; force two target-relative samples before
        -- the first Farm range check when the post-travel gap exceeds hit range.
        if arrivalDistance > 80 then
            journal("combat_reanchor", {initialDistance = arrivalDistance, limit = 80})
            if farm and type(farm.ApplyHover) == "function" then
                pcall(function() farm:ApplyHover(true) end)
                task.wait(0.05)
                pcall(function() farm:ApplyHover(true) end)
            end
        end
        if not Flow.State.farmAutoAttack then
            Flow.State.farmAutoAttack = true
            journal("combat_forced_auto_attack", {reason = "was_disabled"})
            notify("Farm Eventos", "Auto Attack estava desligado; ligado automaticamente para o combate.", "warning", "auto_attack_forced", 3)
        end
        attackTerrorShark(target)
        return true
    end

    -- Sea Beast combat is deliberately skill-only. It uses normal local key
    -- input after equipping a Tool; no Farm:Attack/M1 path or combat Remote is
    -- used here. Cooldown UI is the gate, so a cooling key is skipped and the
    -- next configured key/category is tried immediately.
    local seaBeastSkillPlan = {
        {id="sword", tooltip="Sword", configPrefix="comboSkillSword", keys={"Z", "X"}},
        {id="weapon", tooltip="Gun", configPrefix="comboSkillWeapon", keys={"Z", "X"}},
        {id="fruit", tooltip="Blox Fruit", configPrefix="comboSkillFruit", keys={"Z", "X", "C", "V", "F"}},
        {id="fighting", tooltip="Melee", configPrefix="comboSkillFighting", keys={"Z", "X", "C"}},
    }
    -- Low-level Moveset aim is deliberately not applied to pure mobility
    -- casts. Normalization removes punctuation/spaces so the same rule covers
    -- in-game variants such as Light-Light, T-Rex and Cursed Dual Katana.
    local mobilityAimBypass = {
        portal={F=true, X=true, C=true}, rumble={F=true}, lightning={F=true}, lightninglightning={F=true},
        light={F=true}, lightlight={F=true}, control={F=true}, pain={F=true}, rubber={F=true}, rubberrubber={F=true},
        kitsune={F=true}, leopard={F=true}, tiger={F=true}, dough={F=true}, doughdough={F=true}, rocket={F=true},
        smoke={F=true}, spring={F=true}, spin={F=true}, falcon={F=true}, phoenix={F=true}, gravity={F=true},
        trex={F=true}, venom={F=true}, dragon={F=true}, mammoth={F=true}, yeti={F=true}, spirit={F=true},
        gas={F=true}, blizzard={F=true}, creation={F=true}, quake={F=true}, shadow={F=true}, sound={F=true},
        blade={F=true}, dark={F=true}, diamond={F=true}, eagle={F=true}, magma={F=true}, buddha={F=true},
        deathstep={Z=true}, electricclaw={Z=true, X=true}, superhuman={Z=true}, godhuman={Z=true},
        sharkmankarate={Z=true}, darkstep={Z=true}, dragontalon={Z=true}, combat={Z=true},
        truetriplekatana={Z=true}, curseddualkatana={Z=true}, gravityblade={Z=true}, darkblade={Z=true},
        dragonheart={Z=true}, hallowscythe={Z=true}, buddysword={Z=true}, saber={Z=true}, saberv2={Z=true},
        soulcane={Z=true}, bisento={Z=true}, pole={Z=true}, polev1={Z=true}, polev2={Z=true},
        dragontrident={Z=true}, shisui={Z=true}, rengoku={Z=true},
        acidumrifle={Z=true}, serpentbow={Z=true}, kabucha={Z=true}, venombow={Z=true},
        mysticslingshot={Z=true}, mysticslingshot={Z=true}, frostbreath={Z=true}, hellthrower={Z=true},
        dragonstorm={Z=true}, refinedslingshot={Z=true}, dualflintlock={Z=true}, magmablaster={Z=true}, bazooka={Z=true},
    }
    local function normalizedSkillToolName(name)
        return lower(name):gsub("[^%w]", "")
    end
    local function mobilityAimRule(toolName, key)
        local normalized = normalizedSkillToolName(toolName)
        local keys = mobilityAimBypass[normalized]
        local normalizedKey = string.upper(tostring(key or ""))
        return keys and keys[normalizedKey] == true, normalized .. ":" .. normalizedKey
    end
    local seaBeastAnimatorConnections = setmetatable({}, {__mode = "k"})
    local seaBeastSoundConnections = setmetatable({}, {__mode = "k"})
    local trySeaBeastEvade

    local function disconnectSeaBeastAttackWatch()
        local runtime = EventFarm.Runtime
        for _, connection in ipairs(runtime.seaBeastConnections or {}) do pcall(function() connection:Disconnect() end) end
        runtime.seaBeastConnections = {}
        runtime.seaBeastBeamSignal = nil
        -- A stopped run may be enabled again in the same Hub instance. Forget
        -- previous bindings after disconnecting so live sounds/animators are
        -- attached again on the new generation.
        seaBeastAnimatorConnections = setmetatable({}, {__mode = "k"})
        seaBeastSoundConnections = setmetatable({}, {__mode = "k"})
    end

    local function seaBeastModelAncestor(item)
        local folder = Workspace and Workspace:FindFirstChild("SeaBeasts")
        local cursor = item
        while cursor and cursor ~= Workspace do
            if cursor:IsA("Model") and cursor.Parent == folder and isSeaBeastName(cursor.Name) then return cursor end
            cursor = cursor.Parent
        end
        return nil
    end

    local function isSeaBeastPreBeamAnimation(track)
        local animation = track and track.Animation
        local id = lower(animation and animation.AnimationId):gsub("[^%d]", "")
        return id == "8708221792"
    end

    local function seaBeastObservationKey()
        local ok, bindings = pcall(function()
            return game:GetService("ContextActionService"):GetAllBoundActionInfo()
        end)
        local action = ok and bindings and bindings.BoundActionKen
        for _, inputType in ipairs(action and action.inputTypes or {}) do
            if typeof(inputType) == "EnumItem" and inputType.EnumType == Enum.KeyCode and not inputType.Name:find("DPad", 1, true) then
                return inputType
            end
        end
        return nil
    end

    local function pressSeaBeastObservationKey(key)
        local input = Flow.Services.VirtualInputManager
        if input and key then
            local down = pcall(function() input:SendKeyEvent(true, key, false, game) end)
            if down then
                task.delay(EventFarm.SeaBeastObservationReleaseSeconds, function()
                    pcall(function() input:SendKeyEvent(false, key, false, game) end)
                end)
                return true, "VirtualInputManager"
            end
        end
        local executor = Flow.Executor or {}
        if key and type(executor.keypress) == "function" and type(executor.keyrelease) == "function" then
            local pressed = pcall(function() executor.keypress(key.Value) end)
            if pressed then
                task.delay(EventFarm.SeaBeastObservationReleaseSeconds, function() pcall(function() executor.keyrelease(key.Value) end) end)
                return true, "keypress"
            end
        end
        return false, "observation_input_unavailable"
    end

    local function triggerSeaBeastObservationAtLaunch(target, source)
        local runtime = EventFarm.Runtime
        if State.eventFarmSeaBeastObservationDodge ~= true or not runtime.active
            or not canContinueTarget("sea_beast") or runtime.target ~= target
            or runtime.seaBeastCombatReady ~= true or not isSeaBeastTarget(target) or not seaBeastAlive(target) then return end
        local observation = runtime.seaBeastObservation or {attempts = 0, activated = 0, skippedActive = 0, skippedNoDodges = 0, skippedUnavailable = 0}
        runtime.seaBeastObservation = observation
        if now() - (observation.lastAt or -math.huge) < EventFarm.SeaBeastObservationDebounce then return end
        observation.lastAt = now()
        observation.attempts = (observation.attempts or 0) + 1
        -- Never toggle it early or turn it off. A pre-existing active Ken is
        -- retained and no second input is emitted for the same launch.
        if player:GetAttribute("KenActive") == true then
            observation.skippedActive = (observation.skippedActive or 0) + 1
            journal("sea_beast_observation_launch", {sent = false, reason = "ken_already_active", source = tostring(source), dodgesLeft = player:GetAttribute("KenDodgesLeft")})
            return
        end
        local dodgesLeft = tonumber(player:GetAttribute("KenDodgesLeft"))
        if dodgesLeft and dodgesLeft <= 0 then
            observation.skippedNoDodges = (observation.skippedNoDodges or 0) + 1
            journal("sea_beast_observation_launch", {sent = false, reason = "ken_no_dodges", source = tostring(source), dodgesLeft = dodgesLeft})
            return
        end
        local key = seaBeastObservationKey()
        if not key then
            observation.skippedUnavailable = (observation.skippedUnavailable or 0) + 1
            journal("sea_beast_observation_launch", {sent = false, reason = "ken_binding_unavailable", source = tostring(source), dodgesLeft = dodgesLeft})
            return
        end
        -- Key-down happens in this marker callback: no pre-beam delay and no
        -- long-lived Haki state. Key-up is scheduled 35 ms later.
        local sent, route = pressSeaBeastObservationKey(key)
        if sent then observation.activated = (observation.activated or 0) + 1; observation.lastKey = key.Name end
        journal("sea_beast_observation_launch", {sent = sent == true, source = tostring(source), key = key.Name, route = route, dodgesLeft = dodgesLeft})
        task.delay(0.12, function()
            if runtime.seaBeastObservation == observation then
                journal("sea_beast_observation_result", {key = key.Name, kenActive = player:GetAttribute("KenActive") == true, dodgesLeft = player:GetAttribute("KenDodgesLeft")})
            end
        end)
    end

    local function recordSeaBeastAttackSignal(kind, source, target)
        local runtime = EventFarm.Runtime
        target = target or runtime.target
        -- Observation remains narrow: it is pressed only at the replicated
        -- launch marker/launch Beam, never when the charging animation begins.
        if kind == "beam_marker" then triggerSeaBeastObservationAtLaunch(target, source) end

        -- While a pre-beam direct climb is active, this is the matching launch
        -- acknowledgement. It must be accepted outside the normal combat phase
        -- because the climb deliberately stopped combat follow and skills.
        if kind == "beam_marker" and runtime.seaBeastEvadeActive == true
            and runtime.seaBeastBeamClimbActive == true and runtime.target == target
            and isSeaBeastTarget(target) and seaBeastAlive(target) then
            if not runtime.seaBeastBeamLaunch then
                runtime.seaBeastBeamLaunch = {at = now(), source = tostring(source), target = target}
                journal("sea_beast_beam_launch_confirmed", {source = tostring(source), target = target.Name})
            end
            return
        end

        if not runtime.active or not canContinueTarget("sea_beast") or runtime.seaBeastCombatReady ~= true
            or runtime.phase ~= "sea_beast_combat" or target ~= runtime.target or not seaBeastAlive(target) then return end
        if kind == "beam_marker" then
            -- The sound marker is a precise confirmation (and is kept in the
            -- journal), but live evidence places damage as soon as ~53 ms later.
            -- It must never be mistaken for the pre-attack climb trigger.
            journal("sea_beast_beam_marker_seen", {source = tostring(source), target = target.Name})
            return
        end
        if State.eventFarmSeaBeastBeamDodge ~= true and State.eventFarmSeaBeastAnimationDodge ~= true then return end
        if now() - (runtime.lastSeaBeastSignalAt or -math.huge) < EventFarm.SeaBeastBeamSignalDebounce then return end
        runtime.lastSeaBeastSignalAt = now()
        runtime.seaBeastBeamSignal = {at = now(), kind = kind, source = tostring(source), target = target}
        journal("sea_beast_attack_signal", {kind = kind, source = tostring(source), target = target.Name})
        task.spawn(function()
            if trySeaBeastEvade then pcall(trySeaBeastEvade, runtime.generation, target) end
        end)
    end

    local function bindSeaBeastSound(sound)
        if not sound or not sound:IsA("Sound") or seaBeastSoundConnections[sound] then return end
        local owner = seaBeastModelAncestor(sound)
        -- The confirmed live marker is normally global:
        -- Workspace._WorldOrigin.Sounds.ProxySound.SeaBeastBeam. Do not reject
        -- it merely because it has no Sea Beast ancestor; exact name plus the
        -- currently locked Sea Beast is the required association.
        if not owner and sound.Name ~= "SeaBeastBeam" then return end
        seaBeastSoundConnections[sound] = true
        local runtime = EventFarm.Runtime
        local function signal(route)
            local target = owner or runtime.target
            if not target then return end
            local broadChargeCue = owner and runtime.seaBeastEvadeActive == true
                and runtime.seaBeastBeamClimbActive == true and runtime.target == owner
            if sound.Name == "SeaBeastBeam" or broadChargeCue then
                recordSeaBeastAttackSignal("beam_marker", "SeaBeastSound." .. tostring(sound.Name) .. "." .. route, target)
            end
        end
        runtime.seaBeastConnections[#runtime.seaBeastConnections + 1] = sound.Played:Connect(function() signal("Played") end)
        runtime.seaBeastConnections[#runtime.seaBeastConnections + 1] = sound:GetPropertyChangedSignal("Playing"):Connect(function() if sound.Playing then signal("Playing") end end)
    end

    local function bindSeaBeastAnimator(animator)
        if not animator or not animator:IsA("Animator") or seaBeastAnimatorConnections[animator] then return end
        local target = seaBeastModelAncestor(animator)
        if not target then return end
        seaBeastAnimatorConnections[animator] = true
        local runtime = EventFarm.Runtime
        runtime.seaBeastConnections[#runtime.seaBeastConnections + 1] = animator.AnimationPlayed:Connect(function(track)
            if isSeaBeastPreBeamAnimation(track) and runtime.target == target
                and runtime.phase == "sea_beast_combat" and not runtime.seaBeastEvadeActive then
                runtime.seaBeastPreBeamTracks = runtime.seaBeastPreBeamTracks or setmetatable({}, {__mode = "k"})
                if runtime.seaBeastPreBeamTracks[track] then return end
                runtime.seaBeastPreBeamTracks[track] = true
                recordSeaBeastAttackSignal("prebeam_animation", "animation_8708221792", target)
            end
        end)
    end

    local function scanSeaBeastPreBeamTracks(target, source)
        local runtime = EventFarm.Runtime
        if not target or not isSeaBeastTarget(target) or runtime.target ~= target
            or runtime.phase ~= "sea_beast_combat" or runtime.seaBeastEvadeActive then return end
        runtime.seaBeastPreBeamTracks = runtime.seaBeastPreBeamTracks or setmetatable({}, {__mode = "k"})
        for _, item in ipairs(target:GetDescendants()) do
            if item:IsA("Animator") then
                local ok, tracks = pcall(function() return item:GetPlayingAnimationTracks() end)
                if ok and type(tracks) == "table" then
                    for _, track in ipairs(tracks) do
                        if isSeaBeastPreBeamAnimation(track) and not runtime.seaBeastPreBeamTracks[track] then
                            runtime.seaBeastPreBeamTracks[track] = true
                            recordSeaBeastAttackSignal("prebeam_animation", "playing_track_scan." .. tostring(source), target)
                        end
                    end
                end
            end
        end
    end

    local function installSeaBeastAttackWatch()
        disconnectSeaBeastAttackWatch()
        local runtime = EventFarm.Runtime
        for _, item in ipairs(Workspace:GetDescendants()) do
            if item:IsA("Sound") then bindSeaBeastSound(item)
            elseif item:IsA("Animator") then bindSeaBeastAnimator(item) end
        end
        runtime.seaBeastConnections[#runtime.seaBeastConnections + 1] = Workspace.DescendantAdded:Connect(function(item)
            if item:IsA("Sound") then
                bindSeaBeastSound(item)
            elseif item:IsA("Animator") then
                bindSeaBeastAnimator(item)
            elseif item.Name == "Beam" or item:IsA("Beam") then
                -- A visual launch may be a Workspace Beam or a descendant of the
                -- verified Sea Beast. It only acknowledges an existing Sea Beast
                -- charge; it never starts a dodge or affects Terror Shark.
                local owner = seaBeastModelAncestor(item)
                if (owner and owner == runtime.target) or item.Parent == Workspace then
                    recordSeaBeastAttackSignal("beam_marker", "SeaBeastVisual." .. tostring(item.Name) .. ".DescendantAdded", runtime.target)
                end
            end
        end)
    end

    local function seaBeastCombatFollow(target)
        local runtime, farm = EventFarm.Runtime, Flow.Features.Farm
        local pRoot = rootPart()
        local initial, combatOffset, combatHeight, anchorInfo, offsetSource = seaBeastCombatPlacement(target, pRoot and pRoot.Position)
        if not farm or not farm.BeginExternalFollow or not initial or not combatOffset or not combatHeight then return false, "sea_beast_follow_module_missing" end
        runtime.combatOffset = combatOffset
        runtime.seaBeastCombatHeight = combatHeight
        journal("sea_beast_follow_anchor", {target = target.Name, anchor = vectorSnapshot(initial), source = anchorInfo and anchorInfo.source, combatOffsetSource = offsetSource, combatHeight = combatHeight, combatOffset = vectorSnapshot(combatOffset)})
        return farm:BeginExternalFollow("sea_event_sea_beast", initial + combatOffset, function()
            local override = runtime.seaBeastBeamCalibrationOverride
            if override and now() < (override.untilAt or 0) then
                -- BeginExternalFollow adds `seaBeastCombatHeight` itself; convert
                -- the explicit player position supplied by calibration into that
                -- provider center without changing normal combat height rules.
                return override.position - Vector3.new(0, runtime.seaBeastCombatHeight or EventFarm.SeaBeastCombatHeight, 0)
            elseif override then
                runtime.seaBeastBeamCalibrationOverride = nil
            end
            local current, liveOffset = seaBeastCombatPlacement(target, rootPart() and rootPart().Position)
            return current and liveOffset and (current + liveOffset) or nil
        end, function()
            return canContinueTarget("sea_beast") and EventFarm.Runtime.active
                and EventFarm.Runtime.seaBeastCombatReady == true and EventFarm.Runtime.target == target
                and not EventFarm.Runtime.seaBeastEvadeActive and isSeaBeastTarget(target)
                and seaBeastAlive(target) and isSeaBeastTargetValid(target)
        end, runtime.seaBeastCombatHeight or EventFarm.SeaBeastCombatHeight)
    end

    local function findSeaBeastSkillTool(tooltip)
        local character = player and player.Character
        local backpack = player and player:FindFirstChildOfClass("Backpack")
        for _, container in ipairs({character, backpack}) do
            if container then
                for _, item in ipairs(container:GetChildren()) do
                    if item:IsA("Tool") and item.ToolTip == tooltip then return item end
                end
            end
        end
        return nil
    end

    local function seaBeastCooldownFrame(toolName, key)
        local pg = player and player:FindFirstChildOfClass("PlayerGui")
        local main = pg and pg:FindFirstChild("Main")
        local skills = main and main:FindFirstChild("Skills")
        local group = skills and skills:FindFirstChild(toolName)
        local slot = group and group:FindFirstChild(key)
        return slot and slot:FindFirstChild("Cooldown")
    end

    local function seaBeastCooldownReady(frame)
        if not frame or not frame.Parent then return true, "ui_missing" end
        local ok, width = pcall(function() return frame.AbsoluteSize.X end)
        return not ok or (width or 0) <= 1, ok and "ready" or "ui_read_failed"
    end

    local function equipSeaBeastTool(tool)
        local h, character = humanoid(), player and player.Character
        if not h or not tool then return false, "tool_or_humanoid_missing" end
        if tool.Parent == character then return true end
        pcall(function() h:UnequipTools() end)
        local called, err = pcall(function() h:EquipTool(tool) end)
        if not called then return false, tostring(err) end
        local deadline = now() + 0.8
        repeat task.wait(0.04) until tool.Parent == character or now() >= deadline or EventFarm.Runtime.seaBeastEvadeActive
        return tool.Parent == character, tool.Parent == character and nil or "equip_timeout"
    end

    -- Low-level Moveset Mouse aim ------------------------------------------------
    --
    -- Blox Fruits' MovesetClientRunner passes require(ReplicatedStorage.Mouse)
    -- into each tool runtime. Lightning V, for example, consumes that context's
    -- `mouse.Hit.p`, sends its own existing RemoteEvent with that point, then
    -- calls InvokeServer("V") with no direction argument. The old camera/global
    -- metamethod aimbot is intentionally replaced here: this lease temporarily
    -- owns only the module table's Hit/Target fields for one selected cast.
    local function movesetAimEnvironment()
        local environment = _G
        local ok, global = pcall(function() return getgenv and getgenv() or nil end)
        if ok and type(global) == "table" then environment = global end
        return type(environment) == "table" and environment or nil
    end

    local function releaseMovesetModuleAim(bridge, reason)
        if not bridge or bridge.installed ~= true then return end
        bridge.active = nil
        local mouse = bridge.mouse
        local ok, err = pcall(function()
            if mouse then
                setmetatable(mouse, bridge.originalMetatable)
                rawset(mouse, "Hit", bridge.lastNativeHit or bridge.originalHit)
                rawset(mouse, "Target", bridge.lastNativeTarget or bridge.originalTarget)
            end
        end)
        bridge.installed = false
        bridge.releaseReason = tostring(reason or "released")
        bridge.lastRestoreError = ok and nil or tostring(err)
    end

    local function movesetAimBridge()
        local environment = movesetAimEnvironment()
        if not environment then return nil, "aim_environment_unavailable" end
        local bridge = environment.FlowKanMovesetModuleAim
        if type(bridge) ~= "table" then
            bridge = {installed = false, active = nil, route = "moveset_mouse_module_v1"}
            environment.FlowKanMovesetModuleAim = bridge
        end
        -- A standalone exploratory lease uses the same Mouse module. Never
        -- layer two table metatables; release it before EventFarm owns a cast.
        local standalone = environment.FlowKanModuleMouseLowLevelAim
        if type(standalone) == "table" and standalone.Active == true and type(standalone.Stop) == "function" then
            pcall(function() standalone:Stop("event_farm_module_aim_takeover") end)
        end
        return bridge, bridge.route
    end

    local function nativeMovesetRead(indexer, tableValue, key)
        if type(indexer) == "function" then return indexer(tableValue, key) end
        if type(indexer) == "table" then return indexer[key] end
        return nil
    end

    local function nativeMovesetWrite(indexer, tableValue, key, value)
        if type(indexer) == "function" then return indexer(tableValue, key, value) end
        if type(indexer) == "table" then indexer[key] = value; return end
        rawset(tableValue, key, value)
    end

    local seaBeastSkillAimPoint

    local function activeMovesetAimGeometry(activation)
        if not activation or now() > (activation.untilAt or 0) then return nil end
        if now() >= (activation.nextRefreshAt or 0) then
            local point, part = seaBeastSkillAimPoint(activation.target, activation.rootOverride)
            activation.point, activation.targetPart = point, part
            activation.nextRefreshAt = now() + 0.05
        end
        local point, part = activation.point, activation.targetPart
        if not point or not part or not part.Parent then return nil end
        local camera = Workspace and Workspace.CurrentCamera
        local hit = camera and CFrame.new(point, camera.CFrame.Position) or CFrame.new(point)
        return hit, part, point
    end

    local function installMovesetModuleAim(bridge)
        if bridge.installed == true and bridge.mouse then return true, bridge.route end
        local mouseModule = ReplicatedStorage and ReplicatedStorage:FindFirstChild("Mouse")
        if not mouseModule then return false, "moveset_mouse_module_missing" end
        local ok, mouse = pcall(require, mouseModule)
        if not ok or type(mouse) ~= "table" then return false, "moveset_mouse_require_failed" end
        local originalMetatable = getmetatable(mouse)
        local originalIndex = originalMetatable and originalMetatable.__index
        local originalNewIndex = originalMetatable and originalMetatable.__newindex
        bridge.mouse, bridge.originalMetatable = mouse, originalMetatable
        bridge.originalHit, bridge.originalTarget = rawget(mouse, "Hit"), rawget(mouse, "Target")
        bridge.lastNativeHit, bridge.lastNativeTarget = bridge.originalHit, bridge.originalTarget
        local replacement = {
            __index = function(tableValue, key)
                local activation = bridge.active
                if activation and key == "Hit" then
                    local hit = activeMovesetAimGeometry(activation)
                    if hit then
                        activation.moduleReads = (activation.moduleReads or 0) + 1
                        return hit
                    end
                    return bridge.lastNativeHit or bridge.originalHit
                end
                if activation and key == "Target" then
                    local _, part = activeMovesetAimGeometry(activation)
                    if part then
                        activation.moduleReads = (activation.moduleReads or 0) + 1
                        return part
                    end
                    return bridge.lastNativeTarget or bridge.originalTarget
                end
                return nativeMovesetRead(originalIndex, tableValue, key)
            end,
            __newindex = function(tableValue, key, value)
                if bridge.active and key == "Hit" then
                    bridge.lastNativeHit = value
                    bridge.active.nativeWrites = (bridge.active.nativeWrites or 0) + 1
                    return
                end
                if bridge.active and key == "Target" then
                    bridge.lastNativeTarget = value
                    bridge.active.nativeWrites = (bridge.active.nativeWrites or 0) + 1
                    return
                end
                return nativeMovesetWrite(originalNewIndex, tableValue, key, value)
            end,
        }
        local installed, installError = pcall(function()
            -- Clearing these existing raw fields routes the game's recurring
            -- Mouse update writes through the scoped table metatable. It is not
            -- a global game hook and it is restored at cast cleanup.
            rawset(mouse, "Hit", nil)
            rawset(mouse, "Target", nil)
            setmetatable(mouse, replacement)
        end)
        if not installed then
            bridge.mouse = nil
            return false, "moveset_mouse_install_failed:" .. tostring(installError)
        end
        bridge.installed, bridge.route = true, "moveset_mouse_module_v1"
        return true, bridge.route
    end

    seaBeastSkillAimPoint = function(target, rootOverride)
        local fallback = rootOverride or targetRoot(target)
        local point, part = fallback and fallback.Position or nil, fallback
        local ok, box, size = pcall(function() return target:GetBoundingBox() end)
        if ok and box and size and size.Y > 0 then
            -- Aim at the upper-middle of the live box rather than the often
            -- submerged root. This follows replicated target geometry only.
            point = box.Position + Vector3.new(0, size.Y * 0.15, 0)
        end
        return point, part
    end

    local function beginSeaBeastSkillAim(target, statsKey, rootOverride, toolName, key)
        local runtime = EventFarm.Runtime
        statsKey = statsKey or "seaBeastSkillAim"
        local stats = runtime[statsKey] or {attempts = 0, applied = 0, moduleReads = 0, nativeWrites = 0, mobilityBypassed = 0, unavailable = 0, lastRoute = nil, lastPoint = nil, lastMobilityRule = nil}
        runtime[statsKey] = stats
        stats.attempts = (stats.attempts or 0) + 1
        local point = seaBeastSkillAimPoint(target, rootOverride)
        local bypass, mobilityRule = mobilityAimRule(toolName, key)
        if bypass then
            stats.mobilityBypassed = (stats.mobilityBypassed or 0) + 1
            stats.lastRoute, stats.lastPoint, stats.lastMobilityRule = "mobility_skill_bypassed", vectorSnapshot(point), mobilityRule
            return false, stats.lastRoute, point
        end
        local bridge, route = movesetAimBridge()
        if not bridge then
            stats.unavailable = (stats.unavailable or 0) + 1
            stats.lastRoute = route
            return false, route, point
        end
        if bridge.active then releaseMovesetModuleAim(bridge, "superseded_by_next_cast") end
        local installed, installRoute = installMovesetModuleAim(bridge)
        if not installed then
            stats.unavailable = (stats.unavailable or 0) + 1
            stats.lastRoute = installRoute
            return false, installRoute, point
        end
        local activation = {
            target = target, rootOverride = rootOverride, point = point, targetPart = rootOverride or targetRoot(target),
            nextRefreshAt = 0, untilAt = now() + EventFarm.SeaBeastSkillAimHoldSeconds,
            stats = stats, moduleReads = 0, nativeWrites = 0, tool = toolName, key = key,
        }
        bridge.active = activation
        stats.applied = (stats.applied or 0) + 1
        stats.lastRoute, stats.lastPoint, stats.lastMobilityRule = installRoute, vectorSnapshot(point), nil
        task.delay(EventFarm.SeaBeastSkillAimHoldSeconds, function()
            if bridge.active == activation and now() >= activation.untilAt then
                stats.moduleReads = (stats.moduleReads or 0) + (activation.moduleReads or 0)
                stats.nativeWrites = (stats.nativeWrites or 0) + (activation.nativeWrites or 0)
                releaseMovesetModuleAim(bridge, "cast_window_elapsed")
            end
        end)
        return true, installRoute, point
    end

    clearSeaBeastSkillAim = function()
        local environment = movesetAimEnvironment()
        local bridge = environment and environment.FlowKanMovesetModuleAim
        if bridge and bridge.active then
            local activation = bridge.active
            local stats = activation.stats
            if stats then
                stats.moduleReads = (stats.moduleReads or 0) + (activation.moduleReads or 0)
                stats.nativeWrites = (stats.nativeWrites or 0) + (activation.nativeWrites or 0)
            end
            releaseMovesetModuleAim(bridge, "cleared")
        end
    end

    local function sendSeaBeastKey(key, target, statsKey, rootOverride, tapSeconds, toolName)
        local input = Flow.Services.UserInputService
        if input and input:GetFocusedTextBox() then return false, "text_box_focused" end
        local code = Enum.KeyCode[key]
        if not code then return false, "invalid_key", "aim_not_started", nil end
        local aimed, aimRoute, aimPoint = beginSeaBeastSkillAim(target, statsKey, rootOverride, toolName, key)
        local vim = Flow.Services.VirtualInputManager
        if vim then
            local ok = pcall(function()
                vim:SendKeyEvent(true, code, false, game)
                task.wait(tapSeconds or EventFarm.SeaBeastSkillTapSeconds)
                vim:SendKeyEvent(false, code, false, game)
            end)
            if ok then return true, "VirtualInputManager", aimRoute, aimPoint, aimed end
        end
        local executor = Flow.Executor or {}
        if type(executor.keypress) == "function" and type(executor.keyrelease) == "function" then
            local ok = pcall(function()
                executor.keypress(code.Value)
                task.wait(tapSeconds or EventFarm.SeaBeastSkillTapSeconds)
                executor.keyrelease(code.Value)
            end)
            if ok then return true, "keypress", aimRoute, aimPoint, aimed end
        end
        if clearSeaBeastSkillAim then clearSeaBeastSkillAim() end
        return false, "input_unavailable", aimRoute, aimPoint, aimed
    end

    local function runSeaBeastSkillCycle(generation, target)
        local runtime = EventFarm.Runtime
        -- Hard isolate the local key-input scheduler. The system cannot send a
        -- skill unless this exact, currently selected model is a named Sea Beast
        -- in Workspace.SeaBeasts and the Sea Beast combat phase is live.
        if not canContinueTarget("sea_beast") or runtime.phase ~= "sea_beast_combat"
            or runtime.target ~= target or runtime.seaBeastCombatReady ~= true
            or runtime.seaBeastEvadeActive or not isSeaBeastTarget(target) or not seaBeastAlive(target) then return end
        local skillState = runtime.seaBeastSkill
        skillState.cycles = (skillState.cycles or 0) + 1
        for _, category in ipairs(seaBeastSkillPlan) do
            for _, key in ipairs(category.keys) do
                if not isCurrent(generation) or not canContinueTarget("sea_beast")
                    or runtime.phase ~= "sea_beast_combat" or runtime.target ~= target
                    or runtime.seaBeastCombatReady ~= true or runtime.seaBeastEvadeActive
                    or not isSeaBeastTarget(target) or not seaBeastAlive(target) then return end
                local configKey = category.configPrefix .. key
                if State[configKey] == false then
                    skillState.skippedDisabled = (skillState.skippedDisabled or 0) + 1
                else
                    local tool = findSeaBeastSkillTool(category.tooltip)
                    if not tool then
                        journal("sea_beast_skill_missing_tool", {category = category.id, key = key, tooltip = category.tooltip})
                    else
                        local attemptKey = tool.Name .. ":" .. key
                        local cooldown = seaBeastCooldownFrame(tool.Name, key)
                        local ready = seaBeastCooldownReady(cooldown)
                        if not ready then
                            skillState.skippedCooldown = (skillState.skippedCooldown or 0) + 1
                        elseif now() - (skillState.lastTry[attemptKey] or -math.huge) < EventFarm.SeaBeastSkillRetrySeconds then
                            -- A skill which produced no local cooldown is not spammed every
                            -- frame; other configured skills continue in the same cycle.
                        else
                            local equipped, equipReason = equipSeaBeastTool(tool)
                            if equipped and not runtime.seaBeastEvadeActive then
                                cooldown = seaBeastCooldownFrame(tool.Name, key)
                                ready = seaBeastCooldownReady(cooldown)
                                if ready then
                                    skillState.lastTry[attemptKey] = now()
                                    local sent, route, aimRoute, aimPoint, aimed = sendSeaBeastKey(key, target, nil, nil, nil, tool.Name)
                                    if sent then
                                        skillState.casts = (skillState.casts or 0) + 1
                                        skillState.lastRoute = route
                                        local deadline, accepted = now() + EventFarm.SeaBeastSkillStartWindow, false
                                        while isCurrent(generation) and not runtime.seaBeastEvadeActive and now() < deadline do
                                            local currentReady = seaBeastCooldownReady(cooldown)
                                            if not currentReady then accepted = true break end
                                            task.wait(0.03)
                                        end
                                        if accepted then skillState.confirmed = (skillState.confirmed or 0) + 1 end
                                        journal("sea_beast_skill_input", {
                                            category = category.id, tool = tool.Name, key = key, route = route,
                                            cooldownAccepted = accepted, aimApplied = aimed == true,
                                            aimRoute = aimRoute, aimPoint = aimPoint and vectorSnapshot(aimPoint) or nil,
                                        })
                                        task.wait(EventFarm.SeaBeastSkillPostCastSeconds)
                                    else
                                        journal("sea_beast_skill_input_failed", {
                                            category = category.id, tool = tool.Name, key = key, reason = route,
                                            aimRoute = aimRoute, aimPoint = aimPoint and vectorSnapshot(aimPoint) or nil,
                                        })
                                    end
                                end
                            else
                                journal("sea_beast_skill_equip_failed", {category = category.id, tool = tool.Name, key = key, reason = equipReason})
                            end
                        end
                    end
                end
            end
        end
    end

    local function dismountSeaBeastBoat(generation)
        local runtime, seat, h = EventFarm.Runtime, EventFarm.Runtime.seat, humanoid()
        if not seat or not seat.Parent then return false, "boat_seat_missing" end
        if not localOccupies(seat) then return true end
        local previousDisabled, previousCanTouch = seat.Disabled, seat.CanTouch
        pcall(function() seat.Disabled = true; seat.CanTouch = false end)
        if h then pcall(function() h.Sit = false end) end
        local deadline = now() + 1.2
        repeat task.wait(0.05) until not isCurrent(generation) or (not localOccupies(seat) and h and h.Sit == false) or now() >= deadline
        pcall(function() seat.Disabled = previousDisabled; seat.CanTouch = previousCanTouch end)
        if not isCurrent(generation) then return false, "stopped" end
        return not localOccupies(seat), not localOccupies(seat) and nil or "could_not_disembark"
    end

    local function travelToSeaBeastCombat(generation, target, owner)
        local teleport = Flow.Features.Teleport
        if not teleport or type(teleport.TravelDirectToPosition) ~= "function" then return false, "sea_beast_travel_module_missing" end
        if not canContinueTarget("sea_beast") or not isSeaBeastTarget(target) then return false, "sea_beast_target_identity_invalid" end
        if not seaBeastAlive(target) then return false, "sea_beast_target_lost" end
        local runtime = EventFarm.Runtime
        local travelReleased, travelReleaseReason = releaseEventFarmTravel("sea_beast_direct_handoff")
        if not travelReleased then
            journal("sea_beast_direct_handoff_blocked", {reason = travelReleaseReason, target = target.Name})
            return false, "sea_beast_travel_lock_" .. tostring(travelReleaseReason)
        end
        for attempt = 1, EventFarm.SeaBeastTravelRetries do
            if not isCurrent(generation) or not seaBeastAlive(target) then return false, "sea_beast_target_lost" end
            local pRoot = rootPart()
            local surface, combatOffset, combatHeight, anchorInfo, offsetSource = seaBeastCombatPlacement(target, pRoot and pRoot.Position)
            if not surface or not combatOffset or not combatHeight then return false, "sea_beast_surface_anchor_missing" end
            runtime.combatOffset = combatOffset
            runtime.seaBeastCombatHeight = combatHeight
            local destination = surface + runtime.combatOffset + Vector3.new(0, combatHeight, 0)
            local moved, reason = teleport:TravelDirectToPosition(destination, owner or "sea_event_sea_beast", "Sea Beast", {
                holdArrivalVelocity = true, arrivalConfirmSeconds = 0.35, maxAttempts = 2,
                ignoreNoSupportWater = true, disableAdaptiveClearance = true,
            })
            local pNow = rootPart()
            local latestSurface, latestInfo = seaBeastSurfaceAnchor(target, pNow and pNow.Position)
            local horizontal = pNow and latestSurface and horizontalDistance(pNow.Position, latestSurface) or math.huge
            local heightAboveSurface = pNow and latestSurface and (pNow.Position.Y - latestSurface.Y) or -math.huge
            local accepted = pNow and latestSurface
                and horizontal <= EventFarm.SeaBeastTravelHorizontalTolerance
                and heightAboveSurface >= EventFarm.SeaBeastTravelMinimumHeightAboveSurface
                and heightAboveSurface <= EventFarm.SeaBeastTravelMaximumHeightAboveSurface
            journal("sea_beast_travel_outcome", {
                target = target.Name, owner = owner, attempt = attempt, moved = moved == true, reason = reason,
                destination = vectorSnapshot(destination), destinationAnchor = vectorSnapshot(surface), anchorSource = anchorInfo and anchorInfo.source,
                combatOffsetSource = offsetSource, combatHeight = combatHeight, combatOffset = vectorSnapshot(runtime.combatOffset),
                finalPlayer = pNow and vectorSnapshot(pNow.Position) or nil, finalAnchor = latestSurface and vectorSnapshot(latestSurface) or nil,
                finalAnchorSource = latestInfo and latestInfo.source, horizontalDistance = horizontal, heightAboveSurface = heightAboveSurface,
                accepted = accepted == true,
            })
            -- `arrival_server_corrected` can still end in a valid safe combat
            -- position. Accept geometry, not merely the travel helper boolean.
            if accepted then return true, moved and "arrived" or "server_corrected_geometry_accepted" end
            if attempt < EventFarm.SeaBeastTravelRetries then task.wait(0.20) end
        end
        return false, "sea_beast_surface_arrival_unconfirmed"
    end

    -- Descend in target-relative TravelDirect segments after either a verified
    -- launch or an unconfirmed charge timeout. The Sea Beast is rechecked on
    -- every segment. As long as it exists, this never falls through to boat
    -- return: it descends to normal combat geometry and resumes attacks.
    local function descendSeaBeastToCombat(generation, target, exitReason)
        local runtime, teleport = EventFarm.Runtime, Flow.Features.Teleport
        if not teleport or type(teleport.TravelDirectToPosition) ~= "function" then return false, "direct_travel_missing" end
        setPhase("sea_beast_beam_descending", exitReason)
        local segments, lastReason = 0, nil
        while isCurrent(generation) and isAlive() and canContinueTarget("sea_beast") and runtime.target == target do
            if not isSeaBeastTarget(target) or not seaBeastAlive(target) then
                return false, "target_unavailable_during_descent"
            end
            local pRoot = rootPart()
            local surface, offset, combatHeight = seaBeastCombatPlacement(target, pRoot and pRoot.Position)
            if not pRoot or not surface or not offset or not combatHeight then return false, "combat_geometry_missing" end
            local destination = surface + offset + Vector3.new(0, combatHeight, 0)
            local horizontal = horizontalDistance(pRoot.Position, surface)
            local height = pRoot.Position.Y - surface.Y
            if horizontal <= EventFarm.SeaBeastTravelHorizontalTolerance
                and height >= EventFarm.SeaBeastTravelMinimumHeightAboveSurface
                and height <= EventFarm.SeaBeastTravelMaximumHeightAboveSurface then
                journal("sea_beast_beam_descent_ready", {reason = exitReason, segments = segments, heightAboveSurface = height, horizontalDistance = horizontal})
                return true, "combat_geometry_reached"
            end
            local nextY = math.max(destination.Y, pRoot.Position.Y - EventFarm.SeaBeastBeamDescentStep)
            local nextPosition = Vector3.new(destination.X, nextY, destination.Z)
            local moved, travelReason = teleport:TravelDirectToPosition(nextPosition, "sea_beast_beam_descend", "Sea Beast beam descend", {
                speed = EventFarm.SeaBeastBeamTravelSpeed, holdArrivalVelocity = true, arrivalConfirmSeconds = 0.05, maxAttempts = 1,
                ignoreNoSupportWater = true, disableAdaptiveClearance = true,
            })
            segments = segments + 1
            lastReason = travelReason
            journal("sea_beast_beam_descent_segment", {reason = exitReason, segment = segments, moved = moved == true, travelReason = travelReason, destination = vectorSnapshot(nextPosition)})
            task.wait(EventFarm.SeaBeastBeamDescentRetryDelay)
        end
        return false, lastReason or "descent_stopped"
    end

    trySeaBeastEvade = function(generation, target)
        local runtime = EventFarm.Runtime
        local signal = runtime.seaBeastBeamSignal
        if not canContinueTarget("sea_beast") or runtime.phase ~= "sea_beast_combat"
            or runtime.target ~= target or not isSeaBeastTarget(target)
            or not signal or runtime.seaBeastCombatReady ~= true or runtime.seaBeastEvadeActive
            or not isCurrent(generation) or not seaBeastAlive(target) then return false end
        local teleportState = Flow.Features.Teleport and Flow.Features.Teleport.ActiveTravel
        if teleportState and not teleportState.finished and not teleportState.cancelled then return false end
        if now() - signal.at > 0.8 then return false end
        runtime.seaBeastBeamSignal = nil
        if signal.kind ~= "prebeam_animation" then
            journal("sea_beast_beam_launch_without_charge", {source = signal.source, target = target.Name})
            return false
        end
        local teleport = Flow.Features.Teleport
        if not teleport or type(teleport.TravelDirectToPosition) ~= "function" then
            journal("sea_beast_beam_climb_unavailable", {reason = "direct_travel_missing", target = target.Name})
            return false
        end

        local preEvadeRoot = rootPart()
        if not preEvadeRoot then return false end
        runtime.seaBeastEvadeRecovery = {target = target, position = preEvadeRoot.Position, at = now()}
        runtime.seaBeastEvadeActive = true
        runtime.seaBeastBeamClimbActive = true
        runtime.seaBeastBeamLaunch = nil
        setPhase("sea_beast_beam_climb", signal.kind)
        -- This is the exact start of evade mode. The fixed three-second
        -- deadline is measured here, never from a later marker/absence check.
        local climbStarted = now()
        endSeaBeastCombat()
        local initialSurface, initialInfo = seaBeastSurfaceAnchor(target)
        if not initialSurface then
            runtime.seaBeastBeamClimbActive = false
            runtime.seaBeastEvadeActive = false
            return false
        end
        journal("sea_beast_beam_climb_enter", {signal = signal.kind, source = signal.source, step = EventFarm.SeaBeastBeamClimbStep, speed = EventFarm.SeaBeastBeamTravelSpeed, startedAt = climbStarted, returnAt = climbStarted + EventFarm.SeaBeastBeamEvadeSeconds, evadeSeconds = EventFarm.SeaBeastBeamEvadeSeconds, healthFloor = "disabled_fixed_window", anchor = vectorSnapshot(initialSurface), anchorSource = initialInfo and initialInfo.source})

        local segments, moved, lastReason, safetyExit = 0, false, nil, nil
        -- The target's range/alive/streaming checks are deliberately inactive
        -- here. The precise beam marker is recorded but does not end this lease:
        -- ascent continues for the whole three seconds from the early telegraph.
        while isCurrent(generation) and isAlive() and canContinueTarget("sea_beast")
            and runtime.target == target do
            if now() - climbStarted >= EventFarm.SeaBeastBeamEvadeSeconds then
                safetyExit = "evade_window_elapsed"
                break
            end
            -- The three-second deadline above is the sole non-death exit for a
            -- confirmed telegraph. Do not turn a low-health defensive moment
            -- into a zero-segment no-op; `isAlive()` already guards death.
            local current = rootPart()
            if not current then safetyExit = "player_root_missing"; break end
            local destination = current.Position + Vector3.new(0, EventFarm.SeaBeastBeamClimbStep, 0)
            local didMove, travelReason = teleport:TravelDirectToPosition(destination, "sea_beast_beam_climb", "Sea Beast beam climb", {speed = EventFarm.SeaBeastBeamTravelSpeed, holdArrivalVelocity = true, arrivalConfirmSeconds = 0.05, maxAttempts = 1, ignoreNoSupportWater = true, disableAdaptiveClearance = true})
            segments = segments + 1
            moved = moved or didMove == true
            lastReason = travelReason
            journal("sea_beast_beam_climb_segment", {segment = segments, moved = didMove == true, reason = travelReason, destination = vectorSnapshot(destination), capped = false})
            task.wait(EventFarm.SeaBeastBeamClimbRetryDelay)
        end

        local launch = runtime.seaBeastBeamLaunch
        runtime.seaBeastBeamClimbActive = false
        if not isAlive() then
            runtime.seaBeastEvadeActive = false
            journal("sea_beast_beam_return_skipped", {reason = "character_dead", signal = signal.kind, segments = segments})
            return false
        end
        local exitReason = safetyExit
        if not exitReason then
            runtime.seaBeastEvadeActive = false
            journal("sea_beast_beam_climb_exit_without_return", {signal = signal.kind, segments = segments, reason = lastReason, targetStillBound = runtime.target == target})
            return false
        end
        journal("sea_beast_beam_climb_return_begin", {reason = exitReason, launchSource = launch and launch.source, segments = segments, moved = moved == true})
        local descended, descentReason = descendSeaBeastToCombat(generation, target, exitReason)
        runtime.seaBeastEvadeActive = false
        if descended then
            runtime.seaBeastCombatReady = true
            local following, followReason = seaBeastCombatFollow(target)
            if following then
                runtime.seaBeastEvadeRecovery = nil
                setPhase("sea_beast_combat", "beam_descend_" .. exitReason)
                journal("sea_beast_beam_climb_exit", {signal = signal.kind, exitReason = exitReason, launchSource = launch and launch.source, segments = segments, moved = moved == true, returnSucceeded = true, descentReason = descentReason})
                return true
            end
            runtime.seaBeastCombatReady = false
            journal("sea_beast_beam_descent_follow_failed", {reason = followReason, exitReason = exitReason})
            return false
        end
        runtime.seaBeastCombatReady = false
        journal("sea_beast_beam_descent_failed", {reason = descentReason, exitReason = exitReason, targetExists = isSeaBeastTarget(target) and seaBeastAlive(target)})
        return false
    end

    local function startSeaBeastCombat(generation, target)
        local runtime = EventFarm.Runtime
        if not canContinueTarget("sea_beast") or not isSeaBeastTarget(target) then return false, "sea_beast_target_identity_invalid" end
        if not isSeaBeastTargetValid(target) then return false, "sea_beast_target_invalid" end
        runtime.target = target
        runtime.seaBeastCombatReady = false
        runtime.seaBeastKillWitness = nil
        runtime.seaBeastAltitudeViolation = nil
        -- Stay on the boat while the newly replicated model rises out of its
        -- temporary submerged spawn geometry. No combat Travel is allowed yet.
        setPhase("sea_beast_spawn_settling")
        local settled, settleInfo = waitForSeaBeastSpawnSurface(generation, target)
        if not settled then
            runtime.target = nil
            return false, "sea_beast_" .. tostring(settleInfo or "spawn_surface_not_stable")
        end
        setPhase("sea_beast_found", settleInfo and settleInfo.source)
        journal("sea_beast_boat_hold", {boat = runtime.boat and runtime.boat.Name or nil})
        -- The combat route must own Teleport before the boat is lifted or the
        -- character dismounts. Without this handoff, a residual long route
        -- returns `travel_busy`, so Sea Beast combat (and beam evade) never
        -- reaches its active phase.
        local travelReleased, travelReleaseReason = releaseEventFarmTravel("sea_beast_prepare")
        if not travelReleased then
            journal("sea_beast_combat_handoff_blocked", {reason = travelReleaseReason, target = target.Name})
            return false, "sea_beast_travel_lock_" .. tostring(travelReleaseReason)
        end
        local directCheckpoint = EventFarm:IsDirectCheckpoint(target, "sea_beast")
        if directCheckpoint then
            journal("checkpoint_direct_combat_begin", {kind = "sea_beast", target = target.Name, route = "no_reusable_boat"})
        else
            -- Temporary live experiment: lift the existing boat by 200 studs,
            -- arm a broad target-relative orbit while seated, then continue
            -- through the established Sea Beast dismount/travel flow.
            if EventFarm.SeaBeastBoatAutonomyExperiment == true then
                local ready, autonomyReason = startSeaBeastBoatAutonomy(generation, target)
                if ready then
                    journal("sea_beast_boat_autonomy_ready_for_dismount", {target = target.Name, lift = runtime.lift})
                    notify("Farm Eventos", "Barco em altura " .. tostring(EventFarm.SeaBeastBoatAutonomyLift) .. " e órbita ampla. Saindo para atacar o Sea Beast.", "info", "sea_beast_boat_autonomy", 2)
                else
                    journal("sea_beast_boat_autonomy_fallback", {target = target.Name, reason = autonomyReason})
                    notify("Farm Eventos", "Órbita do barco não foi confirmada; continuando o combate normal.", "warning", "sea_beast_boat_autonomy_fallback", 3)
                end
            end
            local dismounted, dismountReason = dismountSeaBeastBoat(generation)
            if not dismounted then
                if stopSeaBeastBoatAutonomy then stopSeaBeastBoatAutonomy("dismount_failed") end
                return false, dismountReason
            end
        end
        local arrived, travelReason = travelToSeaBeastCombat(generation, target, "sea_event_sea_beast")
        if not arrived then return false, "sea_beast_travel_failed_" .. tostring(travelReason) end
        local following, followReason = seaBeastCombatFollow(target)
        if not following then return false, followReason or "sea_beast_follow_not_started" end
        runtime.seaBeastCombatReady = true
        runtime.seaBeastPreBeamTracks = setmetatable({}, {__mode = "k"})
        runtime.nextSeaBeastPreBeamScan = 0
        setPhase("sea_beast_combat", "travel_arrived")
        scanSeaBeastPreBeamTracks(target, "combat_entry")
        notify("Farm Eventos", "Sea Beast alcançado: usando somente as skills ativas em Combo Settings.", "success", "sea_beast_combat", 2)
        return true
    end

    local function fightSeaBeast(generation, target)
        local runtime = EventFarm.Runtime
        local directCheckpoint = EventFarm:IsDirectCheckpoint(target, "sea_beast")
        local started, startReason = startSeaBeastCombat(generation, target)
        if not started then
            runtime.targetBackoff[target] = now() + EventFarm.SeaBeastTravelFailureBackoff
            runtime.seaBeastCombatReady = false
            runtime.target = nil
            local returned = EventFarm:CheckpointReturnOrResume(generation, target, "sea_beast", "sea_beast_start_failed")
            return returned and "sea_beast_start_failed" or (startReason or "sea_beast_start_failed")
        end
        -- A Sea Beast may stream or shift while TravelDirect owns beam evade.
        -- Do not treat target range/parent/health as a defeat or abandonment
        -- until evade releases its lease; player death still always wins.
        while isCurrent(generation) and (runtime.seaBeastEvadeActive or seaBeastAlive(target)) do
            local evadingBeam = runtime.seaBeastEvadeActive == true
            if not evadingBeam and not directCheckpoint then
                local tikiReturn, tikiReason = requiresFreshBoatAtTiki()
                if tikiReturn then
                    runtime.tikiReturnNeedsFreshBoat = true
                    runtime.tikiReturnReason = tikiReason
                    journal("sea_beast_tiki_return_rebuy", {reason = tikiReason, target = target.Name})
                    endSeaBeastCombat()
                    runtime.seaBeastCombatReady = false
                    runtime.target = nil
                    return "tiki_return_rebuy"
                end
            end
            if not evadingBeam and (not canContinueTarget("sea_beast") or not isSeaBeastTarget(target)) then
                journal("sea_beast_target_identity_guard", {target = target and target.Name, selectedEvents = EventFarm:GetSelectedEvents()})
                runtime.seaBeastBeamSignal = nil
                endSeaBeastCombat()
                runtime.seaBeastCombatReady = false
                runtime.target = nil
                local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, "sea_beast", "sea_beast_target_identity_changed")
                return returned and "sea_beast_target_identity_changed" or (returnReason or "sea_beast_target_identity_changed")
            end
            if not evadingBeam and runtime.boatLostReason then
                endSeaBeastCombat()
                runtime.seaBeastCombatReady = false
                runtime.target = nil
                return "boat_lost"
            end
            if not isAlive() then
                endSeaBeastCombat()
                runtime.seaBeastCombatReady = false
                runtime.target = nil
                setPhase("waiting_respawn", "sea_beast_character_died")
                repeat task.wait(0.25) until not isCurrent(generation) or isAlive()
                return isCurrent(generation) and "character_died" or "stopped"
            end
            if evadingBeam then
                task.wait(0.05)
                continue
            end
            if runtime.seaBeastCombatReady ~= true then
                runtime.targetBackoff[target] = now() + EventFarm.SeaBeastTravelFailureBackoff
                endSeaBeastCombat()
                runtime.target = nil
                local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, "sea_beast", "sea_beast_combat_recovery_failed")
                return returned and "sea_beast_recovery_failed" or (returnReason or "sea_beast_combat_recovery_failed")
            end
            -- Poll existing tracks as a race-safe fallback to AnimationPlayed.
            -- It is bounded to combat and weakly de-duplicated per live track.
            if now() >= (runtime.nextSeaBeastPreBeamScan or 0) then
                runtime.nextSeaBeastPreBeamScan = now() + 0.20
                scanSeaBeastPreBeamTracks(target, "combat_poll")
            end
            -- Skills must stop before a bad anchor can carry the player away.
            -- Evade has a deliberately higher temporary altitude and owns its
            -- own return, so it is excluded until its lease is released.
            if not runtime.seaBeastEvadeActive then
                local altitudeSafe, altitudeReason, altitude = seaBeastCombatAltitudeSafe(target)
                if not altitudeSafe then
                    local violation = runtime.seaBeastAltitudeViolation
                    if not violation or violation.reason ~= altitudeReason then
                        violation = {since = now(), reason = altitudeReason, geometry = altitude}
                        runtime.seaBeastAltitudeViolation = violation
                        journal("sea_beast_altitude_recovery", {reason = altitudeReason, target = target.Name, geometry = altitude})
                    end
                    -- A low/brief server correction is recoverable. Reassert
                    -- the already-owned Sea Beast follow, pause skills, and only
                    -- abandon after it remains unsafe for the bounded window.
                    local farm = Flow.Features.Farm
                    if farm and farm.State and farm.State.hoverOwner == "sea_event_sea_beast" and type(farm.ApplyHover) == "function" then
                        pcall(function() farm:ApplyHover(true) end)
                    end
                    if now() - violation.since >= EventFarm.SeaBeastCombatAltitudeRecoverySeconds then
                        runtime.targetBackoff[target] = now() + EventFarm.SeaBeastTravelFailureBackoff
                        journal("sea_beast_vertical_guard", {reason = altitudeReason, target = target.Name, geometry = altitude, recoverySeconds = now() - violation.since})
                        endSeaBeastCombat()
                        runtime.seaBeastCombatReady = false
                        runtime.target = nil
                        setPhase("returning_to_boat", "sea_beast_vertical_guard")
                        notify("Farm Eventos", seaBeastAltitudeAbandonMessage(altitudeReason, altitude), "warning", "sea_beast_vertical_guard", 2)
                        local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, "sea_beast", "sea_beast_vertical_guard")
                        return returned and "sea_beast_vertical_guard" or (returnReason or "sea_beast_vertical_guard")
                    end
                else
                    runtime.seaBeastAltitudeViolation = nil
                    runSeaBeastSkillCycle(generation, target)
                end
            end
            task.wait(0.05)
        end
        endSeaBeastCombat()
        runtime.seaBeastCombatReady = false
        local defeated, defeatEvidence = seaBeastTerminalDefeat(target)
        if defeated then runtime.seaBeastKillWitness = defeatEvidence end
        local killWitness = runtime.seaBeastKillWitness
        runtime.target = nil
        if killWitness and isCurrent(generation) then
            journal("sea_beast_defeat_confirmed", {target = target.Name, evidence = killWitness})
            setPhase("returning_to_boat", "sea_beast_defeated")
            notify("Farm Eventos", "Sea Beast derrotado. Retornando ao barco para procurar o próximo.", "success", "sea_beast_defeated", 1)
            local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, "sea_beast", "sea_beast_defeated")
            return returned and "target_defeated" or (returnReason or "return_failed")
        end
        if isCurrent(generation) then
            journal("sea_beast_target_lost_unconfirmed", {target = target.Name, hadParent = target.Parent ~= nil, reason = "no_terminal_health_evidence"})
            setPhase("returning_to_boat", "sea_beast_lost_unconfirmed")
            notify("Farm Eventos", "Sea Beast abandonado: alvo saiu da replicação sem HP terminal; não foi contado como derrota.", "warning", "sea_beast_lost_unconfirmed", 2)
        end
        local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, "sea_beast", "sea_beast_lost_unconfirmed")
        return returned and "target_gone_unconfirmed" or (returnReason or "target_gone_unconfirmed")
    end

    -- Raid boats deliberately reuse the same configured local Tool/key plan and
    -- scoped mouse-ray aim bridge as Sea Beast. The target boundary is different
    -- and explicit: only a currently selected live raid Model in Workspace.Enemies
    -- can open this scheduler.
    local function endRaidBoatCombat()
        if clearSeaBeastSkillAim then clearSeaBeastSkillAim() end
        local farm = Flow.Features.Farm
        if farm and farm.EndExternalHover then pcall(function() farm:EndExternalHover("sea_event_raid_boat") end) end
    end

    local function raidBoatCombatFollow(target, kind)
        local runtime, farm = EventFarm.Runtime, Flow.Features.Farm
        local initial = raidBoatRoot(target)
        if not farm or not farm.BeginExternalFollow or not initial then return false, "raid_boat_follow_module_missing" end
        local playerRoot = rootPart()
        local flat = playerRoot and Vector3.new(playerRoot.Position.X - initial.Position.X, 0, playerRoot.Position.Z - initial.Position.Z) or Vector3.new(0, 0, 1)
        if flat.Magnitude < 1 then flat = Vector3.new(0, 0, 1) end
        runtime.raidBoatCombatOffset = flat.Unit * EventFarm.RaidBoatCombatLateralOffset
        return farm:BeginExternalFollow("sea_event_raid_boat", initial.Position + runtime.raidBoatCombatOffset, function()
            local current = raidBoatRoot(target)
            return current and (current.Position + (runtime.raidBoatCombatOffset or Vector3.new(0, 0, EventFarm.RaidBoatCombatLateralOffset))) or nil
        end, function()
            return EventFarm.Runtime.active and EventFarm.Runtime.targetKind == kind and EventFarm.Runtime.target == target
                and isRaidBoatTarget(target, kind) and raidBoatAlive(target)
        end, EventFarm.RaidBoatCombatHeight)
    end

    local function travelToRaidBoatCombat(generation, target, kind)
        local teleport = Flow.Features.Teleport
        if not teleport or type(teleport.TravelDirectToPosition) ~= "function" then return false, "raid_boat_travel_module_missing" end
        if not isCurrent(generation) or EventFarm.Runtime.targetKind ~= kind or EventFarm.Runtime.target ~= target
            or not isRaidBoatTarget(target, kind) or not raidBoatAlive(target) then
            return false, "raid_boat_target_identity_invalid"
        end
        local released, releaseReason = releaseEventFarmTravel("raid_boat_direct_handoff")
        if not released then return false, "raid_boat_travel_lock_" .. tostring(releaseReason) end
        local runtime = EventFarm.Runtime
        for attempt = 1, 2 do
            local root = raidBoatRoot(target)
            local playerRoot = rootPart()
            if not root or not playerRoot then return false, "raid_boat_or_player_root_missing" end
            local flat = Vector3.new(playerRoot.Position.X - root.Position.X, 0, playerRoot.Position.Z - root.Position.Z)
            if flat.Magnitude < 1 then flat = Vector3.new(0, 0, 1) end
            runtime.raidBoatCombatOffset = flat.Unit * EventFarm.RaidBoatCombatLateralOffset
            local destination = root.Position + runtime.raidBoatCombatOffset + Vector3.new(0, EventFarm.RaidBoatCombatHeight, 0)
            local moved, reason = teleport:TravelDirectToPosition(destination, "sea_event_raid_boat", "Raid boat", {
                speed = EventFarm.RaidBoatTravelSpeed, holdArrivalVelocity = true, arrivalConfirmSeconds = 0.30,
                maxAttempts = 1, ignoreNoSupportWater = true, disableAdaptiveClearance = true,
            })
            local arrived = rootPart()
            local liveRoot = raidBoatRoot(target)
            local horizontal = arrived and liveRoot and horizontalDistance(arrived.Position, liveRoot.Position) or math.huge
            local height = arrived and liveRoot and (arrived.Position.Y - liveRoot.Position.Y) or -math.huge
            local accepted = arrived and liveRoot and horizontal <= EventFarm.RaidBoatTravelHorizontalTolerance
                and height >= EventFarm.RaidBoatTravelMinimumHeight and height <= EventFarm.RaidBoatTravelMaximumHeight
            journal("raid_boat_travel_outcome", {
                target = target.Name, kind = kind, attempt = attempt, moved = moved == true, reason = reason,
                destination = vectorSnapshot(destination), finalPlayer = arrived and vectorSnapshot(arrived.Position) or nil,
                finalTarget = liveRoot and vectorSnapshot(liveRoot.Position) or nil,
                horizontalDistance = horizontal, heightAboveTarget = height, accepted = accepted == true,
            })
            if accepted then return true, moved and "arrived" or "server_corrected_geometry_accepted" end
            if attempt < 2 then task.wait(0.20) end
        end
        return false, "raid_boat_arrival_unconfirmed"
    end

    local function runRaidBoatSkillCycle(generation, target, kind)
        local runtime = EventFarm.Runtime
        if not isCurrent(generation) or not canContinueTarget(kind) or runtime.phase ~= "raid_boat_combat"
            or runtime.target ~= target or not isRaidBoatTarget(target, kind) or not raidBoatAlive(target) then return end
        local skillState = runtime.raidBoatSkill
        skillState.cycles = (skillState.cycles or 0) + 1
        for _, category in ipairs(seaBeastSkillPlan) do
            for _, key in ipairs(category.keys) do
                if not isCurrent(generation) or not canContinueTarget(kind) or runtime.phase ~= "raid_boat_combat"
                    or runtime.target ~= target or not isRaidBoatTarget(target, kind) or not raidBoatAlive(target) then return end
                local configKey = category.configPrefix .. key
                if State[configKey] == false then
                    skillState.skippedDisabled = (skillState.skippedDisabled or 0) + 1
                else
                    local tool = findSeaBeastSkillTool(category.tooltip)
                    if not tool then
                        journal("raid_boat_skill_missing_tool", {kind = kind, category = category.id, key = key, tooltip = category.tooltip})
                    else
                        local attemptKey = tool.Name .. ":" .. key
                        local cooldown = seaBeastCooldownFrame(tool.Name, key)
                        local ready = seaBeastCooldownReady(cooldown)
                        if not ready then
                            skillState.skippedCooldown = (skillState.skippedCooldown or 0) + 1
                        elseif now() - (skillState.lastTry[attemptKey] or -math.huge) >= EventFarm.RaidBoatSkillRetrySeconds then
                            local equipped, equipReason = equipSeaBeastTool(tool)
                            if equipped then
                                cooldown = seaBeastCooldownFrame(tool.Name, key)
                                ready = seaBeastCooldownReady(cooldown)
                                if ready then
                                    skillState.lastTry[attemptKey] = now()
                                    local sent, route, aimRoute, aimPoint, aimed = sendSeaBeastKey(key, target, "raidBoatSkillAim", raidBoatRoot(target), EventFarm.RaidBoatSkillTapSeconds, tool.Name)
                                    if sent then
                                        skillState.casts = (skillState.casts or 0) + 1
                                        skillState.lastRoute = route
                                        local deadline, accepted = now() + EventFarm.RaidBoatSkillStartWindow, false
                                        while isCurrent(generation) and canContinueTarget(kind) and runtime.target == target and now() < deadline do
                                            if not seaBeastCooldownReady(cooldown) then accepted = true break end
                                            task.wait(0.03)
                                        end
                                        if accepted then skillState.confirmed = (skillState.confirmed or 0) + 1 end
                                        journal("raid_boat_skill_input", {
                                            target = target.Name, kind = kind, category = category.id, tool = tool.Name, key = key,
                                            route = route, cooldownAccepted = accepted, aimApplied = aimed == true,
                                            aimRoute = aimRoute, aimPoint = aimPoint and vectorSnapshot(aimPoint) or nil,
                                        })
                                        task.wait(EventFarm.RaidBoatSkillPostCastSeconds)
                                    else
                                        journal("raid_boat_skill_input_failed", {target = target.Name, kind = kind, category = category.id, tool = tool.Name, key = key, reason = route, aimRoute = aimRoute})
                                    end
                                end
                            else
                                journal("raid_boat_skill_equip_failed", {target = target.Name, kind = kind, category = category.id, tool = tool.Name, key = key, reason = equipReason})
                            end
                        end
                    end
                end
            end
        end
    end

    local function startRaidBoatCombat(generation, target, kind)
        local runtime = EventFarm.Runtime
        local directCheckpoint = EventFarm:IsDirectCheckpoint(target, kind)
        if not isRaidBoatKind(kind) or not canContinueTarget(kind) or not isRaidBoatTarget(target, kind) then return false, "raid_boat_target_identity_invalid" end
        if not isRaidBoatTargetValid(target, kind) then return false, "raid_boat_target_invalid" end
        runtime.target = target
        setPhase("raid_boat_found", kind)
        local released, releaseReason = releaseEventFarmTravel("raid_boat_prepare")
        if not released then return false, "raid_boat_travel_lock_" .. tostring(releaseReason) end
        if directCheckpoint then
            journal("checkpoint_direct_combat_begin", {kind = kind, target = target.Name, route = "no_reusable_boat"})
        else
            -- Orbit is mandatory whenever a usable boat exists: never dismount
            -- beside an armed enemy hull if native orbit could not be confirmed.
            local orbitReady, orbitReason = startRaidBoatAutonomy(generation, target, kind)
            if not orbitReady then
                if stopRaidBoatAutonomy then stopRaidBoatAutonomy("prepare_failed") end
                runtime.targetBackoff[target] = now() + 8
                runtime.target = nil
                journal("raid_boat_orbit_blocked", {target = target.Name, kind = kind, reason = orbitReason})
                setPhase("sea_cruise", "raid_boat_orbit_unconfirmed")
                notify("Farm Eventos", "Órbita do barco de raid não foi confirmada; mantendo o casco fora do combate.", "warning", "raid_boat_orbit_blocked", 2)
                return false, orbitReason
            end
            local dismounted, dismountReason = dismountSeaBeastBoat(generation)
            if not dismounted then
                if stopRaidBoatAutonomy then stopRaidBoatAutonomy("dismount_failed") end
                return false, dismountReason
            end
        end
        local arrived, travelReason = travelToRaidBoatCombat(generation, target, kind)
        if not arrived then
            if stopRaidBoatAutonomy then stopRaidBoatAutonomy("travel_failed") end
            return false, travelReason
        end
        local following, followReason = raidBoatCombatFollow(target, kind)
        if not following then
            if stopRaidBoatAutonomy then stopRaidBoatAutonomy("follow_failed") end
            return false, followReason or "raid_boat_follow_not_started"
        end
        runtime.raidBoatSkill = {lastTry = {}, cycles = 0, casts = 0, confirmed = 0, skippedCooldown = 0, skippedDisabled = 0, lastRoute = nil}
        runtime.raidBoatSkillAim = {attempts = 0, applied = 0, moduleReads = 0, nativeWrites = 0, mobilityBypassed = 0, unavailable = 0, lastRoute = nil, lastPoint = nil, lastMobilityRule = nil}
        setPhase("raid_boat_combat", kind)
        journal("raid_boat_combat_ready", {target = target.Name, kind = kind})
        notify("Farm Eventos", "Raid " .. tostring(target.Name) .. " alcançada: usando as skills ativas em Combo Settings.", "success", "raid_boat_combat", 2)
        return true
    end

    local function handoffRaidBoatCombat(generation, previousTarget, nextTarget, nextKind)
        local runtime = EventFarm.Runtime
        if not isCurrent(generation) or not isRaidBoatKind(nextKind) or not isTargetSelected(nextKind)
            or not isRaidBoatTargetValid(nextTarget, nextKind) then
            return false, "next_raid_target_invalid"
        end
        local mode = runtime.raidBoatAutonomy
        if not mode or mode.finalized == true or mode.active ~= true then return false, "raid_orbit_not_active" end
        local nextRoot = raidBoatRoot(nextTarget)
        if not nextRoot then return false, "next_raid_root_missing" end
        -- End only the player follow/aim lease. The boat lease deliberately
        -- remains active and is rebound below; it must not stop between the
        -- first, second and third hull of one raid encounter.
        endRaidBoatCombat()
        runtime.target, runtime.targetKind = nextTarget, nextKind
        local seat = runtime.seat
        local radial = seat and Vector3.new(seat.Position.X - nextRoot.Position.X, 0, seat.Position.Z - nextRoot.Position.Z) or nil
        if not radial or radial.Magnitude < 8 then radial = mode.lastRadial end
        mode.target, mode.kind, mode.lastCenter = nextTarget, nextKind, nextRoot.Position
        mode.lastRadial = radial and radial.Magnitude > 0.01 and radial.Unit or Vector3.new(0, 0, 1)
        mode.orbitArmed, mode.active = true, true
        mode.handoffs = (mode.handoffs or 0) + 1
        journal("raid_boat_group_handoff", {
            fromTarget = previousTarget and previousTarget.Name or nil,
            toTarget = nextTarget.Name,
            toKind = nextKind,
            distance = raidBoatOperationalDistance(nextTarget),
            handoffs = mode.handoffs,
        })
        setPhase("raid_boat_handoff", nextKind)
        local arrived, travelReason = travelToRaidBoatCombat(generation, nextTarget, nextKind)
        if not arrived then return false, "raid_boat_handoff_travel_" .. tostring(travelReason) end
        local following, followReason = raidBoatCombatFollow(nextTarget, nextKind)
        if not following then return false, "raid_boat_handoff_follow_" .. tostring(followReason) end
        runtime.raidBoatSkill = {lastTry = {}, cycles = 0, casts = 0, confirmed = 0, skippedCooldown = 0, skippedDisabled = 0, lastRoute = nil}
        runtime.raidBoatSkillAim = {attempts = 0, applied = 0, moduleReads = 0, nativeWrites = 0, mobilityBypassed = 0, unavailable = 0, lastRoute = nil, lastPoint = nil, lastMobilityRule = nil}
        setPhase("raid_boat_combat", nextKind)
        notify("Farm Eventos", "Próximo barco da raid encontrado: " .. tostring(nextTarget.Name) .. ". Mantendo a órbita protetora.", "info", "raid_boat_group_handoff", 2)
        return true
    end

    local function fightRaidBoat(generation, target, kind, continuingGroup)
        local runtime = EventFarm.Runtime
        local directCheckpoint = EventFarm:IsDirectCheckpoint(target, kind)
        if not continuingGroup then
            local started, startReason = startRaidBoatCombat(generation, target, kind)
            if not started then
                runtime.targetBackoff[target] = now() + 8
                runtime.target = nil
                local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, kind, "raid_boat_start_failed")
                return returned and "raid_boat_start_failed" or (startReason or returnReason or "raid_boat_start_failed")
            end
        end
        local lastWatch = 0
        while isCurrent(generation) and raidBoatAlive(target) do
            if not canContinueTarget(kind) or not isRaidBoatTarget(target, kind) then
                endRaidBoatCombat()
                runtime.target = nil
                local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, kind, "raid_boat_unselected_or_replaced")
                return returned and "raid_boat_unselected_or_replaced" or (returnReason or "raid_boat_unselected_or_replaced")
            end
            if runtime.boatLostReason then
                endRaidBoatCombat()
                runtime.target = nil
                return "boat_lost"
            end
            if not isAlive() then
                endRaidBoatCombat()
                runtime.target = nil
                setPhase("waiting_respawn", "raid_boat_character_died")
                repeat task.wait(0.25) until not isCurrent(generation) or isAlive()
                return isCurrent(generation) and "character_died" or "stopped"
            end
            runRaidBoatSkillCycle(generation, target, kind)
            if now() - lastWatch >= 1 then
                lastWatch = now()
                local health, maximum = raidBoatHealth(target)
                local orbit = runtime.raidBoatAutonomy
                journal("raid_boat_orbit_watch", {
                    target = target.Name, kind = kind, health = health, maxHealth = maximum,
                    radius = orbit and orbit.lastRadius or nil, configuredRadius = EventFarm.RaidBoatAutonomyRadius,
                    outerRadius = EventFarm.RaidBoatAutonomyOuterRadius, recoveries = orbit and orbit.recoveries or 0,
                })
            end
            task.wait(0.05)
        end
        endRaidBoatCombat()
        local defeated, evidence = raidBoatTerminalDefeat(target)
        if defeated and isCurrent(generation) then
            journal("raid_boat_defeat_confirmed", {target = target.Name, kind = kind, evidence = evidence})
        elseif isCurrent(generation) then
            -- Some hulls expose only MaxHealth. The model loss releases this
            -- target but is not counted as a confirmed kill without health 0.
            journal("raid_boat_target_lost_unconfirmed", {target = target.Name, kind = kind, hadParent = target.Parent ~= nil})
        end

        -- Do not return after hull one. While any checked live raid hull remains
        -- in range, retarget the *same* native boat orbit and continue skill
        -- combat. Only a clear group releases the player back to the seat.
        local nextTarget, nextKind = nextSelectedRaidBoat(target)
        if not nextTarget and isCurrent(generation) then
            setPhase("raid_boat_group_scan", kind)
            local deadline = now() + EventFarm.RaidBoatGroupSettleSeconds
            repeat
                task.wait(0.10)
                nextTarget, nextKind = nextSelectedRaidBoat(target)
            until nextTarget or not isCurrent(generation) or now() >= deadline
        end
        if nextTarget and isCurrent(generation) then
            if directCheckpoint then
                local checkpoint = runtime.progress and runtime.progress.checkpoint
                if checkpoint then
                    checkpoint.target, checkpoint.targetName, checkpoint.kind = nextTarget, nextTarget.Name, nextKind
                end
                runtime.target, runtime.targetKind = nextTarget, nextKind
                journal("checkpoint_direct_raid_handoff", {fromTarget = target.Name, toTarget = nextTarget.Name, toKind = nextKind})
                return fightRaidBoat(generation, nextTarget, nextKind, false)
            end
            local handedOff, handoffReason = handoffRaidBoatCombat(generation, target, nextTarget, nextKind)
            if handedOff then return fightRaidBoat(generation, nextTarget, nextKind, true) end
            journal("raid_boat_group_handoff_failed", {fromTarget = target.Name, toTarget = nextTarget.Name, toKind = nextKind, reason = handoffReason})
            runtime.targetBackoff[nextTarget] = now() + 8
        end

        if stopRaidBoatAutonomy then stopRaidBoatAutonomy("raid_group_cleared") end
        runtime.target = nil
        if defeated and isCurrent(generation) then
            setPhase("returning_to_boat", "raid_group_cleared")
            notify("Farm Eventos", "Raid de barcos limpa. Retornando ao barco para continuar o Farm Eventos.", "success", "raid_boat_group_cleared", 1)
            local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, kind, "raid_group_cleared")
            return returned and "raid_group_cleared" or (returnReason or "return_failed")
        end
        if isCurrent(generation) then setPhase("returning_to_boat", "raid_boat_target_lost") end
        local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, kind, "raid_boat_target_lost")
        return returned and "target_gone_unconfirmed" or (returnReason or "target_gone_unconfirmed")
    end

    local function consumeExternalVortexSignal()
        local detector = (getgenv and getgenv() or _G).FlowKanTerrorsharkPatternDetector
        if type(detector) ~= "table" or type(detector.GetSnapshot) ~= "function" then return nil end
        local ok, snapshot = pcall(function() return detector:GetSnapshot() end)
        local observations = ok and snapshot and snapshot.observations
        local newest = observations and observations[#observations]
        if not newest or newest.type ~= "vortex" then return nil end
        local observedAt = (tonumber(detector.StartedAt) or 0) + (tonumber(newest.observedAt) or 0)
        if observedAt <= 0 or now() - observedAt > 0.9 then return nil end
        return {at = observedAt, source = newest.source or "external_pattern_detector", instance = newest}
    end

    local function tryVortexEvade(generation, target)
        if not State.eventFarmVortexEvade then return false end
        local runtime = EventFarm.Runtime
        local activeAnimation, track = terrorDangerAnimation(target)
        local signal = runtime.vortexSignal
        if not signal or now() - signal.at > 0.9 then signal = consumeExternalVortexSignal() end
        if activeAnimation then signal = signal or {at = now(), source = "animation_14977820392", instance = track} end
        if not signal then return false end
        if runtime.evadeActive then return true end
        local root, terrorRoot = rootPart(), targetRoot(target)
        if not root or not terrorRoot or distance(root.Position, terrorRoot.Position) > EventFarm.TerrorSharkVortexResponseRange then return false end
        runtime.lastVortexObservation = signal.instance
        runtime.vortexSignal = nil
        runtime.evadeActive = true
        runtime.emergencyUntil = now() + 1.2
        setPhase("evading_vortex_test6", signal.source)
        endExternalCombat()
        destroyVortexLift()
        -- Extracted Test 6 behavior: keep an elevated, target-relative posture
        -- while the specific danger animation/Vortex is active, rather than
        -- relying on one short impulse with a fixed return time.
        local farm = Flow.Features.Farm
        if farm and farm.BeginExternalFollow then
            farm:BeginExternalFollow("sea_event_vortex_evade", terrorRoot.Position + EventFarm.TerrorSharkEvadeOffset, function()
                local current = targetRoot(target)
                return current and (current.Position + EventFarm.TerrorSharkEvadeOffset) or nil
            end, function() return EventFarm.Runtime.active and EventFarm.Runtime.evadeActive and targetAlive(target) end, 30)
        end
        journal("evade_enter", {source = signal.source, target = target.Name})
        notify("Farm Eventos", "Terror Shark: evasão Teste 6 sustentada ativada.", "warning", "vortex_evade_test6", 1)
        local lastActive = now()
        local timeout = now() + 4
        while isCurrent(generation) and targetAlive(target) and now() < timeout do
            local playing = terrorDangerAnimation(target)
            if playing then lastActive = now() end
            if now() - lastActive >= EventFarm.TerrorSharkEvadeGrace then break end
            task.wait(0.05)
        end
        runtime.evadeActive = false
        local f = Flow.Features.Farm
        if f and f.EndExternalHover then pcall(function() f:EndExternalHover("sea_event_vortex_evade") end) end
        if isCurrent(generation) and targetAlive(target) then combatFollow(target); setPhase("combat", "evade_complete") end
        journal("evade_exit", {target = target.Name})
        return true
    end

    local function fightTerrorShark(generation, target)
        local runtime = EventFarm.Runtime
        local directCheckpoint = EventFarm:IsDirectCheckpoint(target, "terror_shark")
        if not canContinueTarget("terror_shark") then return "terror_shark_not_selected" end
        if not isTerrorSharkTargetValid(target) then return "target_out_of_range" end
        runtime.target = target
        runtime.boatSafeTarget = nil
        runtime.boatAwayFallbackTarget = nil
        runtime.deferBoatLossUntilTargetDefeated = false
        runtime.combatBoatLossReason = nil
        setPhase("terror_shark_found")
        if directCheckpoint then
            journal("checkpoint_direct_combat_begin", {kind = "terror_shark", target = target.Name, route = "no_reusable_boat"})
        else
            -- Protective orbit is the only boat-safety route for Terror Shark.
            -- Unlike the old one-shot drive-away path, it stays armed after the
            -- player dismounts and keeps its 700-stud native separation live.
            local orbitReady, orbitReason = startTerrorSharkBoatAutonomy(generation, target)
            if not orbitReady then
                if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("prepare_failed") end
                runtime.targetBackoff[target] = now() + 8
                runtime.target = nil
                journal("terror_shark_boat_orbit_blocked", {reason = orbitReason, target = target.Name})
                setPhase("sea_cruise", "terror_shark_orbit_unconfirmed")
                notify("Farm Eventos", "Órbita protetora do Terror Shark não foi confirmada; mantendo o barco fora do combate.", "warning", "terror_shark_boat_orbit_blocked", 3)
                return "terror_shark_boat_orbit_unconfirmed_" .. tostring(orbitReason)
            end
            if runtime.boatLostReason then
                if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("target_or_boat_lost_before_combat") end
                return "boat_lost"
            end
        end
        if not isCurrent(generation) or not targetAlive(target) then
            if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("target_lost_before_combat") end
            return "target_gone"
        end
        local ok, reason = startCombat(generation, target)
        if not ok then
            runtime.targetBackoff[target] = now() + 6
            runtime.target = nil
            runtime.boatAwayFallbackTarget = nil
            journal("terror_released", {reason = reason})
            local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, "terror_shark", "combat_start_failed")
            if not returned and runtime.boatLostReason then return "boat_lost" end
            setPhase("sea_cruise", "combat_guard_" .. tostring(reason) .. "_" .. tostring(returnReason or "returned"))
            notify("Farm Eventos", "Combate não iniciou: " .. tostring(reason), "warning", "combat_guard", 2)
            return reason
        end
        local combatStartTime = now()
        runtime.lastDamageLog = nil
        local lastAttack, lastOrbitWatch = 0, 0
        while isCurrent(generation) and targetAlive(target) do
            local tikiReturn, tikiReason = false, nil
            if not directCheckpoint then tikiReturn, tikiReason = requiresFreshBoatAtTiki() end
            if tikiReturn then
                runtime.tikiReturnNeedsFreshBoat = true
                runtime.tikiReturnReason = tikiReason
                journal("terror_shark_tiki_return_rebuy", {reason = tikiReason, target = target.Name})
                if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("tiki_return_rebuy") end
                endExternalCombat()
                destroyVortexLift()
                runtime.target = nil
                return "tiki_return_rebuy"
            end
            -- Do not interrupt a Shark merely because another selected mob
            -- appears. Only a direct deselection ends this lock, and it still
            -- exits through the normal hover/boat cleanup below.
            if not canContinueTarget("terror_shark") then
                endExternalCombat()
                destroyVortexLift()
                runtime.target = nil
                setPhase("returning_to_boat", "terror_shark_unselected")
                local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, "terror_shark", "terror_shark_unselected")
                return returned and "terror_shark_unselected" or (returnReason or "terror_shark_unselected")
            end
            -- Do not begin or prolong a high-risk Terror Shark fight with a
            -- hull below the declared 50% reuse floor. Unlike an unexpected
            -- destroyed hull, this is a planned retirement: leave combat now,
            -- replace the hull, and resume farm with real survivability.
            if not directCheckpoint and not runtime.boatLostReason then
                local boatRatio, boatHealth, boatMaximum, healthSource = boatHealthRatio(runtime.boat)
                if boatRatio == nil or boatRatio < EventFarm.BoatReuseMinimumHealthRatio then
                    runtime.boatLostReason = "boat_health_below_50_percent_" .. tostring(boatRatio and math.floor(boatRatio * 100) or "unknown")
                    journal("combat_boat_health_retired", {
                        ratio = boatRatio,
                        health = boatHealth,
                        maximum = boatMaximum,
                        healthSource = healthSource,
                        target = target.Name,
                        minimumRatio = EventFarm.BoatReuseMinimumHealthRatio,
                    })
                    if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("boat_health_retired") end
                    endExternalCombat()
                    destroyVortexLift()
                    runtime.target = nil
                    return "boat_lost"
                end
            end
            if runtime.boatLostReason and not runtime.deferBoatLossUntilTargetDefeated then
                -- The target is already in an active combat loop. Do not kill or
                -- restart the player merely because the parked hull disappeared;
                -- stop all boat-only work and finish this specific Shark fight.
                runtime.deferBoatLossUntilTargetDefeated = true
                runtime.combatBoatLossReason = runtime.boatLostReason
                runtime.boatAwayActive = false
                runtime.boatSafeTarget = nil
                runtime.boatAwayFallbackTarget = nil
                runtime.awayProgressCheck = nil
                if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("boat_lost_during_combat") end
                runtime.direction = nil
                runtime.speed = 0
                journal("combat_boat_loss_deferred", {
                    reason = runtime.combatBoatLossReason,
                    target = target.Name,
                })
                notify("Farm Eventos", "Barco perdido durante o combate; finalizando este Terror Shark antes de repor o barco.", "warning", "combat_boat_loss_deferred", 2)
            end
            local human = humanoid()
            local state = human and human:GetState()
            local damagePlayerRoot = rootPart()
            local damageSharkRoot = targetRoot(target)
            -- v1.6.5 FIX-24: passive injury telemetry only. It neither changes
            -- humanoid state nor writes movement/health values.
            if not runtime.lastDamageLog or now() - runtime.lastDamageLog > 0.5 then
                runtime.lastDamageLog = now()
                journal("combat_damage_sample", {
                    playerHP = human and human.Health or nil,
                    playerMaxHP = human and human.MaxHealth or nil,
                    playerPos = damagePlayerRoot and {damagePlayerRoot.Position.X, damagePlayerRoot.Position.Y, damagePlayerRoot.Position.Z} or nil,
                    sharkPos = damageSharkRoot and {damageSharkRoot.Position.X, damageSharkRoot.Position.Y, damageSharkRoot.Position.Z} or nil,
                    dist = damagePlayerRoot and damageSharkRoot and (damagePlayerRoot.Position - damageSharkRoot.Position).Magnitude or -1,
                })
            end
            local closeThreat = damageSharkRoot and damagePlayerRoot and distance(damageSharkRoot.Position, damagePlayerRoot.Position) or math.huge
            local graceActive = now() - combatStartTime < 0.5
            local isFalling = state == Enum.HumanoidStateType.Freefall or state == Enum.HumanoidStateType.Swimming
            -- v1.6.0 FIX-14: bounded, raw positional trace for the live
            -- follow/range relationship. This is diagnostics only.
            if not runtime.lastCombatPosLog or now() - runtime.lastCombatPosLog > 0.5 then
                runtime.lastCombatPosLog = now()
                local pRoot = rootPart()
                local sRoot = targetRoot(target)
                if pRoot and sRoot then
                    local h = humanoid()
                    journal("combat_pos_sample", {
                        playerPos = {pRoot.Position.X, pRoot.Position.Y, pRoot.Position.Z},
                        sharkPos = {sRoot.Position.X, sRoot.Position.Y, sRoot.Position.Z},
                        dist = (pRoot.Position - sRoot.Position).Magnitude,
                        state = h and h:GetState().Name,
                    })
                end
            end
            local farm = Flow.Features.Farm
            if farm and farm.State and (not runtime.lastHoverStatsLog or now() - runtime.lastHoverStatsLog > 1.0) then
                runtime.lastHoverStatsLog = now()
                local farmState = farm.State
                journal("hover_stats", {
                    attempts = farmState.hoverAttemptCount or 0,
                    corrections = farmState.hoverCorrectionCount or 0,
                    providerFails = farmState.hoverProviderFailCount or 0,
                    lastHorizontal = farmState.hoverLastHorizontal,
                    hoverOwner = farmState.hoverOwner,
                })
            end
            local hoverActive = farm and type(farm.IsHoverActive) == "function" and farm:IsHoverActive("sea_event_farm")
            if not graceActive and not hoverActive and isFalling and closeThreat <= EventFarm.TerrorSharkEmergencyRange then
                if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("emergency_water_escape") end
                endExternalCombat()
                destroyVortexLift()
                runtime.targetBackoff[target] = now() + 12
                runtime.target = nil
                setPhase("emergency_water_escape", tostring(state.Name))
                return "emergency_water_escape"
            end
            if not isAlive() then
                if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("character_died") end
                endExternalCombat()
                destroyVortexLift()
                setPhase("waiting_respawn")
                repeat task.wait(0.25) until not isCurrent(generation) or isAlive()
                if isCurrent(generation) then
                    runtime.target = nil
                    return "character_died"
                end
                return "stopped"
            end
            if tryVortexEvade(generation, target) then lastAttack = now() end
            if now() - lastAttack > 0.18 then
                attackTerrorShark(target)
                lastAttack = now()
            end
            -- The retired static parking/re-park route is deliberately absent.
            -- The native autonomy command above continuously corrects the live
            -- target-relative radius while the player remains in combat.
            local orbitMode = runtime.terrorSharkBoatAutonomy
            if State.eventFarmMoveBoatAway and orbitMode and orbitMode.active and now() - lastOrbitWatch >= 1 then
                lastOrbitWatch = now()
                local sharkRoot = targetRoot(target)
                local seat = runtime.seat
                journal("terror_shark_boat_orbit_watch", {
                    radius = orbitMode.lastRadius,
                    configuredRadius = EventFarm.TerrorSharkBoatAutonomyRadius,
                    outerRadius = EventFarm.TerrorSharkBoatAutonomyOuterRadius,
                    distance3D = sharkRoot and seat and distance(sharkRoot.Position, seat.Position) or nil,
                    recoveries = orbitMode.recoveries or 0,
                })
            end
            task.wait(0.06)
        end
        if stopTerrorSharkBoatAutonomy then stopTerrorSharkBoatAutonomy("terror_shark_combat_end") end
        endExternalCombat()
        destroyVortexLift()
        local defeated = not targetAlive(target)
        runtime.target = nil
        runtime.boatSafeTarget = nil
        runtime.boatAwayFallbackTarget = nil
        if defeated and isCurrent(generation) then
            if runtime.deferBoatLossUntilTargetDefeated then
                local lossReason = runtime.combatBoatLossReason or runtime.boatLostReason or "boat_removed_during_combat"
                journal("combat_target_defeated_with_boat_lost", {
                    target = target.Name,
                    reason = lossReason,
                })
                notify("Farm Eventos", "Terror Shark derrotado sem barco. Repondo o barco apenas agora para continuar o farm.", "success", "terror_defeated_boat_lost", 2)
                -- The target is terminal; it is now safe to release the stale
                -- native writer. restoreBoatControl clears the loss flag, so put
                -- the retained reason back for the outer recovery worker.
                clearNativeControl()
                runtime.boat = nil
                runtime.seat = nil
                runtime.boatLostReason = lossReason
                runtime.deferBoatLossUntilTargetDefeated = false
                runtime.combatBoatLossReason = nil
                return "target_defeated_boat_lost"
            end
            notify("Farm Eventos", "Terror Shark derrotado. Retornando ao barco.", "success", "terror_defeated", 1)
            setPhase("returning_to_boat")
            local returned, returnReason = EventFarm:CheckpointReturnOrResume(generation, target, "terror_shark", "terror_defeated")
            if not returned and runtime.boatLostReason then return "boat_lost" end
            return returned and "target_defeated" or (returnReason or "return_failed")
        end
        if runtime.deferBoatLossUntilTargetDefeated then
            -- A despawn is not a confirmed player kill. Preserve the player's
            -- current life and stop instead of converting this into a sea reset.
            journal("combat_target_lost_with_boat_lost", {
                target = target.Name,
                reason = runtime.combatBoatLossReason or runtime.boatLostReason,
            })
            setPhase("combat_target_lost_without_boat")
            return "target_lost_with_boat_lost"
        end
        return runtime.boatLostReason and "boat_lost" or "target_gone"
    end

    -- Both workers can restart the same active generation after a boat-loss
    -- reset. The Frozen worker is intentionally separate from combat `run` so
    -- its cruise can never resolve a sea-mob opportunity.
    local run

    local function restoreSeaBeastCameraAfterRespawn(generation)
        -- Native-control teardown clears the old combat lock before respawn;
        -- retain this presentation recovery whenever Sea Beast remains checked.
        if not isTargetSelected("sea_beast") or not isCurrent(generation) then return end
        local camera, h = Workspace and Workspace.CurrentCamera, humanoid()
        if camera and h and h.Health > 0 then
            pcall(function() camera.CameraType = Enum.CameraType.Custom; camera.CameraSubject = h end)
            journal("sea_beast_camera_restore", {subject = "local_humanoid"})
        end
    end

    local function restartAfterCombatDeath(generation, source)
        local runtime = EventFarm.Runtime
        if not isCurrent(generation) then return false end
        -- Respawned at Tiki after a combat death: do not make the character
        -- chase the old hull across the sea. Re-enter the normal acquisition
        -- flow and buy a fresh boat through the verified dealer instead.
        clearNativeControl()
        runtime.boat = nil
        runtime.seat = nil
        runtime.target = nil
        runtime.boatSafeTarget = nil
        runtime.forceFreshBoat = true
        setPhase("restarting_after_combat_death")
        if source == "sea_beast" then
            restoreSeaBeastCameraAfterRespawn(generation)
            task.delay(0.35, function() restoreSeaBeastCameraAfterRespawn(generation) end)
        end
        task.spawn(function()
            if isCurrent(generation) then run(generation) end
        end)
        return true
    end

    local function restartAfterTikiReturn(generation)
        local runtime = EventFarm.Runtime
        if not isCurrent(generation) then return false end
        -- The player is already at Tiki. Never TravelDirect to the old hull and
        -- never force another death: release its native control, keep the live
        -- character, and let acquireBoat buy a different owned instance.
        clearNativeControl()
        runtime.boat = nil
        runtime.seat = nil
        runtime.boatCharacter = nil
        runtime.target = nil
        runtime.boatSafeTarget = nil
        runtime.forceFreshBoat = true
        runtime.tikiReturnNeedsFreshBoat = true
        setPhase("restarting_after_tiki_return", runtime.tikiReturnReason or "tiki_return_rebuy")
        task.spawn(function()
            if isCurrent(generation) then run(generation) end
        end)
        return true
    end

    local function resetAfterBoatLoss(generation)
        local runtime = EventFarm.Runtime
        local lossReason = runtime.boatLostReason
        if not lossReason then return false, "boat_loss_not_pending" end
        if runtime.resettingAfterBoatLoss then return false, "boat_loss_reset_already_running" end
        runtime.resettingAfterBoatLoss = true

        -- Position, rather than DangerLevel, decides whether this is sea loss.
        -- Therefore level 1 through 6 behave identically: a lost boat away
        -- from Tiki resets immediately instead of walking/sailing back.
        local lossPosition = runtime.lastPosition
            or (runtime.seat and runtime.seat.Position)
            or (rootPart() and rootPart().Position)
        local resetAtSea = not isAtTiki(lossPosition)
        setPhase(resetAtSea and "resetting_after_sea_boat_loss" or "replacing_boat_at_tiki", lossReason)
        notify("Farm Eventos", resetAtSea
            and "Barco perdido no mar. Resetando para voltar rápido a Tiki e comprar outro."
            or "Barco perdido em Tiki. Comprando outro no Boat Dealer correto.",
            "warning", "boat_lost_reset", 1)

        clearNativeControl()
        runtime.boat = nil
        runtime.seat = nil
        runtime.target = nil
        runtime.forceFreshBoat = true
        runtime.boatLostReason = nil

        if resetAtSea then
            local oldCharacter = player and player.Character
            local h = humanoid()
            if not h then
                runtime.resettingAfterBoatLoss = false
                return false, "character_missing_for_sea_reset"
            end
            pcall(function() h.Health = 0 end)
            local deadline = now() + 18
            repeat
                task.wait(0.15)
                local freshHumanoid = humanoid()
                if player.Character ~= oldCharacter and freshHumanoid and freshHumanoid.Health > 0 and rootPart() then
                    runtime.resettingAfterBoatLoss = false
                    return true
                end
            until not isCurrent(generation) or now() >= deadline
            runtime.resettingAfterBoatLoss = false
            return false, "sea_reset_respawn_timeout"
        end

        runtime.resettingAfterBoatLoss = false
        return isCurrent(generation), "stopped"
    end

    local function recoverBoatLossAndRestart(generation)
        local recovered, reason = resetAfterBoatLoss(generation)
        if recovered and isCurrent(generation) then
            task.spawn(function()
                if isCurrent(generation) then run(generation) end
            end)
            return true
        end
        if isCurrent(generation) then EventFarm:SetEnabled(false, reason or "boat_loss_recovery_failed") end
        return false
    end

    function EventFarm:CheckpointTargetValid(checkpoint)
        if not checkpoint or not checkpoint.target then return false end
        if checkpoint.kind == "sea_beast" then return isSeaBeastTargetValid(checkpoint.target) end
        if checkpoint.kind == "terror_shark" then return isTerrorSharkTargetValid(checkpoint.target) end
        if isRaidBoatKind(checkpoint.kind) then return isRaidBoatTargetValid(checkpoint.target, checkpoint.kind) end
        return false
    end

    function EventFarm:RunCheckpointTarget(generation, checkpoint)
        local runtime = EventFarm.Runtime
        if not EventFarm:CheckpointTargetValid(checkpoint) then
            journal("checkpoint_target_invalid", {kind = checkpoint and checkpoint.kind, target = checkpoint and checkpoint.targetName})
            return false, "checkpoint_target_invalid"
        end
        runtime.target, runtime.targetKind = checkpoint.target, checkpoint.kind
        journal("checkpoint_target_dispatch", {
            kind = checkpoint.kind, target = checkpoint.target.Name, mode = checkpoint.mode,
            source = checkpoint.source, distance = checkpoint.distance,
        })
        if checkpoint.kind == "sea_beast" then
            return true, fightSeaBeast(generation, checkpoint.target)
        end
        if checkpoint.kind == "terror_shark" then
            return true, fightTerrorShark(generation, checkpoint.target)
        end
        if isRaidBoatKind(checkpoint.kind) then
            return true, fightRaidBoat(generation, checkpoint.target, checkpoint.kind)
        end
        return false, "checkpoint_target_kind_invalid"
    end

    run = function(generation, skipActivationCheckpoint)
        local runtime = EventFarm.Runtime
        -- Activation is a real checkpoint: claim a currently live selected
        -- event before beginning dealer travel or a blind open-sea search.
        -- The target remains an Instance only for this generation; a later
        -- validation always proves it is still alive and in range.
        local checkpoint = nil
        if not skipActivationCheckpoint then
            local choice, candidateCount = EventFarm:ResolveLiveSelectedTarget()
            if choice then
                checkpoint = {
                    kind = choice.kind, target = choice.target, targetName = choice.target.Name,
                    distance = choice.distance, source = "activation_live_scan", candidates = candidateCount,
                    mode = "boat_target",
                }
                runtime.progress.checkpoint = checkpoint
                setPhase("checkpoint_target_detected", choice.kind)
                journal("checkpoint_target_detected", {
                    kind = choice.kind, target = choice.target.Name, distance = choice.distance,
                    simultaneousCandidates = candidateCount,
                })
            end
        end

        -- When a live target already exists, take a usable current hull only.
        -- If none is safely reusable, combat starts directly instead of buying
        -- a boat and potentially losing the active encounter during Tiki exit.
        local boat, acquireReason
        if checkpoint then
            boat, acquireReason = acquireBoat(generation, {skipPurchase = true, checkpointKind = checkpoint.kind})
            if not boat then
                checkpoint.mode = "direct_target"
                runtime.progress.checkpoint = checkpoint
                setPhase("checkpoint_direct_target", checkpoint.kind)
                local dispatched, result = EventFarm:RunCheckpointTarget(generation, checkpoint)
                if not dispatched and checkpoint.target then runtime.targetBackoff[checkpoint.target] = now() + 8 end
                runtime.progress.checkpoint = nil
                runtime.target, runtime.targetKind = nil, nil
                journal("checkpoint_direct_target_exit", {kind = checkpoint.kind, target = checkpoint.targetName, result = result})
                if isCurrent(generation) then return run(generation, true) end
                return
            end
        else
            boat, acquireReason = acquireBoat(generation)
        end
        if not boat then
            if isCurrent(generation) then
                notify("Farm Eventos", "Não foi possível preparar o barco: " .. tostring(acquireReason), "error", "prepare_fail", 1)
                EventFarm:SetEnabled(false, acquireReason)
            end
            return
        end

        -- Each hull receives a full measured 500/700/900 exit sequence. A
        -- failed hull is discarded, then a fresh instance gets a complete new
        -- sequence; the bounded cap prevents an unobservable buy loop.
        local launchAttempt = 0
        while isCurrent(generation) and launchAttempt < EventFarm.TikiExitMaximumHulls do
            launchAttempt = launchAttempt + 1
            setPhase("entering_boat")
            local attached, attachReason = attachNativeControl(boat)
            if not attached then
                local cannotReachOwnedBoat = attachReason == "could_not_enter_driver_seat"
                if cannotReachOwnedBoat and runtime.tikiSeatRecoveryAttempts < 1 and isCurrent(generation) then
                    -- A trapped Tiki hull and a hull left far offshore after a
                    -- death have the same safe answer: never chase or reuse a
                    -- seat that cannot be entered. Go straight to the verified
                    -- west/open-sea dealer and force one clean replacement.
                    runtime.tikiSeatRecoveryAttempts = runtime.tikiSeatRecoveryAttempts + 1
                    runtime.forceFreshBoat = true
                    runtime.boat = nil
                    runtime.seat = nil
                    local atTiki = isAtTiki(positionOf(boat))
                    notify("Farm Eventos", atTiki
                        and "Não foi possível entrar no barco preso em Tiki. Voltando ao Boat Dealer do mar aberto para comprar outro."
                        or "Não foi possível entrar no barco perdido no mar. Voltando ao Boat Dealer do mar aberto para comprar outro.",
                        "warning", "tiki_seat_rebuy", 1)
                    task.spawn(function()
                        if isCurrent(generation) then run(generation) end
                    end)
                    return
                end
                notify("Farm Eventos", "Não foi possível assumir o assento: " .. tostring(attachReason), "error", "seat_fail", 1)
                EventFarm:SetEnabled(false, attachReason)
                return
            end
            setPhase("settling_native_boat")
            if not settleNativeBoat(generation) then
                if runtime.boatLostReason then recoverBoatLossAndRestart(generation)
                else EventFarm:SetEnabled(false, "native_boat_settle_failed") end
                return
            end

            -- A reusable boat is already under native control. If activation
            -- found a live selected target, engage it now rather than spending
            -- time on a Tiki exit/calibration cycle first.
            if checkpoint and EventFarm:CheckpointTargetValid(checkpoint) then
                checkpoint.mode = "boat_target"
                runtime.progress.checkpoint = checkpoint
                setPhase("checkpoint_target_handoff", checkpoint.kind)
                local dispatched, checkpointResult = EventFarm:RunCheckpointTarget(generation, checkpoint)
                journal("checkpoint_boat_target_exit", {
                    kind = checkpoint.kind, target = checkpoint.targetName,
                    dispatched = dispatched == true, result = checkpointResult,
                })
                runtime.progress.checkpoint = nil
                checkpoint = nil
                if runtime.boatLostReason then
                    recoverBoatLossAndRestart(generation)
                    return
                end
                if not isCurrent(generation) then return end
            elseif checkpoint then
                journal("checkpoint_target_expired_before_handoff", {kind = checkpoint.kind, target = checkpoint.targetName})
                runtime.progress.checkpoint = nil
                checkpoint = nil
            end

            local currentBoatPosition = runtime.seat and runtime.seat.Position or positionOf(boat)
            local readyForSea = true
            if isAtTiki(currentBoatPosition) then
                local escaped, escapeReason = setOpenSeaCourse(generation)
                if not escaped then
                    if runtime.boatLostReason then
                        recoverBoatLossAndRestart(generation)
                        return
                    end
                    -- Only the measured no-progress outcome is a reason to
                    -- replace a boat. Manual stops and unrelated failures must
                    -- never purchase another hull.
                    local noMeaningfulProgress = type(escapeReason) == "string"
                        and string.find(escapeReason, "open_sea_exit_not_confirmed_projection_", 1, true) ~= nil
                    if isCurrent(generation) and noMeaningfulProgress and launchAttempt < EventFarm.TikiExitMaximumHulls then
                        notify("Farm Eventos", "Barco não avançou o suficiente saindo de Tiki; voltando ao Boat Dealer do mar aberto para comprar outro.", "warning", "tiki_rebuy", 1)
                        local stuckBoat = runtime.boat or boat
                        -- The Farm must not keep a stale RenderStep writer or
                        -- control a seat while Farm.MoveTo returns to the NPC.
                        clearNativeControl()
                        runtime.boat = nil
                        runtime.seat = nil
                        runtime.target = nil
                        local h = humanoid()
                        if h then pcall(function() h.Sit = false end) end
                        boat, escapeReason = buyReplacementBoatAtTikiWestDealer(generation, stuckBoat)
                        if boat and isCurrent(generation) then
                            notify("Farm Eventos", "Novo barco comprado no Boat Dealer do mar aberto. Tentando a saída de Tiki novamente.", "success", "tiki_rebuy_ok", 1)
                            readyForSea = false
                        else
                            notify("Farm Eventos", "Não foi possível comprar o barco substituto: " .. tostring(escapeReason), "error", "tiki_rebuy_fail", 1)
                            EventFarm:SetEnabled(false, escapeReason or "replacement_boat_unavailable")
                            return
                        end
                    else
                        if isCurrent(generation) then
                            notify("Farm Eventos", "A saída para mar aberto falhou: " .. tostring(escapeReason), "error", "exit_fail", 1)
                            EventFarm:SetEnabled(false, escapeReason)
                        end
                        return
                    end
                end
            else
                -- Already sailing at a real sea level: keep the native seat, skip
                -- the Tiki lift/exit entirely, and only calibrate usable height.
                local flatLook = runtime.seat and Vector3.new(runtime.seat.CFrame.LookVector.X, 0, runtime.seat.CFrame.LookVector.Z) or EventFarm.TikiOpenSeaDirection
                runtime.cruiseDirection = flatLook.Magnitude > 0.01 and flatLook.Unit or EventFarm.TikiOpenSeaDirection
                beginExistingSeaCalibration()
            end

            -- A failed Tiki escape may have replaced the hull above; attach to
            -- that new instance before attempting the route again.
            if readyForSea then
                while isCurrent(generation) do
                    local target, seaReason = driveSea(generation)
                    if seaReason == "tiki_return_rebuy" then
                        restartAfterTikiReturn(generation)
                        return
                    end
                    if seaReason == "boat_lost" or runtime.boatLostReason then
                        recoverBoatLossAndRestart(generation)
                        return
                    end
                    if seaReason == "character_died" then
                        restartAfterCombatDeath(generation)
                        return
                    end
                    if target and isCurrent(generation) and seaReason == "sea_beast" and canContinueTarget("sea_beast") then
                        local entered, fightReason = xpcall(function() return fightSeaBeast(generation, target) end, function(err)
                            return (debug and debug.traceback and debug.traceback(tostring(err), 2)) or tostring(err)
                        end)
                        if not entered then
                            journal("sea_beast_fight_crash", {error = fightReason, target = target.Name})
                            if stopSeaBeastBoatAutonomy then stopSeaBeastBoatAutonomy("sea_beast_fight_crash") end
                            endExternalCombat()
                            runtime.target = nil
                            setPhase("sea_cruise", "sea_beast_fight_crash")
                            notify("Farm Eventos", "Sea Beast: combate interrompido; voltando à busca.", "warning", "sea_beast_fight_crash", 2)
                        elseif fightReason == "character_died" then
                            restartAfterCombatDeath(generation, "sea_beast")
                            return
                        elseif fightReason == "tiki_return_rebuy" then
                            restartAfterTikiReturn(generation)
                            return
                        elseif fightReason == "boat_lost" or runtime.boatLostReason then
                            recoverBoatLossAndRestart(generation)
                            return
                        end
                    end
                    if target and isCurrent(generation) and isRaidBoatKind(seaReason) and canContinueTarget(seaReason) then
                        local entered, fightReason = xpcall(function() return fightRaidBoat(generation, target, seaReason) end, function(err)
                            return (debug and debug.traceback and debug.traceback(tostring(err), 2)) or tostring(err)
                        end)
                        if not entered then
                            journal("raid_boat_fight_crash", {error = fightReason, target = target.Name, kind = seaReason})
                            if stopRaidBoatAutonomy then stopRaidBoatAutonomy("fight_crash") end
                            endRaidBoatCombat()
                            runtime.target = nil
                            setPhase("sea_cruise", "raid_boat_fight_crash")
                            notify("Farm Eventos", "Combate da raid interrompido; voltando à busca.", "warning", "raid_boat_fight_crash", 2)
                        elseif fightReason == "character_died" then
                            restartAfterCombatDeath(generation, "raid_boat")
                            return
                        elseif fightReason == "boat_lost" or runtime.boatLostReason then
                            recoverBoatLossAndRestart(generation)
                            return
                        end
                    end
                    if target and isCurrent(generation) and seaReason == "terror_shark" and canContinueTarget("terror_shark") then
                        local entered, fightReason = xpcall(function() return fightTerrorShark(generation, target) end, function(err)
                            return (debug and debug.traceback and debug.traceback(tostring(err), 2)) or tostring(err)
                        end)
                        if not entered then
                            journal("fight_crash", {error = fightReason, target = target.Name})
                            endExternalCombat()
                            runtime.target = nil
                            setPhase("sea_cruise", "fight_crash")
                            notify("Farm Eventos", "Falha de combate capturada; retornando ao cruzeiro sem deixar estado preso.", "warning", "fight_crash", 2)
                        elseif fightReason == "character_died" then
                            restartAfterCombatDeath(generation)
                            return
                        elseif fightReason == "tiki_return_rebuy" then
                            restartAfterTikiReturn(generation)
                            return
                        elseif fightReason == "target_defeated_boat_lost" then
                            -- v1.6.6: only after the active Shark is terminal do
                            -- we reset/rebuy for a lost hull.
                            recoverBoatLossAndRestart(generation)
                            return
                        elseif fightReason == "target_lost_with_boat_lost" then
                            -- No confirmed kill: preserve the player and stop;
                            -- never turn a vanished target into a forced reset.
                            EventFarm:SetEnabled(false, fightReason)
                            return
                        elseif fightReason == "boat_lost" or runtime.boatLostReason then
                            recoverBoatLossAndRestart(generation)
                            return
                        end
                    end
                    if runtime.boatLostReason and not runtime.deferBoatLossUntilTargetDefeated then
                        recoverBoatLossAndRestart(generation)
                        return
                    end
                    if isCurrent(generation) then
                        local seat = runtime.seat
                        if not localOccupies(seat) and not otherPlayerDrives(seat) then
                            local h = humanoid()
                            if h then pcall(function() seat:Sit(h) end) end
                        end
                        waitSeconds(generation, 0.25)
                    end
                end
                return
            end
        end
    end

    -- Frozen Dimension is a sea-island search, not an Event Farm target. It
    -- deliberately reuses boat acquisition, verified west-Tiki exit, native
    -- lift, obstruction recovery and seat recovery through driveSea, while the
    -- `ignoreSeaTargets` boundary above excludes all mob/event combat logic.
    function EventFarm.RunFrozenDimensionSearch(generation)
        local runtime = EventFarm.Runtime
        local boat, acquireReason = acquireBoat(generation)
        if not boat then
            if isCurrent(generation) then
                notify("Dimensão Congelada", "Não foi possível preparar o barco: " .. tostring(acquireReason), "error", "frozen_prepare_fail", 1)
                EventFarm:SetFrozenDimensionSearch(false, acquireReason or "boat_prepare_failed")
            end
            return
        end

        local launchAttempt = 0
        while isCurrent(generation) and launchAttempt < EventFarm.TikiExitMaximumHulls do
            launchAttempt = launchAttempt + 1
            setPhase("entering_boat", "frozen_dimension_search")
            local attached, attachReason = attachNativeControl(boat)
            if not attached then
                -- Preserve the Farm's conservative ownership rule: do not pull
                -- a stale/far hull. A bounded fresh dealer purchase is safer.
                if attachReason == "could_not_enter_driver_seat" and launchAttempt < EventFarm.TikiExitMaximumHulls then
                    runtime.forceFreshBoat = true
                    runtime.boat, runtime.seat = nil, nil
                    boat, attachReason = buyReplacementBoatAtTikiWestDealer(generation, boat)
                    if boat and isCurrent(generation) then
                        continue
                    end
                end
                if isCurrent(generation) then
                    notify("Dimensão Congelada", "Não foi possível assumir o assento: " .. tostring(attachReason), "error", "frozen_seat_fail", 1)
                    EventFarm:SetFrozenDimensionSearch(false, attachReason or "seat_unavailable")
                end
                return
            end
            setPhase("settling_native_boat", "frozen_dimension_search")
            if not settleNativeBoat(generation) then
                if runtime.boatLostReason then
                    local recovered, recoveryReason = resetAfterBoatLoss(generation)
                    if recovered and isCurrent(generation) then
                        task.spawn(function() if isCurrent(generation) then EventFarm.RunFrozenDimensionSearch(generation) end end)
                    elseif isCurrent(generation) then
                        EventFarm:SetFrozenDimensionSearch(false, recoveryReason or "native_boat_settle_failed")
                    end
                elseif isCurrent(generation) then
                    EventFarm:SetFrozenDimensionSearch(false, "native_boat_settle_failed")
                end
                return
            end

            local currentBoatPosition = runtime.seat and runtime.seat.Position or positionOf(boat)
            local readyForSea = true
            if isAtTiki(currentBoatPosition) then
                local escaped, escapeReason = setOpenSeaCourse(generation)
                if not escaped then
                    if runtime.boatLostReason then
                        local recovered, recoveryReason = resetAfterBoatLoss(generation)
                        if recovered and isCurrent(generation) then
                            task.spawn(function() if isCurrent(generation) then EventFarm.RunFrozenDimensionSearch(generation) end end)
                        elseif isCurrent(generation) then
                            EventFarm:SetFrozenDimensionSearch(false, recoveryReason or "boat_loss_recovery_failed")
                        end
                        return
                    end
                    local noMeaningfulProgress = type(escapeReason) == "string"
                        and string.find(escapeReason, "open_sea_exit_not_confirmed_projection_", 1, true) ~= nil
                    if isCurrent(generation) and noMeaningfulProgress and launchAttempt < EventFarm.TikiExitMaximumHulls then
                        local stuckBoat = runtime.boat or boat
                        clearNativeControl()
                        runtime.boat, runtime.seat = nil, nil
                        local h = humanoid()
                        if h then pcall(function() h.Sit = false end) end
                        boat, escapeReason = buyReplacementBoatAtTikiWestDealer(generation, stuckBoat)
                        if boat and isCurrent(generation) then
                            readyForSea = false
                        else
                            EventFarm:SetFrozenDimensionSearch(false, escapeReason or "replacement_boat_unavailable")
                            return
                        end
                    else
                        if isCurrent(generation) then EventFarm:SetFrozenDimensionSearch(false, escapeReason or "open_sea_exit_failed") end
                        return
                    end
                end
            else
                local look = runtime.seat and Vector3.new(runtime.seat.CFrame.LookVector.X, 0, runtime.seat.CFrame.LookVector.Z)
                    or EventFarm.TikiOpenSeaDirection
                runtime.cruiseDirection = look.Magnitude > 0.01 and look.Unit or EventFarm.TikiOpenSeaDirection
                beginExistingSeaCalibration()
            end

            if readyForSea then
                setPhase("searching_frozen_dimension")
                local frozenTarget, seaReason = driveSea(generation, {
                    ignoreSeaTargets = true,
                    resolveTarget = function()
                        local candidate = EventFarm.FindFrozenDimension()
                        if not candidate or not candidate.instance or not candidate.position then
                            if runtime.phase ~= "searching_frozen_dimension" then setPhase("searching_frozen_dimension") end
                            return nil
                        end
                        local seat = runtime.seat
                        local boatPosition = seat and seat.Position or rootPart() and rootPart().Position
                        if not boatPosition then return nil end
                        local distanceToDimension = horizontalDistance(boatPosition, candidate.position)
                        candidate.distance = distanceToDimension
                        if distanceToDimension <= EventFarm.FrozenDimensionArrivalDistance then
                            return candidate.instance, "frozen_dimension"
                        end
                        local heading = Vector3.new(candidate.position.X - boatPosition.X, 0, candidate.position.Z - boatPosition.Z)
                        if heading.Magnitude > 0.1 then
                            runtime.cruiseDirection = heading.Unit
                            drive(runtime.cruiseDirection, 300)
                        end
                        if runtime.phase ~= "approaching_frozen_dimension" then
                            setPhase("approaching_frozen_dimension")
                            journal("frozen_dimension_approach", {distance = distanceToDimension, name = candidate.instance.Name})
                        end
                        return nil
                    end,
                })
                if frozenTarget and seaReason == "frozen_dimension" and isCurrent(generation) then
                    local frozen = runtime.frozenDimension or {}
                    setPhase("frozen_dimension_reached", "verified_nearby")
                    journal("frozen_dimension_reached", {
                        name = frozenTarget.Name,
                        distance = frozen.distance,
                        arrivalDistance = EventFarm.FrozenDimensionArrivalDistance,
                    })
                    notify("Dimensão Congelada", "Dimensão Congelada encontrada nas proximidades. Controle nativo do barco restaurado.", "success", "frozen_dimension_reached", 1)
                    EventFarm:SetFrozenDimensionSearch(false, "frozen_dimension_reached")
                    return
                end
                if seaReason == "tiki_return_rebuy" and isCurrent(generation) then
                    clearNativeControl()
                    runtime.boat, runtime.seat, runtime.boatCharacter = nil, nil, nil
                    runtime.forceFreshBoat = true
                    runtime.tikiReturnNeedsFreshBoat = true
                    task.spawn(function() if isCurrent(generation) then EventFarm.RunFrozenDimensionSearch(generation) end end)
                    return
                end
                if seaReason == "boat_lost" or runtime.boatLostReason then
                    local recovered, recoveryReason = resetAfterBoatLoss(generation)
                    if recovered and isCurrent(generation) then
                        task.spawn(function() if isCurrent(generation) then EventFarm.RunFrozenDimensionSearch(generation) end end)
                    elseif isCurrent(generation) then
                        EventFarm:SetFrozenDimensionSearch(false, recoveryReason or "boat_loss_recovery_failed")
                    end
                    return
                end
                if seaReason == "character_died" and isCurrent(generation) then
                    clearNativeControl()
                    runtime.boat, runtime.seat, runtime.boatCharacter = nil, nil, nil
                    runtime.forceFreshBoat = true
                    task.spawn(function() if isCurrent(generation) then EventFarm.RunFrozenDimensionSearch(generation) end end)
                    return
                end
                return
            end
        end
        if isCurrent(generation) then EventFarm:SetFrozenDimensionSearch(false, "tiki_exit_attempts_exhausted") end
    end

    function EventFarm:GetCoordinatorCheckpoint(reason)
        local runtime = self.Runtime
        local targetPosition = positionOf(runtime.target)
        local activeCheckpoint = runtime.progress and runtime.progress.checkpoint or nil
        return {
            stage = runtime.phase or "idle",
            reason = reason or runtime.reason,
            target = runtime.target and {
                kind = runtime.targetKind,
                name = runtime.target.Name,
                position = vectorSnapshot(targetPosition),
            } or (activeCheckpoint and {
                kind = activeCheckpoint.kind,
                name = activeCheckpoint.targetName,
                position = activeCheckpoint.target and vectorSnapshot(positionOf(activeCheckpoint.target)) or nil,
            }) or nil,
            boat = {
                selectedName = State.eventFarmBoat,
                mode = runtime.mode == "frozen_dimension_search" and runtime.mode
                    or (activeCheckpoint and activeCheckpoint.mode) or runtime.mode,
            },
        }
    end

    function EventFarm:CanYieldForCoordinator(context)
        local runtime = self.Runtime
        if runtime.active ~= true then return true, "event_not_active" end
        if runtime.mode == "frozen_dimension_search" then
            -- The search owns one continuous boat/navigation lease until the
            -- island is verified nearby or the player stops it. No unrelated
            -- farm may reroute it through a mob/event opportunity.
            return false, "frozen_dimension_search_active"
        end
        local phase = tostring(runtime.phase or "")
        -- Boat attach/settle, active combat, evasion and recovery are physical
        -- handoffs. They are never interrupted merely because a fruit scored
        -- well; the queued opportunity will be re-evaluated on the next safe
        -- cruise/preparing checkpoint.
        if phase:find("combat", 1, true) or phase:find("entering_boat", 1, true)
            or phase:find("settling", 1, true) or phase:find("evade", 1, true)
            or phase:find("recover", 1, true) or runtime.targetKind ~= nil then
            return false, "event_physical_or_combat_stage"
        end
        local requester = type(context) == "table" and context.requester or nil
        if requester == "fruit" then
            local requestContext = context.request and context.request.context or {}
            local policy = Flow.Features and Flow.Features.FruitPriority
            if policy and policy.CanInterrupt then
                local allowed, detail = policy:CanInterrupt(requestContext.fruitName, requestContext.selected == true, "event_farm")
                if not allowed then return false, detail end
            end
        end
        return true, "event_safe_checkpoint"
    end

    function EventFarm:PauseForCoordinator(context)
        local runtime = self.Runtime
        if runtime.active ~= true then return true, "event_already_paused" end
        runtime.suspendedByCoordinator = {
            by = type(context) == "table" and context.requester or "coordinator",
