        if typeof(position) ~= "Vector3" then return false, "calibration_position_invalid" end
        if not canContinueTarget("sea_beast") or runtime.phase ~= "sea_beast_combat"
            or runtime.seaBeastCombatReady ~= true or not isSeaBeastTarget(runtime.target)
            or not seaBeastAlive(runtime.target) then return false, "sea_beast_combat_required" end
