        local state = self.State
        state.monitorGeneration = (state.monitorGeneration or 0) + 1
        local monitorGeneration = state.monitorGeneration
        task.spawn(function()
            while state.running and state.generation == runGeneration and state.monitorGeneration == monitorGeneration do
