            ownershipDetail = self.State.ownershipDetail or "",
            mobs = #mobs,
            target = self.State.target,
            weapon = self.State.effectiveWeapon,
            selectedFruit = self.State.selectedFruit,
            chipResponse = self.State.lastChipResponse or "",
            chipDecision = self.State.lastChipDecision or "",
            summonTravelMode = self.State.summonTravelMode or "",
            summonTravelReason = self.State.summonTravelReason or "",
            waveSeen = self.State.waveSeen == true,
            activeWaveSeen = self.State.activeWaveSeen == true,
            waitingAtNextIsland = self.State.waitingAtNextIsland == true,
            traceCount = #(self.State.diagnosticTrace or {}),
            completed = self.State.completedCount or 0,
            repeatGoal = self:GetRepeatGoal(),
            repeatProgress = self:GetRepeatProgress(),
            repeatGoalReached = self:HasReachedRepeatGoal(),
            attackAccepted = self.State.attackAccepted or 0,
            attackRejected = self.State.attackRejected or 0,
            fastCycles = self.State.fastCycles or 0,
            fastClickEvents = self.State.fastClickEvents or 0,
            fastAttackEvents = self.State.fastAttackEvents or 0,
            fastHitEvents = self.State.fastHitEvents or 0,
            combatPath = self.State.sendHitsResolved and "send_hits_to_server" or "register_hit",
            combatAnchor = self.State.combatAnchor and tostring(self.State.combatAnchor) or "",
            v4 = v4,
            v4Prompted = self.State.v4Prompted == true,
            v4PromptPending = self.State.v4PromptPending == true,
            v4ActivationWaiting = (self.State.v4ActivationDeadline or 0) > os.clock(),
            awaitingNativeReturn = self.State.awaitingNativeReturn == true,
