    RaidMonitor.MaxHistory = 180
    RaidMonitor.MaxScan = 80
    RaidMonitor.ExportFile = "FlowKanHub_RaidMonitor.json"
    RaidMonitor.State = {
        running = false,
        generation = 0,
        connections = {},
        history = {},
        snapshot = nil,
