                beli = row.beli,
                rarityRank = self.RarityOrder[row.rarity] or 0,
            }
        end
        table.sort(list, function(a, b)
            if a.rarityRank == b.rarityRank then return a.beli < b.beli end
            return a.rarityRank < b.rarityRank
        end)
