    FruitPriority.RarityScore = {common = 1, uncommon = 4, rare = 12, legendary = 40, mythical = 120}
    FruitPriority.RequestPriority = {common = 16, uncommon = 22, rare = 32, legendary = 68, mythical = 94}

    local function catalog()
        return Flow.Features and Flow.Features.FruitCatalog or nil
    end

    function FruitPriority:GetProfileName()
        local requested = tostring(State.farmProfile or "balanced")
        return self.Profiles[requested] and requested or "balanced"
    end

    function FruitPriority:GetProfile()
        return self.Profiles[self:GetProfileName()]
    end

    function FruitPriority:SetProfile(name)
        name = tostring(name or "balanced")
        if not self.Profiles[name] then return false, "farm_profile_invalid" end
        State.farmProfile = name
        State.farmProfileRevision = 1
        if Flow.Config then Flow.Config:Save() end
