            if name == current then
                return self:SetProfile(self.ProfileOrder[index % #self.ProfileOrder + 1])
            end
        end
        return self:SetProfile("balanced")
    end

    function FruitPriority:Describe(value, selected)
        local source = catalog()
        local data, normalized = source and source:Get(value) or nil, tostring(value or "")
        if not data then
            return {
                name = normalized:gsub("%s+[Ff]ruit$", ""),
                displayName = tostring(value or ""),
                rarity = "unknown",
                type = "unknown",
                beli = 0,
                rarityRank = 0,
                score = 0,
                requestPriority = 0,
                collectable = false,
