        if data.rarity == "legendary" then requestPriority = profile.legendaryPriority or requestPriority end
        if data.rarity == "mythical" then requestPriority = profile.mythicalPriority or requestPriority end
        if selected == true then requestPriority = requestPriority + math.min(6, profile.collectionBonus or 0) end
        local permitted = data.rarityRank >= (profile.minimumRank or 6) and requestPriority > 0

        return {
            name = data.name,
            displayName = data.name .. " Fruit",
            rarity = data.rarity,
            type = data.type,
            beli = data.beli,
            rarityRank = data.rarityRank,
            score = score,
            baseScore = score,
            travelCost = 0,
            requestPriority = requestPriority,
            collectable = permitted,
            profile = profileName,
            reason = permitted and "profile_threshold_met" or "profile_threshold_not_met",
        }
    end

    function FruitPriority:CanInterrupt(value, selected, activeOwner)
        local info = self:Describe(value, selected)
        if not info.collectable then return false, info.reason, info end
        local profile = self:GetProfile()
        if activeOwner == "event_farm" and profile.allowEventPreempt ~= true then
            return false, "event_preemption_disabled_by_profile", info
        end
        return true, "profile_threshold_met", info
    end

    function FruitPriority:GetSnapshot()
        local profileName, profile = self:GetProfileName(), self:GetProfile()
        return {
            profile = profileName,
            label = profile.label,
            minimumRank = profile.minimumRank,
            catalogRevision = (catalog() and catalog().Revision) or "unavailable",
        }
    end

