        else
            if coordinator then coordinator:Release("raid", "raid_inactive") end
            if State.autoCollectEnabled == true and finder and finder.SetAutoCollectRaw and not (finder.State and finder.State.running) then
                pcall(function() finder:SetAutoCollectRaw(true) end)
            end
            if State.autoCollectEnabled == true then winner, reason = "fruit", "fruit_intent_armed"
            elseif State.farmLevelEnabled == true then
                -- The shared Farm master can drive either executor; report the
                -- one that actually owns movement so telemetry stays honest.
                if State.farmAutomationMode == "missions" then
                    winner, reason = "missions", "mission_intent_armed"
                else
                    winner, reason = "farm", "farm_intent_armed"
                end
            end
        end

        if winner ~= self.State.winner or reason ~= self.State.reason then
            self.State.winner, self.State.reason, self.State.lastChangedAt = winner, reason, os.clock()
            Flow:Log("Priority | " .. winner .. " | " .. reason)
        end
        return winner, reason
    end

    function Priority:SetFruitIntent(enabled, onChange)
        enabled = enabled == true
        State.autoCollectEnabled = enabled
        if Flow.Config then pcall(function() Flow.Config:Save() end) end
        local finder = feature("FruitFinder")
        if not enabled and finder and finder.SetAutoCollectRaw then
            pcall(function() finder:SetAutoCollectRaw(false) end)
        end
        self:Reconcile()
        if onChange then pcall(onChange, enabled and not self:IsRaidPriority()) end
        return true, enabled and "requested" or "stopped"
    end

    function Priority:GetBlockReason(requester)
        local coordinator = feature("FarmCoordinator")
        if not coordinator then return nil end
        local owner = requester == "farm" and "farm_level"
            or (requester == "missions" and "farm_special_quest" or tostring(requester or ""))
        return coordinator:GetBlockReason(owner, {resources = {"movement", "combat"}})
    end

    function Priority:Start()
        if self.State.running then return true, "already_running" end
        self.State.running = true
        self.State.generation = self.State.generation + 1
        local generation = self.State.generation
        local coordinator = feature("FarmCoordinator")
        if coordinator then coordinator:Start() end
        task.spawn(function()
            while self.State.running and self.State.generation == generation do
                pcall(function() self:Reconcile() end)
                task.wait(self.PollSeconds)
            end
        end)
        self:Reconcile()
        return true, "started"
    end

    function Priority:Stop()
        self.State.running = false
        self.State.generation = self.State.generation + 1
        local finder = feature("FruitFinder")
        if finder and finder.SetAutoCollectRaw then pcall(function() finder:SetAutoCollectRaw(false) end) end
        local coordinator = feature("FarmCoordinator")
        if coordinator then coordinator:Release("raid", "priority_stopped") end
        return true
    end

    function Priority:GetSnapshot()
        local coordinator = feature("FarmCoordinator")
        return {
            running = self.State.running == true,
            winner = self.State.winner,
            reason = self.State.reason,
            raidPriority = self:IsRaidPriority(),
            coordinator = coordinator and coordinator:GetSnapshot() or nil,
        }
    end

    function Priority:Shutdown()
        return self:Stop()
    end

    Flow.Features.SystemPriority = Priority
end)(Flow)
Flow.Performance.modules['features/system_priority.lua'] = math.floor((os.clock() - __flow_module_started) * 1000 + 0.5) / 1000
end

-- >>> MODULE: features/system_telemetry.lua
do
local __flow_module_started = os.clock()
;(function(Flow)
    local Telemetry = {}
    local State = Flow.State
    local services = Flow.Services
    local player = Flow.Player
    local workspace = services.Workspace
    local runService = services.RunService
    local http = services.HttpService

    Telemetry.SampleSeconds = 0.25
    Telemetry.MaxHistory = 600
    Telemetry.ExportFile = "FlowKanHub_SystemTelemetry.json"
    Telemetry.State = {
        running = false,
        generation = 0,
        connections = {},
        history = {},
        remoteSummary = {},
        snapshot = nil,
        signature = "",
        lastPersistAt = 0,
        lastError = nil,
    }

    local function rootOf(character)
        return character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart) or nil
    end
    local function round(value) return type(value) == "number" and math.floor(value * 10 + 0.5) / 10 or nil end
    local function vec(value)
        if typeof(value) ~= "Vector3" then return nil end
        return { x = round(value.X), y = round(value.Y), z = round(value.Z) }
    end
    local function motion(value)
        if typeof(value) ~= "Vector3" then return { velocity = nil, speed = nil, direction = nil } end
        local horizontal = Vector3.new(value.X, 0, value.Z)
        local magnitude = horizontal.Magnitude
        return {
            velocity = vec(value), speed = round(value.Magnitude),
            direction = magnitude > 0.05 and vec(horizontal / magnitude) or nil,
        }
    end
    local function attrs(object)
        local result = {}
        local ok, values = pcall(function() return object and object:GetAttributes() end)
        if ok and type(values) == "table" then
            for key, value in pairs(values) do result[tostring(key)] = tostring(value) end
        end
        return result
    end
    local function feature(name) return Flow.Features and Flow.Features[name] or nil end

    function Telemetry:Record(kind, detail, data)
        local entry = { at = round(os.clock()), kind = tostring(kind or "event"), detail = tostring(detail or ""), data = data }
        table.insert(self.State.history, entry)
        while #self.State.history > self.MaxHistory do table.remove(self.State.history, 1) end
    end

    function Telemetry:RecordKnownRemote(name, phase, detail)
        -- Aggregates only calls emitted by Hub modules themselves. This is not
        -- a Remote spy: no game traffic is intercepted, enumerated or replayed.
        local key = tostring(name or "known"):sub(1, 96)
        local summary = self.State.remoteSummary
        local bucket = summary[key]
        if not bucket then
            local count = 0; for _ in pairs(summary) do count = count + 1 end
            if count >= 32 then key = "other_known_hub_action"; bucket = summary[key] end
            bucket = bucket or { intents = 0, succeeded = 0, failed = 0 }
            summary[key] = bucket
        end
        if phase == "intent" then bucket.intents = (bucket.intents or 0) + 1
        elseif phase == "result" and tostring(detail):find("ok=true", 1, true) then bucket.succeeded = (bucket.succeeded or 0) + 1
        elseif phase == "result" then bucket.failed = (bucket.failed or 0) + 1 end
        bucket.lastAt, bucket.last = round(os.clock()), tostring(detail or ""):sub(1, 160)
        self:Record("known_remote_" .. tostring(phase), key .. "|" .. bucket.last)
    end

    function Telemetry:GetRemoteSummary() return self.State.remoteSummary end

    function Telemetry:Snapshot()
        local character = player and player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = rootOf(character)
        local raid, farm, finder = feature("Raid"), feature("Farm"), feature("FruitFinder")
        local teleport, priority, telemetry = feature("Teleport"), feature("SystemPriority"), feature("SystemTelemetry")
        local target = raid and raid.State and raid.State.combatTarget
        local targetHumanoid = target and target:FindFirstChildOfClass("Humanoid")
        local targetRoot = rootOf(target)
        local ticket = teleport and teleport.ActiveTravel
        local playerMotion = motion(root and root.AssemblyLinearVelocity)
        local enemies = workspace and workspace:FindFirstChild("Enemies")
        local prioritySnapshot = priority and priority.GetSnapshot and priority:GetSnapshot() or {}
        return {
            at = round(os.clock()),
            player = {
                health = humanoid and round(humanoid.Health), maxHealth = humanoid and round(humanoid.MaxHealth),
                humanoidState = humanoid and tostring(humanoid:GetState()), root = vec(root and root.Position),
                velocity = playerMotion.velocity, speed = playerMotion.speed, direction = playerMotion.direction,
                islandRaiding = player and player:GetAttribute("IslandRaiding") == true,
            },
            options = {
                autoFruit = State.autoCollectEnabled == true, fruitLive = State.isCollecting == true,
                farm = State.farmLevelEnabled == true, bring = State.farmBringMobs == true,
                bringRadius = State.farmBringRadius, attack = State.farmAutoAttack == true,
                raidType = State.raidType, telemetry = State.telemetryEnabled == true,
            },
            raid = raid and raid.State and {
                running = raid.State.running == true, phase = raid.State.phase, detail = raid.State.detail,
                world = raid:IsRaiding(), island = raid.State.activeIslandId, target = target and target.Name,
                targetHealth = targetHumanoid and round(targetHumanoid.Health), targetMaxHealth = targetHumanoid and round(targetHumanoid.MaxHealth),
                targetRoot = vec(targetRoot and targetRoot.Position), combatActive = raid.State.combatActive == true,
                fastCycles = raid.State.fastCycles, attacks = raid.State.fastAttackEvents, hits = raid.State.fastHitEvents,
                accepted = raid.State.attackAccepted, rejected = raid.State.attackRejected,
                chipCommitted = raid.State.chipCommitted == true, chipBlocked = raid.State.chipCooldownBlocked == true,
                finalFollow = raid.State.finalBossFollow == true, finalSurface = raid.State.finalBossSurfaceDetail,
            } or nil,
            farm = farm and farm.State and {
                running = farm.State.running == true, phase = farm.State.phase, detail = farm.State.detail,
                hoverOwner = farm.State.hoverOwner, hoverHeight = farm.State.hoverHeightOverride,
                hoverCorrections = farm.State.hoverCorrections or 0,
                hoverVerticalCorrections = farm.State.hoverVerticalCorrections or 0,
                hoverDriftY = round(farm.State.hoverLastDriftY),
                combatStartedAt = round(farm.State.combatStartedAt),
                firstAttackAt = round(farm.State.firstAttackAt),
                firstDamageAt = round(farm.State.firstDamageAt),
                attackAttempts = farm.State.attackAttempts or 0,
                lastAttackReason = farm.State.lastAttackReason,
                weaponEquipTransitions = farm.State.weaponEquipTransitions or 0,
                prewarmSeconds = round(farm.State.combatPrewarmSeconds),
                attackPulse = farm.State.attackPulseRunning == true,
                priorityPause = farm.State.priorityPauseReason,
            } or nil,
            fruit = finder and finder.State and { running = finder.State.running == true, target = finder.State.target and finder.State.target.name } or nil,
            teleport = ticket and { owner = ticket.owner, target = vec(ticket.target), startedAt = round(ticket.startedAt), cancelled = ticket.cancelled == true } or nil,
            priority = prioritySnapshot,
            knownRemoteActions = telemetry and telemetry.GetRemoteSummary and telemetry:GetRemoteSummary() or {},
            enemies = enemies and #enemies:GetChildren() or 0,
        }
    end

    function Telemetry:Signature(snapshot)
        local p, r, f, t = snapshot.player or {}, snapshot.raid or {}, snapshot.farm or {}, snapshot.teleport or {}
        local pos, velocity = p.root or {}, p.velocity or {}
        return table.concat({
            tostring(p.health), tostring(p.humanoidState), tostring(pos.x), tostring(pos.y), tostring(pos.z), tostring(velocity.y), tostring(p.islandRaiding),
            tostring(r.running), tostring(r.world), tostring(r.phase), tostring(r.detail), tostring(r.island), tostring(r.target), tostring(r.targetHealth), tostring(r.combatActive), tostring(r.fastCycles), tostring(r.hits),
            tostring(f.hoverOwner), tostring(f.hoverCorrections), tostring(f.hoverVerticalCorrections), tostring(f.hoverDriftY), tostring(f.combatStartedAt), tostring(f.firstAttackAt), tostring(f.firstDamageAt), tostring(f.attackAttempts), tostring(f.lastAttackReason), tostring(f.weaponEquipTransitions), tostring(f.prewarmSeconds), tostring(f.attackPulse), tostring(f.priorityPause), tostring(t.owner), tostring(t.target and t.target.x), tostring(t.target and t.target.y), tostring(t.target and t.target.z),
            tostring(snapshot.enemies), tostring(snapshot.priority and snapshot.priority.winner),
        }, "|")
    end

    function Telemetry:Persist(force)
        local now = os.clock()
        if not force and now - (self.State.lastPersistAt or 0) < 1 then return false end
        local writer = Flow.Executor and Flow.Executor.writefile
        if not writer or not http then return false end
        local payload = { version = Flow.Version, snapshot = self.State.snapshot, history = self.State.history, lastError = self.State.lastError }
        local ok, encoded = pcall(function() return http:JSONEncode(payload) end)
        if not ok then return false end
        local wrote = pcall(writer, self.ExportFile, encoded)
        if wrote then self.State.lastPersistAt = now end
        return wrote
    end

    function Telemetry:Capture(reason)
        local snapshot = self:Snapshot()
        local signature = self:Signature(snapshot)
        self.State.snapshot = snapshot
        if signature ~= self.State.signature then
            self.State.signature = signature
            self:Record(reason or "state", "state_changed", snapshot)
            self:Persist(false)
        end
        return snapshot
    end

    function Telemetry:Watch(signal, kind, formatter)
        if not signal or type(signal.Connect) ~= "function" then return end
        local ok, connection = pcall(function()
            return signal:Connect(function(...)
                if not self.State.running then return end
                local detail = formatter and formatter(...) or ""
                self:Record(kind, detail)
                self:Persist(false)
            end)
        end)
        if ok and connection then table.insert(self.State.connections, connection) end
    end

    function Telemetry:Disconnect()
        for _, connection in ipairs(self.State.connections) do pcall(function() connection:Disconnect() end) end
        self.State.connections = {}
    end

    function Telemetry:WatchCharacter(character)
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        self:Watch(humanoid and humanoid.HealthChanged, "player_health", function(health) return tostring(round(health)) end)
        self:Watch(humanoid and humanoid.StateChanged, "humanoid_state", function(_, newState) return tostring(newState) end)
    end

    function Telemetry:Start()
        if self.State.running then return true, "already_running" end
        self:Disconnect()
        self.State.running = true
        self.State.generation = self.State.generation + 1
        local generation = self.State.generation
        self:Record("telemetry_started", "passive_hub_scope")
        self:Watch(player and player.CharacterAdded, "character_added", function(character)
            self:WatchCharacter(character)
            return character and character.Name or "character"
        end)
        self:Watch(player and player:GetAttributeChangedSignal("IslandRaiding"), "island_raiding", function() return tostring(player:GetAttribute("IslandRaiding")) end)
        self:WatchCharacter(player and player.Character)
        local enemies = workspace and workspace:FindFirstChild("Enemies")
        self:Watch(enemies and enemies.ChildAdded, "npc_added", function(npc) return npc and npc.Name or "npc" end)
        self:Watch(enemies and enemies.ChildRemoved, "npc_removed", function(npc) return npc and npc.Name or "npc" end)
        self:Capture("initial")
        self:Persist(true)
        task.spawn(function()
            while self.State.running and self.State.generation == generation do
                local ok, err = pcall(function() self:Capture("poll") end)
                if not ok then self.State.lastError = tostring(err); self:Record("telemetry_error", self.State.lastError) end
                task.wait(self.SampleSeconds)
            end
        end)
        return true, "started"
    end

    function Telemetry:Stop(updatePreference)
        if not self.State.running then return true end
        self.State.running = false
        self.State.generation = self.State.generation + 1
        self:Disconnect()
        self:Record("telemetry_stopped", "")
        self:Persist(true)
        if updatePreference then State.telemetryEnabled = false; if Flow.Config then pcall(function() Flow.Config:Save() end) end end
        return true
    end
    function Telemetry:SetEnabled(enabled)
        if enabled then State.telemetryEnabled = true; if Flow.Config then pcall(function() Flow.Config:Save() end) end; return self:Start() end
        return self:Stop(true)
    end
    function Telemetry:GetSnapshot() return self.State.snapshot or {} end
    function Telemetry:Shutdown() return self:Stop(false) end
    Flow.Features.SystemTelemetry = Telemetry
end)(Flow)
Flow.Performance.modules['features/system_telemetry.lua'] = math.floor((os.clock() - __flow_module_started) * 1000 + 0.5) / 1000
end

