    -- Lucide icon subset (ISC license): rasterized locally and embedded so the
    -- standalone bundle never downloads an icon package at runtime.
    local lucideEncoded = {
        fruit = [[]],
        travel = [[]],
        maritime = [[]],
        status = [[]],
        misc = [[]],
        settings = [[]],
        target = [[]],
        cake = [[]],
        crown = [[]],
        skull = [[]],
        check = [[]],
        unavailable = [[]],
        location = [[]],
        timer = [[]],
        mobs = [[]],
        minimize = [[]],
        close = [[]],
        refresh = [[]],
        join = [[]],
        hop = [[]],
        rejoin = [[]],
        map = [[]],
        servers = [[]],
        style = [[]],
        language = [[]],
        antiAfk = [[]],
        fog = [[]],
        portal = [[]],
        speed = [[]],
        players = [[]],
        moon = [[]],
        inventory = [[]],
        accent = [[]],
    }

    -- Decode only when an executor-side cache file is missing. The prior
    -- bit-string expansion allocated several megabytes for the old 512 px logo
    -- and all Lucide files, delaying the first visible Hub frame. Decode four
    -- Base64 characters directly to up to three bytes instead.
    local function decodeBase64(input)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local values = {}
        for index = 1, #alphabet do values[alphabet:sub(index, index)] = index - 1 end
        input = input:gsub("[^A-Za-z0-9%+/%=]", "")
        local output, count = {}, 0
        for index = 1, #input, 4 do
            local a = values[input:sub(index, index)] or 0
            local b = values[input:sub(index + 1, index + 1)] or 0
            local third = input:sub(index + 2, index + 2)
            local fourth = input:sub(index + 3, index + 3)
            local c = values[third] or 0
            local d = values[fourth] or 0
            count = count + 1
            output[count] = string.char(a * 4 + math.floor(b / 16))
            if third ~= "=" and third ~= "" then
                count = count + 1
                output[count] = string.char((b % 16) * 16 + math.floor(c / 4))
            end
            if fourth ~= "=" and fourth ~= "" then
                count = count + 1
                output[count] = string.char((c % 4) * 64 + d)
            end
        end
        return table.concat(output)
    end

    local function executorFunction(name)
        return Flow:GetExecutorFunction(name)
    end

    local function loadLocalAsset(path, data)
        local getAsset = executorFunction("getcustomasset") or executorFunction("getsynasset")
        local writeFile = Flow.Executor.writefile
        local isFile = Flow.Executor.isfile
        if not getAsset or not writeFile then return "" end

        local exists = false
        if isFile then
            local ok, result = pcall(isFile, path)
            exists = ok and result
        end
        if not exists then
            pcall(writeFile, path, decodeBase64(data))
        end

        local ok, asset = pcall(getAsset, path)
        return ok and asset or ""
    end

    local function loadIcon()
        return loadLocalAsset("FlowKanHub_Icon_v4_128.png", encoded)
    end

    local lucideAssets = {}
    for name, data in pairs(lucideEncoded) do
        lucideAssets[name] = loadLocalAsset("FlowKanHub_Lucide_" .. name .. ".png", data)
    end

    Flow.Assets = {
        Icon = loadIcon(),
        Icons = lucideAssets,
        IconSize = 128,
    }
end)(Flow)
Flow.Performance.modules['core/assets.lua'] = math.floor((os.clock() - __flow_module_started) * 1000 + 0.5) / 1000
end

-- >>> MODULE: features/system_notifications.lua
do
local __flow_module_started = os.clock()
;(function(Flow)
    local Notifications = {}
    local State = Flow.State
    local Theme = Flow.Theme
    local tweenService = Flow.Services.TweenService

    Notifications.MaxVisible = 2
    Notifications.DefaultDuration = 4
    Notifications.DefaultQuestionTimeout = 30
    Notifications.DuplicateWindow = 2
    Notifications.State = {
        queue = {}, active = 0, sequence = 0, gui = nil, holder = nil,
        cards = {}, recent = {}, suppressed = 0,
    }

    local positions = {
        bottom_right = {anchor = Vector2.new(1, 1), position = UDim2.new(1, -14, 1, -14), vertical = Enum.VerticalAlignment.Bottom, horizontal = Enum.HorizontalAlignment.Right},
        bottom_left = {anchor = Vector2.new(0, 1), position = UDim2.new(0, 14, 1, -14), vertical = Enum.VerticalAlignment.Bottom, horizontal = Enum.HorizontalAlignment.Left},
        top_right = {anchor = Vector2.new(1, 0), position = UDim2.new(1, -14, 0, 14), vertical = Enum.VerticalAlignment.Top, horizontal = Enum.HorizontalAlignment.Right},
        top_left = {anchor = Vector2.new(0, 0), position = UDim2.new(0, 14, 0, 14), vertical = Enum.VerticalAlignment.Top, horizontal = Enum.HorizontalAlignment.Left},
    }
    local styles = {
        modern = {height = 72, background = function() return Theme.panel2 end, transparency = 0, stroke = function() return Theme.border end},
        glass = {height = 72, background = function() return Theme.panel end, transparency = 0.12, stroke = function() return Theme.accent end},
        compact = {height = 58, background = function() return Theme.panel3 end, transparency = 0, stroke = function() return Theme.border end},
    }
    local accents = {
        info = function() return Theme.accent2 end,
        success = function() return Theme.success end,
        warning = function() return Theme.warning or Color3.fromRGB(235, 177, 67) end,
        error = function() return Theme.danger end,
        question = function() return Color3.fromRGB(106, 163, 255) end,
        input = function() return Theme.accent2 end,
    }

    local function validPosition(value) return positions[value] ~= nil end
    local function validStyle(value) return styles[value] ~= nil end
    local function now() return os.clock() end
    local function tr(key, fallback)
        local language = Flow.Language
        if language and language.T then
            local value = language:T(key)
            if value and value ~= key then return value end
        end
        return fallback or key
    end
    local function configurationSave()
        if Flow.Config and Flow.Config.Save then pcall(function() Flow.Config:Save() end) end
    end
    local function assets() return Flow.Assets and Flow.Assets.Icons or {} end
    local function defaultIcon(kind)
        local icon = assets()
        if kind == "success" then return icon.check or icon.accent end
        if kind == "error" then return icon.close or icon.skull end
        if kind == "warning" then return icon.fog or icon.status end
        if kind == "question" or kind == "input" then return icon.settings or icon.inventory end
        return icon.status or icon.accent
    end
    local function interactive(options)
        return options.mode == "confirm" or options.mode == "input"
    end

    -- Makes all historical Flow:Notify call shapes behave identically.
    function Notifications:Normalize(raw)
        raw = type(raw) == "table" and raw or {message = raw}
        local options = {}
        for key, value in pairs(raw) do options[key] = value end
        options.kind = accents[options.kind or options.type] and (options.kind or options.type) or "info"
        options.title = tostring(options.title or tr("notification_title", "Flow Kan Hub"))
        options.message = tostring(options.message or options.content or options.text or "")
        options.duration = tonumber(options.duration) or self.DefaultDuration
        options.repeatCount = math.max(1, tonumber(options.repeatCount) or 1)
        -- Interactive prompts are never collapsed: each callback belongs to a
        -- specific action and must remain available to the player.
        if not interactive(options) then
            options.dedupeKey = tostring(options.dedupeKey or (options.kind .. "\31" .. options.title .. "\31" .. options.message))
        end
        return options
    end

    function Notifications:GetPosition() return validPosition(State.notificationPosition) and State.notificationPosition or "bottom_right" end
    function Notifications:GetStyle() return validStyle(State.notificationStyle) and State.notificationStyle or "compact" end

    function Notifications:ApplyPresentation()
        local holder = self.State.holder
        if not holder then return end
        local location = positions[self:GetPosition()]
        holder.AnchorPoint = location.anchor
        holder.Position = location.position
        local layout = holder:FindFirstChildOfClass("UIListLayout")
        if layout then
            layout.VerticalAlignment = location.vertical
            layout.HorizontalAlignment = location.horizontal
        end
    end

    function Notifications:SetPosition(position)
        if not validPosition(position) then return false, "notification_position_invalid" end
        State.notificationPosition = position
        self:ApplyPresentation()
        configurationSave()
        return true
    end

    function Notifications:SetStyle(style)
        if not validStyle(style) then return false, "notification_style_invalid" end
        State.notificationStyle = style
        self:ApplyPresentation()
        configurationSave()
        return true
    end

    function Notifications:GetSnapshot()
        return {
            position = self:GetPosition(), style = self:GetStyle(), queued = #self.State.queue,
            visible = self.State.active, suppressed = self.State.suppressed,
        }
    end

    function Notifications:Attach(gui)
        if not gui then return false, "gui_missing" end
        local state = self.State
        if state.holder and state.holder.Parent == gui then
            state.gui = gui
            self:ApplyPresentation()
            self:Pump()
            return true
        end
        if state.holder then pcall(function() state.holder:Destroy() end) end
        state.gui = gui
        state.holder = Theme.New("Frame", {
            Name = "FlowKanHubNotifications",
            -- Scale width makes cards readable on a phone without exceeding a
            -- comfortable desktop width. Height is only a layout container.
            Size = UDim2.new(0.86, 0, 0, 340),
            BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 900, Parent = gui,
        })
        local constraint = Instance.new("UISizeConstraint")
        constraint.MaxSize = Vector2.new(360, 340)
        constraint.MinSize = Vector2.new(180, 0)
        constraint.Parent = state.holder
        local layout = Instance.new("UIListLayout")
        layout.Padding = UDim.new(0, 6)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Parent = state.holder
        self:ApplyPresentation()
        self:Pump()
        return true
    end

    function Notifications:RefreshCard(card)
        if not card or not card.options then return end
        local count = tonumber(card.options.repeatCount) or 1
        if card.count then
            card.count.Visible = count > 1
            card.count.Text = "×" .. tostring(count)
        end
        if card.message then card.message.Text = tostring(card.options.message or "") end
    end

    function Notifications:ScheduleDismiss(card, seconds)
        if not card or not card.options or interactive(card.options) or seconds <= 0 then return end
        card.expiresAt = now() + seconds
        task.delay(seconds, function()
            if not card or card.closing then return end
            local remaining = (card.expiresAt or 0) - now()
            if remaining > 0.05 then
                self:ScheduleDismiss(card, remaining)
            else
                self:Dismiss(card.options.id, false, nil)
            end
        end)
    end

    function Notifications:Dismiss(id, response, input)
        local card = self.State.cards[id]
        if not card or card.closing then return false end
        card.closing = true
        self.State.cards[id] = nil
        if card.dedupeKey then self.State.recent[card.dedupeKey] = now() end
        local function finalize()
            if card.frame and card.frame.Parent then card.frame:Destroy() end
            self.State.active = math.max(0, self.State.active - 1)
            if card.options and type(card.options.onResult) == "function" then
                pcall(card.options.onResult, response, input)
            end
            self:Pump()
        end
        if card.frame and tweenService then
            local ok, tween = pcall(function()
                return tweenService:Create(card.frame, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
                    BackgroundTransparency = 1,
                    Position = UDim2.new(card.frame.Position.X.Scale, card.frame.Position.X.Offset + 12, card.frame.Position.Y.Scale, card.frame.Position.Y.Offset),
                })
            end)
            if ok and tween then tween:Play(); task.delay(0.17, finalize); return true end
        end
        finalize()
        return true
    end

    function Notifications:BuildCard(options)
        local state = self.State
        local style = styles[self:GetStyle()]
        local isInteractive = interactive(options)
        local cardHeight = isInteractive and (options.mode == "input" and 154 or 122) or style.height
        local cardFrame = Theme.New("Frame", {
            Name = "Notification_" .. tostring(options.id), Size = UDim2.new(1, 0, 0, cardHeight),
            BackgroundColor3 = style.background(), BackgroundTransparency = 1, BorderSizePixel = 0,
            ZIndex = 901, LayoutOrder = options.id, Parent = state.holder,
        })
        Theme.Round(cardFrame, 10)
        local stroke = Theme.Stroke(cardFrame, style.stroke(), 1, 0.15)
        local accent = accents[options.kind]()
        local rail = Theme.New("Frame", {Size = UDim2.new(0, 3, 1, -16), Position = UDim2.new(0, 0, 0, 8), BackgroundColor3 = accent, BorderSizePixel = 0, ZIndex = 902, Parent = cardFrame})
        Theme.Round(rail, 2)
        local iconFrame = Theme.New("Frame", {Size = UDim2.new(0, 26, 0, 26), Position = UDim2.new(0, 12, 0, 11), BackgroundColor3 = accent, BorderSizePixel = 0, ZIndex = 902, Parent = cardFrame})
        Theme.Round(iconFrame, 8)
        Theme.New("ImageLabel", {Size = UDim2.new(0, 14, 0, 14), Position = UDim2.new(0.5, -7, 0.5, -7), BackgroundTransparency = 1, Image = options.icon or defaultIcon(options.kind) or "", ImageColor3 = Theme.text, ScaleType = Enum.ScaleType.Fit, ZIndex = 903, Parent = iconFrame})
        local title = Theme.New("TextLabel", {Size = UDim2.new(1, -92, 0, 17), Position = UDim2.new(0, 47, 0, 9), BackgroundTransparency = 1, Text = options.title, TextColor3 = Theme.text, TextSize = 11, Font = Enum.Font.GothamBold, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 902, Parent = cardFrame})
        local message = Theme.New("TextLabel", {Size = UDim2.new(1, -62, 0, isInteractive and 40 or 29), Position = UDim2.new(0, 47, 0, 28), BackgroundTransparency = 1, Text = options.message, TextColor3 = Theme.muted, TextSize = 10, Font = Enum.Font.Gotham, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 902, Parent = cardFrame})
        local count = Theme.New("TextLabel", {Size = UDim2.new(0, 26, 0, 16), Position = UDim2.new(1, -54, 0, 10), BackgroundColor3 = Theme.panel3, BorderSizePixel = 0, Text = "", TextColor3 = Theme.text, TextSize = 9, Font = Enum.Font.GothamBold, TextXAlignment = Enum.TextXAlignment.Center, TextYAlignment = Enum.TextYAlignment.Center, Visible = false, ZIndex = 903, Parent = cardFrame})
        Theme.Round(count, 6)
