            input = Theme.New("TextBox", {Size = UDim2.new(1, -26, 0, 27), Position = UDim2.new(0, 13, 0, 70), BackgroundColor3 = Theme.panel3, BorderSizePixel = 0, Text = tostring(options.default or ""), PlaceholderText = tostring(options.placeholder or ""), ClearTextOnFocus = false, TextColor3 = Theme.text, PlaceholderColor3 = Theme.muted, TextSize = 10, Font = Enum.Font.Gotham, ZIndex = 902, Parent = cardFrame})
            Theme.Round(input, 7); Theme.Stroke(input, Theme.border, 1, 0.2)
