            local confirm = Theme.New("TextButton", {Size = UDim2.new(0.5, -17, 0, 28), Position = UDim2.new(0.5, 4, 0, bottom), BackgroundColor3 = accent, BorderSizePixel = 0, Text = tostring(options.confirmText or tr("continue", "Continue")), TextColor3 = Theme.text, TextSize = 10, Font = Enum.Font.GothamBold, AutoButtonColor = false, ZIndex = 902, Parent = cardFrame})
            Theme.Round(cancel, 7); Theme.Round(confirm, 7)
