            confirm.MouseButton1Click:Connect(function() self:Dismiss(options.id, true, input and input.Text or nil) end)
        end
        closeButton.MouseButton1Click:Connect(function() self:Dismiss(options.id, false, input and input.Text or nil) end)
        cardFrame.BackgroundTransparency = style.transparency
        local showTween
        if tweenService then
            local target = cardFrame.BackgroundTransparency
            cardFrame.BackgroundTransparency = 1
            local ok, tween = pcall(function()
                return tweenService:Create(cardFrame, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundTransparency = target})
            end)
            if ok then showTween = tween end
        end
        if showTween then showTween:Play() end
        local card = {frame = cardFrame, options = options, closing = false, stroke = stroke, message = message, count = count, dedupeKey = options.dedupeKey}
        self:RefreshCard(card)
        return card
    end

    function Notifications:Pump()
        local state = self.State
        if not state.holder or not state.holder.Parent then return end
        while state.active < self.MaxVisible and #state.queue > 0 do
            local options = table.remove(state.queue, 1)
            local card = self:BuildCard(options)
            state.cards[options.id] = card
            state.active = state.active + 1
            local seconds = interactive(options) and (tonumber(options.timeout) or self.DefaultQuestionTimeout) or options.duration
            self:ScheduleDismiss(card, seconds)
        end
    end

    function Notifications:Push(raw)
        local options = self:Normalize(raw)
        local state = self.State
        local key = options.dedupeKey
        if key then
            for _, card in pairs(state.cards) do
                if not card.closing and card.dedupeKey == key then
                    card.options.repeatCount = (card.options.repeatCount or 1) + options.repeatCount
                    card.options.duration = math.max(card.options.duration or 0, options.duration or 0)
                    self:RefreshCard(card)
                    self:ScheduleDismiss(card, card.options.duration)
                    return card.options.id, "notification_merged"
                end
            end
            for _, queued in ipairs(state.queue) do
                if queued.dedupeKey == key then
                    queued.repeatCount = (queued.repeatCount or 1) + options.repeatCount
                    queued.duration = math.max(queued.duration or 0, options.duration or 0)
                    return queued.id, "notification_merged"
                end
            end
            local last = state.recent[key]
            if last and now() - last < self.DuplicateWindow and options.allowRepeat ~= true then
                state.suppressed = state.suppressed + 1
                return false, "notification_deduplicated"
            end
        end
        state.sequence = state.sequence + 1
        options.id = state.sequence
        table.insert(state.queue, options)
        self:Pump()
        return options.id
    end

    function Notifications:Info(title, message, options)
        options = options or {}; options.kind = "info"; options.title = title; options.message = message; return self:Push(options)
    end
    function Notifications:Success(title, message, options)
        options = options or {}; options.kind = "success"; options.title = title; options.message = message; return self:Push(options)
    end
    function Notifications:Warning(title, message, options)
        options = options or {}; options.kind = "warning"; options.title = title; options.message = message; return self:Push(options)
    end
    function Notifications:Error(title, message, options)
        options = options or {}; options.kind = "error"; options.title = title; options.message = message; return self:Push(options)
    end
    function Notifications:Confirm(title, message, callback, options)
        options = options or {}; options.kind = "question"; options.mode = "confirm"; options.title = title; options.message = message; options.onResult = callback; return self:Push(options)
    end
    function Notifications:Input(title, message, callback, options)
        options = options or {}; options.kind = "input"; options.mode = "input"; options.title = title; options.message = message; options.onResult = callback; return self:Push(options)
    end

    function Notifications:Shutdown()
        local state = self.State
        state.queue, state.cards, state.recent, state.active, state.suppressed = {}, {}, {}, 0, 0
        if state.holder then pcall(function() state.holder:Destroy() end) end
        state.holder, state.gui = nil, nil
    end

    Flow.Features.Notifications = Notifications
end)(Flow)
Flow.Performance.modules['features/system_notifications.lua'] = math.floor((os.clock() - __flow_module_started) * 1000 + 0.5) / 1000
end

