        ["ẻ"] = "Ẻ", ["ẽ"] = "Ẽ", ["ẹ"] = "Ẹ", ["ề"] = "Ề", ["ế"] = "Ế", ["ể"] = "Ể", ["ễ"] = "Ễ", ["ệ"] = "Ệ", ["ỉ"] = "Ỉ", ["ĩ"] = "Ĩ", ["ị"] = "Ị", ["ỏ"] = "Ỏ", ["ọ"] = "Ọ", ["ồ"] = "Ồ", ["ố"] = "Ố", ["ổ"] = "Ổ", ["ỗ"] = "Ỗ", ["ộ"] = "Ộ", ["ờ"] = "Ờ", ["ớ"] = "Ớ", ["ở"] = "Ở", ["ỡ"] = "Ỡ", ["ợ"] = "Ợ",
        ["ủ"] = "Ủ", ["ũ"] = "Ũ", ["ụ"] = "Ụ", ["ừ"] = "Ừ", ["ứ"] = "Ứ", ["ử"] = "Ử", ["ữ"] = "Ữ", ["ự"] = "Ự", ["ỳ"] = "Ỳ", ["ỷ"] = "Ỷ", ["ỹ"] = "Ỹ", ["ỵ"] = "Ỵ",
    }
    local acronyms = {"AFK", "ESP", "FOV", "ID", "M1", "MCP", "NPC", "PVP", "RGB", "TP", "UI", "V4"}

    local function lowerUnicode(value)
        local lowered = string.lower(value)
        for upper, lower in pairs(unicodeLower) do lowered = string.gsub(lowered, upper, lower) end
        return lowered
    end

    local function normalizeUppercaseWords(value)
        -- A status can mix an all-caps label with normal prose, e.g.
        -- "BARCO ARMADO · toque em ATIVAR". Normalize each word rather than
        -- only strings that are entirely uppercase. A later acronym pass puts
        -- intentional technical abbreviations back in their proper form.
        return string.gsub(value, "%S+", function(word)
            local lowered = lowerUnicode(word)
            if lowered ~= word and not word:find("[a-z]") then return lowered end
            return word
        end)
    end

    local function titleFirst(value)
        local first = string.sub(value, 1, 1)
        if first:match("%l") then return string.upper(first) .. string.sub(value, 2) end
        for lower, upper in pairs(unicodeUpperFirst) do
            if string.sub(value, 1, #lower) == lower then return upper .. string.sub(value, #lower + 1) end
        end
        return value
    end

    function Language:FormatDisplay(value)
        value = tostring(value or "")
        value = normalizeUppercaseWords(value)
        value = titleFirst(value)
        for _, acronym in ipairs(acronyms) do
            local letters = ""
            for index = 1, #acronym do
                local letter = string.sub(acronym, index, index)
                letters = letters .. "[" .. string.lower(letter) .. string.upper(letter) .. "]"
            end
            value = string.gsub(value, "%f[%w]" .. letters .. "%f[^%w]", acronym)
        end
        return value
    end

    function Language:GetCode()
        local code = Flow.State.language
        return self.Translations[code] and code or "en"
    end

    function Language:T(key, ...)
        local dictionary = self.Translations[self:GetCode()] or self.Translations.en
        local value = self:FormatDisplay(dictionary[key] or self.Translations.en[key] or key)
        if select("#", ...) > 0 then
            local ok, formatted = pcall(string.format, value, ...)
            if ok then return formatted end
        end
        return value
    end

    function Language:Set(code)
        if not self.Translations[code] then return false end
        Flow.State.language = code
        return true
    end

    Flow.Language = Language
end)(Flow)
Flow.Performance.modules['core/language.lua'] = math.floor((os.clock() - __flow_module_started) * 1000 + 0.5) / 1000
end

