            frame(holder, {Size = UDim2.new(0, 3, 0, 23), Position = UDim2.new(0, 0, 0, 1), BackgroundColor3 = Theme.accent}, 2)
            label(holder, {Size = UDim2.new(1, -12, 0, 22), Position = UDim2.new(0, 10, 0, 0), Text = text, TextSize = 15, Font = Enum.Font.GothamBold})
            label(holder, {Size = UDim2.new(1, -12, 0, 16), Position = UDim2.new(0, 10, 0, 25), Text = description or "", TextSize = 9, TextColor3 = Theme.muted, TextTruncate = Enum.TextTruncate.AtEnd})
            return holder
        end
        local function numberRow(parent, rowTitle, description, minimum, maximum, initial, formatter, callback)
            local row = frame(parent, {Size = UDim2.new(1, 0, 0, 76), BackgroundColor3 = Theme.panel2}, 8)
            Theme.Stroke(row, Theme.border, 1, 0)
            frame(row, {Size = UDim2.new(0, 3, 1, -16), Position = UDim2.new(0, 0, 0, 8), BackgroundColor3 = Theme.accent}, 2)
            label(row, {Size = UDim2.new(1, -118, 0, 18), Position = UDim2.new(0, 13, 0, 8), Text = rowTitle, TextSize = 12, Font = Enum.Font.GothamBold})
            label(row, {Size = UDim2.new(1, -28, 0, 16), Position = UDim2.new(0, 13, 0, 28), Text = description, TextSize = 9, TextColor3 = Theme.muted, TextTruncate = Enum.TextTruncate.AtEnd})
            local value = label(row, {Size = UDim2.new(0, 102, 0, 18), Position = UDim2.new(1, -112, 0, 8), Text = "", TextSize = 10, Font = Enum.Font.GothamBold, TextColor3 = Theme.accent2, TextXAlignment = Enum.TextXAlignment.Right})
            local control
            control = Theme.Slider(row, initial, minimum, maximum, function(raw)
                local result = callback and callback(raw) or raw
                if result ~= nil and control then control:Set(result, true) end
                value.Text = formatter(result or raw)
            end)
            control.Frame.Size = UDim2.new(1, -38, 0, 6)
            control.Frame.Position = UDim2.new(0, 17, 1, -15)
            value.Text = formatter(initial)
            return {control = control, value = value, formatter = formatter}
        end
        local function colorRow(parent, settings)
            local row = frame(parent, {Size = UDim2.new(1, 0, 0, 66), BackgroundColor3 = Theme.panel2}, 8)
            Theme.Stroke(row, Theme.border, 1, 0)
            frame(row, {Size = UDim2.new(0, 3, 1, -16), Position = UDim2.new(0, 0, 0, 8), BackgroundColor3 = Theme.accent}, 2)
            label(row, {Size = UDim2.new(0, 160, 0, 18), Position = UDim2.new(0, 13, 0, 8), Text = t("esp_color"), TextSize = 12, Font = Enum.Font.GothamBold})
            label(row, {Size = UDim2.new(0, 180, 0, 15), Position = UDim2.new(0, 13, 0, 29), Text = t("esp_color_desc"), TextSize = 9, TextColor3 = Theme.muted, TextTruncate = Enum.TextTruncate.AtEnd})
            local swatch = frame(row, {Size = UDim2.new(0, 22, 0, 22), Position = UDim2.new(1, -34, 0, 9), BackgroundColor3 = Color3.fromRGB(settings.color[1], settings.color[2], settings.color[3])}, 5)
            local boxes = {}
            local labels = {"R", "G", "B"}
            for index, channel in ipairs(labels) do
                label(row, {Size = UDim2.new(0, 10, 0, 14), Position = UDim2.new(0, 208 + ((index - 1) * 72), 0, 35), Text = channel, TextSize = 9, TextColor3 = Theme.muted, Font = Enum.Font.GothamBold, TextXAlignment = Enum.TextXAlignment.Center})
                local box = textBox(row, settings.color[index])
                box.Size = UDim2.new(0, 54, 0, 22)
                box.Position = UDim2.new(0, 221 + ((index - 1) * 72), 0, 31)
                box.TextSize = 9
                boxes[index] = box
                box.FocusLost:Connect(function()
                    local value = tonumber(box.Text)
                    if value then settings.color[index] = math.max(0, math.min(255, math.floor(value))) end
                    box.Text = tostring(settings.color[index])
                    swatch.BackgroundColor3 = Color3.fromRGB(settings.color[1], settings.color[2], settings.color[3])
                    updateVisuals()
                end)
            end
            return {row = row, refresh = function()
                for index, box in ipairs(boxes) do box.Text = tostring(settings.color[index]) end
                swatch.BackgroundColor3 = Color3.fromRGB(settings.color[1], settings.color[2], settings.color[3])
            end}
        end

        sectionHeader(espPage, t("esp"), "")
        local targetsTab = subButton(espPage, t("esp_targets"), 0, 94)
        local styleTab = subButton(espPage, t("esp_style"), 100, 82)
        targetsTab.BackgroundColor3 = Theme.accent
        local status = label(espPage, {Size = UDim2.new(0, 170, 0, 26), Position = UDim2.new(1, -170, 0, 34), Text = "", TextSize = 10, TextColor3 = Theme.muted, TextXAlignment = Enum.TextXAlignment.Right, TextYAlignment = Enum.TextYAlignment.Center})
        local targetsPage = Theme.New("Frame", {Size = UDim2.new(1, 0, 1, -70), Position = UDim2.new(0, 0, 0, 70), BackgroundTransparency = 1, Parent = espPage})
        local stylePage = Theme.New("Frame", {Size = UDim2.new(1, 0, 1, -70), Position = UDim2.new(0, 0, 0, 70), BackgroundTransparency = 1, Visible = false, Parent = espPage})
        local targetsList, styleList = scrolling(targetsPage), scrolling(stylePage)
        local typeControls, styleControls, advancedRows = {}, {}, {}
        local advancedToggle
        local function applyAdvancedVisibility()
            local active = State.espAdvancedMode == true
            styleTab.Visible = active
            for _, row in ipairs(advancedRows) do row.Visible = active end
            if not active then
                targetsPage.Visible, stylePage.Visible = true, false
                targetsTab.BackgroundColor3, styleTab.BackgroundColor3 = Theme.accent, Theme.panel3
            end
        end

        local information = frame(targetsList, {Size = UDim2.new(1, 0, 0, 42), BackgroundColor3 = Theme.panel2}, 8)
        Theme.Stroke(information, Theme.border, 1, 0)
        label(information, {Size = UDim2.new(1, -24, 1, -8), Position = UDim2.new(0, 12, 0, 4), Text = t("esp_local_only"), TextSize = 9, TextColor3 = Theme.muted, TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Center})
        local _, masterToggle = Theme.OptionRow(targetsList, t("esp_master"), t("esp_master_desc"), function(active)
            if Esp and Esp.SetMaster then Esp:SetMaster(active) else State.espMasterEnabled = active end
            updateVisuals()
        end, lucide.target)
        local _, createdAdvancedToggle = Theme.OptionRow(targetsList, t("esp_advanced_mode"), t("esp_advanced_mode_desc"), function(active)
            State.espAdvancedMode = active
            applyAdvancedVisibility()
            saveSoon()
        end, lucide.settings)
        advancedToggle = createdAdvancedToggle

        local typeOrder = (Esp and Esp.TypeOrder) or {"fruit", "islands", "players", "boats", "bosses", "chests", "race_v2", "berries", "haki", "special"}
        for _, typeName in ipairs(typeOrder) do
            local currentType = typeName
            local settings = State.espTypes[currentType]
            title(targetsList, t("esp_type_" .. currentType), "")
            local controls = {settings = settings}
            local typeLabel = t("esp_type_" .. currentType)
            local _, enabled = Theme.OptionRow(targetsList, t("esp_enable_type", typeLabel), t("esp_enable_type_desc", typeLabel), function(active)
                settings.enabled = active
                updateVisuals()
            end, lucide.target)
            controls.enabled = enabled
            controls.color = colorRow(targetsList, settings)
            advancedRows[#advancedRows + 1] = controls.color.row
            local options = {
                {"showName", "esp_show_name", "esp_show_name_desc"}, {"showDistance", "esp_show_distance", "esp_show_distance_desc"},
                {"showHealth", "esp_show_health", "esp_show_health_desc"}, {"highlight", "esp_highlight", "esp_highlight_desc"},
                {"box", "esp_box", "esp_box_desc"}, {"tracer", "esp_tracer", "esp_tracer_desc"},
            }
            controls.options = {}
            for _, option in ipairs(options) do
                local key = option[1]
                local optionRow, toggle = Theme.OptionRow(targetsList, t(option[2]), t(option[3]), function(active)
                    settings[key] = active
                    updateVisuals()
                end, key == "highlight" and lucide.accent or (key == "tracer" and lucide.target or nil))
                controls.options[key] = toggle
                advancedRows[#advancedRows + 1] = optionRow
            end
            typeControls[currentType] = controls
        end

        title(styleList, t("esp_style"), t("esp_local_only"))
        styleControls.maximum = numberRow(styleList, t("esp_max_distance"), t("esp_max_distance_desc"), 0, 30000, State.espMaxDistance, function(value)
            return value <= 0 and t("esp_unlimited") or (tostring(math.floor(value)) .. " studs")
        end, function(value)
            State.espMaxDistance = math.floor(value); updateVisuals(); return State.espMaxDistance
        end)
        styleControls.textSize = numberRow(styleList, t("esp_text_size"), t("esp_text_size_desc"), 8, 28, State.espTextSize, function(value) return tostring(math.floor(value)) .. " px" end, function(value)
            State.espTextSize = math.floor(value); updateVisuals(); return State.espTextSize
        end)
        local _, outlineToggle = Theme.OptionRow(styleList, t("esp_text_outline"), t("esp_text_outline_desc"), function(active)
            State.espTextOutline = active; updateVisuals()
        end, lucide.accent)
        styleControls.outlineToggle = outlineToggle
        styleControls.fill = numberRow(styleList, t("esp_fill_transparency"), t("esp_fill_transparency_desc"), 0, 100, State.espFillTransparency * 100, function(value) return tostring(math.floor(value)) .. "%" end, function(value)
            State.espFillTransparency = math.floor(value) / 100; updateVisuals(); return State.espFillTransparency * 100
        end)
        styleControls.outline = numberRow(styleList, t("esp_outline_transparency"), t("esp_outline_transparency_desc"), 0, 100, State.espOutlineTransparency * 100, function(value) return tostring(math.floor(value)) .. "%" end, function(value)
            State.espOutlineTransparency = math.floor(value) / 100; updateVisuals(); return State.espOutlineTransparency * 100
        end)
        styleControls.boxThickness = numberRow(styleList, t("esp_box_thickness"), t("esp_box_thickness_desc"), 1, 8, State.espBoxThickness, function(value) return tostring(math.floor(value)) end, function(value)
            State.espBoxThickness = math.floor(value); updateVisuals(); return State.espBoxThickness
        end)
        styleControls.boxTransparency = numberRow(styleList, t("esp_box_transparency"), t("esp_box_transparency_desc"), 0, 100, State.espBoxTransparency * 100, function(value) return tostring(math.floor(value)) .. "%" end, function(value)
            State.espBoxTransparency = math.floor(value) / 100; updateVisuals(); return State.espBoxTransparency * 100
        end)
        styleControls.tracerThickness = numberRow(styleList, t("esp_tracer_thickness"), t("esp_tracer_thickness_desc"), 1, 6, State.espTracerThickness, function(value) return tostring(math.floor(value)) .. " px" end, function(value)
            State.espTracerThickness = math.floor(value); updateVisuals(); return State.espTracerThickness
        end)
        styleControls.tracerTransparency = numberRow(styleList, t("esp_tracer_transparency"), t("esp_tracer_transparency_desc"), 0, 95, State.espTracerTransparency * 100, function(value) return tostring(math.floor(value)) .. "%" end, function(value)
            State.espTracerTransparency = math.floor(value) / 100; updateVisuals(); return State.espTracerTransparency * 100
        end)
        local originRow = frame(styleList, {Size = UDim2.new(1, 0, 0, 56), BackgroundColor3 = Theme.panel2}, 8)
        Theme.Stroke(originRow, Theme.border, 1, 0)
        frame(originRow, {Size = UDim2.new(0, 3, 1, -16), Position = UDim2.new(0, 0, 0, 8), BackgroundColor3 = Theme.accent}, 2)
        label(originRow, {Size = UDim2.new(1, -165, 0, 18), Position = UDim2.new(0, 13, 0, 9), Text = t("esp_tracer_origin"), TextSize = 12, Font = Enum.Font.GothamBold})
        label(originRow, {Size = UDim2.new(1, -165, 0, 16), Position = UDim2.new(0, 13, 0, 30), Text = t("esp_tracer_origin_desc"), TextSize = 9, TextColor3 = Theme.muted, TextTruncate = Enum.TextTruncate.AtEnd})
        local originButton = button(originRow, "", Theme.panel3, 7)
        originButton.Size = UDim2.new(0, 128, 0, 26)
        originButton.Position = UDim2.new(1, -140, 0.5, -13)
        originButton.MouseButton1Click:Connect(function()
            State.espTracerOrigin = State.espTracerOrigin == "bottom" and "center" or "bottom"
            updateVisuals()
        end)
        styleControls.originButton = originButton
        styleControls.interval = numberRow(styleList, t("esp_refresh_rate"), t("esp_refresh_rate_desc"), 20, 300, State.espRefreshInterval * 100, function(value) return string.format("%.2fs", value / 100) end, function(value)
            State.espRefreshInterval = math.floor(value) / 100; updateVisuals(); return State.espRefreshInterval * 100
        end)

        local function refresh()
            masterToggle:Set(State.espMasterEnabled == true, true)
            advancedToggle:Set(State.espAdvancedMode == true, true)
            applyAdvancedVisibility()
            for _, controls in pairs(typeControls) do
                local settings = controls.settings
                controls.enabled:Set(settings.enabled == true, true)
                controls.color.refresh()
                for key, control in pairs(controls.options) do control:Set(settings[key] == true, true) end
            end
            styleControls.maximum.control:Set(State.espMaxDistance, true); styleControls.maximum.value.Text = styleControls.maximum.formatter(State.espMaxDistance)
            styleControls.textSize.control:Set(State.espTextSize, true); styleControls.textSize.value.Text = styleControls.textSize.formatter(State.espTextSize)
            styleControls.outlineToggle:Set(State.espTextOutline ~= false, true)
            for _, spec in ipairs({
                {styleControls.fill, State.espFillTransparency * 100}, {styleControls.outline, State.espOutlineTransparency * 100},
                {styleControls.boxThickness, State.espBoxThickness}, {styleControls.boxTransparency, State.espBoxTransparency * 100},
                {styleControls.tracerThickness, State.espTracerThickness}, {styleControls.tracerTransparency, State.espTracerTransparency * 100},
                {styleControls.interval, State.espRefreshInterval * 100},
            }) do spec[1].control:Set(spec[2], true); spec[1].value.Text = spec[1].formatter(spec[2]) end
            originButton.Text = State.espTracerOrigin == "center" and t("esp_origin_center") or t("esp_origin_bottom")
            local snapshot = Esp and Esp.GetSnapshot and Esp:GetSnapshot() or {counts = {}}
            local count = 0
            for _, value in pairs(snapshot.counts or {}) do count = count + (tonumber(value) or 0) end
            status.Text = t("esp_active_targets", count)
        end
        local function setTab(name)
            if name == "style" and State.espAdvancedMode ~= true then name = "targets" end
            local targets = name == "targets"
            targetsPage.Visible, stylePage.Visible = targets, not targets
            targetsTab.BackgroundColor3 = targets and Theme.accent or Theme.panel3
            styleTab.BackgroundColor3 = targets and Theme.panel3 or Theme.accent
            refresh()
        end
        Flow:Track(targetsTab.MouseButton1Click:Connect(function() setTab("targets") end))
        Flow:Track(styleTab.MouseButton1Click:Connect(function() setTab("style") end))
        task.spawn(function()
            while gui and gui.Parent do
                task.wait(0.40)
                if espPage.Visible then refresh() end
            end
        end)
        refresh()
        return {refresh = refresh}
    end

    local function buildEventFarmPage(eventFarmPage, gui, lucide, t, setStatus, subButton, sectionHeader)
        local EventFarm = Flow.Features.EventFarm
        sectionHeader(eventFarmPage, t("event_farm_title"), "")
        local list = Theme.New("ScrollingFrame", {
            Size = UDim2.new(1, 0, 1, -34), Position = UDim2.new(0, 0, 0, 34),
            BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 4,
            ScrollBarImageColor3 = Theme.accent, AutomaticCanvasSize = Enum.AutomaticSize.Y,
            CanvasSize = UDim2.new(), Parent = eventFarmPage,
        })
        local layout = Instance.new("UIListLayout")
        layout.Padding = UDim.new(0, 7)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Parent = list
        local padding = Instance.new("UIPadding")
        padding.PaddingRight = UDim.new(0, 5)
        padding.PaddingBottom = UDim.new(0, 8)
        padding.Parent = list

        local function selectionRow(title, iconAssetPath)
            local row = frame(list, {Size = UDim2.new(1, 0, 0, 62), BackgroundColor3 = Theme.panel2}, 8)
            Theme.Stroke(row, Theme.border, 1, 0)
            frame(row, {Size = UDim2.new(0, 3, 1, -16), Position = UDim2.new(0, 0, 0, 8), BackgroundColor3 = Theme.accent}, 2)
            if iconAssetPath and iconAssetPath ~= "" then
                Theme.New("ImageLabel", {Size = UDim2.new(0, 15, 0, 15), Position = UDim2.new(0, 12, 0, 10), BackgroundTransparency = 1, Image = iconAssetPath, ImageColor3 = Theme.accent2, ScaleType = Enum.ScaleType.Fit, Parent = row})
            end
            label(row, {Size = UDim2.new(1, -44, 0, 17), Position = UDim2.new(0, iconAssetPath and 34 or 12, 0, 7), Text = title, TextSize = 11, Font = Enum.Font.GothamBold})
            -- The current value is the control itself. Clicking this compact
            -- field opens a small tray immediately below this selection; there
            -- is no modal and no separate generic "CHANGE" button.
            local field = button(row, t("event_farm_no_selection"), Theme.panel3, 6, "")
            field.Size = UDim2.new(1, -24, 0, 25)
            field.Position = UDim2.new(0, 12, 0, 30)
            field.TextSize = 9
            field.TextXAlignment = Enum.TextXAlignment.Left
            return field
        end

        local function selectionTray()
            local tray = frame(list, {Size = UDim2.new(1, 0, 0, 0), BackgroundColor3 = Theme.panel3, Visible = false}, 8)
            Theme.Stroke(tray, Theme.border, 1, 0)
            local title = label(tray, {Size = UDim2.new(1, -22, 0, 21), Position = UDim2.new(0, 11, 0, 6), Text = "", TextSize = 9, Font = Enum.Font.GothamBold, TextColor3 = Theme.accent2})
            local scroll = Theme.New("ScrollingFrame", {Size = UDim2.new(1, -14, 1, -34), Position = UDim2.new(0, 7, 0, 28), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3, ScrollBarImageColor3 = Theme.accent, AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(), Parent = tray})
            local trayLayout = Instance.new("UIListLayout")
            trayLayout.Padding = UDim.new(0, 4)
            trayLayout.Parent = scroll
            return {frame = tray, title = title, scroll = scroll}
        end

        local statusRow = frame(list, {Size = UDim2.new(1, 0, 0, 38), BackgroundColor3 = Theme.panel2}, 8)
        Theme.Stroke(statusRow, Theme.border, 1, 0)
        label(statusRow, {Size = UDim2.new(0, 92, 1, 0), Position = UDim2.new(0, 12, 0, 0), Text = t("event_farm_status"), TextSize = 10, Font = Enum.Font.GothamBold})
        local statusValue = label(statusRow, {Size = UDim2.new(1, -116, 1, 0), Position = UDim2.new(0, 104, 0, 0), Text = t("idle"), TextSize = 9, TextColor3 = Theme.muted, TextXAlignment = Enum.TextXAlignment.Right, TextTruncate = Enum.TextTruncate.AtEnd})

        local _, autoToggle = Theme.OptionRow(list, t("auto_farm_events"), t("auto_farm_events_desc"), function(active)
            if not EventFarm then return end
            local ok, reason = EventFarm:SetEnabled(active)
            if not ok then
                autoToggle:Set(false, true)
                setStatus(t("fail") .. ": " .. tostring(reason), Theme.danger)
            else
                setStatus(active and t("active") or t("idle"), active and Theme.success or Theme.muted)
            end
        end, lucide.maritime or lucide.mobs)

        local boatField = selectionRow(t("event_farm_boat"), lucide.maritime)
        local boatTray = selectionTray()
        local mobField = selectionRow(t("event_farm_targets"), lucide.target)
        local mobTray = selectionTray()
        local _, vortexToggle = Theme.OptionRow(list, t("event_farm_vortex"), t("event_farm_vortex_desc"), function(active)
            if EventFarm then EventFarm:SetVortexEvade(active) end
        end, lucide.accent or lucide.activity)
        local _, moveBoatToggle = Theme.OptionRow(list, t("event_farm_move_boat"), t("event_farm_move_boat_desc"), function(active)
            if EventFarm then EventFarm:SetMoveBoatAway(active) end
        end, lucide.maritime or lucide.speed)
        local _, seaBeastBeamToggle = Theme.OptionRow(list, t("event_farm_sea_beast_beam"), t("event_farm_sea_beast_beam_desc"), function(active)
            if EventFarm then EventFarm:SetSeaBeastBeamDodge(active) end
        end, lucide.radar or lucide.activity)
        local _, seaBeastObservationToggle = Theme.OptionRow(list, t("event_farm_sea_beast_observation"), t("event_farm_sea_beast_observation_desc"), function(active)
            if EventFarm then EventFarm:SetSeaBeastObservationDodge(active) end
        end, lucide.eye or lucide.radar or lucide.activity)
        local activeTray = nil
        local function hideTray(tray)
            tray.frame.Visible = false
            tray.frame.Size = UDim2.new(1, 0, 0, 0)
        end
        local function clearChoices(tray)
            for _, child in ipairs(tray.scroll:GetChildren()) do
                if child:IsA("GuiObject") then child:Destroy() end
            end
        end
        local function showChoices(kind, tray, refreshOnly)
            if not refreshOnly and activeTray == tray and tray.frame.Visible then
                hideTray(tray)
                activeTray = nil
                return
            end
            if activeTray and activeTray ~= tray then hideTray(activeTray) end
            activeTray = tray
            clearChoices(tray)
            local entries = kind == "boat" and (EventFarm and EventFarm:GetBoats() or {}) or (EventFarm and EventFarm:GetSupportedEvents() or {})
            tray.title.Text = kind == "boat" and t("event_farm_choose_boat") or t("event_farm_choose_targets")
            if #entries == 0 then
                label(tray.scroll, {Size = UDim2.new(1, -4, 0, 28), Text = kind == "boat" and t("event_farm_no_boats") or t("event_farm_no_selection"), TextSize = 9, TextColor3 = Theme.muted, TextWrapped = true})
            else
                for _, item in ipairs(entries) do
                    local primary = kind == "boat" and item.display or item.name
                    local identifier = kind == "boat" and item.name or item.id
                    local extra = ""
                    if kind == "boat" then
                        if item.cost then extra = " · $" .. tostring(item.cost) end
                        if item.display ~= item.name then extra = extra .. " · " .. item.name end
                    end
                    local selected = kind ~= "boat" and EventFarm and EventFarm:IsTargetSelected(identifier) == true
                    local prefix = kind == "boat" and "" or (selected and "✓ " or "○ ")
                    local entry = button(tray.scroll, prefix .. primary .. extra, Theme.panel2, 6, "")
                    entry.Size = UDim2.new(1, -4, 0, 27)
                    entry.TextSize = 9
                    entry.TextXAlignment = Enum.TextXAlignment.Left
                    Flow:Track(entry.MouseButton1Click:Connect(function()
                        local ok, reason
                        if kind == "boat" then
                            ok, reason = EventFarm:SetBoat(identifier)
                        else
                            -- Keep this tray open: each row is an independent
                            -- checked mob, not a replacement for the last one.
                            ok, reason = EventFarm:SetTargetSelected(identifier, not selected)
                        end
                        if ok then
                            setStatus(t("saved"), Theme.success)
                            if kind == "boat" then
                                hideTray(tray)
                                activeTray = nil
                            else
                                showChoices(kind, tray, true)
                            end
                        else
                            setStatus(t("fail") .. ": " .. tostring(reason), Theme.danger)
                        end
                    end))
                end
            end
            tray.frame.Visible = true
            -- The compact tray stays open for multi-selection and scrolls if
            -- future updates add more farmable mobs.
            tray.frame.Size = UDim2.new(1, 0, 0, math.min(150, 36 + (#entries * 31)))
        end
        Flow:Track(boatField.MouseButton1Click:Connect(function() showChoices("boat", boatTray) end))
        Flow:Track(mobField.MouseButton1Click:Connect(function() showChoices("targets", mobTray) end))

        local function refresh()
            if not EventFarm then
                statusValue.Text = t("fail")
                return
            end
            local snapshot = EventFarm:GetSnapshot()
            local boatName = State.eventFarmBoat
            boatField.Text = boatName ~= "" and boatName or t("event_farm_no_selection")
            local selectedNames = {}
            local terrorSelected = EventFarm:IsTargetSelected("terror_shark")
            local seaBeastSelected = EventFarm:IsTargetSelected("sea_beast")
            -- Target rows are data-driven so the checked raid boats appear in
            -- this compact field without a second manual control.
            for _, definition in ipairs(EventFarm:GetSupportedEvents()) do
                if definition.selected then
                    local label = definition.id == "terror_shark" and t("terror_shark")
                        or definition.id == "sea_beast" and t("sea_beast") or definition.name
                    table.insert(selectedNames, label)
                end
            end
            mobField.Text = #selectedNames > 0 and table.concat(selectedNames, " + ") or t("event_farm_no_selection")
            -- Both groups remain visible when multiple mobs are checked. Their
            -- runtime is still serialized by EventFarm's one-target lock.
            vortexToggle.Frame.Parent.Visible = terrorSelected
            moveBoatToggle.Frame.Parent.Visible = terrorSelected
            seaBeastBeamToggle.Frame.Parent.Visible = seaBeastSelected
            seaBeastObservationToggle.Frame.Parent.Visible = seaBeastSelected
            autoToggle:Set(snapshot.enabled, true)
            vortexToggle:Set(State.eventFarmVortexEvade == true, true)
            moveBoatToggle:Set(State.eventFarmMoveBoatAway == true, true)
            seaBeastBeamToggle:Set(State.eventFarmSeaBeastBeamDodge == true or State.eventFarmSeaBeastAnimationDodge == true, true)
            seaBeastObservationToggle:Set(State.eventFarmSeaBeastObservationDodge == true, true)
            local phase = tostring(snapshot.phase or "idle")
            if snapshot.enabled then
                local altitude = tonumber(snapshot.lift) or 0
                statusValue.Text = phase .. " · +" .. string.format("%.0f", altitude)
                statusValue.TextColor3 = Theme.success
            else
                statusValue.Text = phase == "idle" and t("idle") or phase
                statusValue.TextColor3 = Theme.muted
            end
        end
        task.spawn(function()
            while gui and gui.Parent do
                task.wait(0.35)
                if eventFarmPage.Visible then refresh() end
            end
        end)
        refresh()
        return {refresh = refresh}
    end

    -- Sea Events > Islands deliberately exposes no second boat selector. The
    -- Frozen Dimension worker reads the exact Event Farm selection, so a player
    -- cannot accidentally configure a different hull for the same Tiki exit.
    local function buildSeaIslandsPage(islandsPage, gui, lucide, t, setStatus, subButton, sectionHeader)
        local EventFarm = Flow.Features.EventFarm
        sectionHeader(islandsPage, t("sea_islands"), "")
        local list = Theme.New("ScrollingFrame", {
            Size = UDim2.new(1, 0, 1, -34), Position = UDim2.new(0, 0, 0, 34),
            BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 4,
            ScrollBarImageColor3 = Theme.accent, AutomaticCanvasSize = Enum.AutomaticSize.Y,
            CanvasSize = UDim2.new(), Parent = islandsPage,
        })
        local layout = Instance.new("UIListLayout")
        layout.Padding = UDim.new(0, 7)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Parent = list
        local padding = Instance.new("UIPadding")
        padding.PaddingRight = UDim.new(0, 5)
        padding.PaddingBottom = UDim.new(0, 8)
        padding.Parent = list

        local info = frame(list, {Size = UDim2.new(1, 0, 0, 72), BackgroundColor3 = Theme.panel2}, 8)
        Theme.Stroke(info, Theme.border, 1, 0)
        frame(info, {Size = UDim2.new(0, 3, 1, -16), Position = UDim2.new(0, 0, 0, 8), BackgroundColor3 = Theme.accent}, 2)
        label(info, {Size = UDim2.new(1, -24, 0, 18), Position = UDim2.new(0, 12, 0, 8), Text = t("frozen_dimension"), TextSize = 12, Font = Enum.Font.GothamBold})
        label(info, {Size = UDim2.new(1, -24, 0, 35), Position = UDim2.new(0, 12, 0, 29), Text = t("frozen_dimension_desc"), TextSize = 9, TextColor3 = Theme.muted, TextWrapped = true})

        local boatRow = frame(list, {Size = UDim2.new(1, 0, 0, 42), BackgroundColor3 = Theme.panel2}, 8)
        Theme.Stroke(boatRow, Theme.border, 1, 0)
        label(boatRow, {Size = UDim2.new(0, 130, 1, 0), Position = UDim2.new(0, 12, 0, 0), Text = t("frozen_dimension_boat"), TextSize = 10, Font = Enum.Font.GothamBold})
        local boatValue = label(boatRow, {Size = UDim2.new(1, -154, 1, 0), Position = UDim2.new(0, 142, 0, 0), Text = "", TextSize = 9, TextColor3 = Theme.accent2, TextXAlignment = Enum.TextXAlignment.Right, TextTruncate = Enum.TextTruncate.AtEnd})

        local statusRow = frame(list, {Size = UDim2.new(1, 0, 0, 42), BackgroundColor3 = Theme.panel2}, 8)
        Theme.Stroke(statusRow, Theme.border, 1, 0)
        label(statusRow, {Size = UDim2.new(0, 108, 1, 0), Position = UDim2.new(0, 12, 0, 0), Text = t("frozen_dimension_status"), TextSize = 10, Font = Enum.Font.GothamBold})
        local statusValue = label(statusRow, {Size = UDim2.new(1, -134, 1, 0), Position = UDim2.new(0, 122, 0, 0), Text = t("idle"), TextSize = 9, TextColor3 = Theme.muted, TextXAlignment = Enum.TextXAlignment.Right, TextTruncate = Enum.TextTruncate.AtEnd})

        local _, searchToggle = Theme.OptionRow(list, t("frozen_dimension_search"), t("frozen_dimension_search_desc"), function(active)
            if not EventFarm or type(EventFarm.SetFrozenDimensionSearch) ~= "function" then
                searchToggle:Set(false, true)
                setStatus(t("fail"), Theme.danger)
                return
            end
            local ok, reason = EventFarm:SetFrozenDimensionSearch(active)
            if not ok then
                searchToggle:Set(false, true)
                setStatus(t("fail") .. ": " .. tostring(reason), Theme.danger)
            else
                setStatus(active and t("active") or t("idle"), active and Theme.success or Theme.muted)
            end
        end, lucide.maritime or lucide.map)

        local function refresh()
            local boatName = State.eventFarmBoat
            boatValue.Text = boatName ~= "" and boatName or t("frozen_dimension_boat_missing")
            if not EventFarm then
                searchToggle:Set(false, true)
                statusValue.Text = t("fail")
                statusValue.TextColor3 = Theme.danger
                return
            end
            local snapshot = EventFarm:GetSnapshot()
            local searching = snapshot.mode == "frozen_dimension_search" and snapshot.frozenDimensionSearchEnabled == true
            searchToggle:Set(searching, true)
            if searching then
                local phase = tostring(snapshot.phase or "searching_frozen_dimension")
                local target = snapshot.frozenDimension
                if target and target.distance then
                    statusValue.Text = phase .. " · " .. string.format("%.0f", target.distance) .. " studs"
                else
                    statusValue.Text = phase
                end
                statusValue.TextColor3 = Theme.success
            else
                statusValue.Text = snapshot.phase == "idle" and t("idle") or tostring(snapshot.phase)
                statusValue.TextColor3 = Theme.muted
            end
        end
        task.spawn(function()
            while gui and gui.Parent do
                task.wait(0.35)
                if islandsPage.Visible then refresh() end
            end
        end)
        refresh()
        return {refresh = refresh}
    end

    -- Missions live in their own category for clarity, but they use the same
    -- persisted Farm master and coordinator as Farm Level. The page contains
    -- one General subcategory with every supported mission; it never starts
    -- independent loops or creates a second resume toggle.
    local function buildMissionsPage(missionsPage, gui, lucide, t, setStatus, subButton, sectionHeader)
        sectionHeader(missionsPage, t("missions"), "")
        local generalTab = subButton(missionsPage, t("mission_general"), 0, 92)
        generalTab.BackgroundColor3 = Theme.accent
        local generalPage = Theme.New("ScrollingFrame", {
            Size = UDim2.new(1, 0, 1, -70), Position = UDim2.new(0, 0, 0, 70),
            BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 4,
            ScrollBarImageColor3 = Theme.accent, AutomaticCanvasSize = Enum.AutomaticSize.Y,
            CanvasSize = UDim2.new(), Parent = missionsPage,
        })
        local layout = Instance.new("UIListLayout")
        layout.Padding = UDim.new(0, 7)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Parent = generalPage
        local padding = Instance.new("UIPadding")
        padding.PaddingRight = UDim.new(0, 5)
        padding.PaddingBottom = UDim.new(0, 8)
        padding.Parent = generalPage

        local function detailsRow(title, icon, rowName, valueName)
            local row = frame(generalPage, {Size = UDim2.new(1, 0, 0, 56), BackgroundColor3 = Theme.panel2}, 8)
            if rowName then row.Name = rowName end
            Theme.Stroke(row, Theme.border, 1, 0)
            Theme.New("ImageLabel", {
                Size = UDim2.new(0, 16, 0, 16), Position = UDim2.new(0, 14, 0, 10), BackgroundTransparency = 1,
                Image = icon or "", ImageColor3 = Theme.accent2, ScaleType = Enum.ScaleType.Fit,
                Visible = icon and icon ~= "", Parent = row,
            })
            label(row, {Size = UDim2.new(1, -42, 0, 17), Position = UDim2.new(0, 37, 0, 8), Text = title, TextSize = 12, Font = Enum.Font.GothamBold})
            local value = label(row, {Size = UDim2.new(1, -24, 0, 18), Position = UDim2.new(0, 12, 0, 29), Text = t("mission_status_idle"), TextSize = 9, TextColor3 = Theme.muted, TextTruncate = Enum.TextTruncate.AtEnd})
            -- Stable names so the offline suite (and a player reading the console)
            -- can point at exactly the line that looks wrong.
            if valueName then value.Name = valueName end
            return value
        end

        local function reasonText(snapshot)
            local eligibility = snapshot and snapshot.eligibility or {}
            local reason = tostring((eligibility and eligibility.reason) or (snapshot and snapshot.detail) or "")
            if string.sub(reason, 1, 12) == "level_below_" then
                return "Lv. " .. tostring(eligibility.minimumLevel or "?") .. " required"
            end
            if reason == "" then
                local status = tostring(eligibility and eligibility.status or "idle")
                return t("mission_status_" .. status)
            end
            -- A few reasons carry a colon and the live detail they are about, for
            -- example "npc_not_replicated:Ice Admiral". Translate the code and keep
            -- the detail instead of printing a raw key in the panel.
            local colon = string.find(reason, ":", 1, true)
            local code = colon and string.sub(reason, 1, colon - 1) or reason
            local key = "mission_reason_" .. code
            local text = t(key)
            if text == key then text = (string.gsub(code, "_", " ")) end
            if colon then
                local note = string.sub(reason, colon + 1)
                if note ~= "" then text = text .. ": " .. note end
            end
            return text
        end

        local masterRow, masterToggle
        masterRow, masterToggle = Theme.OptionRow(generalPage, t("mission_start"), t("mission_mode_active"), function(active)
            if not SpecialQuests then
                masterToggle:Set(false, true)
                if setStatus then setStatus(t("mission_reason_evidence_unavailable"), Theme.danger) end
                return
            end
            local ok, reason
            if active then
                -- Switching from Level is serialized: disarm the prior owner
                -- before the shared Farm master is routed to the Mission owner.
                if State.farmLevelEnabled and State.farmAutomationMode ~= "missions" and Farm then
                    Farm:SetEnabled(false)
                end
                State.farmAutomationMode = "missions"
                if Farm and Farm.SetEnabled then
                    ok, reason = Farm:SetEnabled(true)
                else
                    ok, reason = SpecialQuests:SetEnabled(true, "mission_ui_enabled")
                end
            else
                -- A stop click only ever disarms this mode. Turning the mission
                -- off must never touch a level-farm intent that was already on.
                ok, reason = SpecialQuests:SetEnabled(false, "mission_ui_disabled")
            end
            masterToggle:Set(ok and active or false, true)
            if setStatus then
                local snapshot = SpecialQuests:GetSnapshot()
                setStatus(ok and t("mission_status_ready") or reasonText(snapshot), ok and Theme.success or Theme.danger)
            end
        end, lucide.target or lucide.mobs)
        -- Stable names keep the page debuggable in-game and let the offline UI
        -- suite fire the same handlers a player's click would.
        masterRow.Name = "FlowMissionMaster"

        local selectedValue = detailsRow(t("mission_select"), lucide.target or lucide.mobs)
        local requirementsValue = detailsRow(t("mission_requirements"), lucide.check or lucide.status)
        local stateValue = detailsRow(t("mission_state"), lucide.refresh)
        local progressValue = detailsRow(t("mission_progress"), lucide.eye or lucide.refresh, "FlowMissionProgressRow", "FlowMissionProgress")
        local actionsValue = detailsRow(t("mission_actions"), lucide.status or lucide.refresh, "FlowMissionActionsRow", "FlowMissionActions")
        local checkpointValue = detailsRow(t("mission_checkpoint"), lucide.save or lucide.settings)

        local missionHeader = label(generalPage, {Size = UDim2.new(1, 0, 0, 24), Text = t("mission_general"), TextSize = 14, Font = Enum.Font.GothamBold})
        missionHeader.Name = "MissionFunctionsHeader"
        -- The selection rows below must redraw the page, so the local is declared
        -- before their handlers are compiled rather than captured as a global.
        local refresh
        local missionButtons = {}
        local jobOrder = {"access_second_sea", "access_third_sea", "bartilo", "citizen", "elite_hunter"}
        for index, jobId in ipairs(jobOrder) do
            local row = frame(generalPage, {Size = UDim2.new(1, 0, 0, 58), BackgroundColor3 = Theme.panel2}, 8)
            Theme.Stroke(row, Theme.border, 1, 0)
            frame(row, {Size = UDim2.new(0, 3, 1, -16), Position = UDim2.new(0, 0, 0, 8), BackgroundColor3 = Theme.accent}, 2)
            label(row, {Size = UDim2.new(1, -142, 0, 18), Position = UDim2.new(0, 14, 0, 8), Text = t("mission_" .. jobId), TextSize = 12, Font = Enum.Font.GothamBold})
            local description = label(row, {Size = UDim2.new(1, -142, 0, 17), Position = UDim2.new(0, 14, 0, 30), Text = "", TextSize = 9, TextColor3 = Theme.muted, TextTruncate = Enum.TextTruncate.AtEnd})
            local selectButton = button(row, t("select"), Theme.panel3, 7, lucide.check)
            selectButton.Name = "FlowMissionSelect_" .. jobId
            selectButton.Size = UDim2.new(0, 110, 0, 27)
            selectButton.Position = UDim2.new(1, -122, 0.5, -13)
            selectButton.TextSize = 9
            missionButtons[jobId] = {row = row, button = selectButton, description = description, index = index}
            Flow:Track(selectButton.MouseButton1Click:Connect(function()
                if not SpecialQuests then return end
                -- Choosing a chain is a profile change, not a second switch: the
                -- owner that currently holds movement is disarmed first so the
                -- Level worker and the mission can never both be armed.
                if State.farmLevelEnabled then
                    if State.farmAutomationMode == "missions" then
                        SpecialQuests:SetEnabled(false, "mission_changed")
                    elseif Farm and Farm.SetEnabled then
                        Farm:SetEnabled(false)
                    end
                end
                local ok, result = SpecialQuests:SetSelectedJob(jobId)
                refresh()
                if setStatus then setStatus(ok and t("mission_reason_mission_selected") or tostring(result), ok and Theme.success or Theme.danger) end
            end))
        end

        local checkpointRow = frame(generalPage, {Size = UDim2.new(1, 0, 0, 53), BackgroundColor3 = Theme.panel2}, 8)
        Theme.Stroke(checkpointRow, Theme.border, 1, 0)
        label(checkpointRow, {Size = UDim2.new(1, -140, 0, 18), Position = UDim2.new(0, 14, 0, 8), Text = t("mission_clear_checkpoint"), TextSize = 12, Font = Enum.Font.GothamBold})
        label(checkpointRow, {Size = UDim2.new(1, -140, 0, 16), Position = UDim2.new(0, 14, 0, 29), Text = t("mission_capability_pending"), TextSize = 8, TextColor3 = Theme.muted, TextTruncate = Enum.TextTruncate.AtEnd})
        local clearButton = button(checkpointRow, t("mission_clear_checkpoint"), Theme.panel3, 7, lucide.close)
        clearButton.Name = "FlowMissionClearCheckpoint"
        clearButton.Size = UDim2.new(0, 120, 0, 27)
        clearButton.Position = UDim2.new(1, -132, 0.5, -13)
        clearButton.TextSize = 8
        Flow:Track(clearButton.MouseButton1Click:Connect(function()
            if SpecialQuests then SpecialQuests:ClearCheckpoint() end
            if setStatus then setStatus(t("mission_reason_checkpoint_cleared"), Theme.success) end
        end))

        local fruitRow = frame(generalPage, {Size = UDim2.new(1, 0, 0, 78), BackgroundColor3 = Theme.panel2}, 8)
        Theme.Stroke(fruitRow, Theme.border, 1, 0)
        fruitRow.Name = "FlowMissionFruitRow"
        label(fruitRow, {Size = UDim2.new(1, -146, 0, 18), Position = UDim2.new(0, 14, 0, 8), Text = t("mission_trevor_policy"), TextSize = 12, Font = Enum.Font.GothamBold})
        local fruitValue = label(fruitRow, {Size = UDim2.new(1, -146, 0, 26), Position = UDim2.new(0, 14, 0, 28), Text = "", TextSize = 8, TextColor3 = Theme.muted, TextWrapped = true})
        fruitValue.Name = "FlowMissionFruitText"
        local fruitConfirm = button(fruitRow, t("mission_confirm_fruit"), Theme.accent, 7, lucide.check)
        fruitConfirm.Name = "FlowMissionConfirmFruit"
        fruitConfirm.Size = UDim2.new(0, 130, 0, 24)
        fruitConfirm.Position = UDim2.new(1, -142, 0, 10)
        fruitConfirm.TextSize = 8
        local fruitPolicy = button(fruitRow, t("mission_fruit_policy_switch"), Theme.panel3, 7, lucide.rotate or lucide.settings)
        fruitPolicy.Name = "FlowMissionFruitPolicy"
        fruitPolicy.Size = UDim2.new(0, 130, 0, 24)
        fruitPolicy.Position = UDim2.new(1, -142, 0, 40)
        fruitPolicy.TextSize = 8
        Flow:Track(fruitConfirm.MouseButton1Click:Connect(function()
            if not SpecialQuests then return end
            local ok, result = SpecialQuests:ConfirmTrevorFruit()
            if setStatus then setStatus(ok and t("mission_status_ready") or reasonText(SpecialQuests:GetSnapshot()), ok and Theme.success or Theme.danger) end
            refresh()
        end))
        Flow:Track(fruitPolicy.MouseButton1Click:Connect(function()
            if not SpecialQuests then return end
            local following = State.farmTrevorFruitPolicy == "allow_list" and "ask" or "allow_list"
            SpecialQuests:SetTrevorFruitPolicy(following)
            if setStatus then setStatus(t("mission_fruit_" .. following), Theme.accent2) end
            refresh()
        end))

        refresh = function()
            if not SpecialQuests then
                masterToggle:Set(false, true)
                selectedValue.Text = t("mission_reason_evidence_unavailable")
                requirementsValue.Text = t("mission_reason_evidence_unavailable")
                stateValue.Text = t("mission_reason_evidence_unavailable")
                progressValue.Text = t("mission_reason_evidence_unavailable")
                actionsValue.Text = t("mission_status_idle")
                checkpointValue.Text = t("mission_status_idle")
                fruitRow.Visible = false
                return
            end
            local snapshot = SpecialQuests:GetSnapshot()
            local eligibility = snapshot.eligibility or {}
            masterToggle:Set(snapshot.enabled == true, true)
            selectedValue.Text = t("mission_" .. tostring(snapshot.job))
            requirementsValue.Text = "Sea " .. tostring(eligibility.sea or "?") .. " · Lv. " .. tostring(eligibility.level or 0) .. " / " .. tostring(eligibility.minimumLevel or 0)
            local statePrefix = t("mission_status_" .. tostring(eligibility.status or "idle"))
            local stageIndex = tonumber(snapshot.stageIndex) or 0
            local stageTotal = tonumber(snapshot.stageTotal) or 0
            local stageProgress = stageTotal > 0 and (" " .. stageIndex .. "/" .. stageTotal) or ""
            stateValue.Text = statePrefix .. stageProgress .. " · " .. reasonText(snapshot)
            stateValue.TextColor3 = eligibility.status == "completed" and Theme.success or (eligibility.status == "ready" and Theme.accent2 or Theme.muted)
            checkpointValue.Text = tostring(snapshot.stage or "idle") .. " · " .. tostring(snapshot.blocker or t("mission_status_idle"))
            -- What the server actually reported for this chain. Sorted so a row
            -- does not reshuffle every 0.6 s tick while pairs order varies.
            local observed = {}
            local progress = snapshot.progress
            if type(progress) == "table" then
                if type(progress.label) == "string" and progress.label ~= "" then observed[#observed + 1] = progress.label end
                if type(progress.flags) == "table" then
                    for name, value in pairs(progress.flags) do
                        if value == true then observed[#observed + 1] = tostring(name) end
                    end
                end
                if type(progress.numbers) == "table" then
                    for name, value in pairs(progress.numbers) do
                        observed[#observed + 1] = tostring(name) .. "=" .. tostring(value)
                    end
                end
                if progress.known ~= true and type(progress.reason) == "string" and #observed == 0 then
                    observed[#observed + 1] = reasonText({detail = progress.reason, eligibility = snapshot.eligibility})
                end
            elseif progress ~= nil then
                observed[#observed + 1] = tostring(progress)
            end
            table.sort(observed)
            progressValue.Text = #observed > 0 and table.concat(observed, " · ") or t("mission_status_idle")
            actionsValue.Text = t("mission_actions_attempt") .. " " .. tostring(snapshot.attempt or 0)
                .. " · " .. t("mission_actions_transitions") .. " " .. tostring(snapshot.transitions or 0) .. "/" .. tostring(snapshot.maxTransitions or 0)
                .. " · " .. t("mission_actions_calls") .. " " .. tostring(snapshot.issuedCalls or 0)
                .. " · " .. t("mission_actions_refused") .. " " .. tostring(snapshot.callIssues or 0) .. "/" .. tostring(snapshot.maxCallIssues or 0)
            fruitRow.Visible = snapshot.job == "access_third_sea"
            local policy = State.farmTrevorFruitPolicy == "allow_list" and "allow_list" or "ask"
            fruitValue.Text = t("mission_fruit_" .. policy) .. " · " .. t("mission_confirm_fruit_desc")
            for jobId, controls in pairs(missionButtons) do
                local job = SpecialQuests.Jobs[jobId]
                local selected = jobId == snapshot.job
                controls.button.Text = "    " .. (selected and t("selected") or t("select"))
                controls.button.BackgroundColor3 = selected and Theme.accent or Theme.panel3
                controls.row.BackgroundColor3 = selected and Theme.panel3 or Theme.panel2
                controls.description.Text = "Sea " .. tostring(job.requiredSea) .. " · Lv. " .. tostring(job.minimumLevel) .. (SpecialQuests:HasCapability(jobId) and " · ready" or " · " .. t("mission_capability_pending"))
            end
        end

        Flow:Track(generalTab.MouseButton1Click:Connect(function()
            generalPage.Visible = true
            generalTab.BackgroundColor3 = Theme.accent
            refresh()
        end))
        task.spawn(function()
            while gui and gui.Parent do
                task.wait(0.6)
                if missionsPage.Visible then refresh() end
            end
        end)
        refresh()
        return {refresh = refresh, toggle = masterToggle}
    end

    local function buildComboSettingsPage(comboPage, gui, lucide, t, setStatus, subButton, sectionHeader)
        sectionHeader(comboPage, t("combo_settings"), "")
        local generalTab = subButton(comboPage, t("combo_general"), 0, 86)
        generalTab.BackgroundColor3 = Theme.accent
        local generalPage = Theme.New("ScrollingFrame", {
            Size = UDim2.new(1, 0, 1, -70), Position = UDim2.new(0, 0, 0, 70),
            BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 4,
            ScrollBarImageColor3 = Theme.accent, AutomaticCanvasSize = Enum.AutomaticSize.Y,
            CanvasSize = UDim2.new(), Parent = comboPage,
        })
        local layout = Instance.new("UIListLayout")
        layout.Padding = UDim.new(0, 7)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Parent = generalPage
        local padding = Instance.new("UIPadding")
        padding.PaddingRight = UDim.new(0, 5)
        padding.PaddingBottom = UDim.new(0, 8)
        padding.Parent = generalPage

        local typeRow = frame(generalPage, {Size = UDim2.new(1, 0, 0, 58), BackgroundColor3 = Theme.panel2}, 8)
        Theme.Stroke(typeRow, Theme.border, 1, 0)
        frame(typeRow, {Size = UDim2.new(0, 3, 1, -16), Position = UDim2.new(0, 0, 0, 8), BackgroundColor3 = Theme.accent}, 2)
        label(typeRow, {Size = UDim2.new(1, -22, 0, 18), Position = UDim2.new(0, 12, 0, 8), Text = t("combo_type") .. " · " .. t("combo_skills_farm"), TextSize = 12, Font = Enum.Font.GothamBold})
        label(typeRow, {Size = UDim2.new(1, -22, 0, 24), Position = UDim2.new(0, 12, 0, 28), Text = t("combo_skills_farm_desc"), TextSize = 9, TextColor3 = Theme.muted, TextWrapped = true})

        local controls = {}
        local function group(title, keys)
            local header = label(generalPage, {Size = UDim2.new(1, 0, 0, 25), Text = title, TextSize = 14, Font = Enum.Font.GothamBold, TextColor3 = Theme.text})
            header.Name = "ComboGroup_" .. title
            for _, row in ipairs(keys) do
                local stateKey, key = row[1], row[2]
                local _, toggle = Theme.OptionRow(generalPage, t("combo_use_skill", key), t("combo_use_skill_desc"), function(active)
                    State[stateKey] = active == true
                    if Flow.Config then Flow.Config:Save() end
                    setStatus(t("saved"), Theme.success)
                end, lucide.swords or lucide.activity)
                controls[stateKey] = toggle
            end
        end

        -- Native Blox Fruits input slots: Gun and Sword expose Z/X; fighting
        -- styles expose Z/X/C; fruit moves expose Z/X/C/V/F. These are config
        -- defaults only and deliberately have no executor/action consumer yet.
        group(t("combo_weapon"), {{"comboSkillWeaponZ", "Z"}, {"comboSkillWeaponX", "X"}})
        group(t("combo_sword"), {{"comboSkillSwordZ", "Z"}, {"comboSkillSwordX", "X"}})
        group(t("combo_fighting_style"), {{"comboSkillFightingZ", "Z"}, {"comboSkillFightingX", "X"}, {"comboSkillFightingC", "C"}})
        group(t("combo_fruit"), {{"comboSkillFruitZ", "Z"}, {"comboSkillFruitX", "X"}, {"comboSkillFruitC", "C"}, {"comboSkillFruitV", "V"}, {"comboSkillFruitF", "F"}})

        local function refresh()
            for stateKey, toggle in pairs(controls) do toggle:Set(State[stateKey] ~= false, true) end
        end
        Flow:Track(generalTab.MouseButton1Click:Connect(function()
            generalPage.Visible = true
            generalTab.BackgroundColor3 = Theme.accent
            refresh()
        end))
        refresh()
        return {refresh = refresh}
    end

    local function buildFarmPage(farmHubPage, gui, lucide, t, setStatus, subButton, sectionHeader)
-- Farm keeps its quest, combat and configuration controls together.
-- Its executor is the local Farm feature; this page never loads a hub,
-- downloads source, or discovers unknown remotes at runtime.
sectionHeader(farmHubPage, t("farm"), "")
