local maxFarmOverlay
local farmLevelRow, farmToggle
farmLevelRow, farmToggle = Theme.OptionRow(farmGeneralList, t("farm_level"), t("farm_level_desc"), function(active)
    -- The Farm page is explicitly the Level executor. Mission automation has
    -- its own category but shares this same persisted master; switching here
    -- first disarms the mission owner so the two cannot run together.
    if active and State.farmAutomationMode == "missions" then
        if SpecialQuests and SpecialQuests.SetEnabled then SpecialQuests:SetEnabled(false, "switched_to_level") end
        State.farmAutomationMode = "level"
        Config:Save()
    end
    if not Farm then
        farmToggle:Set(false, true)
        return
    end
    -- Cap consent always takes precedence over weapon validation. Otherwise a
    -- player at level 2800 with no saved type sees the toggle turn off and
    -- never receives the Cancel / Enable choice.
    if active and Farm:IsAtQuestCap() then
        State.farmCapPromptPending = false
        farmToggle:Set(false, true)
        if maxFarmOverlay then maxFarmOverlay.Visible = true end
        return
    end
    if active and (State.farmWeaponType ~= "Melee" and State.farmWeaponType ~= "Sword") then
        farmToggle:Set(false, true)
        if setStatus then setStatus(t("farm_no_weapon"), Theme.danger) end
        return
    end
    local ok, reason = Farm:SetEnabled(active)
    farmToggle:Set(ok and active or false, true)
    if setStatus then
        setStatus(ok and (active and t("farm_phase_resolving_quest") or t("cancelled")) or t("farm_phase_" .. tostring(reason)), ok and (active and Theme.muted or Theme.success) or Theme.danger)
    end
end, lucide.mobs)

