local function renderFarmWeapons()
    for _, child in ipairs(weaponList:GetChildren()) do
        if child:IsA("TextButton") or child:IsA("TextLabel") then child:Destroy() end
    end
    local choices = {
        {toolType = "Melee", label = t("farm_fighting_style"), description = t("farm_fighting_style_desc"), icon = lucide.mobs},
        {toolType = "Sword", label = t("farm_sword"), description = t("farm_sword_desc"), icon = lucide.swords or lucide.mobs},
    }
    for index, entry in ipairs(choices) do
        local selected = entry.toolType == State.farmWeaponType
        local row = Theme.New("TextButton", {
            Size = UDim2.new(1, 0, 0, 54), BackgroundColor3 = selected and Theme.accent or Theme.panel2,
            BorderSizePixel = 0, Text = "", AutoButtonColor = false, LayoutOrder = index,
            ZIndex = 173, Parent = weaponList,
        })
        Theme.Round(row, 7)
        Theme.New("ImageLabel", {
            Size = UDim2.new(0, 17, 0, 17), Position = UDim2.new(0, 11, 0, 10),
            BackgroundTransparency = 1, Image = entry.icon or "", ImageColor3 = Theme.accent2,
            ScaleType = Enum.ScaleType.Fit, Visible = entry.icon and entry.icon ~= "", ZIndex = 174, Parent = row,
        })
        label(row, {
            Size = UDim2.new(1, -42, 0, 18), Position = UDim2.new(0, 37, 0, 7),
            Text = entry.label, TextSize = 12, Font = Enum.Font.GothamBold, ZIndex = 174,
        })
        label(row, {
            Size = UDim2.new(1, -42, 0, 16), Position = UDim2.new(0, 37, 0, 28),
            Text = entry.description, TextSize = 9, TextColor3 = Theme.muted, ZIndex = 174,
        })
        row.MouseButton1Click:Connect(function()
            if Farm then Farm:SetWeaponType(entry.toolType) end
            weaponOverlay.Visible = false
            if setStatus then setStatus(t("saved"), Theme.success) end
        end)
    end
end
-- The level cap may be detected after the user has changed pages or after
-- delayed Data.Level replication. Its decision cannot depend on the Farm page
-- still being visible: always present the same Cancel / Activate modal globally.
local function showPendingFarmCapPrompt()
    if State.farmCapPromptPending and maxFarmOverlay and not maxFarmOverlay.Visible then
        State.farmCapPromptPending = false
        farmToggle:Set(false, true)
        maxFarmOverlay.Visible = true
        return true
    end
    return false
end

local function refreshFarmUI()
    local snapshot = Farm and Farm:GetSnapshot() or {}
    farmToggle:Set(State.farmAutomationMode ~= "missions" and State.farmLevelEnabled, true)
    showPendingFarmCapPrompt()
    farmAutoAttackToggle:Set(State.farmAutoAttack, true)
    farmBringToggle:Set(State.farmBringMobs, true)
    farmRadiusInput.Text = tostring(State.farmBringRadius)
    farmHeightInput.Text = tostring(State.farmHeight)
    farmWeaponValue.Text = State.farmWeaponType == "Melee" and t("farm_fighting_style") or (State.farmWeaponType == "Sword" and t("farm_sword") or t("farm_no_weapon"))
    farmQuestValue.Text = snapshot.quest or t("idle")
    farmTargetValue.Text = snapshot.target or t("idle")
    local phaseKey = "farm_phase_" .. tostring(snapshot.phase or "idle")
    farmStateValue.Text = t(phaseKey)
    farmStateValue.TextColor3 = snapshot.phase == "combat" and Theme.success or (snapshot.phase == "error" and Theme.danger or Theme.muted)
    farmEfficiencyValue.Text = t("farm_efficiency_value", tonumber(snapshot.attackAccepted) or 0, tonumber(snapshot.attackRejected) or 0, tonumber(snapshot.cooldown) or 0.25)
    farmEfficiencyValue.TextColor3 = (tonumber(snapshot.attackRejected) or 0) > (tonumber(snapshot.attackAccepted) or 0) and Theme.danger or Theme.muted
    refreshFarmMode()
end
chooseFarmWeapon.MouseButton1Click:Connect(function()
