    local function buildRaidPage(raidPage, gui, lucide, t, setStatus)
        local Raid = Flow.Features.Raid
        local list = Theme.New("ScrollingFrame", {
            Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, BorderSizePixel = 0,
            ScrollBarThickness = 4, ScrollBarImageColor3 = Theme.accent,
            AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(), Parent = raidPage,
        })
        local layout = Instance.new("UIListLayout")
        layout.Padding = UDim.new(0, 6)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Parent = list
        local padding = Instance.new("UIPadding")
        padding.PaddingRight = UDim.new(0, 5)
        padding.PaddingBottom = UDim.new(0, 6)
        padding.Parent = list

        local function statusRow(title, icon)
            local row = frame(list, { Size = UDim2.new(1, 0, 0, 50), BackgroundColor3 = Theme.panel2 }, 8)
            Theme.Stroke(row, Theme.border, 1, 0)
            Theme.New("ImageLabel", {
                Size = UDim2.new(0, 15, 0, 15), Position = UDim2.new(0, 12, 0, 10),
                BackgroundTransparency = 1, Image = icon or "", ImageColor3 = Theme.accent2,
                ScaleType = Enum.ScaleType.Fit, Visible = icon and icon ~= "", Parent = row,
            })
            label(row, { Size = UDim2.new(1, -38, 0, 16), Position = UDim2.new(0, 34, 0, 8), Text = title, TextSize = 11, Font = Enum.Font.GothamBold })
            return label(row, { Size = UDim2.new(1, -22, 0, 16), Position = UDim2.new(0, 12, 0, 27), Text = t("idle"), TextSize = 10, TextColor3 = Theme.muted, TextTruncate = Enum.TextTruncate.AtEnd })
        end

        local raidToggle
        local _, toggle = Theme.OptionRow(list, t("auto_raid"), t("auto_raid_desc"), function(active)
            if not Raid then
                if raidToggle then raidToggle:Set(false, true) end
                return
            end
            local ok, reason = Raid:SetEnabled(active)
            if raidToggle then raidToggle:Set(ok and active or false, true) end
            setStatus(ok and (active and t("raid_phase_preflight") or t("idle")) or t("raid_phase_" .. tostring(reason)), ok and (active and Theme.accent2 or Theme.muted) or Theme.danger)
        end, lucide.mobs)
        raidToggle = toggle

        local typeRow = frame(list, { Size = UDim2.new(1, 0, 0, 56), BackgroundColor3 = Theme.panel2, Active = true }, 8)
        Theme.Stroke(typeRow, Theme.border, 1, 0)
        label(typeRow, { Size = UDim2.new(1, -125, 0, 18), Position = UDim2.new(0, 12, 0, 9), Text = t("raid_type"), TextSize = 13, Font = Enum.Font.GothamBold })
        local raidTypeValue = label(typeRow, { Size = UDim2.new(1, -125, 0, 16), Position = UDim2.new(0, 12, 0, 30), Text = "", TextSize = 10, TextColor3 = Theme.muted, TextTruncate = Enum.TextTruncate.AtEnd })
        local selectRaidType = button(typeRow, t("select"), Theme.accent, 7, lucide.inventory)
        selectRaidType.Size = UDim2.new(0, 86, 0, 26)
        selectRaidType.Position = UDim2.new(1, -97, 0.5, -13)

        local repeatRow = frame(list, { Size = UDim2.new(1, 0, 0, 56), BackgroundColor3 = Theme.panel2, Active = true }, 8)
