        local function refreshRaidUI()
            local snapshot = Raid and Raid:GetSnapshot() or {}
            raidToggle:Set(snapshot.running == true, true)
            useFruitToggle:Set(State.raidUseFruitWhenLowMoney == true, true)
            moneyInput.Text = tostring(State.raidMoneyThreshold or 100000)
            raidTypeValue.Text = tostring(State.raidType or "Flame")
            for key, control in pairs(categoryToggles) do control:Set(State.raidFruitCategories and State.raidFruitCategories[key] == true, true) end
            selectedValue.Text = t("raid_selected_count", selectedCount())
            blockedValue.Text = t("raid_blocked_count", blockedCount())
            local goal, progress = tonumber(snapshot.repeatGoal) or 0, tonumber(snapshot.repeatProgress) or 0
            repeatValue.Text = goal > 0 and t("raid_repeat_goal", progress, goal) or t("raid_repeat_infinite", progress)
            local phase = tostring(snapshot.phase or "idle")
            local message
            if snapshot.repeatGoalReached then
                message = t("raid_repeat_goal_done")
            elseif not snapshot.running then
                message = t("raid_status_off")
            elseif phase == "combat" then
                message = t("raid_phase_combat") .. " · " .. t("raid_island_mobs", tostring(snapshot.island or "?"), tonumber(snapshot.mobs) or 0)
            elseif phase == "next_island" then
                message = t("raid_phase_next_island")
            elseif phase == "awaiting_native_raid_teleport" then
                message = t("raid_phase_awaiting_native_raid_teleport")
            else
                message = t("raid_phase_" .. phase)
            end
            local repeatText = goal > 0 and t("raid_repeat_goal", progress, goal) or t("raid_repeat_infinite", progress)
            local chipText = snapshot.chip and t("raid_chip_ready") or t("raid_chip_missing")
            raidStatusValue.Text = message .. "\n" .. repeatText .. " · " .. chipText
            raidStatusValue.TextColor3 = phase == "combat" and Theme.success or ((phase == "error" or phase == "start_unavailable") and Theme.danger or Theme.muted)
        end

        configureRepeat.MouseButton1Click:Connect(function()
            local goal = Raid and Raid:GetRepeatGoal() or 0
            repeatInput.Text = goal > 0 and tostring(goal) or ""
            repeatOverlay.Visible = true
        end)
        closeRepeat.MouseButton1Click:Connect(function() repeatOverlay.Visible = false end)
        infiniteRepeat.MouseButton1Click:Connect(function()
            if Raid then Raid:SetRepeatGoal(0) end
            repeatInput.Text = ""
            refreshRaidUI()
        end)
        saveRepeat.MouseButton1Click:Connect(function()
            local amount = tonumber(repeatInput.Text)
            if not Raid or not amount or amount < 1 then
                setStatus(t("fail"), Theme.danger)
                return
            end
            local ok = Raid:SetRepeatGoal(amount)
            if ok then repeatOverlay.Visible = false; refreshRaidUI(); setStatus(t("saved"), Theme.success) else setStatus(t("fail"), Theme.danger) end
        end)
        resetRepeat.MouseButton1Click:Connect(function()
            if Raid then Raid:ResetRepeatProgress() end
            refreshRaidUI()
            setStatus(t("saved"), Theme.success)
        end)
        selectRaidType.MouseButton1Click:Connect(function()
            renderRaidTypeSelector()
            typeOverlay.Visible = true
        end)
        closeType.MouseButton1Click:Connect(function() typeOverlay.Visible = false end)
        editSelected.MouseButton1Click:Connect(function()
            renderSelectedSelector()
            selectedOverlay.Visible = true
        end)
        closeSelected.MouseButton1Click:Connect(function() selectedOverlay.Visible = false end)
        moneyInput.FocusLost:Connect(function()
            local value = tonumber(moneyInput.Text)
            if value and value >= 100000 and value <= 1000000000 then
                State.raidMoneyThreshold = math.floor(value)
                Config:Save()
                setStatus(t("saved"), Theme.success)
            else
                moneyInput.Text = tostring(State.raidMoneyThreshold or 100000)
                setStatus(t("fail"), Theme.danger)
            end
        end)
        editBlocked.MouseButton1Click:Connect(function() renderBlockedSelector(); overlay.Visible = true end)
        closeBlocked.MouseButton1Click:Connect(function() overlay.Visible = false end)
        task.spawn(function()
            while gui and gui.Parent do
                task.wait(0.25)
                if raidPage.Visible then refreshRaidUI() end
            end
        end)
        refreshRaidUI()
        return { refresh = refreshRaidUI, toggle = raidToggle }
    end

    function UI:Create()
        local uiCreatedAt = os.clock()
        local function markUi(name)
            if Flow.MarkStartupPhase then
                Flow:MarkStartupPhase("ui_" .. tostring(name), string.format("%.0fms", (os.clock() - uiCreatedAt) * 1000))
            end
        end
        local Language = Flow.Language
        local function t(key, ...)
            return Language:T(key, ...)
        end
        local setStatus
        -- Executing before PlayerGui replication previously waited forever and
        -- looked exactly like a frozen script. Give replication a generous,
        -- finite window and return a diagnosable startup reason instead.
        local playerGui = Flow.Player and (Flow.Player:FindFirstChildOfClass("PlayerGui") or Flow.Player:WaitForChild("PlayerGui", 15))
        if not playerGui then return nil, "playergui_timeout" end

        local previous = playerGui:FindFirstChild("FlowKanHubGui")
        if previous then previous:Destroy() end

        local gui = Theme.New("ScreenGui", {
            Name = "FlowKanHubGui",
            ResetOnSpawn = false,
            IgnoreGuiInset = true,
            DisplayOrder = 99999,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
            Parent = playerGui,
        })
        Flow.Runtime.gui = gui
        if Flow.Features and Flow.Features.Notifications and Flow.Features.Notifications.Attach then
            pcall(function() Flow.Features.Notifications:Attach(gui) end)
        end
        local iconAsset = Flow.Assets and Flow.Assets.Icon or ""
        local lucide = Flow.Assets and Flow.Assets.Icons or {}
        local tweenService = Flow.Services.TweenService

        local main = frame(gui, {
            Name = "Main",
            -- The fixed design canvas is scaled as one unit by HubScale below.
            -- Do not multiply this Size directly: that leaves fixed-pixel
            -- children oversized on a smaller mobile frame.
            Size = UDim2.new(0, State.layoutWidth, 0, State.layoutHeight),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(State.hubPosition[1], State.hubPosition[2], State.hubPosition[3], State.hubPosition[4]),
            BackgroundColor3 = Theme.bg,
            Active = true,
        }, 12)
        Theme.Stroke(main, Theme.border, 1, 0)
        local hubScale = Instance.new("UIScale")
        hubScale.Name = "HubScale"
        hubScale.Scale = 1
        hubScale.Parent = main

        local header = frame(main, {
            Name = "Header",
            Size = UDim2.new(1, 0, 0, 52),
            BackgroundColor3 = Theme.panel,
            Active = true,
        }, 12)
        frame(header, {
            Size = UDim2.new(1, 0, 0, 12),
            Position = UDim2.new(0, 0, 1, -12),
            BackgroundColor3 = Theme.panel,
        })
        frame(header, {
            Size = UDim2.new(1, -24, 0, 2),
            Position = UDim2.new(0, 12, 1, -2),
            BackgroundColor3 = Theme.accent,
        }, 1)

        local headerIcon = Theme.New("ImageLabel", {
            Size = UDim2.new(0, 34, 0, 34),
            Position = UDim2.new(0, 10, 0, 8),
            BackgroundTransparency = 1,
            Image = iconAsset,
            ScaleType = Enum.ScaleType.Fit,
            Visible = iconAsset ~= "",
            Parent = header,
        })
        local headerMark = Theme.New("TextLabel", {
            Size = UDim2.new(0, 34, 0, 34),
            Position = UDim2.new(0, 10, 0, 8),
            BackgroundColor3 = Theme.accent,
            BorderSizePixel = 0,
            Text = "FK",
            TextSize = 11,
            TextColor3 = Theme.text,
            Font = Enum.Font.GothamBold,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextYAlignment = Enum.TextYAlignment.Center,
            Visible = iconAsset == "",
            Parent = header,
        })

        label(header, {
            Name = "BrandTitle",
            Size = UDim2.new(0, 240, 0, 20),
            Position = UDim2.new(0, 54, 0, 8),
            Text = "Flow Kan",
            TextSize = 14,
            Font = Enum.Font.GothamBold,
            TextYAlignment = Enum.TextYAlignment.Center,
        })
        label(header, {
            Name = "BrandCaption",
            Size = UDim2.new(0, 240, 0, 14),
            Position = UDim2.new(0, 54, 0, 27),
            Text = t("interface_caption"),
            TextSize = 8,
            TextColor3 = Theme.muted,
            Font = Enum.Font.GothamBold,
            TextYAlignment = Enum.TextYAlignment.Center,
        })

        local versionChip = frame(header, {
            Name = "VersionChip",
            Size = UDim2.new(0, 72, 0, 22),
            Position = UDim2.new(1, -148, 0, 15),
            BackgroundColor3 = Theme.panel3,
        }, 7)
        Theme.Stroke(versionChip, Theme.border, 1, 0)
        label(versionChip, {
            Size = UDim2.new(1, 0, 1, 0),
            Text = "v" .. tostring(Flow.Version),
            TextSize = 8,
            Font = Enum.Font.GothamBold,
            TextColor3 = Theme.muted,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextYAlignment = Enum.TextYAlignment.Center,
