        -- Building every hidden page created thousands of Instances and
        -- connections before the first visible frame. Keep each feature intact,
        -- but construct its controls on first use. Saved Farm intent is handled
        -- below by syncConfig so no active automation is silently skipped.
        local pageBuilders, pageBuildState = {}, {}
        local function ensurePageBuilt(name)
            if pageBuildState[name] == true then return true end
            if pageBuildState[name] == "building" then return false, "building" end
            local builder = pageBuilders[name]
            if not builder then return false, "unknown_page" end
            pageBuildState[name] = "building"
            local startedAt = os.clock()
            local ok, result = pcall(builder)
            pageBuildState[name] = ok and true or false
            if ok then
                if Flow.MarkStartupPhase then
                    Flow:MarkStartupPhase("ui_page_built", tostring(name) .. "|" .. string.format("%.0fms", (os.clock() - startedAt) * 1000))
                end
                return true, result
            end
            if setStatus then setStatus(t("fail"), Theme.danger) end
            Flow:Log("UI page build failed | " .. tostring(name) .. " | " .. tostring(result))
            return false, result
        end

