        local layoutPresets = { small = 0.78, normal = 1.00, large = 1.12 }
        local layoutTween
        local function updateLayout(smooth)
            local configuredWidth = math.max(480, math.min(1000, tonumber(State.layoutWidth) or 620))
            local height = math.max(340, math.min(720, tonumber(State.layoutHeight) or 440))
            local requested = layoutPresets[State.layoutSize] or tonumber(State.layoutScale) or 1
            local camera = Flow.Services.Workspace and Flow.Services.Workspace.CurrentCamera
            local viewport = camera and camera.ViewportSize or Vector2.new(configuredWidth, height)
            -- On narrow phones, scaling a 620 px desktop canvas makes all copy
            -- unreadable. Switch only the chrome to an icon rail and use a
            -- smaller logical canvas, leaving every page/feature intact.
            local narrow = viewport.X < 540
            local width = narrow and math.min(configuredWidth, 400) or configuredWidth
            main.Size = UDim2.new(0, width, 0, height)
            sidebar.Size = narrow and UDim2.new(0, 52, 1, -87) or UDim2.new(0, 150, 1, -87)
            content.Position = narrow and UDim2.new(0, 70, 0, 60) or UDim2.new(0, 172, 0, 60)
            content.Size = narrow and UDim2.new(1, -80, 1, -87) or UDim2.new(1, -182, 1, -87)
            local brandTitle = header:FindFirstChild("BrandTitle")
            local brandCaption = header:FindFirstChild("BrandCaption")
            local version = header:FindFirstChild("VersionChip")
            if brandTitle then brandTitle.Size = narrow and UDim2.new(0, 170, 0, 20) or UDim2.new(0, 240, 0, 20) end
            if brandCaption then brandCaption.Visible = not narrow end
            if version then version.Visible = true end
            -- Navigation is created with a fixed pitch, but the category list can
            -- grow (Missions added a tenth entry). Recompute pitch and item height
            -- from the real sidebar height so nothing is pushed below the panel.
            local navItems = {}
            for _, nav in ipairs(sidebar:GetChildren()) do
                if nav:IsA("TextButton") and string.sub(nav.Name, 1, 4) == "Nav_" then
                    navItems[#navItems + 1] = nav
                end
            end
            table.sort(navItems, function(a, b)
                return (tonumber(a.LayoutOrder) or 0) < (tonumber(b.LayoutOrder) or 0)
            end)
            local available = math.max(120, (sidebar.AbsoluteSize.Y > 1 and sidebar.AbsoluteSize.Y or (height - 87)) - 12)
            local pitch = math.min(40, math.max(24, math.floor(available / math.max(1, #navItems))))
            local navHeight = math.min(38, pitch - 2)
            for index, nav in ipairs(navItems) do
                nav.Position = UDim2.new(0, 6, 0, 6 + ((index - 1) * pitch))
                nav.Size = UDim2.new(1, -12, 0, navHeight)
                local tile, title = nav:FindFirstChild("IconTile"), nav:FindFirstChild("Title")
                if tile then tile.Position = narrow and UDim2.new(0.5, -13, 0.5, -13) or UDim2.new(0, 7, 0.5, -13) end
                if title then title.Visible = not narrow end
            end
            -- All secondary tabs retain their original positions on desktop.
            -- The compact rail gets enough horizontal room by proportionally
            -- reducing their fixed pixel widths, never their click targets.
            for _, control in ipairs(gui:GetDescendants()) do
                if control:IsA("TextButton") and control.Name == "FlowSubButton" then
                    local baseX = control:GetAttribute("FlowBaseX") or 0
                    local baseWidth = control:GetAttribute("FlowBaseWidth") or 80
                    local factor = narrow and 0.90 or 1
                    control.Position = UDim2.new(0, math.floor(baseX * factor), 0, 34)
                    control.Size = UDim2.new(0, math.max(54, math.floor(baseWidth * factor)), 0, 26)
                    control.TextSize = narrow and 8 or 10
                end
            end
            -- Reserve five percent at each edge. The adaptive canvas above
            -- avoids the old 0.4-scale text on compact Android displays.
            local fit = math.min((math.max(1, viewport.X * 0.90) / width), (math.max(1, viewport.Y * 0.90) / height))
            local scale = math.max(0.05, math.min(requested, fit))
            if layoutTween then pcall(function() layoutTween:Cancel() end) end
            if smooth and tweenService then
                local ok, tween = pcall(function()
                    return tweenService:Create(hubScale, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = scale })
                end)
                if ok and tween then layoutTween = tween; tween:Play(); return end
            end
            hubScale.Scale = scale
        end

        local function updateNumber(box, key, minimum, maximum)
            local value = tonumber(box.Text)
            if value and value >= minimum and value <= maximum then
                State[key] = value
                Config:Save()
                setStatus(t("saved"), Theme.success)
            else
                box.Text = tostring(State[key])
                setStatus(t("fail"), Theme.danger)
            end
        end

        local observedCamera
        local function observeViewport()
            local workspaceService = Flow.Services.Workspace
            local camera = workspaceService and workspaceService.CurrentCamera
            if not camera or camera == observedCamera then return end
            observedCamera = camera
            Flow:Track(camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
                updateLayout(true)
            end))
        end
        if Flow.Services.Workspace then
            Flow:Track(Flow.Services.Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
                observedCamera = nil
                observeViewport()
                updateLayout(true)
            end))
        end
