        local portalTestCancelRequested = false
        local function setPortalTestBusy(busy)
            portalTestRunning = busy == true
            portalTestContinue.Active = not portalTestRunning
            portalTestContinue.AutoButtonColor = not portalTestRunning
            portalTestContinue.BackgroundColor3 = portalTestRunning and Theme.panel3 or Theme.accent
            portalTestContinue.Text = portalTestRunning and "..." or ("    " .. t("continue"))
            portalTestCancel.Active = true
            portalTestCancel.Text = portalTestCancelRequested and "..." or ("    " .. t("cancel"))
        end

        local function showWorldPortalTest(keys)
            if portalTestRunning then return end
            local list = WorldPortals and WorldPortals:DescribeKeys(keys) or ""
            portalTestCancelRequested = false
            portalTestTitle.Text = t("world_portal_test_title")
            portalTestBody.Text = t("world_portal_test_message") .. "\n\n" .. t("world_portal_test_missing", list)
            setPortalTestBusy(false)
            portalTestOverlay.Visible = true
        end

        bindConfirmationPress(portalTestCancel, function()
            if portalTestRunning then
                -- Cancel must remain a real action while the approved physical
                -- test is moving. The native controller owns an exact ticket,
                -- so this cannot cancel another feature's route.
                portalTestCancelRequested = true
                portalTestCancel.Active = false
                portalTestCancel.Text = "..."
                portalTestBody.Text = t("cancelled")
                if WorldPortals and WorldPortals.CancelTest then
                    WorldPortals:CancelTest("user_cancelled")
                end
                return
            end
            portalTestOverlay.Visible = false
            setWorldPortals(false, t("world_portals_off"), Theme.muted)
        end)
        bindConfirmationPress(portalTestContinue, function()
            if portalTestRunning or not WorldPortals then return end
            portalTestCancelRequested = false
            setPortalTestBusy(true)
            portalTestBody.Text = t("world_portal_checking")
            setStatus(t("world_portal_checking"), Theme.muted)
            task.spawn(function()
                local callOk, testOk, testReason = pcall(function()
                    return WorldPortals:TestUnconfirmed()
                end)
                local cancelled = portalTestCancelRequested or (callOk and testReason == "cancelled")
                local enabled = callOk and not cancelled and WorldPortals:HasAvailable()
                portalTestRunning = false
                portalTestCancelRequested = false
                if gui and gui.Parent then
                    portalTestOverlay.Visible = false
                    setPortalTestBusy(false)
                    if cancelled then
                        setWorldPortals(false, t("cancelled"), Theme.muted)
                    elseif enabled then
                        local message = testOk and t("world_portal_ready") or t("world_portal_partial")
                        setWorldPortals(true, message, Theme.success)
                    else
                        setWorldPortals(false, t("world_portal_unavailable"), Theme.danger)
                    end
                end
            end)
        end)

