        label(boatInfo, {Size = UDim2.new(1, -22, 0, 18), Position = UDim2.new(0, 11, 0, 9), Text = t("boat_tp"), TextSize = 13, Font = Enum.Font.GothamBold})
        label(boatInfo, {
