        local selectedFriendRow = frame(boatList, {Size = UDim2.new(1, 0, 0, 52), BackgroundColor3 = Theme.panel2}, 8)
        label(selectedFriendRow, {Size = UDim2.new(1, -22, 0, 16), Position = UDim2.new(0, 11, 0, 8), Text = t("boat_tp_selected"), TextSize = 11, Font = Enum.Font.GothamBold})
        local selectedFriendText = label(selectedFriendRow, {Size = UDim2.new(1, -22, 0, 17), Position = UDim2.new(0, 11, 0, 28), Text = t("boat_tp_none"), TextSize = 10, TextColor3 = Theme.muted, TextTruncate = Enum.TextTruncate.AtEnd})
        local playerPicker = Theme.New("ScrollingFrame", {
            Size = UDim2.new(1, 0, 0, 142), BackgroundColor3 = Theme.panel2, BorderSizePixel = 0,
            ScrollBarThickness = 4, ScrollBarImageColor3 = Theme.accent, AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(), Parent = boatList,
