        Theme.Round(playerPicker, 8)
        local playerPickerLayout = Instance.new("UIListLayout")
        playerPickerLayout.Padding = UDim.new(0, 4)
        playerPickerLayout.Parent = playerPicker
        local playerPickerPadding = Instance.new("UIPadding")
        playerPickerPadding.PaddingTop, playerPickerPadding.PaddingBottom = UDim.new(0, 6), UDim.new(0, 6)
        playerPickerPadding.PaddingLeft, playerPickerPadding.PaddingRight = UDim.new(0, 6), UDim.new(0, 6)
        playerPickerPadding.Parent = playerPicker
        local boatFriendToggle
        local boatFriendStatus = label(boatList, {Size = UDim2.new(1, 0, 0, 19), Text = t("boat_tp_status", t("boat_tp_waiting")), TextSize = 10, TextColor3 = Theme.muted})
        local selectedBoatFriendPlayer = nil
        local function boatFriendStatusText(snapshot)
            local phase = snapshot and snapshot.phase or "idle"
            if phase == "idle" and snapshot and snapshot.reason == "native_remote_not_ready" then
                return t("boat_tp_handoff_wait")
            elseif phase == "idle" and snapshot and snapshot.reason == "physical_authority_lost" then
                return t("boat_tp_authority_lost")
            end
            local map = {
                idle = t("boat_tp_waiting"), arming_boat = t("boat_tp_arming"), approaching_friend = t("boat_tp_approaching"),
                holding_for_boarding = t("boat_tp_boarding"), settling_passenger = t("boat_tp_settling"),
                returning_owner = t("boat_tp_returning"), delivered = t("boat_tp_delivered"),
            }
            return map[phase] or t("boat_tp_reason_unknown")
        end
        refreshBoatFriendPlayers = function()
            for _, child in ipairs(playerPicker:GetChildren()) do
                if child.Name == "BoatFriendEntry" then child:Destroy() end
            end
            if not BoatFriend then return end
            local candidates = BoatFriend:GetPlayers()
            if #candidates == 0 then
                local empty = label(playerPicker, {Size = UDim2.new(1, 0, 0, 28), Text = t("boat_tp_no_players"), TextSize = 10, TextColor3 = Theme.muted, TextXAlignment = Enum.TextXAlignment.Center})
                empty.Name = "BoatFriendEntry"
                return
            end
            for _, candidate in ipairs(candidates) do
                local row = button(playerPicker, "@" .. candidate.Name .. "  ·  " .. candidate.DisplayName, selectedBoatFriendPlayer == candidate and Theme.accent or Theme.panel3, 7)
                row.Name = "BoatFriendEntry"
                row.Size = UDim2.new(1, 0, 0, 29)
                Flow:Track(row.MouseButton1Click:Connect(function()
                    selectedBoatFriendPlayer = candidate
                    selectedFriendText.Text = "@" .. candidate.Name
                    refreshBoatFriendPlayers()
                end))
            end
        end
        local _, pullFriendToggle = Theme.OptionRow(boatList, t("boat_tp_pull"), t("boat_tp_pull_desc"), function(active)
            if not BoatFriend then return end
            if not active then
                BoatFriend:Stop("user_disabled")
                boatFriendStatus.Text = t("boat_tp_status", t("boat_tp_disabled"))
                return
            end
            if not selectedBoatFriendPlayer then
                pullFriendToggle:Set(false, true)
                boatFriendStatus.Text = t("boat_tp_status", t("boat_tp_select_player"))
                setStatus(t("boat_tp_select_player_notice"), Theme.danger)
                return
            end
            local ok, reason = BoatFriend:Start(selectedBoatFriendPlayer)
            if not ok then
                pullFriendToggle:Set(false, true)
                local messages = {
                    sit_in_own_pilot_seat_first = t("boat_tp_reason_sit"), owned_boat_missing = t("boat_tp_reason_boat"),
                    no_passenger_seat = t("boat_tp_reason_seat"), pilot_seat_busy = t("boat_tp_reason_pilot_busy"),
                    remote_boat_missing = t("boat_tp_reason_remote"), eventfarm_native_controller_missing = t("boat_tp_reason_controller"),
                }
                boatFriendStatus.Text = t("boat_tp_status", messages[reason] or t("boat_tp_reason_unknown"))
            end
        end, lucide.travel)
        boatFriendToggle = pullFriendToggle
        if BoatFriend then
            BoatFriend:SetChangedCallback(function(snapshot)
                if boatFriendStatus and boatFriendStatus.Parent then boatFriendStatus.Text = t("boat_tp_status", boatFriendStatusText(snapshot)) end
                if boatFriendToggle and boatFriendToggle.Parent then boatFriendToggle:Set(snapshot.active == true, true) end
            end)
        end
        refreshBoatFriendPlayers()

