        local ok, result = pcall(callback)
        mark(name, string.format("%.0fms|ok=%s", (os.clock() - startedAt) * 1000, tostring(ok)))
        if not ok then Flow:Log("Startup phase failed | " .. tostring(name) .. " | " .. tostring(result)) end
