    -- WorldPortals inventory proof can call getgc(true), and passive monitors
    -- can scan replicated objects; both used to hold the first UI frame back.
    local worldPortals = Flow.Features.WorldPortals
    if worldPortals and worldPortals.Initialize then
        pcall(function() worldPortals:Initialize(false) end)
    end

    local uiStartedAt = os.clock()
    local gui, reason = Flow.UI:Create()
    mark("ui_created", string.format("%.0fms", (os.clock() - uiStartedAt) * 1000))
