        if misc and misc.ApplySaved then
            runDeferredPhase("saved_misc_applied", function() return misc:ApplySaved() end)
        end

        local raidMonitor = Flow.Features.RaidMonitor
        if Flow.State.raidMonitorEnabled and raidMonitor and raidMonitor.Start then
            runDeferredPhase("raid_monitor_started", function() return raidMonitor:Start() end)
        end

        local priority = Flow.Features.SystemPriority
        if priority and priority.Start then
            runDeferredPhase("priority_started", function() return priority:Start() end)
        end

        local telemetry = Flow.Features.SystemTelemetry
        if Flow.State.telemetryEnabled and telemetry and telemetry.Start then
            runDeferredPhase("telemetry_started", function() return telemetry:Start() end)
